INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('aarakocra', 'Aarakocra', 'humanoid', 'aarakocra', 'M', 'N, G', 12, 13, '{"walk": 20, "fly": 50}', 10, 14, 10, 11, 12, 11, '1/4', 0, 2, '{}', '{"perception": "+5"}', '[]', '[]', '[]', '[]', '["Auran", "Aarakocra"]', '[{"name": "Dive Attack", "entries": ["If the aarakocra is flying and dives at least 30 feet straight toward a target and then hits it with a melee weapon attack, the attack deals an extra 3 ({@damage 1d6}) damage to the target."]}]', '[{"name": "Talon", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}4 ({@damage 1d4 + 2}) slashing damage."]}, {"name": "Javelin", "entries": ["{@atk mw,rw} {@hit 4} to hit, reach 5 ft. or range 30/120 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage."]}, {"name": "Summon Air Elemental", "entries": ["Five aarakocra within 30 feet of each other can magically summon an {@creature air elemental}. Each of the five must use its action and movement on three consecutive turns to perform an aerial dance and must maintain {@status concentration} while doing so (as if {@status concentration||concentrating} on a spell). When all five have finished their third turn of the dance, the elemental appears in an unoccupied space within 60 feet of them. It is friendly toward them and obeys their spoken commands. It remains for 1 hour, until it or all its summoners die, or until any of its summoners dismisses it as a bonus action. A summoner can''t perform the dance again until it finishes a short rest. When the elemental returns to the Elemental Plane of Air, any aarakocra within 5 feet of it can return with it."]}]', '[]', '[]', '["mountain"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('aboleth', 'Aboleth', 'aberration', '', 'L', 'L, E', 17, 135, '{"walk": 10, "swim": 40}', 21, 9, 15, 18, 15, 18, '10', 0, 2, '{"con": "+6", "int": "+8", "wis": "+6"}', '{"history": "+12", "perception": "+10"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Deep Speech", "telepathy 120 ft."]', '[{"name": "Amphibious", "entries": ["The aboleth can breathe air and water."]}, {"name": "Mucous Cloud", "entries": ["While underwater, the aboleth is surrounded by transformative mucus. A creature that touches the aboleth or that hits it with a melee attack while within 5 feet of it must make a {@dc 14} Constitution saving throw. On a failure, the creature is diseased for {@dice 1d4} hours. The diseased creature can breathe only underwater."]}, {"name": "Probing Telepathy", "entries": ["If a creature communicates telepathically with the aboleth, the aboleth learns the creature''s greatest desires if the aboleth can see the creature."]}]', '[{"name": "Multiattack", "entries": ["The aboleth makes three tentacle attacks."]}, {"name": "Tentacle", "entries": ["{@atk mw} {@hit 9} to hit, reach 10 ft., one target. {@h}12 ({@damage 2d6 + 5}) bludgeoning damage. If the target is a creature, it must succeed on a {@dc 14} Constitution saving throw or become diseased. The disease has no effect for 1 minute and can be removed by any magic that cures disease. After 1 minute, the diseased creature''s skin becomes translucent and slimy, the creature can''t regain hit points unless it is underwater, and the disease can be removed only by {@spell heal} or another disease-curing spell of 6th level or higher. When the creature is outside a body of water, it takes 6 ({@damage 1d12}) acid damage every 10 minutes unless moisture is applied to the skin before 10 minutes have passed."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 9} to hit, reach 10 ft., one target. {@h}15 ({@damage 3d6 + 5}) bludgeoning damage."]}, {"name": "Enslave (3/Day)", "entries": ["The aboleth targets one creature it can see within 30 feet of it. The target must succeed on a {@dc 14} Wisdom saving throw or be magically {@condition charmed} by the aboleth until the aboleth dies or until it is on a different plane of existence from the target. The {@condition charmed} target is under the aboleth''s control and can''t take reactions, and the aboleth and the target can communicate telepathically with each other over any distance.", "Whenever the {@condition charmed} target takes damage, the target can repeat the saving throw. On a success, the effect ends. No more than once every 24 hours, the target can also repeat the saving throw when it is at least 1 mile away from the aboleth."]}]', '[{"name": "Detect", "entries": ["The aboleth makes a Wisdom ({@skill Perception}) check."]}, {"name": "Tail Swipe", "entries": ["The aboleth makes one tail attack."]}, {"name": "Psychic Drain (Costs 2 Actions)", "entries": ["One creature {@condition charmed} by the aboleth takes 10 ({@damage 3d6}) psychic damage, and the aboleth regains hit points equal to the damage the creature takes."]}]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('abominable_yeti', 'Abominable Yeti', 'monstrosity', '', 'H', 'C, E', 15, 137, '{"walk": 40, "climb": 40}', 24, 10, 22, 9, 13, 9, '9', 0, 2, '{}', '{"perception": "+5", "stealth": "+4"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Yeti"]', '[{"name": "Fear of Fire", "entries": ["If the yeti takes fire damage, it has disadvantage on attack rolls and ability checks until the end of its next turn."]}, {"name": "Keen Smell", "entries": ["The yeti has advantage on Wisdom ({@skill Perception}) checks that rely on smell."]}, {"name": "Snow Camouflage", "entries": ["The yeti has advantage on Dexterity ({@skill Stealth}) checks made to hide in snowy terrain."]}]', '[{"name": "Multiattack", "entries": ["The yeti can use its Chilling Gaze and makes two claw attacks."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 11} to hit, reach 5 ft., one target. {@h}14 ({@damage 2d6 + 7}) slashing damage plus 7 ({@damage 2d6}) cold damage."]}, {"name": "Chilling Gaze", "entries": ["The yeti targets one creature it can see within 30 feet of it. If the target can see the yeti, the target must succeed on a {@dc 18} Constitution saving throw against this magic or take 21 ({@damage 6d6}) cold damage and then be {@condition paralyzed} for 1 minute, unless it is immune to cold damage. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If the target''s saving throw is successful, or if the effect ends on it, the target is immune to this yeti''s gaze for 1 hour."]}, {"name": "Cold Breath {@recharge}", "entries": ["The yeti exhales a 30-foot cone of frigid air. Each creature in that area must make a {@dc 18} Constitution saving throw, taking 45 ({@damage 10d8}) cold damage on a failed save, or half as much damage on a successful one."]}]', '[]', '[]', '["arctic"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('acolyte', 'Acolyte', 'humanoid', 'any race', 'M', 'A', 10, 9, '{"walk": 30}', 10, 10, 10, 10, 14, 11, '1/4', 0, 2, '{}', '{"medicine": "+4", "religion": "+2"}', '[]', '[]', '[]', '[]', '["any one language (usually Common)"]', '[]', '[{"name": "Club", "entries": ["{@atk mw} {@hit 2} to hit, reach 5 ft., one target. {@h}2 ({@damage 1d4}) bludgeoning damage."]}]', '[]', '[]', '["urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('adult_black_dragon', 'Adult Black Dragon', 'dragon', '', 'H', 'C, E', 19, 195, '{"walk": 40, "fly": 80, "swim": 40}', 23, 14, 21, 14, 13, 17, '14', 0, 2, '{"dex": "+7", "con": "+10", "wis": "+6", "cha": "+8"}', '{"perception": "+11", "stealth": "+7"}', '[]', '[]', '[]', '["blindsight 60 ft.", "darkvision 120 ft."]', '["Common", "Draconic"]', '[{"name": "Amphibious", "entries": ["The dragon can breathe air and water."]}, {"name": "Legendary Resistance (3/Day)", "entries": ["If the dragon fails a saving throw, it can choose to succeed instead."]}]', '[{"name": "Multiattack", "entries": ["The dragon can use its Frightful Presence. It then makes three attacks: one with its bite and two with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 11} to hit, reach 10 ft., one target. {@h}17 ({@damage 2d10 + 6}) piercing damage plus 4 ({@damage 1d8}) acid damage."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 11} to hit, reach 5 ft., one target. {@h}13 ({@damage 2d6 + 6}) slashing damage."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 11} to hit, reach 15 ft., one target. {@h}15 ({@damage 2d8 + 6}) bludgeoning damage."]}, {"name": "Frightful Presence", "entries": ["Each creature of the dragon''s choice that is within 120 feet of the dragon and aware of it must succeed on a {@dc 16} Wisdom saving throw or become {@condition frightened} for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the dragon''s Frightful Presence for the next 24 hours."]}, {"name": "Acid Breath {@recharge 5}", "entries": ["The dragon exhales acid in a 60-foot line that is 5 feet wide. Each creature in that line must make a {@dc 18} Dexterity saving throw, taking 54 ({@damage 12d8}) acid damage on a failed save, or half as much damage on a successful one."]}]', '[{"name": "Detect", "entries": ["The dragon makes a Wisdom ({@skill Perception}) check."]}, {"name": "Tail Attack", "entries": ["The dragon makes a tail attack."]}, {"name": "Wing Attack (Costs 2 Actions)", "entries": ["The dragon beats its wings. Each creature within 10 feet of the dragon must succeed on a {@dc 19} Dexterity saving throw or take 13 ({@damage 2d6 + 6}) bludgeoning damage and be knocked {@condition prone}. The dragon can then fly up to half its flying speed."]}]', '[]', '["swamp"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('adult_blue_dracolich', 'Adult Blue Dracolich', 'undead', '', 'H', 'L, E', 19, 225, '{"walk": 40, "burrow": 30, "fly": 80}', 25, 10, 23, 16, 15, 19, '17', 0, 2, '{"dex": "+6", "con": "+12", "wis": "+8", "cha": "+10"}', '{"perception": "+14", "stealth": "+6"}', '[]', '[]', '[]', '["blindsight 60 ft.", "darkvision 120 ft."]', '["Common", "Draconic"]', '[{"name": "Legendary Resistance (3/Day)", "entries": ["If the dracolich fails a saving throw, it can choose to succeed instead."]}, {"name": "Magic Resistance", "entries": ["The dracolich has advantage on saving throws against spells and other magical effects."]}]', '[{"name": "Multiattack", "entries": ["The dracolich can use its Frightful Presence. It then makes three attacks: one with its bite and two with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 13} to hit, reach 10 ft., one target. {@h}18 ({@damage 2d10 + 7}) piercing damage plus 5 ({@damage 1d10}) lightning damage."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 13} to hit, reach 5 ft., one target. {@h}14 ({@damage 2d6 + 7}) slashing damage."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 13} to hit, reach 15 ft., one target. {@h}16 ({@damage 2d8 + 7}) bludgeoning damage."]}, {"name": "Frightful Presence", "entries": ["Each creature of the dracolich''s choice that is within 120 feet of the dracolich and aware of it must succeed on a {@dc 18} Wisdom saving throw or become {@condition frightened} for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the dracolich''s Frightful Presence for the next 24 hours."]}, {"name": "Lightning Breath {@recharge 5}", "entries": ["The dracolich exhales lightning in a 90-foot line that is 5 feet wide. Each creature in that line must make a {@dc 20} Dexterity saving throw, taking 66 ({@damage 12d10}) lightning damage on a failed save, or half as much damage on a successful one."]}]', '[{"name": "Detect", "entries": ["The dracolich makes a Wisdom ({@skill Perception}) check."]}, {"name": "Tail Attack", "entries": ["The dracolich makes a tail attack."]}, {"name": "Wing Attack (Costs 2 Actions)", "entries": ["The dracolich beats its tattered wings. Each creature within 10 feet of the dracolich must succeed on a {@dc 21} Dexterity saving throw or take 14 ({@damage 2d6 + 7}) bludgeoning damage and be knocked {@condition prone}. After beating its wings this way, the dracolich can fly up to half its flying speed."]}]', '[]', '["desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('adult_blue_dragon', 'Adult Blue Dragon', 'dragon', '', 'H', 'L, E', 19, 225, '{"walk": 40, "burrow": 30, "fly": 80}', 25, 10, 23, 16, 15, 19, '16', 0, 2, '{"dex": "+5", "con": "+11", "wis": "+7", "cha": "+9"}', '{"perception": "+12", "stealth": "+5"}', '[]', '[]', '[]', '["blindsight 60 ft.", "darkvision 120 ft."]', '["Common", "Draconic"]', '[{"name": "Legendary Resistance (3/Day)", "entries": ["If the dragon fails a saving throw, it can choose to succeed instead."]}]', '[{"name": "Multiattack", "entries": ["The dragon can use its Frightful Presence. It then makes three attacks: one with its bite and two with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 12} to hit, reach 10 ft., one target. {@h}18 ({@damage 2d10 + 7}) piercing damage plus 5 ({@damage 1d10}) lightning damage."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 12} to hit, reach 5 ft., one target. {@h}14 ({@damage 2d6 + 7}) slashing damage."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 12} to hit, reach 15 ft., one target. {@h}16 ({@damage 2d8 + 7}) bludgeoning damage."]}, {"name": "Frightful Presence", "entries": ["Each creature of the dragon''s choice that is within 120 feet of the dragon and aware of it must succeed on a {@dc 17} Wisdom saving throw or become {@condition frightened} for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the dragon''s Frightful Presence for the next 24 hours."]}, {"name": "Lightning Breath {@recharge 5}", "entries": ["The dragon exhales lightning in a 90-foot line that is 5 feet wide. Each creature in that line must make a {@dc 19} Dexterity saving throw, taking 66 ({@damage 12d10}) lightning damage on a failed save, or half as much damage on a successful one."]}]', '[{"name": "Detect", "entries": ["The dragon makes a Wisdom ({@skill Perception}) check."]}, {"name": "Tail Attack", "entries": ["The dragon makes a tail attack."]}, {"name": "Wing Attack (Costs 2 Actions)", "entries": ["The dragon beats its wings. Each creature within 10 feet of the dragon must succeed on a {@dc 20} Dexterity saving throw or take 14 ({@damage 2d6 + 7}) bludgeoning damage and be knocked {@condition prone}. The dragon can then fly up to half its flying speed."]}]', '[]', '["desert", "coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('adult_brass_dragon', 'Adult Brass Dragon', 'dragon', '', 'H', 'C, G', 18, 172, '{"walk": 40, "burrow": 40, "fly": 80}', 23, 10, 21, 14, 13, 17, '13', 0, 2, '{"dex": "+5", "con": "+10", "wis": "+6", "cha": "+8"}', '{"history": "+7", "perception": "+11", "persuasion": "+8", "stealth": "+5"}', '[]', '[]', '[]', '["blindsight 60 ft.", "darkvision 120 ft."]', '["Common", "Draconic"]', '[{"name": "Legendary Resistance (3/Day)", "entries": ["If the dragon fails a saving throw, it can choose to succeed instead."]}]', '[{"name": "Multiattack", "entries": ["The dragon can use its Frightful Presence. It then makes three attacks: one with its bite and two with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 11} to hit, reach 10 ft., one target. {@h}17 ({@damage 2d10 + 6}) piercing damage."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 11} to hit, reach 5 ft., one target. {@h}13 ({@damage 2d6 + 6}) slashing damage."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 11} to hit, reach 15 ft., one target. {@h}15 ({@damage 2d8 + 6}) bludgeoning damage."]}, {"name": "Frightful Presence", "entries": ["Each creature of the dragon''s choice that is within 120 feet of the dragon and aware of it must succeed on a {@dc 16} Wisdom saving throw or become {@condition frightened} for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the dragon''s Frightful Presence for the next 24 hours."]}, {"name": "Breath Weapons {@recharge 5}", "entries": ["The dragon uses one of the following breath weapons.", {"type": "list", "style": "list-hang-notitle", "items": [{"type": "item", "name": "Fire Breath", "entry": "The dragon exhales fire in a 60-foot line that is 5 feet wide. Each creature in that line must make a {@dc 18} Dexterity saving throw, taking 45 ({@damage 13d6}) fire damage on a failed save, or half as much damage on a successful one."}, {"type": "item", "name": "Sleep Breath", "entry": "The dragon exhales sleep gas in a 60-foot cone. Each creature in that area must succeed on a {@dc 18} Constitution saving throw or fall {@condition unconscious} for 10 minutes. This effect ends for a creature if the creature takes damage or someone uses an action to wake it."}]}]}]', '[{"name": "Detect", "entries": ["The dragon makes a Wisdom ({@skill Perception}) check."]}, {"name": "Tail Attack", "entries": ["The dragon makes a tail attack."]}, {"name": "Wing Attack (Costs 2 Actions)", "entries": ["The dragon beats its wings. Each creature within 10 feet of the dragon must succeed on a {@dc 19} Dexterity saving throw or take 13 ({@damage 2d6 + 6}) bludgeoning damage and be knocked {@condition prone}. The dragon can then fly up to half its flying speed."]}]', '[]', '["desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('adult_bronze_dragon', 'Adult Bronze Dragon', 'dragon', '', 'H', 'L, G', 19, 212, '{"walk": 40, "fly": 80, "swim": 40}', 25, 10, 23, 16, 15, 19, '15', 0, 2, '{"dex": "+5", "con": "+11", "wis": "+7", "cha": "+9"}', '{"insight": "+7", "perception": "+12", "stealth": "+5"}', '[]', '[]', '[]', '["blindsight 60 ft.", "darkvision 120 ft."]', '["Common", "Draconic"]', '[{"name": "Amphibious", "entries": ["The dragon can breathe air and water."]}, {"name": "Legendary Resistance (3/Day)", "entries": ["If the dragon fails a saving throw, it can choose to succeed instead."]}]', '[{"name": "Multiattack", "entries": ["The dragon can use its Frightful Presence. It then makes three attacks: one with its bite and two with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 12} to hit, reach 10 ft., one target. {@h}18 ({@damage 2d10 + 7}) piercing damage."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 12} to hit, reach 5 ft., one target. {@h}14 ({@damage 2d6 + 7}) slashing damage."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 12} to hit, reach 15 ft., one target. {@h}16 ({@damage 2d8 + 7}) bludgeoning damage."]}, {"name": "Frightful Presence", "entries": ["Each creature of the dragon''s choice that is within 120 feet of the dragon and aware of it must succeed on a {@dc 17} Wisdom saving throw or become {@condition frightened} for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the dragon''s Frightful Presence for the next 24 hours."]}, {"name": "Breath Weapons {@recharge 5}", "entries": ["The dragon uses one of the following breath weapons.", {"type": "list", "style": "list-hang-notitle", "items": [{"type": "item", "name": "Lightning Breath", "entry": "The dragon exhales lightning in a 90-foot line that is 5 feet wide. Each creature in that line must make a {@dc 19} Dexterity saving throw, taking 66 ({@damage 12d10}) lightning damage on a failed save, or half as much damage on a successful one."}, {"type": "item", "name": "Repulsion Breath", "entry": "The dragon exhales repulsion energy in a 30-foot cone. Each creature in that area must succeed on a {@dc 19} Strength saving throw. On a failed save, the creature is pushed 60 feet away from the dragon."}]}]}, {"name": "Change Shape", "entries": ["The dragon magically polymorphs into a humanoid or beast that has a challenge rating no higher than its own, or back into its true form. It reverts to its true form if it dies. Any equipment it is wearing or carrying is absorbed or borne by the new form (the dragon''s choice).", "In a new form, the dragon retains its alignment, hit points, Hit Dice, ability to speak, proficiencies, Legendary Resistance, lair actions, and Intelligence, Wisdom, and Charisma scores, as well as this action. Its statistics and capabilities are otherwise replaced by those of the new form, except any class features or legendary actions of that form."]}]', '[{"name": "Detect", "entries": ["The dragon makes a Wisdom ({@skill Perception}) check."]}, {"name": "Tail Attack", "entries": ["The dragon makes a tail attack."]}, {"name": "Wing Attack (Costs 2 Actions)", "entries": ["The dragon beats its wings. Each creature within 10 feet of the dragon must succeed on a {@dc 20} Dexterity saving throw or take 14 ({@damage 2d6 + 7}) bludgeoning damage and be knocked {@condition prone}. The dragon can then fly up to half its flying speed."]}]', '[]', '["coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('adult_copper_dragon', 'Adult Copper Dragon', 'dragon', '', 'H', 'C, G', 18, 184, '{"walk": 40, "climb": 40, "fly": 80}', 23, 12, 21, 18, 15, 17, '14', 0, 2, '{"dex": "+6", "con": "+10", "wis": "+7", "cha": "+8"}', '{"deception": "+8", "perception": "+12", "stealth": "+6"}', '[]', '[]', '[]', '["blindsight 60 ft.", "darkvision 120 ft."]', '["Common", "Draconic"]', '[{"name": "Legendary Resistance (3/Day)", "entries": ["If the dragon fails a saving throw, it can choose to succeed instead."]}]', '[{"name": "Multiattack", "entries": ["The dragon can use its Frightful Presence. It then makes three attacks: one with its bite and two with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 11} to hit, reach 10 ft., one target. {@h}17 ({@damage 2d10 + 6}) piercing damage."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 11} to hit, reach 5 ft., one target. {@h}13 ({@damage 2d6 + 6}) slashing damage."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 11} to hit, reach 15 ft., one target. {@h}15 ({@damage 2d8 + 6}) bludgeoning damage."]}, {"name": "Frightful Presence", "entries": ["Each creature of the dragon''s choice that is within 120 feet of the dragon and aware of it must succeed on a {@dc 16} Wisdom saving throw or become {@condition frightened} for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the dragon''s Frightful Presence for the next 24 hours."]}, {"name": "Breath Weapons {@recharge 5}", "entries": ["The dragon uses one of the following breath weapons.", {"type": "list", "style": "list-hang-notitle", "items": [{"type": "item", "name": "Acid Breath", "entry": "The dragon exhales acid in a 60-foot line that is 5 feet wide. Each creature in that line must make a {@dc 18} Dexterity saving throw, taking 54 ({@damage 12d8}) acid damage on a failed save, or half as much damage on a successful one."}, {"type": "item", "name": "Slowing Breath", "entry": "The dragon exhales gas in a 60-foot cone. Each creature in that area must succeed on a {@dc 18} Constitution saving throw. On a failed save, the creature can''t use reactions, its speed is halved, and it can''t make more than one attack on its turn. In addition, the creature can use either an action or a bonus action on its turn, but not both. These effects last for 1 minute. The creature can repeat the saving throw at the end of each of its turns, ending the effect on itself with a successful save."}]}]}]', '[{"name": "Detect", "entries": ["The dragon makes a Wisdom ({@skill Perception}) check."]}, {"name": "Tail Attack", "entries": ["The dragon makes a tail attack."]}, {"name": "Wing Attack (Costs 2 Actions)", "entries": ["The dragon beats its wings. Each creature within 10 feet of the dragon must succeed on a {@dc 19} Dexterity saving throw or take 13 ({@damage 2d6 + 6}) bludgeoning damage and be knocked {@condition prone}. The dragon can then fly up to half its flying speed."]}]', '[]', '["hill"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('adult_gold_dragon', 'Adult Gold Dragon', 'dragon', '', 'H', 'L, G', 19, 256, '{"walk": 40, "fly": 80, "swim": 40}', 27, 14, 25, 16, 15, 24, '17', 0, 2, '{"dex": "+8", "con": "+13", "wis": "+8", "cha": "+13"}', '{"insight": "+8", "perception": "+14", "persuasion": "+13", "stealth": "+8"}', '[]', '[]', '[]', '["blindsight 60 ft.", "darkvision 120 ft."]', '["Common", "Draconic"]', '[{"name": "Amphibious", "entries": ["The dragon can breathe air and water."]}, {"name": "Legendary Resistance (3/Day)", "entries": ["If the dragon fails a saving throw, it can choose to succeed instead."]}]', '[{"name": "Multiattack", "entries": ["The dragon can use its Frightful Presence. It then makes three attacks: one with its bite and two with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 14} to hit, reach 10 ft., one target. {@h}19 ({@damage 2d10 + 8}) piercing damage."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 14} to hit, reach 5 ft., one target. {@h}15 ({@damage 2d6 + 8}) slashing damage."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 14} to hit, reach 15 ft., one target. {@h}17 ({@damage 2d8 + 8}) bludgeoning damage."]}, {"name": "Frightful Presence", "entries": ["Each creature of the dragon''s choice that is within 120 feet of the dragon and aware of it must succeed on a {@dc 21} Wisdom saving throw or become {@condition frightened} for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the dragon''s Frightful Presence for the next 24 hours."]}, {"name": "Breath Weapons {@recharge 5}", "entries": ["The dragon uses one of the following breath weapons.", {"type": "list", "style": "list-hang-notitle", "items": [{"type": "item", "name": "Fire Breath", "entry": "The dragon exhales fire in a 60-foot cone. Each creature in that area must make a {@dc 21} Dexterity saving throw, taking 66 ({@damage 12d10}) fire damage on a failed save, or half as much damage on a successful one."}, {"type": "item", "name": "Weakening Breath", "entry": "The dragon exhales gas in a 60-foot cone. Each creature in that area must succeed on a {@dc 21} Strength saving throw or have disadvantage on Strength-based attack rolls, Strength checks, and Strength saving throws for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."}]}]}, {"name": "Change Shape", "entries": ["The dragon magically polymorphs into a humanoid or beast that has a challenge rating no higher than its own, or back into its true form. It reverts to its true form if it dies. Any equipment it is wearing or carrying is absorbed or borne by the new form (the dragon''s choice).", "In a new form, the dragon retains its alignment, hit points, Hit Dice, ability to speak, proficiencies, Legendary Resistance, lair actions, and Intelligence, Wisdom, and Charisma scores, as well as this action. Its statistics and capabilities are otherwise replaced by those of the new form, except any class features or legendary actions of that form."]}]', '[{"name": "Detect", "entries": ["The dragon makes a Wisdom ({@skill Perception}) check."]}, {"name": "Tail Attack", "entries": ["The dragon makes a tail attack."]}, {"name": "Wing Attack (Costs 2 Actions)", "entries": ["The dragon beats its wings. Each creature within 10 feet of the dragon must succeed on a {@dc 22} Dexterity saving throw or take 15 ({@damage 2d6 + 8}) bludgeoning damage and be knocked {@condition prone}. The dragon can then fly up to half its flying speed."]}]', '[]', '["grassland", "forest"]');
