 "entries": ["The dragon uses one of the following breath weapons.", {"type": "list", "style": "list-hang-notitle", "items": [{"type": "item", "name": "Cold Breath", "entry": "The dragon exhales an icy blast in a 60-foot cone. Each creature in that area must make a {@dc 20} Constitution saving throw, taking 58 ({@damage 13d8}) cold damage on a failed save, or half as much damage on a successful one."}, {"type": "item", "name": "Paralyzing Breath", "entry": "The dragon exhales paralyzing gas in a 60-foot cone. Each creature in that area must succeed on a {@dc 20} Constitution saving throw or be {@condition paralyzed} for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."}]}]}, {"name": "Change Shape", "entries": ["The dragon magically polymorphs into a humanoid or beast that has a challenge rating no higher than its own, or back into its true form. It reverts to its true form if it dies. Any equipment it is wearing or carrying is absorbed or borne by the new form (the dragon''s choice).", "In a new form, the dragon retains its alignment, hit points, Hit Dice, ability to speak, proficiencies, Legendary Resistance, lair actions, and Intelligence, Wisdom, and Charisma scores, as well as this action. Its statistics and capabilities are otherwise replaced by those of the new form, except any class features or legendary actions of that form."]}]', '[{"name": "Detect", "entries": ["The dragon makes a Wisdom ({@skill Perception}) check."]}, {"name": "Tail Attack", "entries": ["The dragon makes a tail attack."]}, {"name": "Wing Attack (Costs 2 Actions)", "entries": ["The dragon beats its wings. Each creature within 10 feet of the dragon must succeed on a {@dc 22} Dexterity saving throw or take 15 ({@damage 2d6 + 8}) bludgeoning damage and be knocked {@condition prone}. The dragon can then fly up to half its flying speed."]}]', '[]', '["mountain", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('adult_white_dragon', 'Adult White Dragon', 'dragon', '', 'H', 'C, E', 18, 200, '{"walk": 40, "burrow": 30, "fly": 80, "swim": 40}', 22, 10, 22, 8, 12, 12, '13', 0, 2, '{"dex": "+5", "con": "+11", "wis": "+6", "cha": "+6"}', '{"perception": "+11", "stealth": "+5"}', '[]', '[]', '[]', '["blindsight 60 ft.", "darkvision 120 ft."]', '["Common", "Draconic"]', '[{"name": "Ice Walk", "entries": ["The dragon can move across and climb icy surfaces without needing to make an ability check. Additionally, {@quickref difficult terrain||3} composed of ice or snow doesn''t cost it extra movement."]}, {"name": "Legendary Resistance (3/Day)", "entries": ["If the dragon fails a saving throw, it can choose to succeed instead."]}]', '[{"name": "Multiattack", "entries": ["The dragon can use its Frightful Presence. It then makes three attacks: one with its bite and two with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 11} to hit, reach 10 ft., one target. {@h}17 ({@damage 2d10 + 6}) piercing damage plus 4 ({@damage 1d8}) cold damage."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 11} to hit, reach 5 ft., one target. {@h}13 ({@damage 2d6 + 6}) slashing damage."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 11} to hit, reach 15 ft., one target. {@h}15 ({@damage 2d8 + 6}) bludgeoning damage."]}, {"name": "Frightful Presence", "entries": ["Each creature of the dragon''s choice that is within 120 feet of the dragon and aware of it must succeed on a {@dc 14} Wisdom saving throw or become {@condition frightened} for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the dragon''s Frightful Presence for the next 24 hours."]}, {"name": "Cold Breath {@recharge 5}", "entries": ["The dragon exhales an icy blast in a 60-foot cone. Each creature in that area must make a {@dc 19} Constitution saving throw, taking 54 ({@damage 12d8}) cold damage on a failed save, or half as much damage on a successful one."]}]', '[{"name": "Detect", "entries": ["The dragon makes a Wisdom ({@skill Perception}) check."]}, {"name": "Tail Attack", "entries": ["The dragon makes a tail attack."]}, {"name": "Wing Attack (Costs 2 Actions)", "entries": ["The dragon beats its wings. Each creature within 10 feet of the dragon must succeed on a {@dc 19} Dexterity saving throw or take 13 ({@damage 2d6 + 6}) bludgeoning damage and be knocked {@condition prone}. The dragon can then fly up to half its flying speed."]}]', '[]', '["arctic"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('air_elemental', 'Air Elemental', 'elemental', '', 'L', 'N', 15, 90, '{"fly": {"number": 90, "condition": "(hover)"}, "canHover": true}', 14, 20, 14, 6, 10, 6, '5', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Auran"]', '[{"name": "Air Form", "entries": ["The elemental can enter a hostile creature''s space and stop there. It can move through a space as narrow as 1 inch wide without squeezing."]}]', '[{"name": "Multiattack", "entries": ["The elemental makes two slam attacks."]}, {"name": "Slam", "entries": ["{@atk mw} {@hit 8} to hit, reach 5 ft., one target. {@h}14 ({@damage 2d8 + 5}) bludgeoning damage."]}, {"name": "Whirlwind {@recharge 4}", "entries": ["Each creature in the elemental''s space must make a {@dc 13} Strength saving throw. On a failure, a target takes 15 ({@damage 3d8 + 2}) bludgeoning damage and is flung up 20 feet away from the elemental in a random direction and knocked {@condition prone}. If a thrown target strikes an object, such as a wall or floor, the target takes 3 ({@damage 1d6}) bludgeoning damage for every 10 feet it was thrown. If the target is thrown at another creature, that creature must succeed on a {@dc 13} Dexterity saving throw or take the same damage and be knocked {@condition prone}.", "If the saving throw is successful, the target takes half the bludgeoning damage and isn''t flung away or knocked {@condition prone}."]}]', '[]', '[]', '["mountain", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('allosaurus', 'Allosaurus', 'beast', '', 'L', 'U', 13, 51, '{"walk": 60}', 19, 13, 17, 2, 12, 5, '2', 0, 2, '{}', '{"perception": "+5"}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Pounce", "entries": ["If the allosaurus moves at least 30 feet straight toward a creature and then hits it with a claw attack on the same turn, that target must succeed on a {@dc 13} Strength saving throw or be knocked {@condition prone}. If the target is {@condition prone}, the allosaurus can make one bite attack against it as a bonus action."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}15 ({@damage 2d10 + 4}) piercing damage."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}8 ({@damage 1d8 + 4}) slashing damage."]}]', '[]', '[]', '["grassland"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('ancient_black_dragon', 'Ancient Black Dragon', 'dragon', '', 'G', 'C, E', 22, 367, '{"walk": 40, "fly": 80, "swim": 40}', 27, 14, 25, 16, 15, 19, '21', 0, 2, '{"dex": "+9", "con": "+14", "wis": "+9", "cha": "+11"}', '{"perception": "+16", "stealth": "+9"}', '[]', '[]', '[]', '["blindsight 60 ft.", "darkvision 120 ft."]', '["Common", "Draconic"]', '[{"name": "Amphibious", "entries": ["The dragon can breathe air and water."]}, {"name": "Legendary Resistance (3/Day)", "entries": ["If the dragon fails a saving throw, it can choose to succeed instead."]}]', '[{"name": "Multiattack", "entries": ["The dragon can use its Frightful Presence. It then makes three attacks: one with its bite and two with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 15} to hit, reach 15 ft., one target. {@h}19 ({@damage 2d10 + 8}) piercing damage plus 9 ({@damage 2d8}) acid damage."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 15} to hit, reach 10 ft., one target. {@h}15 ({@damage 2d6 + 8}) slashing damage."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 15} to hit, reach 20 ft., one target. {@h}17 ({@damage 2d8 + 8}) bludgeoning damage."]}, {"name": "Frightful Presence", "entries": ["Each creature of the dragon''s choice that is within 120 feet of the dragon and aware of it must succeed on a {@dc 19} Wisdom saving throw or become {@condition frightened} for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the dragon''s Frightful Presence for the next 24 hours."]}, {"name": "Acid Breath {@recharge 5}", "entries": ["The dragon exhales acid in a 90-foot line that is 10 feet wide. Each creature in that line must make a {@dc 22} Dexterity saving throw, taking 67 ({@damage 15d8}) acid damage on a failed save, or half as much damage on a successful one."]}]', '[{"name": "Detect", "entries": ["The dragon makes a Wisdom ({@skill Perception}) check."]}, {"name": "Tail Attack", "entries": ["The dragon makes a tail attack."]}, {"name": "Wing Attack (Costs 2 Actions)", "entries": ["The dragon beats its wings. Each creature within 15 feet of the dragon must succeed on a {@dc 23} Dexterity saving throw or take 15 ({@damage 2d6 + 8}) bludgeoning damage and be knocked {@condition prone}. The dragon can then fly up to half its flying speed."]}]', '[]', '["swamp"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('ancient_blue_dragon', 'Ancient Blue Dragon', 'dragon', '', 'G', 'L, E', 22, 481, '{"walk": 40, "burrow": 40, "fly": 80}', 29, 10, 27, 18, 17, 21, '23', 0, 2, '{"dex": "+7", "con": "+15", "wis": "+10", "cha": "+12"}', '{"perception": "+17", "stealth": "+7"}', '[]', '[]', '[]', '["blindsight 60 ft.", "darkvision 120 ft."]', '["Common", "Draconic"]', '[{"name": "Legendary Resistance (3/Day)", "entries": ["If the dragon fails a saving throw, it can choose to succeed instead."]}]', '[{"name": "Multiattack", "entries": ["The dragon can use its Frightful Presence. It then makes three attacks: one with its bite and two with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 16} to hit, reach 15 ft., one target. {@h}20 ({@damage 2d10 + 9}) piercing damage plus 11 ({@damage 2d10}) lightning damage."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 16} to hit, reach 10 ft., one target. {@h}16 ({@damage 2d6 + 9}) slashing damage."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 16} to hit, reach 20 ft., one target. {@h}18 ({@damage 2d8 + 9}) bludgeoning damage."]}, {"name": "Frightful Presence", "entries": ["Each creature of the dragon''s choice that is within 120 feet of the dragon and aware of it must succeed on a {@dc 20} Wisdom saving throw or become {@condition frightened} for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the dragon''s Frightful Presence for the next 24 hours."]}, {"name": "Lightning Breath {@recharge 5}", "entries": ["The dragon exhales lightning in a 120-foot line that is 10 feet wide. Each creature in that line must make a {@dc 23} Dexterity saving throw, taking 88 ({@damage 16d10}) lightning damage on a failed save, or half as much damage on a successful one."]}]', '[{"name": "Detect", "entries": ["The dragon makes a Wisdom ({@skill Perception}) check."]}, {"name": "Tail Attack", "entries": ["The dragon makes a tail attack."]}, {"name": "Wing Attack (Costs 2 Actions)", "entries": ["The dragon beats its wings. Each creature within 15 feet of the dragon must succeed on a {@dc 24} Dexterity saving throw or take 16 ({@damage 2d6 + 9}) bludgeoning damage and be knocked {@condition prone}. The dragon can then fly up to half its flying speed."]}]', '[]', '["desert", "coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('ancient_brass_dragon', 'Ancient Brass Dragon', 'dragon', '', 'G', 'C, G', 20, 297, '{"walk": 40, "burrow": 40, "fly": 80}', 27, 10, 25, 16, 15, 19, '20', 0, 2, '{"dex": "+6", "con": "+13", "wis": "+8", "cha": "+10"}', '{"history": "+9", "perception": "+14", "persuasion": "+10", "stealth": "+6"}', '[]', '[]', '[]', '["blindsight 60 ft.", "darkvision 120 ft."]', '["Common", "Draconic"]', '[{"name": "Legendary Resistance (3/Day)", "entries": ["If the dragon fails a saving throw, it can choose to succeed instead."]}]', '[{"name": "Multiattack", "entries": ["The dragon can use its Frightful Presence. It then makes three attacks: one with its bite and two with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 14} to hit, reach 15 ft., one target. {@h}19 ({@damage 2d10 + 8}) piercing damage."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 14} to hit, reach 10 ft., one target. {@h}15 ({@damage 2d6 + 8}) slashing damage."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 14} to hit, reach 20 ft., one target. {@h}17 ({@damage 2d8 + 8}) bludgeoning damage."]}, {"name": "Frightful Presence", "entries": ["Each creature of the dragon''s choice that is within 120 feet of the dragon and aware of it must succeed on a {@dc 18} Wisdom saving throw or become {@condition frightened} for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the dragon''s Frightful Presence for the next 24 hours."]}, {"name": "Breath Weapons {@recharge 5}", "entries": ["The dragon uses one of the following breath weapons:", {"type": "list", "style": "list-hang-notitle", "items": [{"type": "item", "name": "Fire Breath", "entry": "The dragon exhales fire in a 90-foot line that is 10 feet wide. Each creature in that line must make a {@dc 21} Dexterity saving throw, taking 56 ({@damage 16d6}) fire damage on a failed save, or half as much damage on a successful one."}, {"type": "item", "name": "Sleep Breath", "entry": "The dragon exhales sleep gas in a 90-foot cone. Each creature in that area must succeed on a {@dc 21} Constitution saving throw or fall {@condition unconscious} for 10 minutes. This effect ends for a creature if the creature takes damage or someone uses an action to wake it."}]}]}, {"name": "Change Shape", "entries": ["The dragon magically polymorphs into a humanoid or beast that has a challenge rating no higher than its own, or back into its true form. It reverts to its true form if it dies. Any equipment it is wearing or carrying is absorbed or borne by the new form (the dragon''s choice).", "In a new form, the dragon retains its alignment, hit points, Hit Dice, ability to speak, proficiencies, Legendary Resistance, lair actions, and Intelligence, Wisdom, and Charisma scores, as well as this action. Its statistics and capabilities are otherwise replaced by those of the new form, except any class features or legendary actions of that form."]}]', '[{"name": "Detect", "entries": ["The dragon makes a Wisdom ({@skill Perception}) check."]}, {"name": "Tail Attack", "entries": ["The dragon makes a tail attack."]}, {"name": "Wing Attack (Costs 2 Actions)", "entries": ["The dragon beats its wings. Each creature within 15 feet of the dragon must succeed on a {@dc 22} Dexterity saving throw or take 15 ({@damage 2d6 + 8}) bludgeoning damage and be knocked {@condition prone}. The dragon can then fly up to half its flying speed."]}]', '[]', '["desert"]');
