INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('brass_dragon_wyrmling', 'Brass Dragon Wyrmling', 'dragon', '', 'M', 'C, G', 16, 16, '{"walk": 30, "burrow": 15, "fly": 60}', 15, 10, 13, 10, 11, 13, '1', 0, 2, '{"dex": "+2", "con": "+3", "wis": "+2", "cha": "+3"}', '{"perception": "+4", "stealth": "+2"}', '[]', '[]', '[]', '["blindsight 10 ft.", "darkvision 60 ft."]', '["Draconic"]', '[]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}7 ({@damage 1d10 + 2}) piercing damage."]}, {"name": "Breath Weapons {@recharge 5}", "entries": ["The dragon uses one of the following breath weapons.", {"type": "list", "style": "list-hang-notitle", "items": [{"type": "item", "name": "Fire Breath", "entry": "The dragon exhales fire in a 20-foot line that is 5 feet wide. Each creature in that line must make a {@dc 11} Dexterity saving throw, taking 14 ({@damage 4d6}) fire damage on a failed save, or half as much damage on a successful one."}, {"type": "item", "name": "Sleep Breath", "entry": "The dragon exhales sleep gas in a 15-foot cone. Each creature in that area must succeed on a {@dc 11} Constitution saving throw or fall {@condition unconscious} for 1 minute. This effect ends for a creature if the creature takes damage or someone uses an action to wake it."}]}]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('bronze_dragon_wyrmling', 'Bronze Dragon Wyrmling', 'dragon', '', 'M', 'L, G', 17, 32, '{"walk": 30, "fly": 60, "swim": 30}', 17, 10, 15, 12, 11, 15, '2', 0, 2, '{"dex": "+2", "con": "+4", "wis": "+2", "cha": "+4"}', '{"perception": "+4", "stealth": "+2"}', '[]', '[]', '[]', '["blindsight 10 ft.", "darkvision 60 ft."]', '["Draconic"]', '[{"name": "Amphibious", "entries": ["The dragon can breathe air and water."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}8 ({@damage 1d10 + 3}) piercing damage."]}, {"name": "Breath Weapons {@recharge 5}", "entries": ["The dragon uses one of the following breath weapons.", {"type": "list", "style": "list-hang-notitle", "items": [{"type": "item", "name": "Lightning Breath", "entry": "The dragon exhales lightning in a 40-foot line that is 5 feet wide. Each creature in that line must make a {@dc 12} Dexterity saving throw, taking 16 ({@damage 3d10}) lightning damage on a failed save, or half as much damage on a successful one."}, {"type": "item", "name": "Repulsion Breath", "entry": "The dragon exhales repulsion energy in a 30-foot cone. Each creature in that area must succeed on a {@dc 12} Strength saving throw. On a failed save, the creature is pushed 30 feet away from the dragon."}]}]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('brown_bear', 'Brown Bear', 'beast', '', 'L', 'U', 11, 34, '{"walk": 40, "climb": 30}', 19, 10, 16, 2, 13, 7, '1', 0, 2, '{}', '{"perception": "+3"}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Keen Smell", "entries": ["The bear has advantage on Wisdom ({@skill Perception}) checks that rely on smell."]}]', '[{"name": "Multiattack", "entries": ["The bear makes two attacks: one with its bite and one with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}8 ({@damage 1d8 + 4}) piercing damage."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}11 ({@damage 2d6 + 4}) slashing damage."]}]', '[]', '[]', '["forest", "hill", "arctic"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('bugbear', 'Bugbear', 'humanoid', 'goblinoid', 'M', 'C, E', 16, 27, '{"walk": 30}', 15, 14, 13, 8, 11, 9, '1', 0, 2, '{}', '{"stealth": "+6", "survival": "+2"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Common", "Goblin"]', '[{"name": "Brute", "entries": ["A melee weapon deals one extra die of its damage when the bugbear hits with it (included in the attack)."]}, {"name": "Surprise Attack", "entries": ["If the bugbear surprises a creature and hits it with an attack during the first round of combat, the target takes an extra 7 ({@damage 2d6}) damage from the attack."]}]', '[{"name": "Morningstar", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}11 ({@damage 2d8 + 2}) piercing damage."]}, {"name": "Javelin", "entries": ["{@atk mw,rw} {@hit 4} to hit, reach 5 ft. or range 30/120 ft., one target. {@h}9 ({@damage 2d6 + 2}) piercing damage in melee or 5 ({@damage 1d6 + 2}) piercing damage at range."]}]', '[]', '[]', '["underdark", "grassland", "forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('bugbear_chief', 'Bugbear Chief', 'humanoid', 'goblinoid', 'M', 'C, E', 17, 65, '{"walk": 30}', 17, 14, 14, 11, 12, 11, '3', 0, 2, '{}', '{"intimidation": "+2", "stealth": "+6", "survival": "+3"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Common", "Goblin"]', '[{"name": "Brute", "entries": ["A melee weapon deals one extra die of its damage when the bugbear hits with it (included in the attack)."]}, {"name": "Surprise Attack", "entries": ["If the bugbear surprises a creature and hits it with an attack during the first round of combat, the target takes an extra 7 ({@damage 2d6}) damage from the attack."]}, {"name": "Heart of Hruggek", "entries": ["The bugbear has advantage on saving throws against being {@condition charmed}, {@condition frightened}, {@condition paralyzed}, {@condition poisoned}, {@condition stunned}, or put to sleep."]}]', '[{"name": "Multiattack", "entries": ["The bugbear makes two melee attacks."]}, {"name": "Morningstar", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}11 ({@damage 2d8 + 3}) piercing damage."]}, {"name": "Javelin", "entries": ["{@atk mw,rw} {@hit 5} to hit, reach 5 ft. or range 30/120 ft., one target. {@h}9 ({@damage 2d6 + 3}) piercing damage in melee or 5 ({@damage 1d6 + 3}) piercing damage at range."]}]', '[]', '[]', '["underdark", "grassland", "forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('bulette', 'Bulette', 'monstrosity', '', 'L', 'U', 17, 94, '{"walk": 40, "burrow": 40}', 19, 11, 21, 2, 10, 5, '5', 0, 2, '{}', '{"perception": "+6"}', '[]', '[]', '[]', '["darkvision 60 ft.", "tremorsense 60 ft."]', '[]', '[{"name": "Standing Leap", "entries": ["The bulette''s long jump is up to 30 feet and its high jump is up to 15 feet, with or without a running start."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}30 ({@damage 4d12 + 4}) piercing damage."]}, {"name": "Deadly Leap", "entries": ["If the bulette jumps at least 15 feet as part of its movement, it can then use this action to land on its feet in a space that contains one or more other creatures. Each of those creatures must succeed on a {@dc 16} Strength or Dexterity saving throw (target''s choice) or be knocked {@condition prone} and take 14 ({@damage 3d6 + 4}) bludgeoning damage plus 14 ({@damage 3d6 + 4}) slashing damage. On a successful save, the creature takes only half the damage, isn''t knocked {@condition prone}, and is pushed 5 feet out of the bulette''s space into an unoccupied space of the creature''s choice. If no unoccupied space is within range, the creature instead falls {@condition prone} in the bulette''s space."]}]', '[]', '[]', '["mountain", "grassland", "hill"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('bullywug', 'Bullywug', 'humanoid', 'bullywug', 'M', 'N, E', 15, 11, '{"walk": 20, "swim": 40}', 12, 12, 13, 7, 10, 7, '1/4', 0, 2, '{}', '{"stealth": "+3"}', '[]', '[]', '[]', '[]', '["Bullywug"]', '[{"name": "Amphibious", "entries": ["The bullywug can breathe air and water."]}, {"name": "Speak with Frogs and Toads", "entries": ["The bullywug can communicate simple concepts to frogs and toads when it speaks in Bullywug."]}, {"name": "Swamp Camouflage", "entries": ["The bullywug has advantage on Dexterity ({@skill Stealth}) checks made to hide in swampy terrain."]}, {"name": "Standing Leap", "entries": ["The bullywug''s long jump is up to 20 feet and its high jump is up to 10 feet, with or without a running start."]}]', '[{"name": "Multiattack", "entries": ["The bullywug makes two melee attacks: one with its bite and one with its spear."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}3 ({@damage 1d4 + 1}) bludgeoning damage."]}, {"name": "Spear", "entries": ["{@atk mw,rw} {@hit 3} to hit, reach 5 ft. or range 20/60 ft., one target. {@h}4 ({@damage 1d6 + 1}) piercing damage, or 5 ({@damage 1d8 + 1}) piercing damage if used with two hands to make a melee attack."]}]', '[]', '[]', '["swamp"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('cambion', 'Cambion', 'fiend', '', 'M', 'L, NX, C, E', 19, 82, '{"walk": 30, "fly": 60}', 18, 18, 16, 14, 12, 16, '5', 0, 2, '{"str": "+7", "con": "+6", "int": "+5", "cha": "+6"}', '{"deception": "+6", "intimidation": "+6", "perception": "+4", "stealth": "+7"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Abyssal", "Common", "Infernal"]', '[{"name": "Fiendish Blessing", "entries": ["The AC of the cambion includes its Charisma bonus."]}]', '[{"name": "Multiattack", "entries": ["The cambion makes two melee attacks or uses its Fire Ray twice."]}, {"name": "Spear", "entries": ["{@atk mw,rw} {@hit 7} to hit, reach 5 ft. or range 20/60 ft., one target. {@h}7 ({@damage 1d6 + 4}) piercing damage, or 8 ({@damage 1d8 + 4}) piercing damage if used with two hands to make a melee attack, plus 3 ({@damage 1d6}) fire damage."]}, {"name": "Fire Ray", "entries": ["{@atk rs} {@hit 7} to hit, range 120 ft., one target. {@h}10 ({@damage 3d6}) fire damage."]}, {"name": "Fiendish Charm", "entries": ["One humanoid the cambion can see within 30 feet of it must succeed on a {@dc 14} Wisdom saving throw or be magically {@condition charmed} for 1 day. The {@condition charmed} target obeys the cambion''s spoken commands. If the target suffers any harm from the cambion or another creature or receives a suicidal command from the cambion, the target can repeat the saving throw, ending the effect on itself on a success. If a target''s saving throw is successful, or if the effect ends for it, the creature is immune to the cambion''s Fiendish Charm for the next 24 hours."]}]', '[]', '[]', '["urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('camel', 'Camel', 'beast', '', 'L', 'U', 9, 15, '{"walk": 50}', 16, 8, 14, 2, 8, 5, '1/8', 0, 2, '{}', '{}', '[]', '[]', '[]', '[]', '[]', '[]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}2 ({@damage 1d4}) bludgeoning damage."]}]', '[]', '[]', '["desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('carrion_crawler', 'Carrion Crawler', 'monstrosity', '', 'L', 'U', 13, 51, '{"walk": 30, "climb": 30}', 14, 13, 16, 1, 12, 5, '2', 0, 2, '{}', '{"perception": "+3"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '[]', '[{"name": "Keen Smell", "entries": ["The carrion crawler has advantage on Wisdom ({@skill Perception}) checks that rely on smell."]}, {"name": "Spider Climb", "entries": ["The carrion crawler can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."]}]', '[{"name": "Multiattack", "entries": ["The carrion crawler makes two attacks: one with its tentacles and one with its bite."]}, {"name": "Tentacles", "entries": ["{@atk mw} {@hit 8} to hit, reach 10 ft., one creature. {@h}4 ({@damage 1d4 + 2}) poison damage, and the target must succeed on a {@dc 13} Constitution saving throw or be {@condition poisoned} for 1 minute. Until this poison ends, the target is {@condition paralyzed}. The target can repeat the saving throw at the end of each of its turns, ending the poison on itself on a success."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}7 ({@damage 2d4 + 2}) piercing damage."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('cat', 'Cat', 'beast', '', 'T', 'U', 12, 2, '{"walk": 40, "climb": 30}', 3, 15, 10, 3, 12, 7, '0', 0, 2, '{}', '{"perception": "+3", "stealth": "+4"}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Keen Smell", "entries": ["The cat has advantage on Wisdom ({@skill Perception}) checks that rely on smell."]}]', '[{"name": "Claws", "entries": ["{@atk mw} {@hit 0} to hit, reach 5 ft., one target. {@h}1 slashing damage."]}]', '[]', '[]', '["grassland", "forest", "urban", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('cave_bear', 'Cave Bear', 'beast', '', 'L', 'U', 12, 42, '{"walk": 40, "swim": 30}', 20, 10, 16, 2, 13, 7, '2', 0, 2, '{}', '{"perception": "+3"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '[]', '[{"name": "Keen Smell", "entries": ["The bear has advantage on Wisdom ({@skill Perception}) checks that rely on smell."]}]', '[{"name": "Multiattack", "entries": ["The bear makes two attacks: one with its bite and one with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}9 ({@damage 1d8 + 5}) piercing damage."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}12 ({@damage 2d6 + 5}) slashing damage."]}]', '[]', '[]', '["forest", "underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('centaur', 'Centaur', 'monstrosity', '', 'L', 'N, G', 12, 45, '{"walk": 50}', 18, 14, 14, 9, 13, 11, '2', 0, 2, '{}', '{"athletics": "+6", "perception": "+3", "survival": "+3"}', '[]', '[]', '[]', '[]', '["Elvish", "Sylvan"]', '[{"name": "Charge", "entries": ["If the centaur moves at least 30 feet straight toward a target and then hits it with a pike attack on the same turn, the target takes an extra 10 ({@damage 3d6}) piercing damage."]}]', '[{"name": "Multiattack", "entries": ["The centaur makes two attacks: one with its pike and one with its hooves or two with its longbow."]}, {"name": "Pike", "entries": ["{@atk mw} {@hit 6} to hit, reach 10 ft., one target. {@h}9 ({@damage 1d10 + 4}) piercing damage."]}, {"name": "Hooves", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}11 ({@damage 2d6 + 4}) bludgeoning damage."]}, {"name": "Longbow", "entries": ["{@atk rw} {@hit 4} to hit, range 150/600 ft., one target. {@h}6 ({@damage 1d8 + 2}) piercing damage."]}]', '[]', '[]', '["grassland", "forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('chain_devil', 'Chain Devil', 'fiend', 'devil', 'M', 'L, E', 16, 85, '{"walk": 30}', 18, 15, 18, 11, 12, 14, '8', 0, 2, '{"con": "+7", "wis": "+4", "cha": "+5"}', '{}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Infernal", "telepathy 120 ft."]', '[{"name": "Devil''s Sight", "entries": ["Magical darkness doesn''t impede the devil''s darkvision."]}, {"name": "Magic Resistance", "entries": ["The devil has advantage on saving throws against spells and other magical effects."]}]', '[{"name": "Multiattack", "entries": ["The devil makes two attacks with its chains."]}, {"name": "Chain", "entries": ["{@atk mw} {@hit 8} to hit, reach 10 ft., one target. {@h}11 ({@damage 2d6 + 4}) slashing damage. The target is {@condition grappled} (escape {@dc 14}) if the devil isn''t already grappling a creature. Until this grapple ends, the target is {@condition restrained} and takes 7 ({@damage 2d6}) piercing damage at the start of each of its turns."]}, {"name": "Animate Chains (Recharges after a Short or Long Rest)", "entries": ["Up to four chains the devil can see within 60 feet of it magically sprout razor-edged barbs and animate under the devil''s control, provided that the chains aren''t being worn or carried.", "Each animated chain is an object with AC 20, 20 hit points, resistance to piercing damage, and immunity to psychic and thunder damage. When the devil uses Multiattack on its turn, it can use each animated chain to make one additional chain attack. An animated chain can grapple one creature of its own but can''t make attacks while grappling. An animated chain reverts to its inanimate state if reduced to 0 hit points or if the devil is {@condition incapacitated} or dies."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('chasme', 'Chasme', 'fiend', 'demon', 'L', 'C, E', 15, 84, '{"walk": 20, "fly": 60}', 15, 15, 12, 11, 14, 10, '6', 0, 2, '{"dex": "+5", "wis": "+5"}', '{"perception": "+5"}', '[]', '[]', '[]', '["blindsight 10 ft.", "darkvision 120 ft."]', '["Abyssal", "telepathy 120 ft."]', '[{"name": "Drone", "entries": ["The chasme produces a horrid droning sound to which demons are immune. Any other creature that starts its turn with in 30 feet of the chasme must succeed on a {@dc 12} Constitution saving throw or fall {@condition unconscious} for 10 minutes. A creature that can''t hear the drone automatically succeeds on the save. The effect on the creature ends if it takes damage or if another creature takes an action to splash it with holy water. If a creature''s saving throw is successful or the effect ends for it, it is immune to the drone for the next 24 hours."]}, {"name": "Magic Resistance", "entries": ["The chasme has advantage on saving throws against spells and other magical effects."]}, {"name": "Spider Climb", "entries": ["The chasme can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."]}]', '[{"name": "Proboscis", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one creature. {@h}16 ({@damage 4d6 + 2}) piercing damage plus 24 ({@damage 7d6}) necrotic damage, and the target''s hit point maximum is reduced by an amount equal to the necrotic damage taken. If this effect reduces a creature''s hit point maximum to 0, the creature dies. This reduction to a creature''s hit point maximum lasts until the creature finishes a long rest or until it is affected by a spell like  {@spell greater restoration}."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('chimera', 'Chimera', 'monstrosity', '', 'L', 'C, E', 14, 114, '{"walk": 30, "fly": 60}', 19, 11, 19, 3, 14, 10, '6', 0, 2, '{}', '{"perception": "+8"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["understands Draconic but can''t speak"]', '[]', '[{"name": "Multiattack", "entries": ["The chimera makes three attacks: one with its bite, one with its horns, and one with its claws. When its fire breath is available, it can use the breath in place of its bite or horns."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}11 ({@damage 2d6 + 4}) piercing damage."]}, {"name": "Horns", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}10 ({@damage 1d12 + 4}) bludgeoning damage."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}11 ({@damage 2d6 + 4}) slashing damage."]}, {"name": "Fire Breath {@recharge 5}", "entries": ["The dragon head exhales fire in a 15-foot cone. Each creature in that area must make a {@dc 15} Dexterity saving throw, taking 31 ({@damage 7d8}) fire damage on a failed save, or half as much damage on a successful one."]}]', '[]', '[]', '["underdark", "mountain", "grassland", "hill"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('chuul', 'Chuul', 'aberration', '', 'L', 'C, E', 16, 93, '{"walk": 30, "swim": 30}', 19, 10, 16, 5, 11, 5, '4', 0, 2, '{}', '{"perception": "+4"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["understands Deep Speech but can''t speak"]', '[{"name": "Amphibious", "entries": ["The chuul can breathe air and water."]}, {"name": "Sense Magic", "entries": ["The chuul senses magic within 120 feet of it at will. This trait otherwise works like the {@spell detect magic} spell but isn''t itself magical."]}]', '[{"name": "Multiattack", "entries": ["The chuul makes two pincer attacks. If the chuul is grappling a creature, the chuul can also use its tentacles once."]}, {"name": "Pincer", "entries": ["{@atk mw} {@hit 6} to hit, reach 10 ft., one target. {@h}11 ({@damage 2d6 + 4}) bludgeoning damage. The target is {@condition grappled} (escape {@dc 14}) if it is a Large or smaller creature and the chuul doesn''t have two other creatures {@condition grappled}."]}, {"name": "Tentacles", "entries": ["One creature {@condition grappled} by the chuul must succeed on a {@dc 13} Constitution saving throw or be {@condition poisoned} for 1 minute. Until this poison ends, the target is {@condition paralyzed}. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('clay_golem', 'Clay Golem', 'construct', '', 'L', 'U', 14, 133, '{"walk": 20}', 20, 9, 18, 3, 8, 1, '9', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["understands the languages of its creator but can''t speak"]', '[{"name": "Acid Absorption", "entries": ["Whenever the golem is subjected to acid damage, it takes no damage and instead regains a number of hit points equal to the acid damage dealt."]}, {"name": "Berserk", "entries": ["Whenever the golem starts its turn with 60 hit points or fewer, roll a {@dice d6}. On a 6, the golem goes berserk. On each of its turns while berserk, the golem attacks the nearest creature it can see. If no creature is near enough to move to and attack, the golem attacks an object, with preference for an object smaller than itself. Once the golem goes berserk, it continues to do so until it is destroyed or regains all its hit points."]}, {"name": "Immutable Form", "entries": ["The golem is immune to any spell or effect that would alter its form."]}, {"name": "Magic Resistance", "entries": ["The golem has advantage on saving throws against spells and other magical effects."]}, {"name": "Magic Weapons", "entries": ["The golem''s weapon attacks are magical."]}]', '[{"name": "Multiattack", "entries": ["The golem makes two slam attacks."]}, {"name": "Slam", "entries": ["{@atk mw} {@hit 8} to hit, reach 5 ft., one target. {@h}16 ({@damage 2d10 + 5}) bludgeoning damage. If the target is a creature, it must succeed on a {@dc 15} Constitution saving throw or have its hit point maximum reduced by an amount equal to the damage taken. The target dies if this attack reduces its hit point maximum to 0. The reduction lasts until removed by the  {@spell greater restoration} spell or other magic."]}, {"name": "Haste {@recharge 5}", "entries": ["Until the end of its next turn, the golem magically gains a +2 bonus to its AC, has advantage on Dexterity saving throws, and can use its slam attack as a bonus action."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('cloaker', 'Cloaker', 'aberration', '', 'L', 'C, N', 14, 78, '{"walk": 10, "fly": 40}', 17, 15, 12, 13, 12, 14, '8', 0, 2, '{}', '{"stealth": "+5"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Deep Speech", "Undercommon"]', '[{"name": "Damage Transfer", "entries": ["While attached to a creature, the cloaker takes only half the damage dealt to it (rounded down). and that creature takes the other half."]}, {"name": "False Appearance", "entries": ["While the cloaker remains motionless without its underside exposed, it is indistinguishable from a dark leather cloak."]}, {"name": "Light Sensitivity", "entries": ["While in bright light, the cloaker has disadvantage on attack rolls and Wisdom ({@skill Perception}) checks that rely on sight."]}]', '[{"name": "Multiattack", "entries": ["The cloaker makes two attacks: one with its bite and one with its tail."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one creature. {@h}10 ({@damage 2d6 + 3}) piercing damage, and if the target is Large or smaller, the cloaker attaches to it. If the cloaker has advantage against the target, the cloaker attaches to the target''s head, and the target is {@condition blinded} and unable to breathe while the cloaker is attached. While attached, the cloaker can make this attack only against the target and has advantage on the attack roll. The cloaker can detach itself by spending 5 feet of its movement. A creature, including the target, can take its action to detach the cloaker by succeeding on a {@dc 16} Strength check."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 6} to hit, reach 10 ft., one creature. {@h}7 ({@damage 1d8 + 3}) slashing damage."]}, {"name": "Moan", "entries": ["Each creature within 60 feet of the cloaker that can hear its moan and that isn''t an aberration must succeed on a {@dc 13} Wisdom saving throw or become {@condition frightened} until the end of the cloaker''s next turn. If a creature''s saving throw is successful, the creature is immune to the cloaker''s moan for the next 24 hours."]}, {"name": "Phantasms (Recharges after a Short or Long Rest)", "entries": ["The cloaker magically creates three illusory duplicates of itself if it isn''t in bright light. The duplicates move with it and mimic its actions, shifting position so as to make it impossible to track which cloaker is the real one. If the cloaker is ever in an area of bright light, the duplicates disappear.", "Whenever any creature targets the cloaker with an attack or a harmful spell while a duplicate remains, that creature rolls randomly to determine whether it targets the cloaker or one of the duplicates. A creature is unaffected by this magical effect if it can''t see or if it relies on senses other than sight.", "A duplicate has the cloaker''s AC and uses its saving throws. If an attack hits a duplicate, or if a duplicate fails a saving throw against an effect that deals damage, the duplicate disappears."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('cloud_giant', 'Cloud Giant', 'giant', '', 'H', '[''N'', ''G''], [''N'', ''E'']', 14, 200, '{"walk": 40}', 27, 10, 22, 12, 16, 16, '9', 0, 2, '{"con": "+10", "wis": "+7", "cha": "+7"}', '{"insight": "+7", "perception": "+7"}', '[]', '[]', '[]', '[]', '["Common", "Giant"]', '[{"name": "Keen Smell", "entries": ["The giant has advantage on Wisdom ({@skill Perception}) checks that rely on smell."]}]', '[{"name": "Multiattack", "entries": ["The giant makes two morningstar attacks."]}, {"name": "Morningstar", "entries": ["{@atk mw} {@hit 12} to hit, reach 10 ft., one target. {@h}21 ({@damage 3d8 + 8}) piercing damage."]}, {"name": "Rock", "entries": ["{@atk rw} {@hit 12} to hit, range 60/240 ft., one target. {@h}30 ({@damage 4d10 + 8}) bludgeoning damage."]}]', '[]', '[]', '["mountain"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('cockatrice', 'Cockatrice', 'monstrosity', '', 'S', 'U', 11, 22, '{"walk": 20, "fly": 40}', 6, 12, 12, 2, 13, 5, '1/2', 0, 2, '{}', '{}', '[]', '[]', 'Petrified', '["darkvision 60 ft."]', '[]', '[]', '[{"name": "Petrifying Bite", "entries": ["Melee Attack Roll: +3, reach 5 ft. Hit: 3 (1d4 + 1) Piercing damage. If the target is a creature: Constitution Saving Throw DC 11. First Failure: Target has Restrained condition. Target repeats save at end of next turn if still Restrained, ending effect on success. Second Failure: Target has Petrified condition for 24 hours."]}]', '[]', '[]', '["grassland"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('commoner', 'Commoner', 'humanoid', 'any race', 'M', 'A', 10, 4, '{"walk": 30}', 10, 10, 10, 10, 10, 10, '0', 0, 2, '{}', '{}', '[]', '[]', '[]', '[]', '["any one language (usually Common)"]', '[]', '[{"name": "Club", "entries": ["{@atk mw} {@hit 2} to hit, reach 5 ft., one target. {@h}2 ({@damage 1d4}) bludgeoning damage."]}]', '[]', '[]', '["arctic", "desert", "coastal", "grassland", "hill", "urban", "forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('constrictor_snake', 'Constrictor Snake', 'beast', '', 'L', 'U', 12, 13, '{"walk": 30, "swim": 30}', 15, 14, 12, 1, 10, 3, '1/4', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 10 ft."]', '[]', '[]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one creature. {@h}5 ({@damage 1d6 + 2}) piercing damage."]}, {"name": "Constrict", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one creature. {@h}6 ({@damage 1d8 + 2}) bludgeoning damage, and the target is {@condition grappled} (escape {@dc 14}). Until this grapple ends, the creature is {@condition restrained}, and the snake can''t constrict another target."]}]', '[]', '[]', '["underwater", "forest", "swamp", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('copper_dragon_wyrmling', 'Copper Dragon Wyrmling', 'dragon', '', 'M', 'C, G', 16, 22, '{"walk": 30, "climb": 30, "fly": 60}', 15, 12, 13, 14, 11, 13, '1', 0, 2, '{"dex": "+3", "con": "+3", "wis": "+2", "cha": "+3"}', '{"perception": "+4", "stealth": "+3"}', '[]', '[]', '[]', '["blindsight 10 ft.", "darkvision 60 ft."]', '["Draconic"]', '[]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}7 ({@damage 1d10 + 2}) piercing damage."]}, {"name": "Breath Weapons {@recharge 5}", "entries": ["The dragon uses one of the following breath weapons.", {"type": "list", "style": "list-hang-notitle", "items": [{"type": "item", "name": "Acid Breath", "entry": "The dragon exhales acid in a 20-foot line that is 5 feet wide. Each creature in that line must make a {@dc 11} Dexterity saving throw, taking 18 ({@damage 4d8}) acid damage on a failed save, or half as much damage on a successful one."}, {"type": "item", "name": "Slowing Breath", "entry": "The dragon exhales gas in a 15-foot cone. Each creature in that area must succeed on a {@dc 11} Constitution saving throw. On a failed save, the creature can''t use reactions, its speed is halved, and it can''t make more than one attack on its turn. In addition, the creature can use either an action or a bonus action on its turn, but not both. These effects last for 1 minute. The creature can repeat the saving throw at the end of each of its turns, ending the effect on itself with a successful save."}]}]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('couatl', 'Couatl', 'celestial', '', 'M', 'L, G', 19, 97, '{"walk": 30, "fly": 90}', 16, 20, 17, 18, 20, 18, '4', 0, 2, '{"con": "+5", "wis": "+7", "cha": "+6"}', '{}', '[]', '[]', '[]', '["truesight 120 ft."]', '["all", "telepathy 120 ft."]', '[{"name": "Magic Weapons", "entries": ["The couatl''s weapon attacks are magical."]}, {"name": "Shielded Mind", "entries": ["The couatl is immune to scrying and to any effect that would sense its emotions, read its thoughts, or detect its location."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 8} to hit, reach 5 ft., one creature. {@h}8 ({@damage 1d6 + 5}) piercing damage, and the target must succeed on a {@dc 13} Constitution saving throw or be {@condition poisoned} for 24 hours. Until this poison ends, the target is {@condition unconscious}. Another creature can use an action to shake the target awake."]}, {"name": "Constrict", "entries": ["{@atk mw} {@hit 6} to hit, reach 10 ft., one Medium or smaller creature. {@h}10 ({@damage 2d6 + 3}) bludgeoning damage, and the target is {@condition grappled} (escape {@dc 15}). Until this grapple ends, the target is {@condition restrained}, and the couatl can''t constrict another target."]}, {"name": "Change Shape", "entries": ["The couatl magically polymorphs into a humanoid or beast that has a challenge rating equal to or less than its own, or back into its true form. It reverts to its true form if it dies. Any equipment it is wearing or carrying is absorbed or borne by the new form (the couatl''s choice).", "In a new form, the couatl retains its game statistics and ability to speak, but its AC, movement modes, Strength, Dexterity, and other actions are replaced by those of the new form, and it gains any statistics and capabilities (except class features, legendary actions, and lair actions) that the new form has but that it lacks. If the new form has a bite attack, the couatl can use its bite in that form."]}]', '[]', '[]', '["grassland", "forest", "urban", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('crab', 'Crab', 'beast', '', 'T', 'U', 11, 2, '{"walk": 20, "swim": 20}', 2, 11, 10, 1, 8, 2, '0', 0, 2, '{}', '{"stealth": "+2"}', '[]', '[]', '[]', '["blindsight 30 ft."]', '[]', '[{"name": "Amphibious", "entries": ["The crab can breathe air and water."]}]', '[{"name": "Claw", "entries": ["{@atk mw} {@hit 0} to hit, reach 5 ft., one target. {@h}1 bludgeoning damage."]}]', '[]', '[]', '["coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('crawling_claw', 'Crawling Claw', 'undead', '', 'T', 'N, E', 12, 2, '{"walk": 20, "climb": 20}', 13, 14, 11, 5, 10, 4, '0', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 30 ft. (blind beyond this radius)"]', '["understands Common but can''t speak"]', '[{"name": "Turn Immunity", "entries": ["The claw is immune to effects that turn undead."]}]', '[{"name": "Claw", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}3 ({@damage 1d4 + 1}) bludgeoning or slashing damage (claw''s choice)."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('crocodile', 'Crocodile', 'beast', '', 'L', 'U', 12, 19, '{"walk": 20, "swim": 30}', 15, 10, 13, 2, 10, 5, '1/2', 0, 2, '{}', '{"stealth": "+2"}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Hold Breath", "entries": ["The crocodile can hold its breath for 15 minutes."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one creature. {@h}7 ({@damage 1d10 + 2}) piercing damage, and the target is {@condition grappled} (escape {@dc 12}). Until this grapple ends, the target is {@condition restrained}, and the crocodile can''t bite another target"]}]', '[]', '[]', '["swamp", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('cult_fanatic', 'Cult Fanatic', 'humanoid', 'any race', 'M', 'L, NX, C, NY, E', 13, 33, '{"walk": 30}', 11, 14, 12, 10, 13, 14, '2', 0, 2, '{}', '{"deception": "+4", "persuasion": "+4", "religion": "+2"}', '[]', '[]', '[]', '[]', '["any one language (usually Common)"]', '[{"name": "Dark Devotion", "entries": ["The fanatic has advantage on saving throws against being {@condition charmed} or {@condition frightened}."]}]', '[{"name": "Multiattack", "entries": ["The fanatic makes two melee attacks."]}, {"name": "Dagger", "entries": ["{@atk mw,rw} {@hit 4} to hit, reach 5 ft. or range 20/60 ft., one creature. {@h}4 ({@damage 1d4 + 2}) piercing damage."]}]', '[]', '[]', '["urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('cultist', 'Cultist', 'humanoid', 'any race', 'M', 'L, NX, C, NY, E', 12, 9, '{"walk": 30}', 11, 12, 10, 10, 11, 10, '1/8', 0, 2, '{}', '{"deception": "+2", "religion": "+2"}', '[]', '[]', '[]', '[]', '["any one language (usually Common)"]', '[{"name": "Dark Devotion", "entries": ["The cultist has advantage on saving throws against being {@condition charmed} or {@condition frightened}."]}]', '[{"name": "Scimitar", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one creature. {@h}4 ({@damage 1d6 + 1}) slashing damage."]}]', '[]', '[]', '["urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('cyclops', 'Cyclops', 'giant', '', 'H', 'C, N', 14, 138, '{"walk": 30}', 22, 11, 20, 8, 6, 10, '6', 0, 2, '{}', '{}', '[]', '[]', '[]', '[]', '["Giant"]', '[{"name": "Poor Depth Perception", "entries": ["The cyclops has disadvantage on any attack roll against a target more than 30 feet away."]}]', '[{"name": "Multiattack", "entries": ["The cyclops makes two greatclub attacks."]}, {"name": "Greatclub", "entries": ["{@atk mw} {@hit 9} to hit, reach 10 ft., one target. {@h}19 ({@damage 3d8 + 6}) bludgeoning damage."]}, {"name": "Rock", "entries": ["{@atk rw} {@hit 9} to hit, range 30/120 ft., one target. {@h}28 ({@damage 4d10 + 6}) bludgeoning damage."]}]', '[]', '[]', '["underdark", "mountain", "grassland", "hill", "desert", "coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('dao', 'Dao', 'elemental', '', 'L', 'N, E', 18, 187, '{"walk": 30, "burrow": 30, "fly": 30}', 23, 12, 24, 12, 13, 14, '11', 0, 2, '{"int": "+5", "wis": "+5", "cha": "+6"}', '{}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Terran"]', '[{"name": "Earth Glide", "entries": ["The dao can burrow through nonmagical, unworked earth and stone. While doing so, the dao doesn''t disturb the material it moves through."]}, {"name": "Elemental Demise", "entries": ["If the dao dies, its body disintegrates into crystalline powder, leaving behind only equipment the dao was wearing or carrying."]}, {"name": "Sure-Footed", "entries": ["The dao has advantage on Strength and Dexterity saving throws made against effects that would knock it {@condition prone}."]}]', '[{"name": "Multiattack", "entries": ["The Dao makes two fist attacks or two maul attacks."]}, {"name": "Fist", "entries": ["{@atk mw} {@hit 10} to hit, reach 5 ft., one target. {@h}15 ({@damage 2d8 + 6}) bludgeoning damage."]}, {"name": "Maul", "entries": ["{@atk mw} {@hit 10} to hit, reach 5 ft., one target. {@h}20 ({@damage 4d6 + 6}) bludgeoning damage. If the target is a Huge or smaller creature, it must succeed on a {@dc 18} Strength check or be knocked {@condition prone}."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('darkmantle', 'Darkmantle', 'monstrosity', '', 'S', 'U', 11, 22, '{"walk": 10, "fly": 30}', 16, 12, 13, 2, 10, 5, '1/2', 0, 2, '{}', '{"stealth": "+3"}', '[]', '[]', '[]', '["blindsight 60 ft."]', '[]', '[{"name": "Echolocation", "entries": ["The darkmantle can''t use its blindsight while {@condition deafened}."]}, {"name": "False Appearance", "entries": ["While the darkmantle remains motionless, it is indistinguishable from a cave formation such as a stalactite or stalagmite."]}]', '[{"name": "Crush", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one creature. {@h}6 ({@damage 1d6 + 3}) bludgeoning damage, and the darkmantle attaches to the target. If the target is Medium or smaller and the darkmantle has advantage on the attack roll, it attaches by engulfing the target''s head, and the target is also {@condition blinded} and unable to breathe while the darkmantle is attached in this way.", "While attached to the target, the darkmantle can attack no other creature except the target but has advantage on its attack rolls. The darkmantle''s speed also becomes 0, it can''t benefit from any bonus to its speed, and it moves with the target.", "A creature can detach the darkmantle by making a successful {@dc 13} Strength check as an action. On its turn, the darkmantle can detach itself from the target by using 5 feet of movement."]}, {"name": "Darkness Aura (1/Day)", "entries": ["A 15-foot radius of magical darkness extends out from the darkmantle, moves with it, and spreads around corners. The darkness lasts as long as the darkmantle maintains {@status concentration}, up to 10 minutes (as if {@status concentration||concentrating} on a spell). Darkvision can''t penetrate this darkness, and no natural light can illuminate it. If any of the darkness overlaps with an area of light created by a spell of 2nd level or lower, the spell creating the light is dispelled."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('death_dog', 'Death Dog', 'monstrosity', '', 'M', 'N, E', 12, 39, '{"walk": 40}', 15, 14, 14, 3, 13, 6, '1', 0, 2, '{}', '{"perception": "+5", "stealth": "+4"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '[]', '[{"name": "Two-Headed", "entries": ["The dog has advantage on Wisdom ({@skill Perception}) checks and on saving throws against being {@condition blinded}, {@condition charmed}, {@condition deafened}, {@condition frightened}, {@condition stunned}, or knocked {@condition unconscious}."]}]', '[{"name": "Multiattack", "entries": ["The dog makes two bite attacks."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage. If the target is a creature, it must succeed on a {@dc 12} Constitution saving throw against disease or become {@condition poisoned} until the disease is cured. Every 24 hours that elapse, the creature must repeat the saving throw, reducing its hit point maximum by 5 ({@dice 1d10}) on a failure. This reduction lasts until the disease is cured. The creature dies if the disease reduces its hit point maximum to 0."]}]', '[]', '[]', '["desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('death_knight', 'Death Knight', 'undead', '', 'M', 'C, E', 20, 180, '{"walk": 30}', 20, 11, 20, 12, 16, 18, '17', 0, 2, '{"dex": "+6", "wis": "+9", "cha": "+10"}', '{}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Abyssal", "Common"]', '[{"name": "Magic Resistance", "entries": ["The death knight has advantage on saving throws against spells and other magical effects."]}, {"name": "Marshal Undead", "entries": ["Unless the death knight is {@condition incapacitated}, it and undead creatures of its choice within 60 feet of it have advantage on saving throws against features that turn undead."]}]', '[{"name": "Multiattack", "entries": ["The death knight makes three longsword attacks."]}, {"name": "Longsword", "entries": ["{@atk mw} {@hit 11} to hit, reach 5 ft., one target. {@h}9 ({@damage 1d8 + 5}) slashing damage, or 10 ({@damage 1d10 + 5}) slashing damage if used with two hands, plus 18 ({@damage 4d8}) necrotic damage."]}, {"name": "Hellfire Orb (1/Day)", "entries": ["The death knight hurls a magical ball of fire that explodes at a point it can see within 120 feet of it. Each creature in a 20-foot-radius sphere centered on that point must make a {@dc 18} Dexterity saving throw. The sphere spreads around corners. A creature takes 35 ({@damage 10d6}) fire damage and 35 ({@damage 10d6}) necrotic damage on a failed save, or half as much damage on a successful one."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('death_slaad', 'Death Slaad', 'aberration', 'shapechanger', 'M', 'C, E', 18, 170, '{"walk": 30}', 20, 15, 19, 15, 10, 16, '10', 0, 2, '{}', '{"arcana": "+6", "perception": "+8"}', '[]', '[]', '[]', '["blindsight 60 ft.", "darkvision 60 ft."]', '["Slaad", "telepathy 60 ft."]', '[{"name": "Shapechanger", "entries": ["The slaad can use its action to polymorph into a Small or Medium humanoid, or back into its true form. Its statistics, other than its size, are the same in each form. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies."]}, {"name": "Magic Resistance", "entries": ["The slaad has advantage on saving throws against spells and other magical effects."]}, {"name": "Magic Weapons", "entries": ["The slaad''s weapon attacks are magical."]}, {"name": "Regeneration", "entries": ["The slaad regains 10 hit points at the start of its turn if it has at least 1 hit point."]}]', '[{"name": "Multiattack", "entries": ["The slaad makes three attacks: one with its bite and two with its claws or greatsword."]}, {"name": "Bite (Slaad Form Only)", "entries": ["{@atk mw} {@hit 9} to hit, reach 5 ft., one target. {@h}9 ({@damage 1d8 + 5}) piercing damage plus 7 ({@damage 2d6}) necrotic damage."]}, {"name": "Claws (Slaad Form Only)", "entries": ["{@atk mw} {@hit 9} to hit, reach 5 ft., one target. {@h}10 ({@damage 1d10 + 5}) slashing damage plus 7 ({@damage 2d6}) necrotic damage."]}, {"name": "Greatsword", "entries": ["{@atk mw} {@hit 9} to hit, reach 5 ft., one target. {@h}12 ({@damage 2d6 + 5}) slashing damage plus 7 ({@damage 2d6}) necrotic damage."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('death_tyrant', 'Death Tyrant', 'undead', '', 'L', 'L, E', 19, 187, '{"walk": 0, "fly": {"number": 20, "condition": "(hover)"}, "canHover": true}', 10, 14, 14, 19, 15, 19, '{''cr'': ''14'', ''lair'': ''15''}', 0, 2, '{"str": "+5", "con": "+7", "int": "+9", "wis": "+7", "cha": "+9"}', '{"perception": "+12"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Deep Speech", "Undercommon"]', '[{"name": "Negative Energy Cone", "entries": ["The death tyrant''s central eye emits an {@condition invisible}, magical 150-foot cone of negative energy. At the start of each of its turns, the tyrant decides which way the cone faces and whether the cone is active.", "Any creature in that area can''t regain hit points. Any humanoid that dies there becomes a {@creature zombie} under the tyrant''s command. The dead humanoid retains its place in the initiative order and animates at the start of its next turn, provided that its body hasn''t been completely destroyed."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}14 ({@damage 4d6}) piercing damage."]}, {"name": "Eye Rays", "entries": ["The death tyrant shoots three of the following magical eye rays at random (reroll duplicates), choosing one to three targets it can see within 120 feet of it:", {"type": "list", "style": "list-hang-notitle", "items": [{"type": "item", "name": "1. Charm Ray", "style": "italic", "entry": "The targeted creature must succeed on a {@dc 17} Wisdom saving throw or be {@condition charmed} by the death tyrant for 1 hour, or until the death tyrant harms the creature."}, {"type": "item", "name": "2. Paralyzing Ray", "style": "italic", "entry": "The targeted creature must succeed on a {@dc 17} Constitution saving throw or be {@condition paralyzed} for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."}, {"type": "item", "name": "3. Fear Ray", "style": "italic", "entry": "The targeted creature must succeed on a {@dc 17} Wisdom saving throw or be {@condition frightened} for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."}, {"type": "item", "name": "4. Slowing Ray", "style": "italic", "entry": "The targeted creature must succeed on a {@dc 17} Dexterity saving throw. On a failed save, the target''s speed is halved for 1 minute. In addition, the creature can''t take reactions, and it can take either an action or a bonus action on its turn, not both. The creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."}, {"type": "item", "name": "5. Enervation Ray", "style": "italic", "entry": "The targeted creature must make a {@dc 17} Constitution saving throw, taking 36 ({@damage 8d8}) necrotic damage on a failed save, or half as much damage on a successful one."}, {"type": "item", "name": "6. Telekinetic Ray", "style": "italic", "entries": ["If the target is a creature, it must succeed on a {@dc 17} Strength saving throw or the death tyrant moves it up to 30 feet in any direction. It is {@condition restrained} by the ray''s telekinetic grip until the start of the death tyrant''s next turn or until the death tyrant is {@condition incapacitated}.", "If the target is an object weighing 300 pounds or less that isn''t being worn or carried, it is moved up to 30 feet in any direction. The death tyrant can also exert fine control on objects with this ray, such as manipulating a simple tool or opening a door or a container."]}, {"type": "item", "name": "7. Sleep Ray", "style": "italic", "entry": "The targeted creature must succeed on a {@dc 17} Wisdom saving throw or fall asleep and remain {@condition unconscious} for 1 minute. The target awakens if it takes damage or another creature takes an action to wake it. This ray has no effect on constructs and undead."}, {"type": "item", "name": "8. Petrification Ray", "style": "italic", "entry": "The targeted creature must make a {@dc 17} Dexterity saving throw. On a failed save, the creature begins to turn to stone and is {@condition restrained}. It must repeat the saving throw at the end of its next turn. On a success, the effect ends. On a failure, the creature is {@condition petrified} until freed by the  {@spell greater restoration} spell or other magic."}, {"type": "item", "name": "9. Disintegration Ray", "style": "italic", "entries": ["If the target is a creature, it must succeed on a {@dc 17} Dexterity saving throw or take 45 ({@damage 10d8}) force damage. If this damage reduces the creature to 0 hit points, its body becomes a pile of fine gray dust.", "If the target is a Large or smaller nonmagical object or creation of magical force, it is disintegrated without a saving throw. If the target is a Huge or larger object or creation of magical force, this ray disintegrates a 10-foot cube of it."]}, {"type": "item", "name": "10. Death Ray", "style": "italic", "entry": "The targeted creature must succeed on a {@dc 17} Dexterity saving throw or take 55 ({@damage 10d10}) necrotic damage. The target dies if the ray reduces it to 0 hit points."}]}]}]', '[{"name": "Eye Ray", "entries": ["The death tyrant uses one random eye ray."]}]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('deep_gnome_(svirfneblin)', 'Deep Gnome (Svirfneblin)', 'humanoid', 'gnome', 'S', 'N, G', 15, 16, '{"walk": 20}', 15, 14, 14, 12, 10, 9, '1/2', 0, 2, '{}', '{"investigation": "+3", "perception": "+2", "stealth": "+4"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Gnomish", "Terran", "Undercommon"]', '[{"name": "Stone Camouflage", "entries": ["The gnome has advantage on Dexterity ({@skill Stealth}) checks made to hide in rocky terrain."]}, {"name": "Gnome Cunning", "entries": ["The gnome has advantage on Intelligence, Wisdom, and Charisma saving throws against magic."]}]', '[{"name": "War Pick", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}6 ({@damage 1d8 + 2}) piercing damage."]}, {"name": "Poisoned Dart", "entries": ["{@atk rw} {@hit 4} to hit, range 30/120 ft., one creature. {@h}4 ({@damage 1d4 + 2}) piercing damage, and the target must succeed on a {@dc 12} Constitution saving throw or be {@condition poisoned} for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success"]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('deer', 'Deer', 'beast', '', 'M', 'U', 13, 4, '{"walk": 50}', 11, 16, 11, 2, 14, 5, '0', 0, 2, '{}', '{}', '[]', '[]', '[]', '[]', '[]', '[]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 2} to hit, reach 5 ft., one target. {@h}2 ({@damage 1d4}) piercing damage."]}]', '[]', '[]', '["grassland", "forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('demilich', 'Demilich', 'undead', '', 'T', 'N, E', 20, 80, '{"walk": 0, "fly": {"number": 30, "condition": "(hover)"}, "canHover": true}', 1, 20, 10, 20, 17, 20, '{''cr'': ''18'', ''lair'': ''20''}', 0, 2, '{"con": "+6", "int": "+11", "wis": "+9", "cha": "+11"}', '{}', '[]', '[]', '[]', '["truesight 120 ft."]', '[]', '[{"name": "Avoidance", "entries": ["If the demilich is subjected to an effect that allows it to make a saving throw to take only half damage, it instead takes no damage if it succeeds on the saving throw, and only half damage if it fails."]}, {"name": "Legendary Resistance (3/Day)", "entries": ["If the demilich fails a saving throw, it can choose to succeed instead."]}, {"name": "Turn Immunity", "entries": ["The demilich is immune to effects that turn undead."]}]', '[{"name": "Howl {@recharge 5}", "entries": ["The demilich emits a bloodcurdling howl. Each creature within 30 feet of the demilich that can hear the howl must succeed on a {@dc 15} Constitution saving throw or drop to 0 hit points. On a successful save, the creature is {@condition frightened} until the end of its next turn."]}, {"name": "Life Drain", "entries": ["The demilich targets up to three creatures that it can see within 10 feet of it. Each target must succeed on a {@dc 19} Constitution saving throw or take 21 ({@damage 6d6}) necrotic damage, and the demilich regains hit points equal to the total damage dealt to all targets."]}]', '[{"name": "Flight", "entries": ["The demilich flies up to half its flying speed."]}, {"name": "Cloud of Dust", "entries": ["The demilich magically swirls its dusty remains. Each creature within 10 feet of the demilich, including around a corner, must succeed on a {@dc 15} Constitution saving throw or be {@condition blinded} until the end of the demilich''s next turn. A creature that succeeds on the saving throw is immune to this effect until the end of the demilich''s next turn."]}, {"name": "Energy Drain (Costs 2 Actions)", "entries": ["Each creature with in 30 feet of the demilich must make a {@dc 15} Constitution saving throw. On a failed save, the creature''s hit point maximum is magically reduced by 10 ({@dice 3d6}). If a creature''s hit point maximum is reduced to 0 by this effect, the creature dies. A creature''s hit point maximum can be restored with the  {@spell greater restoration} spell or similar magic."]}, {"name": "Vile Curse (Costs 3 Actions)", "entries": ["The demilich targets one creature it can see within 30 feet of it. The target must succeed on a {@dc 15} Wisdom saving throw or be magically cursed. Until the curse ends, the target has disadvantage on attack rolls and saving throws. The target can repeat the saving throw at the end of each of its turns, ending the curse on a success."]}]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('deva', 'Deva', 'celestial', '', 'M', 'L, G', 17, 136, '{"walk": 30, "fly": 90}', 18, 18, 18, 17, 20, 20, '10', 0, 2, '{"wis": "+9", "cha": "+9"}', '{"insight": "+9", "perception": "+9"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["all", "telepathy 120 ft."]', '[{"name": "Angelic Weapons", "entries": ["The deva''s weapon attacks are magical. When the deva hits with any weapon, the weapon deals an extra {@damage 4d8} radiant damage (included in the attack)."]}, {"name": "Magic Resistance", "entries": ["The deva has advantage on saving throws against spells and other magical effects."]}]', '[{"name": "Multiattack", "entries": ["The deva makes two melee attacks."]}, {"name": "Mace", "entries": ["{@atk mw} {@hit 8} to hit, reach 5 ft., one target. {@h}7 ({@damage 1d6 + 4}) bludgeoning damage plus 18 ({@damage 4d8}) radiant damage."]}, {"name": "Healing Touch (3/Day)", "entries": ["The deva touches another creature. The target magically regains 20 ({@dice 4d8 + 2}) hit points and is freed from any curse, disease, poison, blindness, or deafness."]}, {"name": "Change Shape", "entries": ["The deva magically polymorphs into a humanoid or beast that has a challenge rating equal to or less than its own, or back into its true form. It reverts to its true form if it dies. Any equipment it is wearing or carrying is absorbed or borne by the new form (the deva''s choice).", "In a new form, the deva retains its game statistics and ability to speak, but its AC, movement modes, Strength, Dexterity, and special senses are replaced by those of the new form, and it gains any statistics and capabilities (except class features, legendary actions, and lair actions) that the new form has but that it lacks."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('dire_wolf', 'Dire Wolf', 'beast', '', 'L', 'U', 14, 37, '{"walk": 50}', 17, 15, 15, 3, 12, 7, '1', 0, 2, '{}', '{"perception": "+3", "stealth": "+4"}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Keen Hearing and Smell", "entries": ["The wolf has advantage on Wisdom ({@skill Perception}) checks that rely on hearing or smell."]}, {"name": "Pack Tactics", "entries": ["The wolf has advantage on an attack roll against a creature if at least one of the wolf''s allies is within 5 feet of the creature and the ally isn''t {@condition incapacitated}."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}10 ({@damage 2d6 + 3}) piercing damage. If the target is a creature, it must succeed on a {@dc 13} Strength saving throw or be knocked {@condition prone}."]}]', '[]', '[]', '["forest", "hill"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('displacer_beast', 'Displacer Beast', 'monstrosity', '', 'L', 'L, E', 13, 85, '{"walk": 40}', 18, 15, 16, 6, 12, 8, '3', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '[]', '[{"name": "Avoidance", "entries": ["If the displacer beast is subjected to an effect that allows it to make a saving throw to take only half damage, it instead takes no damage if it succeeds on the saving throw, and only half damage if it fails."]}, {"name": "Displacement", "entries": ["The displacer beast projects a magical illusion that makes it appear to be standing near its actual location, causing attack rolls against it to have disadvantage. If it is hit by an attack, this trait is disrupted until the end of its next turn. This trait is also disrupted while the displacer beast is {@condition incapacitated} or has a speed of 0."]}]', '[{"name": "Multiattack", "entries": ["The displacer beast makes two attacks with its tentacles."]}, {"name": "Tentacle", "entries": ["{@atk mw} {@hit 6} to hit, reach 10 ft., one target. {@h}7 ({@damage 1d6 + 4}) bludgeoning damage plus 3 ({@damage 1d6}) piercing damage."]}]', '[]', '[]', '["forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('djinni', 'Djinni', 'elemental', '', 'L', 'C, G', 17, 161, '{"walk": 30, "fly": 90}', 21, 15, 22, 15, 16, 20, '11', 0, 2, '{"dex": "+6", "wis": "+7", "cha": "+9"}', '{}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Auran"]', '[{"name": "Elemental Demise", "entries": ["If the djinni dies, its body disintegrates into a warm breeze, leaving behind only equipment the djinni was wearing or carrying."]}]', '[{"name": "Multiattack", "entries": ["The djinni makes three scimitar attacks."]}, {"name": "Scimitar", "entries": ["{@atk mw} {@hit 9} to hit, reach 5 ft., one target. {@h}12 ({@damage 2d6 + 5}) slashing damage plus 3 ({@damage 1d6}) lightning or thunder damage (djinni''s choice)."]}, {"name": "Create Whirlwind", "entries": ["A 5-foot-radius, 30-foot-tall cylinder of swirling air magically forms on a point the djinni can see within 120 feet of it. The whirlwind lasts as long as the djinni maintains {@status concentration} (as if {@status concentration||concentrating} on a spell). Any creature but the djinni that enters the whirlwind must succeed on a {@dc 18} Strength saving throw or be {@condition restrained} by it. The djinni can move the whirlwind up to 60 feet as an action, and creatures {@condition restrained} by the whirlwind move with it. The whirlwind ends if the djinni loses sight of it.", "A creature can use its action to free a creature {@condition restrained} by the whirlwind, including itself, by succeeding on a {@dc 18} Strength check. If the check succeeds, the creature is no longer {@condition restrained} and moves to the nearest space outside the whirlwind."]}]', '[]', '[]', '["coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('doppelganger', 'Doppelganger', 'monstrosity', 'shapechanger', 'M', 'N', 14, 52, '{"walk": 30}', 11, 18, 14, 11, 12, 14, '3', 0, 2, '{}', '{"deception": "+6", "insight": "+3"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Common"]', '[{"name": "Shapechanger", "entries": ["The doppelganger can use its action to polymorph into a Small or Medium humanoid it has seen, or back into its true form. Its statistics, other than its size, are the same in each form. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies."]}, {"name": "Ambusher", "entries": ["In the first round of a combat, the doppelganger has advantage on attack rolls against any creature it {@status surprised}."]}, {"name": "Surprise Attack", "entries": ["If the doppelganger surprises a creature and hits it with an attack during the first round of combat, the target takes an extra 10 ({@damage 3d6}) damage from the attack."]}]', '[{"name": "Multiattack", "entries": ["The doppelganger makes two melee attacks."]}, {"name": "Slam", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}7 ({@damage 1d6 + 4}) bludgeoning damage."]}, {"name": "Read Thoughts", "entries": ["The doppelganger magically reads the surface thoughts of one creature within 60 feet of it. The effect can penetrate barriers, but 3 feet of wood or dirt, 2 feet of stone, 2 inches of metal, or a thin sheet of lead blocks it. While the target is in range, the doppelganger can continue reading its thoughts, as long as the doppelganger''s {@status concentration} isn''t broken (as if {@status concentration||concentrating} on a spell). While reading the target''s mind, the doppelganger has advantage on Wisdom ({@skill Insight}) and Charisma ({@skill Deception}, {@skill Intimidation}, and {@skill Persuasion}) checks against the target."]}]', '[]', '[]', '["underdark", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('draft_horse', 'Draft Horse', 'beast', '', 'L', 'U', 10, 19, '{"walk": 40}', 18, 10, 12, 2, 11, 7, '1/4', 0, 2, '{}', '{}', '[]', '[]', '[]', '[]', '[]', '[]', '[{"name": "Hooves", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}9 ({@damage 2d4 + 4}) bludgeoning damage."]}]', '[]', '[]', '["urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('dragon_turtle', 'Dragon Turtle', 'dragon', '', 'G', 'N', 20, 341, '{"walk": 20, "swim": 40}', 25, 10, 20, 10, 12, 12, '17', 0, 2, '{"dex": "+6", "con": "+11", "wis": "+7"}', '{}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Aquan", "Draconic"]', '[{"name": "Amphibious", "entries": ["The dragon turtle can breathe air and water."]}]', '[{"name": "Multiattack", "entries": ["The dragon turtle makes three attacks: one with its bite and two with its claws. It can make one tail attack in place of its two claw attacks."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 13} to hit, reach 15 ft., one target. {@h}26 ({@damage 3d12 + 7}) piercing damage."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 13} to hit, reach 10 ft., one target. {@h}16 ({@damage 2d8 + 7}) slashing damage."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 13} to hit, reach 15 ft., one target. {@h}26 ({@damage 3d12 + 7}) bludgeoning damage. If the target is a creature, it must succeed on a {@dc 20} Strength saving throw or be pushed up to 10 feet away from the dragon turtle and knocked {@condition prone}."]}, {"name": "Steam Breath {@recharge 5}", "entries": ["The dragon turtle exhales scalding steam in a 60-foot cone. Each creature in that area must make a {@dc 18} Constitution saving throw, taking 52 ({@damage 15d6}) fire damage on a failed save, or half as much damage on a successful one. Being underwater doesn''t grant resistance against this damage."]}]', '[]', '[]', '["underwater", "coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('dretch', 'Dretch', 'fiend', 'demon', 'S', 'C, E', 11, 18, '{"walk": 20}', 11, 11, 12, 5, 8, 3, '1/4', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Abyssal", "telepathy 60 ft. (works only with creatures that understand Abyssal)"]', '[]', '[{"name": "Multiattack", "entries": ["The dretch makes two attacks: one with its bite and one with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 2} to hit, reach 5 ft., one target. {@h}3 ({@damage 1d6}) piercing damage."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 2} to hit, reach 5 ft., one target. {@h}5 ({@damage 2d4}) slashing damage."]}, {"name": "Fetid Cloud (1/Day)", "entries": ["A 10-foot radius of disgusting green gas extends out from the dretch. The gas spreads around corners, and its area is lightly obscured. It lasts for 1 minute or until a strong wind disperses it. Any creature that starts its turn in that area must succeed on a {@dc 11} Constitution saving throw or be {@condition poisoned} until the start of its next turn. While {@condition poisoned} in this way, the target can take either an action or a bonus action on its turn, not both, and can''t take reactions."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('drider', 'Drider', 'monstrosity', '', 'L', 'C, E', 19, 123, '{"walk": 30, "climb": 30}', 16, 16, 18, 13, 14, 12, '6', 0, 2, '{}', '{"perception": "+5", "stealth": "+9"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Elvish", "Undercommon"]', '[{"name": "Fey Ancestry", "entries": ["The drider has advantage on saving throws against being {@condition charmed}, and magic can''t put the drider to sleep."]}, {"name": "Spider Climb", "entries": ["The drider can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."]}, {"name": "Sunlight Sensitivity", "entries": ["While in sunlight, the drider has disadvantage on attack rolls, as well as on Wisdom ({@skill Perception}) checks that rely on sight."]}, {"name": "Web Walker", "entries": ["The drider ignores movement restrictions caused by webbing."]}]', '[{"name": "Multiattack", "entries": ["The drider makes three attacks, either with its longsword or its longbow. It can replace one of those attacks with a bite attack."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one creature. {@h}2 ({@damage 1d4}) piercing damage plus 9 ({@damage 2d8}) poison damage."]}, {"name": "Longsword", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}7 ({@damage 1d8 + 3}) slashing damage, or 8 ({@damage 1d10 + 3}) slashing damage if used with two hands."]}, {"name": "Longbow", "entries": ["{@atk rw} {@hit 6} to hit, range 150/600 ft., one target. {@h}7 ({@damage 1d8 + 3}) piercing damage plus 4 ({@damage 1d8}) poison damage."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('drow', 'Drow', 'humanoid', 'elf', 'M', 'N, E', 15, 13, '{"walk": 30}', 10, 14, 10, 11, 11, 12, '1/4', 0, 2, '{}', '{"perception": "+2", "stealth": "+4"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Elvish", "Undercommon"]', '[{"name": "Fey Ancestry", "entries": ["The drow has advantage on saving throws against being {@condition charmed}, and magic can''t put the drow to sleep."]}, {"name": "Sunlight Sensitivity", "entries": ["While in sunlight, the drow has disadvantage on attack rolls, as well as on Wisdom ({@skill Perception}) checks that rely on sight."]}]', '[{"name": "Shortsword", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage."]}, {"name": "Hand Crossbow", "entries": ["{@atk rw} {@hit 4} to hit, range 30/120 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage, and the target must succeed on a {@dc 13} Constitution saving throw or be {@condition poisoned} for 1 hour. If the saving throw fails by 5 or more, the target is also {@condition unconscious} while {@condition poisoned} in this way. The target wakes up if it takes damage or if another creature takes an action to shake it awake."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('drow_elite_warrior', 'Drow Elite Warrior', 'humanoid', 'elf', 'M', 'N, E', 18, 71, '{"walk": 30}', 13, 18, 14, 11, 13, 12, '5', 0, 2, '{"dex": "+7", "con": "+5", "wis": "+4"}', '{"perception": "+4", "stealth": "+10"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Elvish", "Undercommon"]', '[{"name": "Fey Ancestry", "entries": ["The drow has advantage on saving throws against being {@condition charmed}, and magic can''t put the drow to sleep."]}, {"name": "Sunlight Sensitivity", "entries": ["While in sunlight, the drow has disadvantage on attack rolls, as well as on Wisdom ({@skill Perception}) checks that rely on sight."]}]', '[{"name": "Multiattack", "entries": ["The drow makes two shortsword attacks."]}, {"name": "Shortsword", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}7 ({@damage 1d6 + 4}) piercing damage plus 10 ({@damage 3d6}) poison damage."]}, {"name": "Hand Crossbow", "entries": ["{@atk rw} {@hit 7} to hit, range 30/120 ft., one target. {@h}7 ({@damage 1d6 + 4}) piercing damage, and the target must succeed on a {@dc 13} Constitution saving throw or be {@condition poisoned} for 1 hour. If the saving throw fails by 5 or more, the target is also {@condition unconscious} while {@condition poisoned} in this way. The target wakes up if it takes damage or if another creature takes an action to shake it awake."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('drow_mage', 'Drow Mage', 'humanoid', 'elf', 'M', 'N, E', 12, 45, '{"walk": 30}', 9, 14, 10, 17, 13, 12, '7', 0, 2, '{}', '{"arcana": "+6", "deception": "+4", "perception": "+4", "stealth": "+5"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Elvish", "Undercommon"]', '[{"name": "Fey Ancestry", "entries": ["The drow has advantage on saving throws against being {@condition charmed}, and magic can''t put the drow to sleep."]}, {"name": "Sunlight Sensitivity", "entries": ["While in sunlight, the drow has disadvantage on attack rolls, as well as on Wisdom ({@skill Perception}) checks that rely on sight."]}]', '[{"name": "Staff", "entries": ["{@atk mw} {@hit 2} to hit, reach 5 ft., one target. {@h}2 ({@damage 1d6 - 1}) bludgeoning damage, or 3 ({@damage 1d8 - 1}) bludgeoning damage if used with two hands, plus 3 ({@damage 1d6}) poison damage."]}, {"name": "Summon Demon (1/Day)", "entries": ["The drow magically summons a {@creature quasit}, or attempts to summon a {@creature shadow demon} with a {@chance 50|50 percent|50% summoning chance} chance of success. The summoned demon appears in an unoccupied space within 60 feet of its summoner, acts as an ally of its summoner, and can''t summon other demons. It remains for 10 minutes, until it or its summoner dies, or until its summoner dismisses it as an action."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('drow_priestess_of_lolth', 'Drow Priestess of Lolth', 'humanoid', 'elf', 'M', 'N, E', 16, 71, '{"walk": 30}', 10, 14, 12, 13, 17, 18, '8', 0, 2, '{"con": "+4", "wis": "+6", "cha": "+7"}', '{"insight": "+6", "perception": "+6", "religion": "+4", "stealth": "+5"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Elvish", "Undercommon"]', '[{"name": "Fey Ancestry", "entries": ["The drow has advantage on saving throws against being {@condition charmed}, and magic can''t put the drow to sleep."]}, {"name": "Sunlight Sensitivity", "entries": ["While in sunlight, the drow has disadvantage on attack rolls, as well as on Wisdom ({@skill Perception}) checks that rely on sight."]}]', '[{"name": "Multiattack", "entries": ["The drow makes two scourge attacks."]}, {"name": "Scourge", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage plus 17 ({@damage 5d6}) poison damage."]}, {"name": "Summon Demon (1/Day)", "entries": ["The drow attempts to magically summon a {@creature yochlol} with a {@chance 30|30 percent|30% summoning chance} chance of success. If the attempt fails, the drow takes 5 ({@damage 1d10}) psychic damage. Otherwise, the summoned demon appears in an unoccupied space within 60 feet of its summoner, acts as an ally of its summoner, and can''t summon other demons. It remains for 10 minutes, until it or its summoner dies, or until its summoner dismisses it as an action."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('druid', 'Druid', 'humanoid', 'any race', 'M', 'A', 11, 27, '{"walk": 30}', 10, 12, 13, 12, 15, 11, '2', 0, 2, '{}', '{"medicine": "+4", "nature": "+3", "perception": "+4"}', '[]', '[]', '[]', '[]', '["Druidic plus any two languages"]', '[]', '[{"name": "Quarterstaff", "entries": ["{@atk mw} {@hit 2} to hit ({@hit 4} to hit with shillelagh), reach 5 ft., one target. {@h}3 ({@damage 1d6}) bludgeoning damage, 4 ({@damage 1d8}) bludgeoning damage if wielded with two hands, or 6 ({@damage 1d8 + 2}) bludgeoning damage with {@spell shillelagh}."]}]', '[]', '[]', '["coastal", "mountain", "grassland", "hill", "arctic", "forest", "swamp", "underdark", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('dryad', 'Dryad', 'fey', '', 'M', 'N', 11, 22, '{"walk": 30}', 10, 12, 11, 14, 15, 18, '1', 0, 2, '{}', '{"perception": "+4", "stealth": "+5"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Elvish", "Sylvan"]', '[{"name": "Magic Resistance", "entries": ["The dryad has advantage on saving throws against spells and other magical effects."]}, {"name": "Speak with Beasts and Plants", "entries": ["The dryad can communicate with beasts and plants as if they shared a language."]}, {"name": "Tree Stride", "entries": ["Once on her turn, the dryad can use 10 feet of her movement to step magically into one living tree within her reach and emerge from a second living tree within 60 feet of the first tree, appearing in an unoccupied space within 5 feet of the second tree. Both trees must be large or bigger."]}]', '[{"name": "Club", "entries": ["{@atk mw} {@hit 2} to hit ({@hit 6} to hit with shillelagh), reach 5 ft., one target. {@h}2 ({@damage 1d4}) bludgeoning damage, or 8 ({@damage 1d8 + 4}) bludgeoning damage with shillelagh."]}, {"name": "Fey Charm", "entries": ["The dryad targets one humanoid or beast that she can see within 30 feet of her. If the target can see the dryad, it must succeed on a {@dc 14} Wisdom saving throw or be magically {@condition charmed}. The {@condition charmed} creature regards the dryad as a trusted friend to be heeded and protected. Although the target isn''t under the dryad''s control, it takes the dryad''s requests or actions in the most favorable way it can.", "Each time the dryad or its allies do anything harmful to the target, it can repeat the saving throw, ending the effect on itself on a success. Otherwise, the effect lasts 24 hours or until the dryad dies, is on a different plane of existence from the target, or ends the effect as a bonus action. If a target''s saving throw is successful, the target is immune to the dryad''s Fey Charm for the next 24 hours.", "The dryad can have no more than one humanoid and up to three beasts {@condition charmed} at a time."]}]', '[]', '[]', '["forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('duergar', 'Duergar', 'humanoid', 'dwarf', 'M', 'L, E', 16, 26, '{"walk": 25}', 14, 11, 14, 11, 10, 9, '1', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Dwarvish", "Undercommon"]', '[{"name": "Duergar Resilience", "entries": ["The duergar has advantage on saving throws against poison, spells, and illusions, as well as to resist being {@condition charmed} or {@condition paralyzed}."]}, {"name": "Sunlight Sensitivity", "entries": ["While in sunlight, the duergar has disadvantage on attack rolls, as well as on Wisdom ({@skill Perception}) checks that rely on sight."]}]', '[{"name": "Enlarge (Recharges after a Short or Long Rest)", "entries": ["For 1 minute, the duergar magically increases in size, along with anything it is wearing or carrying. While enlarged, the duergar is Large, doubles its damage dice on Strength-based weapon attacks (included in the attacks), and makes Strength checks and Strength saving throws with advantage. If the duergar lacks the room to become Large, it attains the maximum size possible in the space available."]}, {"name": "War Pick", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}6 ({@damage 1d8 + 2}) piercing damage, or 11 ({@damage 2d8 + 2}) piercing damage while enlarged."]}, {"name": "Javelin", "entries": ["{@atk mw,rw} {@hit 4} to hit, reach 5 ft. or range 30/120 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage, or 9 ({@damage 2d6 + 2}) piercing damage while enlarged."]}, {"name": "Invisibility (Recharges after a Short or Long Rest)", "entries": ["The duergar magically turns {@condition invisible} until it attacks, casts a spell, or uses its Enlarge, or until its {@status concentration} is broken, up to 1 hour (as if {@status concentration||concentrating} on a spell). Any equipment the duergar wears or carries is {@condition invisible} with it."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('duodrone', 'Duodrone', 'construct', '', 'M', 'L, N', 15, 11, '{"walk": 30}', 11, 13, 12, 6, 10, 7, '1/4', 0, 2, '{}', '{}', '[]', '[]', '[]', '["truesight 120 ft."]', '["Modron"]', '[{"name": "Axiomatic Mind", "entries": ["The duodrone can''t be compelled to act in a manner contrary to its nature or its instructions."]}, {"name": "Disintegration", "entries": ["If the duodrone dies, its body disintegrates into dust, leaving behind its weapons and anything else it was carrying."]}]', '[{"name": "Multiattack", "entries": ["The duodrone makes two fist attacks or two javelin attacks."]}, {"name": "Fist", "entries": ["{@atk mw} {@hit 2} to hit, reach 5 ft., one target. {@h}2 ({@damage 1d4}) bludgeoning damage."]}, {"name": "Javelin", "entries": ["{@atk mw,rw} {@hit 3} to hit, reach 5 ft. or range 30/120 ft., one target. {@h}4 ({@damage 1d6 + 1}) piercing damage."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('dust_mephit', 'Dust Mephit', 'elemental', '', 'S', 'N, E', 12, 17, '{"walk": 30, "fly": 30}', 5, 14, 10, 9, 11, 10, '1/2', 0, 2, '{}', '{"perception": "+2", "stealth": "+4"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Auran", "Terran"]', '[{"name": "Death Burst", "entries": ["When the mephit dies, it explodes in a burst of dust. Each creature within 5 feet of it must then succeed on a {@dc 10} Constitution saving throw or be {@condition blinded} for 1 minute. A {@condition blinded} creature can repeat the saving throw on each of its turns, ending the effect on itself on a success."]}]', '[{"name": "Claws", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one creature. {@h}4 ({@damage 1d4 + 2}) slashing damage."]}, {"name": "Blinding Breath {@recharge}", "entries": ["The mephit exhales a 15-foot cone of blinding dust. Each creature in that area must succeed on a {@dc 10} Dexterity saving throw or be {@condition blinded} for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."]}]', '[]', '[]', '["desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('eagle', 'Eagle', 'beast', '', 'S', 'U', 12, 3, '{"walk": 10, "fly": 60}', 6, 15, 10, 2, 14, 7, '0', 0, 2, '{}', '{"perception": "+4"}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Keen Sight", "entries": ["The eagle has advantage on Wisdom ({@skill Perception}) checks that rely on sight."]}]', '[{"name": "Talons", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}4 ({@damage 1d4 + 2}) slashing damage."]}]', '[]', '[]', '["mountain", "grassland", "hill", "coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('earth_elemental', 'Earth Elemental', 'elemental', '', 'L', 'N', 17, 126, '{"walk": 30, "burrow": 30}', 20, 8, 20, 5, 10, 5, '5', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft.", "tremorsense 60 ft."]', '["Terran"]', '[{"name": "Earth Glide", "entries": ["The elemental can burrow through nonmagical, unworked earth and stone. While doing so, the elemental doesn''t disturb the material it moves through."]}, {"name": "Siege Monster", "entries": ["The elemental deals double damage to objects and structures."]}]', '[{"name": "Multiattack", "entries": ["The elemental makes two slam attacks."]}, {"name": "Slam", "entries": ["{@atk mw} {@hit 8} to hit, reach 10 ft., one target. {@h}14 ({@damage 2d8 + 5}) bludgeoning damage."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('efreeti', 'Efreeti', 'elemental', '', 'L', 'L, E', 17, 200, '{"walk": 40, "fly": 60}', 22, 12, 24, 16, 15, 16, '11', 0, 2, '{"int": "+7", "wis": "+6", "cha": "+7"}', '{}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Ignan"]', '[{"name": "Elemental Demise", "entries": ["If the efreeti dies, its body disintegrates in a flash of fire and puff of smoke, leaving behind only equipment the efreeti was wearing or carrying."]}]', '[{"name": "Multiattack", "entries": ["The efreeti makes two scimitar attacks or uses its Hurl Flame twice."]}, {"name": "Scimitar", "entries": ["{@atk mw} {@hit 10} to hit, reach 5 ft., one target. {@h}13 ({@damage 2d6 + 6}) slashing damage plus 7 ({@damage 2d6}) fire damage."]}, {"name": "Hurl Flame", "entries": ["{@atk rs} {@hit 7} to hit, range 120 ft., one target. {@h}17 ({@damage 5d6}) fire damage."]}]', '[]', '[]', '["desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('elephant', 'Elephant', 'beast', '', 'H', 'U', 12, 76, '{"walk": 40}', 22, 9, 17, 3, 11, 6, '4', 0, 2, '{}', '{}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Trampling Charge", "entries": ["If the elephant moves at least 20 feet straight toward a creature and then hits it with a gore attack on the same turn, that target must succeed on a {@dc 12} Strength saving throw or be knocked {@condition prone}. If the target is {@condition prone}, the elephant can make one stomp attack against it as a bonus action."]}]', '[{"name": "Gore", "entries": ["{@atk mw} {@hit 8} to hit, reach 5 ft., one target. {@h}19 ({@damage 3d8 + 6}) piercing damage."]}, {"name": "Stomp", "entries": ["{@atk mw} {@hit 8} to hit, reach 5 ft., one {@condition prone} creature. {@h}22 ({@damage 3d10 + 6}) bludgeoning damage."]}]', '[]', '[]', '["grassland"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('elk', 'Elk', 'beast', '', 'L', 'U', 10, 13, '{"walk": 50}', 16, 10, 12, 2, 10, 6, '1/4', 0, 2, '{}', '{}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Charge", "entries": ["If the elk moves at least 20 feet straight toward a target and then hits it with a ram attack on the same turn, the target takes an extra 7 ({@damage 2d6}) damage. If the target is a creature, it must succeed on a {@dc 13} Strength saving throw or be knocked {@condition prone}."]}]', '[{"name": "Ram", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}6 ({@damage 1d6 + 3}) bludgeoning damage."]}, {"name": "Hooves", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one {@condition prone} creature. {@h}8 ({@damage 2d4 + 3}) bludgeoning damage."]}]', '[]', '[]', '["grassland", "forest", "hill"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('empyrean', 'Empyrean', 'celestial', 'titan', 'H', '[''C'', ''G''], [''N'', ''E'']', 22, 313, '{"walk": 50, "fly": 50, "swim": 50}', 30, 21, 30, 21, 22, 27, '23', 0, 2, '{"str": "+17", "int": "+12", "wis": "+13", "cha": "+15"}', '{"insight": "+13", "persuasion": "+15"}', '[]', '[]', '[]', '["truesight 120 ft."]', '["all"]', '[{"name": "Legendary Resistance (3/Day)", "entries": ["If the empyrean fails a saving throw, it can choose to succeed instead."]}, {"name": "Magic Resistance", "entries": ["The empyrean has advantage on saving throws against spells and other magical effects."]}, {"name": "Magic Weapons", "entries": ["The empyrean''s weapon attacks are magical."]}]', '[{"name": "Maul", "entries": ["{@atk mw} {@hit 17} to hit, reach 10 ft., one target. {@h}31 ({@damage 6d6 + 10}) bludgeoning damage. If the target is a creature, it must succeed on a {@dc 15} Constitution saving throw or be {@condition stunned} until the end of the empyrean''s next turn."]}, {"name": "Bolt", "entries": ["{@atk rs} {@hit 15} to hit, range 600 ft., one target. {@h}24 ({@damage 7d6}) damage of one of the following types (empyrean''s choice): acid, cold, fire, force, lightning, radiant, or thunder."]}]', '[{"name": "Attack", "entries": ["The empyrean makes one attack."]}, {"name": "Bolster", "entries": ["The empyrean bolsters all nonhostile creatures within 120 feet of it until the end of its next turn. Bolstered creatures can''t be {@condition charmed} or {@condition frightened}, and they gain advantage on ability checks and saving throws until the end of the empyrean''s next turn."]}, {"name": "Trembling Strike (Costs 2 Actions)", "entries": ["The empyrean strikes the ground with its maul, triggering an earth tremor. All other creatures on the ground within 60 feet of the empyrean must succeed on a {@dc 25} Strength saving throw or be knocked {@condition prone}."]}]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('erinyes', 'Erinyes', 'fiend', 'devil', 'M', 'L, E', 18, 153, '{"walk": 30, "fly": 60}', 18, 16, 18, 14, 14, 18, '12', 0, 2, '{"dex": "+7", "con": "+8", "wis": "+6", "cha": "+8"}', '{}', '[]', '[]', '[]', '["truesight 120 ft."]', '["Infernal", "telepathy 120 ft."]', '[{"name": "Hellish Weapons", "entries": ["The erinyes''s weapon attacks are magical and deal an extra 13 ({@damage 3d8}) poison damage on a hit (included in the attacks)."]}, {"name": "Magic Resistance", "entries": ["The erinyes has advantage on saving throws against spells and other magical effects."]}]', '[{"name": "Multiattack", "entries": ["The erinyes makes three attacks."]}, {"name": "Longsword", "entries": ["{@atk mw} {@hit 8} to hit, reach 5 ft., one target. {@h}8 ({@damage 1d8 + 4}) slashing damage, or 9 ({@damage 1d10 + 4}) slashing damage if used with two hands, plus 13 ({@damage 3d8}) poison damage."]}, {"name": "Longbow", "entries": ["{@atk rw} {@hit 7} to hit, range 150/600 ft., one target. {@h}7 ({@damage 1d8 + 3}) piercing damage plus 13 ({@damage 3d8}) poison damage, and the target must succeed on a {@dc 14} Constitution saving throw or be {@condition poisoned}. The poison lasts until it is removed by the {@spell lesser restoration} spell or similar magic."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('ettercap', 'Ettercap', 'monstrosity', '', 'M', 'N, E', 13, 44, '{"walk": 30, "climb": 30}', 14, 15, 13, 7, 12, 8, '2', 0, 2, '{}', '{"perception": "+3", "stealth": "+4", "survival": "+3"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '[]', '[{"name": "Spider Climb", "entries": ["The ettercap can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."]}, {"name": "Web Sense", "entries": ["While in contact with a web, the ettercap knows the exact location of any other creature in contact with the same web."]}, {"name": "Web Walker", "entries": ["The ettercap ignores movement restrictions caused by webbing."]}]', '[{"name": "Multiattack", "entries": ["The ettercap makes two attacks: one with its bite and one with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one creature. {@h}6 ({@damage 1d8 + 2}) piercing damage plus 4 ({@damage 1d8}) poison damage. The target must succeed on a {@dc 11} Constitution saving throw or be {@condition poisoned} for 1 minute. The creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}7 ({@damage 2d4 + 2}) slashing damage."]}, {"name": "Web {@recharge 5}", "entries": ["{@atk rw} {@hit 4} to hit, range 30/60 ft., one Large or smaller creature. {@h}The creature is {@condition restrained} by webbing. As an action, the {@condition restrained} creature can make a {@dc 11} Strength check, escaping from the webbing on a success. The effect ends if the webbing is destroyed. The webbing has AC 10, 5 hit points, is vulnerable to fire damage and immune to bludgeoning, poison and psychic damage."]}]', '[]', '[]', '["forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('ettin', 'Ettin', 'giant', '', 'L', 'C, E', 12, 85, '{"walk": 40}', 21, 8, 17, 6, 10, 8, '4', 0, 2, '{}', '{"perception": "+4"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Giant", "Orc"]', '[{"name": "Two Heads", "entries": ["The ettin has advantage on Wisdom ({@skill Perception}) checks and on saving throws against being {@condition blinded}, {@condition charmed}, {@condition deafened}, {@condition frightened}, {@condition stunned}, and knocked {@condition unconscious}."]}, {"name": "Wakeful", "entries": ["When one of the ettin''s heads is asleep, its other head is awake."]}]', '[{"name": "Multiattack", "entries": ["The ettin makes two attacks: one with its battleaxe and one with its morningstar."]}, {"name": "Battleaxe", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}14 ({@damage 2d8 + 5}) slashing damage."]}, {"name": "Morningstar", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}14 ({@damage 2d8 + 5}) piercing damage."]}]', '[]', '[]', '["underdark", "mountain", "hill"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('faerie_dragon_(blue)', 'Faerie Dragon (Blue)', 'dragon', '', 'T', 'C, G', 15, 14, '{"walk": 10, "fly": 60}', 3, 20, 13, 14, 12, 16, '2', 0, 2, '{}', '{"arcana": "+4", "perception": "+3", "stealth": "+7"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Draconic", "Sylvan"]', '[{"name": "The Colors of Age", "entries": ["A faerie dragon''s scales change hue as it ages, moving through all the colors of the rainbow. All faerie dragons have innate spellcasting ability, gaining new spells as they mature.", "Red\u20145 years or less", "Orange\u20146\u201310 years", "Yellow\u201411\u201320 years", "Green\u201421\u201330 years", "Blue\u201431\u201340 years", "Indigo\u201441\u201350 years", "Violet\u201451 years or more", "A green or older faerie dragon''s CR increases to 2."]}, {"name": "Superior Invisibility", "entries": ["As a bonus action, the dragon can magically turn {@condition invisible} until its {@status concentration} ends (as if {@status concentration||concentrating} on a spell). Any equipment the dragon wears or carries is {@condition invisible} with it."]}, {"name": "Limited Telepathy", "entries": ["Using telepathy, the dragon can magically communicate with any other faerie dragon within 60 feet of it."]}, {"name": "Magic Resistance", "entries": ["The faerie dragon has advantage on saving throws against spells and other magical effects."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one creature. {@h}1 piercing damage."]}, {"name": "Euphoria Breath {@recharge 5}", "entries": ["The dragon exhales a puff of euphoria gas at one creature within 5 feet of it. The target must succeed on a {@dc 11} Wisdom saving throw, or for 1 minute, the target can''t take reactions and must roll a {@dice d6} at the start of each of its turns to determine its behavior during the turn:", "1\u20134. The target takes no action or bonus action and uses all of its movement to move in a random direction.", "5\u20136. The target doesn''t move, and the only thing it can do on its turn is make a {@dc 11} Wisdom saving throw, ending the effect on itself on a success."]}]', '[]', '[]', '["forest"]');
