INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('faerie_dragon_(violet)', 'Faerie Dragon (Violet)', 'dragon', '', 'T', 'C, G', 15, 14, '{"walk": 10, "fly": 60}', 3, 20, 13, 14, 12, 16, '2', 0, 2, '{}', '{"arcana": "+4", "perception": "+3", "stealth": "+7"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Draconic", "Sylvan"]', '[{"name": "The Colors of Age", "entries": ["A faerie dragon''s scales change hue as it ages, moving through all the colors of the rainbow. All faerie dragons have innate spellcasting ability, gaining new spells as they mature.", "Red\u20145 years or less", "Orange\u20146\u201310 years", "Yellow\u201411\u201320 years", "Green\u201421\u201330 years", "Blue\u201431\u201340 years", "Indigo\u201441\u201350 years", "Violet\u201451 years or more", "A green or older faerie dragon''s CR increases to 2."]}, {"name": "Superior Invisibility", "entries": ["As a bonus action, the dragon can magically turn {@condition invisible} until its {@status concentration} ends (as if {@status concentration||concentrating} on a spell). Any equipment the dragon wears or carries is {@condition invisible} with it."]}, {"name": "Limited Telepathy", "entries": ["Using telepathy, the dragon can magically communicate with any other faerie dragon within 60 feet of it."]}, {"name": "Magic Resistance", "entries": ["The faerie dragon has advantage on saving throws against spells and other magical effects."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one creature. {@h}1 piercing damage."]}, {"name": "Euphoria Breath {@recharge 5}", "entries": ["The dragon exhales a puff of euphoria gas at one creature within 5 feet of it. The target must succeed on a {@dc 11} Wisdom saving throw, or for 1 minute, the target can''t take reactions and must roll a {@dice d6} at the start of each of its turns to determine its behavior during the turn:", "1\u20134. The target takes no action or bonus action and uses all of its movement to move in a random direction.", "5\u20136. The target doesn''t move, and the only thing it can do on its turn is make a {@dc 11} Wisdom saving throw, ending the effect on itself on a success."]}]', '[]', '[]', '["forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('faerie_dragon_(yellow)', 'Faerie Dragon (Yellow)', 'dragon', '', 'T', 'C, G', 15, 14, '{"walk": 10, "fly": 60}', 3, 20, 13, 14, 12, 16, '1', 0, 2, '{}', '{"arcana": "+4", "perception": "+3", "stealth": "+7"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Draconic", "Sylvan"]', '[{"name": "The Colors of Age", "entries": ["A faerie dragon''s scales change hue as it ages, moving through all the colors of the rainbow. All faerie dragons have innate spellcasting ability, gaining new spells as they mature.", "Red\u20145 years or less", "Orange\u20146\u201310 years", "Yellow\u201411\u201320 years", "Green\u201421\u201330 years", "Blue\u201431\u201340 years", "Indigo\u201441\u201350 years", "Violet\u201451 years or more", "A green or older faerie dragon''s CR increases to 2."]}, {"name": "Superior Invisibility", "entries": ["As a bonus action, the dragon can magically turn {@condition invisible} until its {@status concentration} ends (as if {@status concentration||concentrating} on a spell). Any equipment the dragon wears or carries is {@condition invisible} with it."]}, {"name": "Limited Telepathy", "entries": ["Using telepathy, the dragon can magically communicate with any other faerie dragon within 60 feet of it."]}, {"name": "Magic Resistance", "entries": ["The faerie dragon has advantage on saving throws against spells and other magical effects."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one creature. {@h}1 piercing damage."]}, {"name": "Euphoria Breath {@recharge 5}", "entries": ["The dragon exhales a puff of euphoria gas at one creature within 5 feet of it. The target must succeed on a {@dc 11} Wisdom saving throw, or for 1 minute, the target can''t take reactions and must roll a {@dice d6} at the start of each of its turns to determine its behavior during the turn:", "1\u20134. The target takes no action or bonus action and uses all of its movement to move in a random direction.", "5\u20136. The target doesn''t move, and the only thing it can do on its turn is make a {@dc 11} Wisdom saving throw, ending the effect on itself on a success."]}]', '[]', '[]', '["forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('fire_elemental', 'Fire Elemental', 'elemental', '', 'L', 'N', 13, 102, '{"walk": 50}', 10, 17, 16, 6, 10, 7, '5', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Ignan"]', '[{"name": "Fire Form", "entries": ["The elemental can move through a space as narrow as 1 inch wide without squeezing. A creature that touches the elemental or hits it with a melee attack while within 5 feet of it takes 5 ({@damage 1d10}) fire damage. In addition, the elemental can enter a hostile creature''s space and stop there. The first time it enters a creature''s space on a turn, that creature takes 5 ({@damage 1d10}) fire damage and catches fire; until someone takes an action to douse the fire, the creature takes 5 ({@damage 1d10}) fire damage at the start of each of its turns."]}, {"name": "Illumination", "entries": ["The elemental sheds bright light in a 30-foot radius and dim light in an additional 30 feet."]}, {"name": "Water Susceptibility", "entries": ["For every 5 feet the elemental moves in water, or for every gallon of water splashed on it, it takes 1 cold damage."]}]', '[{"name": "Multiattack", "entries": ["The elemental makes two touch attacks."]}, {"name": "Touch", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}10 ({@damage 2d6 + 3}) fire damage. If the target is a creature or a flammable object, it ignites. Until a creature takes an action to douse the fire, the target takes 5 ({@damage 1d10}) fire damage at the start of each of its turns."]}]', '[]', '[]', '["desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('fire_giant', 'Fire Giant', 'giant', '', 'H', 'L, E', 18, 162, '{"walk": 30}', 25, 9, 23, 10, 14, 13, '9', 0, 2, '{"dex": "+3", "con": "+10", "cha": "+5"}', '{"athletics": "+11", "perception": "+6"}', '[]', '[]', '[]', '[]', '["Giant"]', '[]', '[{"name": "Multiattack", "entries": ["The giant makes two greatsword attacks."]}, {"name": "Greatsword", "entries": ["{@atk mw} {@hit 11} to hit, reach 10 ft., one target. {@h}28 ({@damage 6d6 + 7}) slashing damage."]}, {"name": "Rock", "entries": ["{@atk rw} {@hit 11} to hit, range 60/240 ft., one target. {@h}29 ({@damage 4d10 + 7}) bludgeoning damage."]}]', '[]', '[]', '["underdark", "mountain"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('fire_snake', 'Fire Snake', 'elemental', '', 'M', 'N, E', 14, 22, '{"walk": 30}', 12, 14, 11, 7, 10, 8, '1', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["understands Ignan but can''t speak"]', '[{"name": "Heated Body", "entries": ["A creature that touches the snake or hits it with a melee attack while within 5 feet of it takes 3 ({@damage 1d6}) fire damage."]}]', '[{"name": "Multiattack", "entries": ["The snake makes two attacks: one with its bite and one with its tail."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}3 ({@damage 1d4 + 1}) piercing damage plus 3 ({@damage 1d6}) fire damage."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}3 ({@damage 1d4 + 1}) bludgeoning damage plus 3 ({@damage 1d6}) fire damage."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('flameskull', 'Flameskull', 'undead', '', 'T', 'N, E', 13, 40, '{"walk": 0, "fly": {"number": 40, "condition": "(hover)"}, "canHover": true}', 1, 17, 14, 16, 10, 11, '4', 0, 2, '{}', '{"arcana": "+5", "perception": "+2"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Common"]', '[{"name": "Illumination", "entries": ["The flameskull sheds either dim light in a 15-foot radius, or bright light in a 15-foot radius and dim light for an additional 15 feet. It can switch between the options as an action."]}, {"name": "Magic Resistance", "entries": ["The flameskull has advantage on saving throws against spells and other magical effects."]}, {"name": "Rejuvenation", "entries": ["If the flameskull is destroyed, it regains all its hit points in 1 hour unless holy water is sprinkled on its remains or a {@spell dispel magic} or {@spell remove curse} spell is cast on them."]}]', '[{"name": "Multiattack", "entries": ["The flameskull uses Fire Ray twice."]}, {"name": "Fire Ray", "entries": ["{@atk rs} {@hit 5} to hit, range 30 ft., one target. {@h}10 ({@damage 3d6}) fire damage."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('flesh_golem', 'Flesh Golem', 'construct', '', 'M', 'N', 9, 93, '{"walk": 30}', 19, 9, 18, 6, 10, 5, '5', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["understands the languages of its creator but can''t speak"]', '[{"name": "Berserk", "entries": ["Whenever the golem starts its turn with 40 hit points or fewer, roll a {@dice d6}. On a 6, the golem goes berserk. On each of its turns while berserk, the golem attacks the nearest creature it can see. If no creature is near enough to move to and attack, the golem attacks an object, with preference for an object smaller than itself. Once the golem goes berserk, it continues to do so until it is destroyed or regains all its hit points.", "The golem''s creator, if within 60 feet of the berserk golem, can try to calm it by speaking firmly and persuasively. The golem must be able to hear its creator, who must take an action to make a {@dc 15} Charisma ({@skill Persuasion}) check. If the check succeeds, the golem ceases being berserk. If it takes damage while still at 40 hit points or fewer, the golem might go berserk again."]}, {"name": "Aversion of Fire", "entries": ["If the golem takes fire damage, it has disadvantage on attack rolls and ability checks until the end of its next turn."]}, {"name": "Immutable Form", "entries": ["The golem is immune to any spell or effect that would alter its form."]}, {"name": "Lightning Absorption", "entries": ["Whenever the golem is subjected to lightning damage, it takes no damage and instead regains a number of hit points equal to the lightning damage dealt."]}, {"name": "Magic Resistance", "entries": ["The golem has advantage on saving throws against spells and other magical effects."]}, {"name": "Magic Weapons", "entries": ["The golem''s weapon attacks are magical."]}]', '[{"name": "Multiattack", "entries": ["The golem makes two slam attacks."]}, {"name": "Slam", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}13 ({@damage 2d8 + 4}) bludgeoning damage."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('flumph', 'Flumph', 'aberration', '', 'S', 'L, G', 12, 7, '{"walk": 5, "fly": 30}', 6, 15, 10, 14, 14, 11, '1/8', 0, 2, '{}', '{"arcana": "+4", "history": "+4", "religion": "+4"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["understands Undercommon but can''t speak", "telepathy 60 ft."]', '[{"name": "Advanced Telepathy", "entries": ["The flumph can perceive the content of any telepathic communication used within 60 feet of it, and it can''t be {@status surprised} by creatures with any form of telepathy."]}, {"name": "Prone Deficiency", "entries": ["If the flumph is knocked {@condition prone}, roll a die. On an odd result, the flumph lands upside-down and is {@condition incapacitated}. At the end of each of its turns, the flumph can make a {@dc 10} Dexterity saving throw, righting itself and ending the {@condition incapacitated} condition if it succeeds."]}, {"name": "Telepathic Shroud", "entries": ["The flumph is immune to any effect that would sense its emotions or read its thoughts, as well as all divination spells."]}]', '[{"name": "Tendrils", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one creature. {@h}4 ({@damage 1d4 + 2}) piercing damage plus 2 ({@damage 1d4}) acid damage. At the end of each of its turns, the target must make a {@dc 10} Constitution saving throw, taking 2 ({@damage 1d4}) acid damage on a failure or ending the recurring acid damage on a success. A {@spell lesser restoration} spell cast on the target also ends the recurring acid damage."]}, {"name": "Stench Spray (1/Day)", "entries": ["Each creature in a 15-foot cone originating from the flumph must succeed on a {@dc 10} Dexterity saving throw or be coated in a foul-smelling liquid. A coated creature exudes a horrible stench for {@dice 1d4} hours. The coated creature is {@condition poisoned} as long as the stench lasts, and other creatures are {@condition poisoned} while with in 5 feet of the coated creature. A creature can remove the stench on itself by using a short rest to bathe in water, alcohol, or vinegar."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('flying_snake', 'Flying Snake', 'beast', '', 'T', 'U', 14, 5, '{"walk": 30, "fly": 60, "swim": 30}', 4, 18, 11, 2, 12, 5, '1/8', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 10 ft."]', '[]', '[{"name": "Flyby", "entries": ["The snake doesn''t provoke opportunity attacks when it flies out of an enemy''s reach."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}1 piercing damage plus 7 ({@damage 3d4}) poison damage."]}]', '[]', '[]', '["grassland", "forest", "urban", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('flying_sword', 'Flying Sword', 'construct', '', 'S', 'U', 17, 17, '{"walk": 0, "fly": {"number": 50, "condition": "(hover)"}, "canHover": true}', 12, 15, 11, 1, 5, 1, '1/4', 0, 2, '{"dex": "+4"}', '{}', '[]', '[]', '[]', '["blindsight 60 ft. (blind beyond this radius)"]', '[]', '[{"name": "Antimagic Susceptibility", "entries": ["The sword is {@condition incapacitated} while in the area of an {@spell antimagic field}. If targeted by {@spell dispel magic}, the sword must succeed on a Constitution saving throw against the caster''s spell save DC or fall {@condition unconscious} for 1 minute."]}, {"name": "False Appearance", "entries": ["While the sword remains motionless and isn''t flying, it is indistinguishable from a normal sword."]}]', '[{"name": "Longsword", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d8 + 1}) slashing damage."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('fomorian', 'Fomorian', 'giant', '', 'H', 'C, E', 14, 149, '{"walk": 30}', 23, 10, 20, 9, 14, 6, '8', 0, 2, '{}', '{"perception": "+8", "stealth": "+3"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Giant", "Undercommon"]', '[]', '[{"name": "Multiattack", "entries": ["The fomorian attacks twice with its greatclub or makes one greatclub attack and uses Evil Eye once."]}, {"name": "Greatclub", "entries": ["{@atk mw} {@hit 9} to hit, reach 15 ft., one target. {@h}19 ({@damage 3d8 + 6}) bludgeoning damage."]}, {"name": "Evil Eye", "entries": ["The fomorian magically forces a creature it can see within 60 feet of it to make a {@dc 14} Charisma saving throw. The creature takes 27 ({@damage 6d8}) psychic damage on a failed save, or half as much damage on a successful one."]}, {"name": "Curse of the Evil Eye (Recharges after a Short or Long Rest)", "entries": ["With a stare, the fomorian uses Evil Eye, but on a failed save, the creature is also cursed with magical deformities. While deformed, the creature has its speed halved and has disadvantage on ability checks, saving throws, and attacks based on Strength or Dexterity.", "The transformed creature can repeat the saving throw whenever it finishes a long rest, ending the effect on a success."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('frog', 'Frog', 'beast', '', 'T', 'U', 11, 1, '{"walk": 20, "swim": 20}', 1, 13, 8, 1, 8, 3, '{''cr'': ''0'', ''xp'': 0}', 0, 2, '{}', '{"perception": "+1", "stealth": "+3"}', '[]', '[]', '[]', '["darkvision 30 ft."]', '[]', '[{"name": "Amphibious", "entries": ["The frog can breathe air and water."]}, {"name": "Standing Leap", "entries": ["The frog''s long jump is up to 10 feet and its high jump is up to 5 feet, with or without a running start."]}]', '[]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('frost_giant', 'Frost Giant', 'giant', '', 'H', 'N, E', 15, 138, '{"walk": 40}', 23, 9, 21, 9, 10, 12, '8', 0, 2, '{"con": "+8", "wis": "+3", "cha": "+4"}', '{"athletics": "+9", "perception": "+3"}', '[]', '[]', '[]', '[]', '["Giant"]', '[]', '[{"name": "Multiattack", "entries": ["The giant makes two greataxe attacks."]}, {"name": "Greataxe", "entries": ["{@atk mw} {@hit 9} to hit, reach 10 ft., one target. {@h}25 ({@damage 3d12 + 6}) slashing damage."]}, {"name": "Rock", "entries": ["{@atk rw} {@hit 9} to hit, range 60/240 ft., one target. {@h}28 ({@damage 4d10 + 6}) bludgeoning damage."]}]', '[]', '[]', '["mountain", "arctic"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('galeb_duhr', 'Galeb Duhr', 'elemental', '', 'M', 'N', 16, 85, '{"walk": {"number": 15, "condition": "(30 ft. when rolling, 60 ft. rolling downhill)"}}', 20, 14, 20, 11, 12, 11, '6', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft.", "tremorsense 60 ft."]', '["Terran"]', '[{"name": "False Appearance", "entries": ["While the galeb duhr remains motionless, it is indistinguishable from a normal boulder."]}, {"name": "Rolling Charge", "entries": ["If the galeb duhr rolls at least 20 feet straight toward a target and then hits it with a slam attack on the same turn, the target takes an extra 7 ({@damage 2d6}) bludgeoning damage. If the target is a creature, it must succeed on a {@dc 16} Strength saving throw or be knocked {@condition prone}."]}]', '[{"name": "Slam", "entries": ["{@atk mw} {@hit 8} to hit, reach 5 ft., one target. {@h}12 ({@damage 2d6 + 5}) bludgeoning damage."]}, {"name": "Animate Boulders (1/Day)", "entries": ["The galeb duhr magically animates up to two boulders it can see within 60 feet of it. A boulder has statistics like those of a galeb duhr, except it has Intelligence 1 and Charisma 1, it can''t be {@condition charmed} or {@condition frightened}, and it lacks this action option. A boulder remains animated as long as the galeb duhr maintains {@status concentration}, up to 1 minute (as if {@status concentration||concentrating} on a spell)."]}]', '[]', '[]', '["mountain", "hill"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('gargoyle', 'Gargoyle', 'elemental', '', 'M', 'C, E', 15, 52, '{"walk": 30, "fly": 60}', 15, 11, 16, 6, 11, 7, '2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Terran"]', '[{"name": "False Appearance", "entries": ["While the gargoyle remains motionless, it is indistinguishable from an inanimate statue."]}]', '[{"name": "Multiattack", "entries": ["The gargoyle makes two attacks: one with its bite and one with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d6 + 2}) slashing damage."]}]', '[]', '[]', '["underdark", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('gas_spore', 'Gas Spore', 'plant', '', 'L', 'U', 5, 1, '{"walk": 0, "fly": {"number": 10, "condition": "(hover)"}, "canHover": true}', 5, 1, 3, 1, 1, 1, '1/2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 30 ft. (blind beyond this radius)"]', '[]', '[{"name": "Death Burst", "entries": ["The gas spore explodes when it drops to 0 hit points. Each creature within 20 feet of it must succeed on a {@dc 15} Constitution saving throw or take 10 ({@damage 3d6}) poison damage and become infected with a disease on a failed save. Creatures immune to the {@condition poisoned} condition are immune to this disease.", "Spores invade an infected creature''s system, killing the creature in a number of hours equal to {@dice 1d12} + the creature''s Constitution score, unless the disease is removed. In half that time, the creature becomes {@condition poisoned} for the rest of the duration. After the creature dies, it sprouts {@dice 2d4} Tiny gas spores that grow to full size in 7 days."]}, {"name": "Eerie Resemblance", "entries": ["The gas spore resembles a beholder. A creature that can see the gas spore can discern its true nature with a successful {@dc 15} Intelligence ({@skill Nature}) check."]}]', '[{"name": "Touch", "entries": ["{@atk mw} {@hit 0} to hit, reach 5 ft., one creature. {@h}1 poison damage, and the creature must succeed on a {@dc 10} Constitution saving throw or become infected with the disease described in the Death Burst trait."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('gelatinous_cube', 'Gelatinous Cube', 'ooze', '', 'L', 'U', 6, 84, '{"walk": 15}', 14, 3, 20, 1, 6, 1, '2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 60 ft. (blind beyond this radius)"]', '[]', '[{"name": "Ooze Cube", "entries": ["The cube takes up its entire space. Other creatures can enter the space, but a creature that does so is subjected to the cube''s Engulf and has disadvantage on the saving throw.", "Creatures inside the cube can be seen but have {@quickref Cover||3||total cover}.", "A creature within 5 feet of the cube can take an action to pull a creature or object out of the cube. Doing so requires a successful {@dc 12} Strength check, and the creature making the attempt takes 10 ({@damage 3d6}) acid damage.", "The cube can hold only one Large creature or up to four Medium or smaller creatures inside it at a time."]}, {"name": "Transparent", "entries": ["Even when the cube is in plain sight, it takes a successful {@dc 15} Wisdom ({@skill Perception}) check to spot a cube that has neither moved nor attacked. A creature that tries to enter the cube''s space while unaware of the cube is {@status surprised} by the cube."]}]', '[{"name": "Pseudopod", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one creature. {@h}10 ({@damage 3d6}) acid damage."]}, {"name": "Engulf", "entries": ["The cube moves up to its speed. While doing so, it can enter Large or smaller creatures'' spaces. Whenever the cube enters a creature''s space, the creature must make a {@dc 12} Dexterity saving throw.", "On a successful save, the creature can choose to be pushed 5 feet back or to the side of the cube. A creature that chooses not to be pushed suffers the consequences of a failed saving throw.", "On a failed save, the cube enters the creature''s space, and the creature takes 10 ({@damage 3d6}) acid damage and is engulfed. The engulfed creature can''t breathe, is {@condition restrained}, and takes 21 ({@damage 6d6}) acid damage at the start of each of the cube''s turns. When the cube moves, the engulfed creature moves with it.", "An engulfed creature can try to escape by taking an action to make a {@dc 12} Strength check. On a success, the creature escapes and enters a space of its choice within 5 feet of the cube."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('ghast', 'Ghast', 'undead', '', 'M', 'C, E', 13, 36, '{"walk": 30}', 16, 17, 10, 11, 10, 8, '2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Common"]', '[{"name": "Stench", "entries": ["Any creature that starts its turn within 5 feet of the ghast must succeed on a {@dc 10} Constitution saving throw or be {@condition poisoned} until the start of its next turn. On a successful saving throw, the creature is immune to the ghast''s Stench for 24 hours."]}, {"name": "Turn Defiance", "entries": ["The ghast and any ghouls within 30 feet of it have advantage on saving throws against effects that turn undead."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one creature. {@h}12 ({@damage 2d8 + 3}) piercing damage."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}10 ({@damage 2d6 + 3}) slashing damage. If the target is a creature other than an undead, it must succeed on a {@dc 10} Constitution saving throw or be {@condition paralyzed} for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."]}]', '[]', '[]', '["underdark", "swamp", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('ghost', 'Ghost', 'undead', '', 'M', 'A', 11, 45, '{"walk": 0, "fly": {"number": 40, "condition": "(hover)"}, "canHover": true}', 7, 13, 10, 10, 12, 17, '4', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["any languages it knew in life"]', '[{"name": "Ethereal Sight", "entries": ["The ghost can see 60 feet into the Ethereal Plane when it is on the Material Plane, and vice versa."]}, {"name": "Incorporeal Movement", "entries": ["The ghost can move through other creatures and objects as if they were {@quickref difficult terrain||3}. It takes 5 ({@damage 1d10}) force damage if it ends its turn inside an object."]}]', '[{"name": "Withering Touch", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}17 ({@damage 4d6 + 3}) necrotic damage."]}, {"name": "Etherealness", "entries": ["The ghost enters the Ethereal Plane from the Material Plane, or vice versa. It is visible on the Material Plane while it is in the Border Ethereal, and vice versa, yet it can''t affect or be affected by anything on the other plane."]}, {"name": "Horrifying Visage", "entries": ["Each non-undead creature within 60 feet of the ghost that can see it must succeed on a {@dc 13} Wisdom saving throw or be {@condition frightened} for 1 minute. If the save fails by 5 or more, the target also ages {@dice 1d4 \u00d7 10} years. A {@condition frightened} target can repeat the saving throw at the end of each of its turns, ending the {@condition frightened} condition on itself on a success. If a target''s saving throw is successful or the effect ends for it, the target is immune to this ghost''s Horrifying Visage for the next 24 hours. The aging effect can be reversed with a  {@spell greater restoration} spell, but only within 24 hours of it occurring."]}, {"name": "Possession {@recharge}", "entries": ["One humanoid that the ghost can see within 5 feet of it must succeed on a {@dc 13} Charisma saving throw or be possessed by the ghost; the ghost then disappears, and the target is {@condition incapacitated} and loses control of its body. The ghost now controls the body but doesn''t deprive the target of awareness. The ghost can''t be targeted by any attack, spell, or other effect, except ones that turn undead, and it retains its alignment, Intelligence, Wisdom, Charisma, and immunity to being {@condition charmed} and {@condition frightened}. It otherwise uses the possessed target''s statistics, but doesn''t gain access to the target''s knowledge, class features, or proficiencies.", "The possession lasts until the body drops to 0 hit points, the ghost ends it as a bonus action, or the ghost is turned or forced out by an effect like the {@spell dispel evil and good} spell. When the possession ends, the ghost reappears in an unoccupied space within 5 feet of the body. The target is immune to this ghost''s Possession for 24 hours after succeeding on the saving throw or after the possession ends."]}]', '[]', '[]', '["underdark", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('ghoul', 'Ghoul', 'undead', '', 'M', 'C, E', 12, 22, '{"walk": 30}', 13, 15, 10, 7, 10, 6, '1', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Common"]', '[]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 2} to hit, reach 5 ft., one creature. {@h}9 ({@damage 2d6 + 2}) piercing damage."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}7 ({@damage 2d4 + 2}) slashing damage. If the target is a creature other than an elf or undead, it must succeed on a {@dc 10} Constitution saving throw or be {@condition paralyzed} for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."]}]', '[]', '[]', '["underdark", "swamp", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_ape', 'Giant Ape', 'beast', '', 'H', 'U', 12, 157, '{"walk": 40, "climb": 40}', 23, 14, 18, 7, 12, 7, '7', 0, 2, '{}', '{"athletics": "+9", "perception": "+4"}', '[]', '[]', '[]', '[]', '[]', '[]', '[{"name": "Multiattack", "entries": ["The ape makes two fist attacks."]}, {"name": "Fist", "entries": ["{@atk mw} {@hit 9} to hit, reach 10 ft., one target. {@h}22 ({@damage 3d10 + 6}) bludgeoning damage."]}, {"name": "Rock", "entries": ["{@atk rw} {@hit 9} to hit, range 50/100 ft., one target. {@h}30 ({@damage 7d6 + 6}) bludgeoning damage."]}]', '[]', '[]', '["forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_badger', 'Giant Badger', 'beast', '', 'M', 'U', 10, 13, '{"walk": 30, "burrow": 10}', 13, 10, 15, 2, 12, 5, '1/4', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 30 ft."]', '[]', '[{"name": "Keen Smell", "entries": ["The badger has advantage on Wisdom ({@skill Perception}) checks that rely on smell."]}]', '[{"name": "Multiattack", "entries": ["The badger makes two attacks: one with its bite and one with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}4 ({@damage 1d6 + 1}) piercing damage."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}6 ({@damage 2d4 + 1}) slashing damage."]}]', '[]', '[]', '["forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_bat', 'Giant Bat', 'beast', '', 'L', 'U', 13, 22, '{"walk": 10, "fly": 60}', 15, 16, 11, 2, 12, 6, '1/4', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 60 ft."]', '[]', '[{"name": "Echolocation", "entries": ["The bat can''t use its blindsight while {@condition deafened}."]}, {"name": "Keen Hearing", "entries": ["The bat has advantage on Wisdom ({@skill Perception}) checks that rely on hearing."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one creature. {@h}5 ({@damage 1d6 + 2}) piercing damage."]}]', '[]', '[]', '["underdark", "forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_boar', 'Giant Boar', 'beast', '', 'L', 'U', 12, 42, '{"walk": 40}', 17, 10, 16, 2, 7, 5, '2', 0, 2, '{}', '{}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Charge", "entries": ["If the boar moves at least 20 feet straight toward a target and then hits it with a tusk attack on the same turn, the target takes an extra 7 ({@damage 2d6}) slashing damage. If the target is a creature, it must succeed on a {@dc 13} Strength saving throw or be knocked {@condition prone}."]}, {"name": "Relentless (Recharges after a Short or Long Rest)", "entries": ["If the boar takes 10 damage or less that would reduce it to 0 hit points, it is reduced to 1 hit point instead."]}]', '[{"name": "Tusk", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}10 ({@damage 2d6 + 3}) slashing damage."]}]', '[]', '[]', '["grassland", "forest", "hill"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_centipede', 'Giant Centipede', 'beast', '', 'S', 'U', 13, 4, '{"walk": 30, "climb": 30}', 5, 14, 12, 1, 7, 3, '1/4', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 30 ft."]', '[]', '[]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one creature. {@h}4 ({@damage 1d4 + 2}) piercing damage, and the target must succeed on a {@dc 11} Constitution saving throw or take 10 ({@damage 3d6}) poison damage. If the poison damage reduces the target to 0 hit points, the target is stable but {@condition poisoned} for 1 hour, even after regaining hit points, and is {@condition paralyzed} while {@condition poisoned} in this way."]}]', '[]', '[]', '["underdark", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_constrictor_snake', 'Giant Constrictor Snake', 'beast', '', 'H', 'U', 12, 60, '{"walk": 30, "swim": 30}', 19, 14, 12, 1, 10, 3, '2', 0, 2, '{}', '{"perception": "+2"}', '[]', '[]', '[]', '["blindsight 10 ft."]', '[]', '[]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 6} to hit, reach 10 ft., one creature. {@h}11 ({@damage 2d6 + 4}) piercing damage."]}, {"name": "Constrict", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one creature. {@h}13 ({@damage 2d8 + 4}) bludgeoning damage, and the target is {@condition grappled} (escape {@dc 16}). Until this grapple ends, the creature is {@condition restrained}, and the snake can''t constrict another target."]}]', '[]', '[]', '["underwater", "underdark", "forest", "swamp", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_crab', 'Giant Crab', 'beast', '', 'M', 'U', 15, 13, '{"walk": 30, "swim": 30}', 13, 15, 11, 1, 9, 3, '1/8', 0, 2, '{}', '{"stealth": "+4"}', '[]', '[]', '[]', '["blindsight 30 ft."]', '[]', '[{"name": "Amphibious", "entries": ["The crab can breathe air and water."]}]', '[{"name": "Claw", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}4 ({@damage 1d6 + 1}) bludgeoning damage, and the target is {@condition grappled} (escape {@dc 11}). The crab has two claws, each of which can grapple only one target."]}]', '[]', '[]', '["coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_crocodile', 'Giant Crocodile', 'beast', '', 'H', 'U', 14, 85, '{"walk": 30, "swim": 50}', 21, 9, 17, 2, 10, 7, '5', 0, 2, '{}', '{"stealth": "+5"}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Hold Breath", "entries": ["The crocodile can hold its breath for 30 minutes."]}]', '[{"name": "Multiattack", "entries": ["The crocodile makes two attacks: one with its bite and one with its tail."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 8} to hit, reach 5 ft., one target. {@h}21 ({@damage 3d10 + 5}) piercing damage, and the target is {@condition grappled} (escape {@dc 16}). Until this grapple ends, the target is {@condition restrained}, and the crocodile can''t bite another target."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 8} to hit, reach 10 ft., one target not {@condition grappled} by the crocodile. {@h}14 ({@damage 2d8 + 5}) bludgeoning damage. If the target is a creature, it must succeed on a {@dc 16} Strength saving throw or be knocked {@condition prone}."]}]', '[]', '[]', '["swamp"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_eagle', 'Giant Eagle', 'beast', '', 'L', 'N, G', 13, 26, '{"walk": 10, "fly": 80}', 16, 17, 13, 8, 14, 10, '1', 0, 2, '{}', '{"perception": "+4"}', '[]', '[]', '[]', '[]', '["Giant Eagle", "understands Common and Auran but can''t speak them"]', '[{"name": "Keen Sight", "entries": ["The eagle has advantage on Wisdom ({@skill Perception}) checks that rely on sight."]}]', '[{"name": "Multiattack", "entries": ["The eagle makes two attacks: one with its beak and one with its talons."]}, {"name": "Beak", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}6 ({@damage 1d6 + 3}) piercing damage."]}, {"name": "Talons", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}10 ({@damage 2d6 + 3}) slashing damage."]}]', '[]', '[]', '["mountain", "grassland", "hill", "coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_elk', 'Giant Elk', 'beast', '', 'H', 'U', 14, 42, '{"walk": 60}', 19, 16, 14, 7, 14, 10, '2', 0, 2, '{}', '{"perception": "+4"}', '[]', '[]', '[]', '[]', '["Giant Elk", "understands Common, Elvish, Sylvan but can''t speak them"]', '[{"name": "Charge", "entries": ["If the elk moves at least 20 feet straight toward a target and then hits it with a ram attack on the same turn, the target takes an extra 7 ({@damage 2d6}) damage. If the target is a creature, it must succeed on a {@dc 14} Strength saving throw or be knocked {@condition prone}."]}]', '[{"name": "Ram", "entries": ["{@atk mw} {@hit 6} to hit, reach 10 ft., one target. {@h}11 ({@damage 2d6 + 4}) bludgeoning damage."]}, {"name": "Hooves", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one {@condition prone} creature. {@h}22 ({@damage 4d8 + 4}) bludgeoning damage."]}]', '[]', '[]', '["mountain", "grassland", "forest", "hill"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_fire_beetle', 'Giant Fire Beetle', 'beast', '', 'S', 'U', 13, 4, '{"walk": 30}', 8, 10, 12, 1, 7, 3, '0', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 30 ft."]', '[]', '[{"name": "Illumination", "entries": ["The beetle sheds bright light in a 10-foot radius and dim light for an additional 10 ft.."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 1} to hit, reach 5 ft., one target. {@h}2 ({@damage 1d6 - 1}) slashing damage."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_frog', 'Giant Frog', 'beast', '', 'M', 'U', 11, 18, '{"walk": 30, "swim": 30}', 12, 13, 11, 2, 10, 3, '1/4', 0, 2, '{}', '{"perception": "+2", "stealth": "+3"}', '[]', '[]', '[]', '["darkvision 30 ft."]', '[]', '[{"name": "Amphibious", "entries": ["The frog can breathe air and water."]}, {"name": "Standing Leap", "entries": ["The frog''s long jump is up to 20 feet and its high jump is up to 10 feet, with or without a running start."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}4 ({@damage 1d6 + 1}) piercing damage, and the target is {@condition grappled} (escape {@dc 11}). Until this grapple ends, the target is {@condition restrained}, and the frog can''t bite another target."]}, {"name": "Swallow", "entries": ["The frog makes one bite attack against a Small or smaller target it is grappling. If the attack hits, the target is swallowed, and the grapple ends. The swallowed target is {@condition blinded} and {@condition restrained}, it has {@quickref Cover||3||total cover} against attacks and other effects outside the frog, and it takes 5 ({@damage 2d4}) acid damage at the start of each of the frog''s turns. The frog can have only one target swallowed at a time. If the frog dies, a swallowed creature is no longer {@condition restrained} by it and can escape from the corpse using 5 feet of movement, exiting {@condition prone}."]}]', '[]', '[]', '["forest", "swamp"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_goat', 'Giant Goat', 'beast', '', 'L', 'U', 11, 19, '{"walk": 40}', 17, 11, 12, 3, 12, 6, '1/2', 0, 2, '{}', '{}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Charge", "entries": ["If the goat moves at least 20 feet straight toward a target and then hits it with a ram attack on the same turn, the target takes an extra 5 ({@damage 2d4}) bludgeoning damage. If the target is a creature, it must succeed on a {@dc 13} Strength saving throw or be knocked {@condition prone}."]}, {"name": "Sure-Footed", "entries": ["The goat has advantage on Strength and Dexterity saving throws made against effects that would knock it {@condition prone}."]}]', '[{"name": "Ram", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}8 ({@damage 2d4 + 3}) bludgeoning damage."]}]', '[]', '[]', '["mountain", "grassland", "hill"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_hyena', 'Giant Hyena', 'beast', '', 'L', 'U', 12, 45, '{"walk": 50}', 16, 14, 14, 2, 12, 7, '1', 0, 2, '{}', '{"perception": "+3"}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Rampage", "entries": ["When the hyena reduces a creature to 0 hit points with a melee attack on its turn, the hyena can take a bonus action to move up to half its speed and make a bite attack."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}10 ({@damage 2d6 + 3}) piercing damage."]}]', '[]', '[]', '["grassland", "forest", "hill", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_lizard', 'Giant Lizard', 'beast', '', 'L', 'U', 12, 19, '{"walk": 30, "climb": 30}', 15, 12, 13, 2, 10, 5, '1/4', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 30 ft."]', '[]', '[]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}6 ({@damage 1d8 + 2}) piercing damage."]}]', '[]', '[]', '["underdark", "forest", "swamp", "desert", "coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_octopus', 'Giant Octopus', 'beast', '', 'L', 'U', 11, 52, '{"walk": 10, "swim": 60}', 17, 13, 13, 4, 10, 4, '1', 0, 2, '{}', '{"perception": "+4", "stealth": "+5"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '[]', '[{"name": "Hold Breath", "entries": ["While out of water, the octopus can hold its breath for 1 hour."]}, {"name": "Underwater Camouflage", "entries": ["The octopus has advantage on Dexterity ({@skill Stealth}) checks made while underwater."]}, {"name": "Water Breathing", "entries": ["The octopus can breathe only underwater."]}]', '[{"name": "Tentacles", "entries": ["{@atk mw} {@hit 5} to hit, reach 15 ft., one target. {@h}10 ({@damage 2d6 + 3}) bludgeoning damage. If the target is a creature, it is {@condition grappled} (escape {@dc 16}). Until this grapple ends, the target is {@condition restrained}, and the octopus can''t use its tentacles on another target."]}, {"name": "Ink Cloud (Recharges after a Short or Long Rest)", "entries": ["A 20-foot-radius cloud of ink extends all around the octopus if it is underwater. The area is heavily obscured for 1 minute, although a significant current can disperse the ink. After releasing the ink, the octopus can use the Dash action as a bonus action."]}]', '[]', '[]', '["underwater"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_owl', 'Giant Owl', 'beast', '', 'L', 'N', 12, 19, '{"walk": 5, "fly": 60}', 13, 15, 12, 8, 13, 10, '1/4', 0, 2, '{}', '{"perception": "+5", "stealth": "+4"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Giant Owl", "understands Common, Elvish, and Sylvan but can''t speak them"]', '[{"name": "Flyby", "entries": ["The owl doesn''t provoke opportunity attacks when it flies out of an enemy''s reach."]}, {"name": "Keen Hearing and Sight", "entries": ["The owl has advantage on Wisdom ({@skill Perception}) checks that rely on hearing or sight."]}]', '[{"name": "Talons", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}8 ({@damage 2d6 + 1}) slashing damage."]}]', '[]', '[]', '["forest", "hill", "arctic"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_poisonous_snake', 'Giant Poisonous Snake', 'beast', '', 'M', 'U', 14, 11, '{"walk": 30, "swim": 30}', 10, 18, 13, 2, 10, 3, '1/4', 0, 2, '{}', '{"perception": "+2"}', '[]', '[]', '[]', '["blindsight 10 ft."]', '[]', '[]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 6} to hit, reach 10 ft., one target. {@h}6 ({@damage 1d4 + 4}) piercing damage, and the target must make a {@dc 11} Constitution saving throw, taking 10 ({@damage 3d6}) poison damage on a failed save, or half as much damage on a successful one."]}]', '[]', '[]', '["underdark", "grassland", "forest", "swamp", "urban", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_rat', 'Giant Rat', 'beast', '', 'S', 'U', 12, 7, '{"walk": 30}', 7, 15, 11, 2, 10, 4, '1/8', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '[]', '[{"name": "Keen Smell", "entries": ["The rat has advantage on Wisdom ({@skill Perception}) checks that rely on smell."]}, {"name": "Pack Tactics", "entries": ["The rat has advantage on an attack roll against a creature if at least one of the rat''s allies is within 5 feet of the creature and the ally isn''t {@condition incapacitated}."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}4 ({@damage 1d4 + 2}) piercing damage."]}]', '[]', '[]', '["underdark", "forest", "swamp", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_scorpion', 'Giant Scorpion', 'beast', '', 'L', 'U', 15, 52, '{"walk": 40}', 15, 13, 15, 1, 9, 3, '3', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 60 ft."]', '[]', '[]', '[{"name": "Multiattack", "entries": ["The scorpion makes three attacks: two with its claws and one with its sting."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}6 ({@damage 1d8 + 2}) bludgeoning damage, and the target is {@condition grappled} (escape {@dc 12}). The scorpion has two claws, each of which can grapple only one target."]}, {"name": "Sting", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one creature. {@h}7 ({@damage 1d10 + 2}) piercing damage, and the target must make a {@dc 12} Constitution saving throw, taking 22 ({@damage 4d10}) poison damage on a failed save, or half as much damage on a successful one."]}]', '[]', '[]', '["desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_sea_horse', 'Giant Sea Horse', 'beast', '', 'L', 'U', 13, 16, '{"walk": 0, "swim": 40}', 12, 15, 11, 2, 12, 5, '1/2', 0, 2, '{}', '{}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Charge", "entries": ["If the sea horse moves at least 20 feet straight toward a target and then hits it with a ram attack on the same turn, the target takes an extra 7 ({@damage 2d6}) bludgeoning damage. If the target is a creature, it must succeed on a {@dc 11} Strength saving throw or be knocked {@condition prone}."]}, {"name": "Water Breathing", "entries": ["The sea horse can breathe only underwater."]}]', '[{"name": "Ram", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}4 ({@damage 1d6 + 1}) bludgeoning damage."]}]', '[]', '[]', '["underwater"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_shark', 'Giant Shark', 'beast', '', 'H', 'U', 13, 126, '{"swim": 50}', 23, 11, 21, 1, 10, 5, '5', 0, 2, '{}', '{"perception": "+3"}', '[]', '[]', '[]', '["blindsight 60 ft."]', '[]', '[{"name": "Blood Frenzy", "entries": ["The shark has advantage on melee attack rolls against any creature that doesn''t have all its hit points."]}, {"name": "Water Breathing", "entries": ["The shark can breathe only underwater."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 9} to hit, reach 5 ft., one target. {@h}22 ({@damage 3d10 + 6}) piercing damage."]}]', '[]', '[]', '["underwater"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_spider', 'Giant Spider', 'beast', '', 'L', 'U', 14, 26, '{"walk": 30, "climb": 30}', 14, 16, 12, 2, 11, 4, '1', 0, 2, '{}', '{"stealth": "+7"}', '[]', '[]', '[]', '["blindsight 10 ft.", "darkvision 60 ft."]', '[]', '[{"name": "Spider Climb", "entries": ["The spider can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."]}, {"name": "Web Sense", "entries": ["While in contact with a web, the spider knows the exact location of any other creature in contact with the same web."]}, {"name": "Web Walker", "entries": ["The spider ignores movement restrictions caused by webbing."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one creature. {@h}7 ({@damage 1d8 + 3}) piercing damage, and the target must make a {@dc 11} Constitution saving throw, taking 9 ({@damage 2d8}) poison damage on a failed save, or half as much damage on a successful one. If the poison damage reduces the target to 0 hit points, the target is stable but {@condition poisoned} for 1 hour, even after regaining hit points, and is {@condition paralyzed} while {@condition poisoned} in this way."]}, {"name": "Web {@recharge 5}", "entries": ["{@atk rw} {@hit 5} to hit, range 30/60 ft., one creature. {@h}The target is {@condition restrained} by webbing. As an action, the {@condition restrained} target can make a {@dc 12} Strength check, bursting the webbing on a success. The webbing can also be attacked and destroyed (AC 10; hp 5; vulnerability to fire damage; immunity to bludgeoning, poison, and psychic damage)."]}]', '[]', '[]', '["underdark", "forest", "swamp", "urban", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_toad', 'Giant Toad', 'beast', '', 'L', 'U', 11, 39, '{"walk": 20, "swim": 40}', 15, 13, 13, 2, 10, 3, '1', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 30 ft."]', '[]', '[{"name": "Amphibious", "entries": ["The toad can breathe air and water."]}, {"name": "Standing Leap", "entries": ["The toad''s long jump is up to 20 feet and its high jump is up to 10 feet, with or without a running start."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}7 ({@damage 1d10 + 2}) piercing damage plus 5 ({@damage 1d10}) poison damage, and the target is {@condition grappled} (escape {@dc 13}). Until this grapple ends, the target is {@condition restrained}, and the toad can''t bite another target."]}, {"name": "Swallow", "entries": ["The toad makes one bite attack against a Medium or smaller target it is grappling. If the attack hits, the target is swallowed, and the grapple ends. The swallowed target is {@condition blinded} and {@condition restrained}, it has {@quickref Cover||3||total cover} against attacks and other effects outside the toad, and it takes 10 ({@damage 3d6}) acid damage at the start of each of the toad''s turns. The toad can have only one target swallowed at a time.", "If the toad dies, a swallowed creature is no longer {@condition restrained} by it and can escape from the corpse using 5 feet of movement, exiting {@condition prone}."]}]', '[]', '[]', '["underdark", "forest", "swamp", "desert", "coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_vulture', 'Giant Vulture', 'beast', '', 'L', 'N, E', 10, 22, '{"walk": 10, "fly": 60}', 15, 10, 15, 6, 12, 7, '1', 0, 2, '{}', '{"perception": "+3"}', '[]', '[]', '[]', '[]', '["understands Common but can''t speak"]', '[{"name": "Keen Sight and Smell", "entries": ["The vulture has advantage on Wisdom ({@skill Perception}) checks that rely on sight or smell."]}, {"name": "Pack Tactics", "entries": ["The vulture has advantage on an attack roll against a creature if at least one of the vulture''s allies is within 5 feet of the creature and the ally isn''t {@condition incapacitated}."]}]', '[{"name": "Multiattack", "entries": ["The vulture makes two attacks: one with its beak and one with its talons."]}, {"name": "Beak", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}7 ({@damage 2d4 + 2}) piercing damage."]}, {"name": "Talons", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}9 ({@damage 2d6 + 2}) slashing damage."]}]', '[]', '[]', '["grassland", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_wasp', 'Giant Wasp', 'beast', '', 'M', 'U', 12, 13, '{"walk": 10, "fly": 50}', 10, 14, 10, 1, 10, 3, '1/2', 0, 2, '{}', '{}', '[]', '[]', '[]', '[]', '[]', '[]', '[{"name": "Sting", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one creature. {@h}5 ({@damage 1d6 + 2}) piercing damage, and the target must make a {@dc 11} Constitution saving throw, taking 10 ({@damage 3d6}) poison damage on a failed save, or half as much damage on a successful one. If the poison damage reduces the target to 0 hit points, the target is stable but {@condition poisoned} for 1 hour, even after regaining hit points, and is {@condition paralyzed} while {@condition poisoned} in this way."]}]', '[]', '[]', '["grassland", "forest", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_weasel', 'Giant Weasel', 'beast', '', 'M', 'U', 13, 9, '{"walk": 40}', 11, 16, 10, 4, 12, 5, '1/8', 0, 2, '{}', '{"perception": "+3", "stealth": "+5"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '[]', '[{"name": "Keen Hearing and Smell", "entries": ["The weasel has advantage on Wisdom ({@skill Perception}) checks that rely on hearing or smell."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d4 + 3}) piercing damage."]}]', '[]', '[]', '["grassland", "forest", "hill"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('giant_wolf_spider', 'Giant Wolf Spider', 'beast', '', 'M', 'U', 13, 11, '{"walk": 40, "climb": 40}', 12, 16, 13, 3, 12, 4, '1/4', 0, 2, '{}', '{"perception": "+3", "stealth": "+7"}', '[]', '[]', '[]', '["blindsight 10 ft.", "darkvision 60 ft."]', '[]', '[{"name": "Spider Climb", "entries": ["The spider can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."]}, {"name": "Web Sense", "entries": ["While in contact with a web, the spider knows the exact location of any other creature in contact with the same web."]}, {"name": "Web Walker", "entries": ["The spider ignores movement restrictions caused by webbing."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one creature. {@h}4 ({@damage 1d6 + 1}) piercing damage, and the target must make a {@dc 11} Constitution saving throw, taking 7 ({@damage 2d6}) poison damage on a failed save, or half as much damage on a successful one. If the poison damage reduces the target to 0 hit points, the target is stable but {@condition poisoned} for 1 hour, even after regaining hit points, and is {@condition paralyzed} while {@condition poisoned} in this way."]}]', '[]', '[]', '["grassland", "forest", "hill", "desert", "coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('gibbering_mouther', 'Gibbering Mouther', 'aberration', '', 'M', 'N', 9, 67, '{"walk": 10, "swim": 10}', 10, 8, 16, 3, 10, 6, '2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '[]', '[{"name": "Aberrant Ground", "entries": ["The ground in a 10-foot radius around the mouther is doughlike {@quickref difficult terrain||3}. Each creature that starts its turn in that area must succeed on a {@dc 10} Strength saving throw or have its speed reduced to 0 until the start of its next turn."]}, {"name": "Gibbering", "entries": ["The mouther babbles incoherently while it can see any creature and isn''t {@condition incapacitated}. Each creature that starts its turn within 20 feet of the mouther and can hear the gibbering must succeed on a {@dc 10} Wisdom saving throw. On a failure, the creature can''t take reactions until the start of its next turn and rolls a {@dice d8} to determine what it does during its turn. On a 1 to 4, the creature does nothing. On a 5 or 6, the creature takes no action or bonus action and uses all its movement to move in a randomly determined direction. On a 7 or 8, the creature makes a melee attack against a randomly determined creature within its reach or does nothing if it can''t make such an attack."]}]', '[{"name": "Multiattack", "entries": ["The gibbering mouther makes one bite attack and, if it can, uses its Blinding Spittle."]}, {"name": "Bites", "entries": ["{@atk mw} {@hit 2} to hit, reach 5 ft., one creature. {@h}17 ({@damage 5d6}) piercing damage. If the target is Medium or smaller, it must succeed on a {@dc 10} Strength saving throw or be knocked {@condition prone}. If the target is killed by this damage, it is absorbed into the mouther."]}, {"name": "Blinding Spittle {@recharge 5}", "entries": ["The mouther spits a chemical glob at a point it can see within 15 feet of it. The glob explodes in a blinding flash of light on impact. Each creature within 5 feet of the flash must succeed on a {@dc 13} Dexterity saving throw or be {@condition blinded} until the end of the mouther''s next turn."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('githyanki_knight', 'Githyanki Knight', 'humanoid', 'gith', 'M', 'L, E', 18, 91, '{"walk": 30}', 16, 14, 15, 14, 14, 15, '8', 0, 2, '{"con": "+5", "int": "+5", "wis": "+5"}', '{}', '[]', '[]', '[]', '[]', '["Gith"]', '[]', '[{"name": "Multiattack", "entries": ["The githyanki makes two silver greatsword attacks."]}, {"name": "Silver Greatsword", "entries": ["{@atk mw} {@hit 9} to hit, reach 5 ft., one target. {@h}13 ({@damage 2d6 + 6}) slashing damage plus 10 ({@damage 3d6}) psychic damage. This is a magic weapon attack. On a critical hit against a target in an astral body (as with the {@spell astral projection} spell), the githyanki can cut the silvery cord that tethers the target to its material body, instead of dealing damage."]}]', '[]', '[]', '[]');
