INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('githzerai_monk', 'Githzerai Monk', 'humanoid', 'gith', 'M', 'L, N', 14, 38, '{"walk": 30}', 12, 15, 12, 13, 14, 10, '2', 0, 2, '{"str": "+3", "dex": "+4", "int": "+3", "wis": "+4"}', '{"insight": "+4", "perception": "+4"}', '[]', '[]', '[]', '[]', '["Gith"]', '[{"name": "Psychic Defense", "entries": ["While the githzerai is wearing no armor and wielding no shield, its AC includes its Wisdom modifier."]}]', '[{"name": "Multiattack", "entries": ["The githzerai makes two unarmed strikes."]}, {"name": "Unarmed Strike", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}6 ({@damage 1d8 + 2}) bludgeoning damage plus 9 ({@damage 2d8}) psychic damage. This is a magic weapon attack."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('githzerai_zerth', 'Githzerai Zerth', 'humanoid', 'gith', 'M', 'L, N', 17, 84, '{"walk": 30}', 13, 18, 15, 16, 17, 12, '6', 0, 2, '{"str": "+4", "dex": "+7", "int": "+6", "wis": "+6"}', '{"arcana": "+6", "insight": "+6", "perception": "+6"}', '[]', '[]', '[]', '[]', '["Gith"]', '[{"name": "Psychic Defense", "entries": ["While the githzerai is wearing no armor and wielding no shield, its AC includes its Wisdom modifier."]}]', '[{"name": "Multiattack", "entries": ["The githzerai makes two unarmed strikes."]}, {"name": "Unarmed Strike", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}11 ({@damage 2d6 + 4}) bludgeoning damage plus 13 ({@damage 3d8}) psychic damage. This is a magic weapon attack."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('glabrezu', 'Glabrezu', 'fiend', 'demon', 'L', 'C, E', 17, 157, '{"walk": 40}', 20, 15, 21, 19, 17, 16, '9', 0, 2, '{"str": "+9", "con": "+9", "wis": "+7", "cha": "+7"}', '{}', '[]', '[]', '[]', '["truesight 120 ft."]', '["Abyssal", "telepathy 120 ft."]', '[{"name": "Magic Resistance", "entries": ["The glabrezu has advantage on saving throws against spells and other magical effects."]}]', '[{"name": "Multiattack", "entries": ["The glabrezu makes four attacks: two with its pincers and two with its fists. Alternatively, it makes two attacks with its pincers and casts one spell."]}, {"name": "Pincer", "entries": ["{@atk mw} {@hit 9} to hit, reach 10 ft., one target. {@h}16 ({@damage 2d10 + 5}) bludgeoning damage. If the target is a Medium or smaller creature, it is {@condition grappled} (escape {@dc 15}). The glabrezu has two pincers, each of which can grapple only one target."]}, {"name": "Fist", "entries": ["{@atk mw} {@hit 9} to hit, reach 5 ft., one target. {@h}7 ({@damage 2d4 + 2}) bludgeoning damage."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('gladiator', 'Gladiator', 'humanoid', 'any race', 'M', 'A', 16, 112, '{"walk": 30}', 18, 15, 16, 10, 12, 15, '5', 0, 2, '{"str": "+7", "dex": "+5", "con": "+6"}', '{"athletics": "+10", "intimidation": "+5"}', '[]', '[]', '[]', '[]', '["any one language (usually Common)"]', '[{"name": "Brave", "entries": ["The gladiator has advantage on saving throws against being {@condition frightened}."]}, {"name": "Brute", "entries": ["A melee weapon deals one extra die of its damage when the gladiator hits with it (included in the attack)."]}]', '[{"name": "Multiattack", "entries": ["The gladiator makes three melee attacks or two ranged attacks."]}, {"name": "Spear", "entries": ["{@atk mw,rw} {@hit 7} to hit, reach 5 ft. and range 20/60 ft., one target. {@h}11 ({@damage 2d6 + 4}) piercing damage, or 13 ({@damage 2d8 + 4}) piercing damage if used with two hands to make a melee attack."]}, {"name": "Shield Bash", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one creature. {@h}9 ({@damage 2d4 + 4}) bludgeoning damage. If the target is a Medium or smaller creature, it must succeed on a {@dc 15} Strength saving throw or be knocked {@condition prone}."]}]', '[]', '[]', '["urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('gnoll', 'Gnoll', 'humanoid', 'gnoll', 'M', 'C, E', 15, 22, '{"walk": 30}', 14, 12, 11, 6, 10, 7, '1/2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Gnoll"]', '[{"name": "Rampage", "entries": ["When the gnoll reduces a creature to 0 hit points with a melee attack on its turn, the gnoll can take a bonus action to move up to half its speed and make a bite attack."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one creature. {@h}4 ({@damage 1d4 + 2}) piercing damage."]}, {"name": "Spear", "entries": ["{@atk mw,rw} {@hit 4} to hit, reach 5 ft. or range 20/60 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage, or 6 ({@damage 1d8 + 2}) piercing damage if used with two hands to make a melee attack."]}, {"name": "Longbow", "entries": ["{@atk rw} {@hit 3} to hit, range 150/600 ft., one target. {@h}5 ({@damage 1d8 + 1}) piercing damage."]}]', '[]', '[]', '["grassland", "forest", "hill", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('gnoll_fang_of_yeenoghu', 'Gnoll Fang of Yeenoghu', 'fiend', 'gnoll', 'M', 'C, E', 14, 65, '{"walk": 30}', 17, 15, 15, 10, 11, 13, '4', 0, 2, '{"con": "+4", "wis": "+2", "cha": "+3"}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Abyssal", "Gnoll"]', '[{"name": "Rampage", "entries": ["When the gnoll reduces a creature to 0 hit points with a melee attack on its turn, the gnoll can take a bonus action to move up to half its speed and make a bite attack."]}]', '[{"name": "Multiattack", "entries": ["The gnoll makes three attacks: one with its bite and two with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one creature. {@h}6 ({@damage 1d6 + 3}) piercing damage, and the target must succeed on a {@dc 12} Constitution saving throw or take 7 ({@damage 2d6}) poison damage."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}7 ({@damage 1d8 + 3}) slashing damage."]}]', '[]', '[]', '["grassland", "forest", "hill", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('gnoll_pack_lord', 'Gnoll Pack Lord', 'humanoid', 'gnoll', 'M', 'C, E', 15, 49, '{"walk": 30}', 16, 14, 13, 8, 11, 9, '2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Gnoll"]', '[{"name": "Rampage", "entries": ["When the gnoll reduces a creature to 0 hit points with a melee attack on its turn, the gnoll can take a bonus action to move up to half its speed and make a bite attack."]}]', '[{"name": "Multiattack", "entries": ["The gnoll makes two attacks, either with its glaive or its longbow, and uses its Incite Rampage if it can."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one creature. {@h}5 ({@damage 1d4 + 3}) piercing damage."]}, {"name": "Glaive", "entries": ["{@atk mw} {@hit 5} to hit, reach 10 ft., one target. {@h}8 ({@damage 1d10 + 3}) slashing damage."]}, {"name": "Longbow", "entries": ["{@atk rw} {@hit 4} to hit, range 150/600 ft., one target. {@h}6 ({@damage 1d8 + 2}) piercing damage."]}, {"name": "Incite Rampage {@recharge 5}", "entries": ["One creature the gnoll can see within 30 feet of it can use its reaction to make a melee attack if it can hear the gnoll and has the Rampage trait."]}]', '[]', '[]', '["grassland", "forest", "hill", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('goat', 'Goat', 'beast', '', 'M', 'U', 10, 4, '{"walk": 40}', 12, 10, 11, 2, 10, 5, '0', 0, 2, '{}', '{}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Charge", "entries": ["If the goat moves at least 20 feet straight toward a target and then hits it with a ram attack on the same turn, the target takes an extra 2 ({@damage 1d4}) bludgeoning damage. If the target is a creature, it must succeed on a {@dc 10} Strength saving throw or be knocked {@condition prone}."]}, {"name": "Sure-Footed", "entries": ["The goat has advantage on Strength and Dexterity saving throws made against effects that would knock it {@condition prone}."]}]', '[{"name": "Ram", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}3 ({@damage 1d4 + 1}) bludgeoning damage."]}]', '[]', '[]', '["mountain", "grassland", "hill", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('goblin', 'Goblin', 'humanoid', 'goblinoid', 'S', 'N, E', 15, 7, '{"walk": 30}', 8, 14, 10, 10, 8, 8, '1/4', 0, 2, '{}', '{"stealth": "+6"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Common", "Goblin"]', '[{"name": "Nimble Escape", "entries": ["The goblin can take the Disengage or Hide action as a bonus action on each of its turns."]}]', '[{"name": "Scimitar", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d6 + 2}) slashing damage."]}, {"name": "Shortbow", "entries": ["{@atk rw} {@hit 4} to hit, range 80/320 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage."]}]', '[]', '[]', '["underdark", "grassland", "forest", "hill"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('goblin_boss', 'Goblin Boss', 'humanoid', 'goblinoid', 'S', 'N, E', 17, 21, '{"walk": 30}', 10, 14, 10, 10, 8, 10, '1', 0, 2, '{}', '{"stealth": "+6"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Common", "Goblin"]', '[{"name": "Nimble Escape", "entries": ["The goblin can take the Disengage or Hide action as a bonus action on each of its turns."]}]', '[{"name": "Multiattack", "entries": ["The goblin makes two attacks with its scimitar. The second attack has disadvantage."]}, {"name": "Scimitar", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d6 + 2}) slashing damage."]}, {"name": "Javelin", "entries": ["{@atk mw,rw} {@hit 2} to hit, reach 5 ft. or range 30/120 ft., one target. {@h}3 ({@damage 1d6}) piercing damage."]}]', '[]', '[]', '["underdark", "grassland", "forest", "hill"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('gold_dragon_wyrmling', 'Gold Dragon Wyrmling', 'dragon', '', 'M', 'L, G', 17, 60, '{"walk": 30, "fly": 60, "swim": 30}', 19, 14, 17, 14, 11, 16, '3', 0, 2, '{"dex": "+4", "con": "+5", "wis": "+2", "cha": "+5"}', '{"perception": "+4", "stealth": "+4"}', '[]', '[]', '[]', '["blindsight 10 ft.", "darkvision 60 ft."]', '["Draconic"]', '[{"name": "Amphibious", "entries": ["The dragon can breathe air and water."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}9 ({@damage 1d10 + 4}) piercing damage."]}, {"name": "Breath Weapons {@recharge 5}", "entries": ["The dragon uses one of the following breath weapons.", {"type": "list", "style": "list-hang-notitle", "items": [{"type": "item", "name": "Fire Breath", "entry": "The dragon exhales fire in a 15-foot cone. Each creature in that area must make a {@dc 13} Dexterity saving throw, taking 22 ({@damage 4d10}) fire damage on a failed save, or half as much damage on a successful one."}, {"type": "item", "name": "Weakening Breath", "entry": "The dragon exhales gas in a 15-foot cone. Each creature in that area must succeed on a {@dc 13} Strength saving throw or have disadvantage on Strength-based attack rolls, Strength checks, and Strength saving throws for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."}]}]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('gorgon', 'Gorgon', 'monstrosity', '', 'L', 'U', 19, 114, '{"walk": 40}', 20, 11, 18, 2, 12, 7, '5', 0, 2, '{}', '{"perception": "+4"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '[]', '[{"name": "Trampling Charge", "entries": ["If the gorgon moves at least 20 feet straight toward a creature and then hits it with a gore attack on the same turn, that target must succeed on a {@dc 16} Strength saving throw or be knocked {@condition prone}. If the target is {@condition prone}, the gorgon can make one attack with its hooves against it as a bonus action."]}]', '[{"name": "Gore", "entries": ["{@atk mw} {@hit 8} to hit, reach 5 ft., one target. {@h}18 ({@damage 2d12 + 5}) piercing damage."]}, {"name": "Hooves", "entries": ["{@atk mw} {@hit 8} to hit, reach 5 ft., one target. {@h}16 ({@damage 2d10 + 5}) bludgeoning damage."]}, {"name": "Petrifying Breath {@recharge 5}", "entries": ["The gorgon exhales petrifying gas in a 30-foot cone. Each creature in that area must succeed on a {@dc 13} Constitution saving throw. On a failed save, a target begins to turn to stone and is {@condition restrained}. The {@condition restrained} target must repeat the saving throw at the end of its next turn. On a success, the effect ends on the target. On a failure, the target is {@condition petrified} until freed by the  {@spell greater restoration} spell or other magic."]}]', '[]', '[]', '["grassland", "forest", "hill"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('goristro', 'Goristro', 'fiend', 'demon', 'H', 'C, E', 19, 310, '{"walk": 40}', 25, 11, 25, 6, 13, 14, '17', 0, 2, '{"str": "+13", "dex": "+6", "con": "+13", "wis": "+7"}', '{"perception": "+7"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Abyssal"]', '[{"name": "Charge", "entries": ["If the goristro moves at least 15 feet straight toward a target and then hits it with a gore attack on the same turn, the target takes an extra 38 ({@damage 7d10}) piercing damage. If the target is a creature, it must succeed on a {@dc 21} Strength saving throw or be pushed up to 20 feet away and knocked {@condition prone}."]}, {"name": "Labyrinthine Recall", "entries": ["The goristro can perfectly recall any path it has traveled."]}, {"name": "Magic Resistance", "entries": ["The goristro has advantage on saving throws against spells and other magical effects."]}, {"name": "Siege Monster", "entries": ["The goristro deals double damage to objects and structures."]}]', '[{"name": "Multiattack", "entries": ["The goristro makes three attacks: two with its fists and one with its hoof."]}, {"name": "Fist", "entries": ["{@atk mw} {@hit 13} to hit, reach 10 ft., one target. {@h}20 ({@damage 3d8 + 7}) bludgeoning damage."]}, {"name": "Hoof", "entries": ["{@atk mw} {@hit 13} to hit, reach 5 ft., one target. {@h}23 ({@damage 3d10 + 7}) bludgeoning damage. If the target is a creature, it must succeed on a {@dc 21} Strength saving throw or be knocked {@condition prone}."]}, {"name": "Gore", "entries": ["{@atk mw} {@hit 13} to hit, reach 10 ft., one target. {@h}45 ({@damage 7d10 + 7}) piercing damage."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('gray_ooze', 'Gray Ooze', 'ooze', '', 'M', 'U', 8, 22, '{"walk": 10, "climb": 10}', 12, 6, 16, 1, 6, 2, '1/2', 0, 2, '{}', '{"stealth": "+2"}', '[]', '[]', '[]', '["blindsight 60 ft. (blind beyond this radius)"]', '[]', '[{"name": "Amorphous", "entries": ["The ooze can move through a space as narrow as 1 inch wide without squeezing."]}, {"name": "Corrode Metal", "entries": ["Any nonmagical weapon made of metal that hits the ooze corrodes. After dealing damage, the weapon takes a permanent and cumulative \u22121 penalty to damage rolls. If its penalty drops to \u22125, the weapon is destroyed. Nonmagical ammunition made of metal that hits the ooze is destroyed after dealing damage.", "The ooze can eat through 2-inch-thick, nonmagical metal in 1 round."]}, {"name": "False Appearance", "entries": ["While the ooze remains motionless, it is indistinguishable from an oily pool or wet rock."]}]', '[{"name": "Pseudopod", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}4 ({@damage 1d6 + 1}) bludgeoning damage plus 7 ({@damage 2d6}) acid damage, and if the target is wearing nonmagical metal armor, its armor is partly corroded and takes a permanent and cumulative \u22121 penalty to the AC it offers. The armor is destroyed if the penalty reduces its AC to 10."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('gray_slaad', 'Gray Slaad', 'aberration', 'shapechanger', 'M', 'C, N', 18, 127, '{"walk": 30}', 17, 17, 16, 13, 8, 14, '9', 0, 2, '{}', '{"arcana": "+5", "perception": "+7"}', '[]', '[]', '[]', '["blindsight 60 ft.", "darkvision 60 ft."]', '["Slaad", "telepathy 60 ft."]', '[{"name": "Shapechanger", "entries": ["The slaad can use its action to polymorph into a Small or Medium humanoid, or back into its true form. Its statistics, other than its size, are the same in each form. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies."]}, {"name": "Magic Resistance", "entries": ["The slaad has advantage on saving throws against spells and other magical effects."]}, {"name": "Magic Weapons", "entries": ["The slaad''s weapon attacks are magical."]}, {"name": "Regeneration", "entries": ["The slaad regains 10 hit points at the start of its turn if it has at least 1 hit point."]}]', '[{"name": "Multiattack", "entries": ["The slaad makes three attacks: one with its bite and two with its claws or greatsword."]}, {"name": "Bite (Slaad Form Only)", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}6 ({@damage 1d6 + 3}) piercing damage."]}, {"name": "Claws (Slaad Form Only)", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}8 ({@damage 1d10 + 3}) slashing damage."]}, {"name": "Greatsword", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}10 ({@damage 2d6 + 3}) slashing damage."]}]', '[]', '[]', '["urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('green_dragon_wyrmling', 'Green Dragon Wyrmling', 'dragon', '', 'M', 'L, E', 17, 38, '{"walk": 30, "fly": 60, "swim": 30}', 15, 12, 13, 14, 11, 13, '2', 0, 2, '{"dex": "+3", "con": "+3", "wis": "+2", "cha": "+3"}', '{"perception": "+4", "stealth": "+3"}', '[]', '[]', '[]', '["blindsight 10 ft.", "darkvision 60 ft."]', '["Draconic"]', '[{"name": "Amphibious", "entries": ["The dragon can breathe air and water."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}7 ({@damage 1d10 + 2}) piercing damage plus 3 ({@damage 1d6}) poison damage."]}, {"name": "Poison Breath {@recharge 5}", "entries": ["The dragon exhales poisonous gas in a 15-foot cone. Each creature in that area must make a {@dc 11} Constitution saving throw, taking 21 ({@damage 6d6}) poison damage on a failed save, or half as much damage on a successful one."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('green_hag', 'Green Hag', 'fey', '', 'M', 'N, E', 17, 82, '{"walk": 30}', 18, 12, 16, 13, 14, 14, '{''cr'': ''3'', ''coven'': ''5''}', 0, 2, '{}', '{"arcana": "+3", "deception": "+4", "perception": "+4", "stealth": "+3"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Common", "Draconic", "Sylvan"]', '[{"name": "Amphibious", "entries": ["The hag can breathe air and water."]}, {"name": "Mimicry", "entries": ["The hag can mimic animal sounds and humanoid voices. A creature that hears the sounds can tell they are imitations with a successful {@dc 14} Wisdom ({@skill Insight}) check."]}]', '[{"name": "Claws", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}13 ({@damage 2d8 + 4}) slashing damage."]}, {"name": "Illusory Appearance", "entries": ["The hag covers herself and anything she is wearing or carrying with a magical illusion that makes her look like another creature of her general size and humanoid shape. The illusion ends if the hag takes a bonus action to end it or if she dies.", "The changes wrought by this effect fail to hold up to physical inspection. For example, the hag could appear to have smooth skin, but someone touching her would feel her rough flesh. Otherwise, a creature must take an action to visually inspect the illusion and succeed on a {@dc 20} Intelligence ({@skill Investigation}) check to discern that the hag is disguised."]}, {"name": "Invisible Passage", "entries": ["The hag magically turns {@condition invisible} until she attacks or casts a spell, or until her {@status concentration} ends (as if {@status concentration||concentrating} on a spell). While {@condition invisible}, she leaves no physical evidence of her passage, so she can be tracked only by magic. Any equipment she wears or carries is {@condition invisible} with her."]}]', '[]', '[]', '["forest", "swamp", "hill"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('green_slaad', 'Green Slaad', 'aberration', 'shapechanger', 'L', 'C, N', 16, 127, '{"walk": 30}', 18, 15, 16, 11, 8, 12, '8', 0, 2, '{}', '{"arcana": "+3", "perception": "+2"}', '[]', '[]', '[]', '["blindsight 30 ft.", "darkvision 60 ft."]', '["Slaad", "telepathy 60 ft."]', '[{"name": "Shapechanger", "entries": ["The slaad can use its action to polymorph into a Small or Medium humanoid, or back into its true form. Its statistics, other than its size, are the same in each form. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies."]}, {"name": "Magic Resistance", "entries": ["The slaad has advantage on saving throws against spells and other magical effects."]}, {"name": "Regeneration", "entries": ["The slaad regains 10 hit points at the start of its turn if it has at least 1 hit point."]}]', '[{"name": "Multiattack", "entries": ["The slaad makes three attacks: one with its bite and two with its claws or staff. Alternatively, it uses its Hurl Flame twice."]}, {"name": "Bite (Slaad Form Only)", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}11 ({@damage 2d6 + 4}) piercing damage."]}, {"name": "Claw (Slaad Form Only)", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}7 ({@damage 1d6 + 4}) slashing damage."]}, {"name": "Staff", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}11 ({@damage 2d6 + 4}) bludgeoning damage."]}, {"name": "Hurl Flame", "entries": ["{@atk rs} {@hit 4} to hit, range 60 ft., one target. {@h}10 ({@damage 3d6}) fire damage. The fire ignites flammable objects that aren''t being worn or carried."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('grell', 'Grell', 'aberration', '', 'M', 'N, E', 12, 55, '{"walk": 10, "fly": {"number": 30, "condition": "(hover)"}, "canHover": true}', 15, 14, 13, 12, 11, 9, '3', 0, 2, '{}', '{"perception": "+4", "stealth": "+6"}', '[]', '[]', '[]', '["blindsight 60 ft. (blind beyond this radius)"]', '["Grell"]', '[]', '[{"name": "Multiattack", "entries": ["The grell makes two attacks: one with its tentacles and one with its beak."]}, {"name": "Tentacles", "entries": ["{@atk mw} {@hit 4} to hit, reach 10 ft., one creature. {@h}7 ({@damage 1d10 + 2}) piercing damage, and the target must succeed on a {@dc 11} Constitution saving throw or be {@condition poisoned} for 1 minute. The {@condition poisoned} target is {@condition paralyzed}, and it can repeat the saving throw at the end of each of its turns, ending the effect on a success.", "The target is also {@condition grappled} (escape {@dc 15}). If the target is Medium or smaller, it is also {@condition restrained} until this grapple ends. While grappling the target, the grell has advantage on attack rolls against it and can ''t use this attack against other targets. When the grell moves, any Medium or smaller target it is grappling moves with it."]}, {"name": "Beak", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}7 ({@damage 2d4 + 2}) piercing damage."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('grick', 'Grick', 'monstrosity', '', 'M', 'N', 14, 27, '{"walk": 30, "climb": 30}', 14, 14, 11, 3, 14, 5, '2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '[]', '[{"name": "Stone Camouflage", "entries": ["The grick has advantage on Dexterity ({@skill Stealth}) checks made to hide in rocky terrain."]}]', '[{"name": "Multiattack", "entries": ["The grick makes one attack with its tentacles. If that attack hits, the grick can make one beak attack against the same target."]}, {"name": "Tentacles", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}9 ({@damage 2d6 + 2}) slashing damage."]}, {"name": "Beak", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage."]}]', '[]', '[]', '["underdark", "forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('grick_alpha', 'Grick Alpha', 'monstrosity', '', 'L', 'N', 18, 75, '{"walk": 30, "climb": 30}', 18, 16, 15, 4, 14, 9, '7', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '[]', '[{"name": "Stone Camouflage", "entries": ["The grick has advantage on Dexterity ({@skill Stealth}) checks made to hide in rocky terrain."]}]', '[{"name": "Multiattack", "entries": ["The grick makes two attacks: one with its tail and one with its tentacles. If it hits with its tentacles, the grick can make one beak attack against the same target."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 7} to hit, reach 10 ft., one target. {@h}11 ({@damage 2d6 + 4}) bludgeoning damage."]}, {"name": "Tentacles", "entries": ["{@atk mw} {@hit 7} to hit, reach 10 ft., one target. {@h}22 ({@damage 4d8 + 4}) slashing damage."]}, {"name": "Beak", "entries": ["{@atk mw} {@hit 7} to hit, reach 10 ft., one target. {@h}13 ({@damage 2d8 + 4}) piercing damage."]}]', '[]', '[]', '["underdark", "forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('griffon', 'Griffon', 'monstrosity', '', 'L', 'U', 12, 59, '{"walk": 30, "fly": 80}', 18, 15, 16, 2, 13, 8, '2', 0, 2, '{}', '{"perception": "+5"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '[]', '[{"name": "Keen Sight", "entries": ["The griffon has advantage on Wisdom ({@skill Perception}) checks that rely on sight."]}]', '[{"name": "Multiattack", "entries": ["The griffon makes two attacks: one with its beak and one with its claws."]}, {"name": "Beak", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}8 ({@damage 1d8 + 4}) piercing damage."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}11 ({@damage 2d6 + 4}) slashing damage."]}]', '[]', '[]', '["mountain", "grassland", "hill", "coastal", "arctic"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('grimlock', 'Grimlock', 'humanoid', 'grimlock', 'M', 'N, E', 11, 11, '{"walk": 30}', 16, 12, 12, 9, 8, 6, '1/4', 0, 2, '{}', '{"athletics": "+5", "perception": "+3", "stealth": "+3"}', '[]', '[]', '[]', '["blindsight 30 ft. or 10 ft. while deafened (blind beyond this radius)"]', '["Undercommon"]', '[{"name": "Blind Senses", "entries": ["The grimlock can''t use its blindsight while {@condition deafened} and unable to smell."]}, {"name": "Keen Hearing and Smell", "entries": ["The grimlock has advantage on Wisdom ({@skill Perception}) checks that rely on hearing or smell."]}, {"name": "Stone Camouflage", "entries": ["The grimlock has advantage on Dexterity ({@skill Stealth}) checks made to hide in rocky terrain."]}]', '[{"name": "Spiked Bone Club", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d4 + 3}) bludgeoning damage plus 2 ({@damage 1d4}) piercing damage."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('guard', 'Guard', 'humanoid', 'any race', 'M', 'A', 16, 11, '{"walk": 30}', 13, 12, 12, 10, 11, 10, '1/8', 0, 2, '{}', '{"perception": "+2"}', '[]', '[]', '[]', '[]', '["any one language (usually Common)"]', '[]', '[{"name": "Spear", "entries": ["{@atk mw,rw} {@hit 3} to hit, reach 5 ft. or range 20/60 ft., one target. {@h}4 ({@damage 1d6 + 1}) piercing damage, or 5 ({@damage 1d8 + 1}) piercing damage if used with two hands to make a melee attack."]}]', '[]', '[]', '["coastal", "mountain", "grassland", "hill", "urban", "forest", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('guardian_naga', 'Guardian Naga', 'monstrosity', '', 'L', 'L, G', 18, 127, '{"walk": 40}', 19, 18, 16, 16, 19, 18, '10', 0, 2, '{"dex": "+8", "con": "+7", "int": "+7", "wis": "+8", "cha": "+8"}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Celestial", "Common"]', '[{"name": "Rejuvenation", "entries": ["If it dies, the naga returns to life in {@dice 1d6} days and regains all its hit points. Only a {@spell wish} spell can prevent this trait from functioning."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 8} to hit, reach 10 ft., one creature. {@h}8 ({@damage 1d8 + 4}) piercing damage, and the target must make a {@dc 15} Constitution saving throw, taking 45 ({@damage 10d8}) poison damage on a failed save, or half as much damage on a successful one."]}, {"name": "Spit Poison", "entries": ["{@atk rw} {@hit 8} to hit, range 15/30 ft., one creature. {@h}The target must make a {@dc 15} Constitution saving throw, taking 45 ({@damage 10d8}) poison damage on a failed save, or half as much damage on a successful one."]}]', '[]', '[]', '["forest", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('gynosphinx', 'Gynosphinx', 'monstrosity', '', 'L', 'L, N', 17, 136, '{"walk": 40, "fly": 60}', 18, 15, 16, 18, 18, 18, '11', 0, 2, '{}', '{"arcana": "+12", "history": "+12", "perception": "+8", "religion": "+8"}', '[]', '[]', '[]', '["truesight 120 ft."]', '["Common", "Sphinx"]', '[{"name": "Inscrutable", "entries": ["The sphinx is immune to any effect that would sense its emotions or read its thoughts, as well as any divination spell that it refuses. Wisdom ({@skill Insight}) checks made to ascertain the sphinx''s intentions or sincerity have disadvantage."]}, {"name": "Magic Weapons", "entries": ["The sphinx''s weapon attacks are magical."]}]', '[{"name": "Multiattack", "entries": ["The sphinx makes two claw attacks."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 8} to hit, reach 5 ft., one target. {@h}13 ({@damage 2d8 + 4}) slashing damage."]}]', '[{"name": "Claw Attack", "entries": ["The sphinx makes one claw attack."]}, {"name": "Teleport (Costs 2 Actions)", "entries": ["The sphinx magically teleports, along with any equipment it is wearing or carrying, up to 120 feet to an unoccupied space it can see."]}, {"name": "Cast a Spell (Costs 3 Actions)", "entries": ["The sphinx casts a spell from its list of prepared spells, using a spell slot as normal."]}]', '[]', '["desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('half-ogre_(ogrillon)', 'Half-Ogre (Ogrillon)', 'giant', '', 'L', 'C, G, NY, E', 12, 30, '{"walk": 30}', 17, 10, 14, 7, 9, 10, '1', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Common", "Giant"]', '[]', '[{"name": "Battleaxe", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}12 ({@damage 2d8 + 3}) slashing damage, or 14 ({@damage 2d10 + 3}) slashing damage if used with two hands."]}, {"name": "Javelin", "entries": ["{@atk mw,rw} {@hit 5} to hit, reach 5 ft. or range 30/120 ft., one target. {@h}10 ({@damage 2d6 + 3}) piercing damage."]}]', '[]', '[]', '["underdark", "mountain", "forest", "hill", "urban", "desert", "arctic"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('half-red_dragon_veteran', 'Half-Red Dragon Veteran', 'humanoid', 'human', 'M', 'A', 18, 65, '{"walk": 30}', 16, 13, 14, 10, 11, 10, '5', 0, 2, '{}', '{"athletics": "+6", "perception": "+3"}', '[]', '[]', '[]', '["blindsight 10 ft.", "darkvision 60 ft."]', '["Common", "Draconic"]', '[]', '[{"name": "Multiattack", "entries": ["The veteran makes two longsword attacks. If it has a shortsword drawn, it can also make a shortsword attack."]}, {"name": "Longsword", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}7 ({@damage 1d8 + 3}) slashing damage, or 8 ({@damage 1d10 + 3}) slashing damage if used with two hands."]}, {"name": "Shortsword", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}6 ({@damage 1d6 + 3}) piercing damage."]}, {"name": "Heavy Crossbow", "entries": ["{@atk rw} {@hit 3} to hit, range 100/400 ft., one target. {@h}6 ({@damage 1d10 + 1}) piercing damage."]}, {"name": "Fire Breath {@recharge 5}", "entries": ["The veteran exhales fire in a 15-foot cone. Each creature in that area must make a {@dc 15} Dexterity saving throw, taking 24 ({@damage 7d6}) fire damage on a failed save, or half as much damage on a successful one."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('harpy', 'Harpy', 'monstrosity', '', 'M', 'C, E', 11, 38, '{"walk": 20, "fly": 40}', 12, 13, 12, 7, 10, 13, '1', 0, 2, '{}', '{}', '[]', '[]', '[]', '[]', '["Common"]', '[]', '[{"name": "Multiattack", "entries": ["The harpy makes two attacks: one with its claws and one with its club."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}6 ({@damage 2d4 + 1}) slashing damage."]}, {"name": "Club", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}3 ({@damage 1d4 + 1}) bludgeoning damage."]}, {"name": "Luring Song", "entries": ["The harpy sings a magical melody. Every humanoid and giant within 300 feet of the harpy that can hear the song must succeed on a {@dc 11} Wisdom saving throw or be {@condition charmed} until the song ends. The harpy must take a bonus action on its subsequent turns to continue singing. It can stop singing at any time. The song ends if the harpy is {@condition incapacitated}.", "While {@condition charmed} by the harpy, a target is {@condition incapacitated} and ignores the songs of other harpies. If the {@condition charmed} target is more than 5 feet away from the harpy, the target must move on its turn toward the harpy by the most direct route. It doesn''t avoid opportunity attacks, but before moving into damaging terrain, such as lava or a pit, and whenever it takes damage from a source other than the harpy, a target can repeat the saving throw. A creature can also repeat the saving throw at the end of each of its turns. If a creature''s saving throw is successful, the effect ends on it.", "A target that successfully saves is immune to this harpy''s song for the next 24 hours."]}]', '[]', '[]', '["mountain", "forest", "hill", "coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('hawk', 'Hawk', 'beast', '', 'T', 'U', 13, 1, '{"walk": 10, "fly": 60}', 5, 16, 8, 2, 14, 6, '0', 0, 2, '{}', '{"perception": "+4"}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Keen Sight", "entries": ["The hawk has advantage on Wisdom ({@skill Perception}) checks that rely on sight."]}]', '[{"name": "Talons", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}1 slashing damage."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('hell_hound', 'Hell Hound', 'fiend', '', 'M', 'L, E', 15, 45, '{"walk": 50}', 17, 12, 14, 6, 13, 6, '3', 0, 2, '{}', '{"perception": "+5"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["understands Infernal but can''t speak it"]', '[{"name": "Keen Hearing and Smell", "entries": ["The hound has advantage on Wisdom ({@skill Perception}) checks that rely on hearing or smell."]}, {"name": "Pack Tactics", "entries": ["The hound has advantage on an attack roll against a creature if at least one of the hound''s allies is within 5 feet of the creature and the ally isn''t {@condition incapacitated}."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}7 ({@damage 1d8 + 3}) piercing damage plus 7 ({@damage 2d6}) fire damage."]}, {"name": "Fire Breath {@recharge 5}", "entries": ["The hound exhales fire in a 15-foot cone. Each creature in that area must make a {@dc 12} Dexterity saving throw, taking 21 ({@damage 6d6}) fire damage on a failed save, or half as much damage on a successful one."]}]', '[]', '[]', '["underdark", "mountain"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('helmed_horror', 'Helmed Horror', 'construct', '', 'M', 'U', 20, 60, '{"walk": 30, "fly": 30}', 18, 13, 16, 10, 10, 10, '4', 0, 2, '{}', '{"perception": "+4"}', '[]', '[]', '[]', '["blindsight 60 ft. (blind beyond this radius)"]', '["understands the languages of its creator but can''t speak"]', '[{"name": "Magic Resistance", "entries": ["The helmed horror has advantage on saving throws against spells and other magical effects."]}, {"name": "Spell Immunity", "entries": ["The helmed horror is immune to three spells chosen by its creator. Typical immunities include {@spell fireball}, {@spell heat metal}, and {@spell lightning bolt}."]}]', '[{"name": "Multiattack", "entries": ["The helmed horror makes two longsword attacks."]}, {"name": "Longsword", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}8 ({@damage 1d8 + 4}) slashing damage, or 9 ({@damage 1d10 + 4}) slashing damage if used with two hands."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('hezrou', 'Hezrou', 'fiend', 'demon', 'L', 'C, E', 16, 136, '{"walk": 30}', 19, 17, 20, 5, 12, 13, '8', 0, 2, '{"str": "+7", "con": "+8", "wis": "+4"}', '{}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Abyssal", "telepathy 120 ft."]', '[{"name": "Magic Resistance", "entries": ["The hezrou has advantage on saving throws against spells and other magical effects."]}, {"name": "Stench", "entries": ["Any creature that starts its turn within 10 feet of the hezrou must succeed on a {@dc 14} Constitution saving throw or be {@condition poisoned} until the start of its next turn. On a successful saving throw, the creature is immune to the hezrou''s stench for 24 hours."]}]', '[{"name": "Multiattack", "entries": ["The hezrou makes three attacks: one with its bite and two with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}15 ({@damage 2d10 + 4}) piercing damage."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}11 ({@damage 2d6 + 4}) slashing damage."]}]', '[]', '[]', '[]');
