INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('hippogriff', 'Hippogriff', 'monstrosity', '', 'L', 'U', 11, 19, '{"walk": 40, "fly": 60}', 17, 13, 13, 2, 12, 8, '1', 0, 2, '{}', '{"perception": "+5"}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Keen Sight", "entries": ["The hippogriff has advantage on Wisdom ({@skill Perception}) checks that rely on sight."]}]', '[{"name": "Multiattack", "entries": ["The hippogriff makes two attacks: one with its beak and one with its claws."]}, {"name": "Beak", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}8 ({@damage 1d10 + 3}) piercing damage."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}10 ({@damage 2d6 + 3}) slashing damage."]}]', '[]', '[]', '["mountain", "grassland", "hill"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('hobgoblin', 'Hobgoblin', 'humanoid', 'goblinoid', 'M', 'L, E', 18, 11, '{"walk": 30}', 13, 12, 12, 10, 10, 9, '1/2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Common", "Goblin"]', '[{"name": "Martial Advantage", "entries": ["Once per turn, the hobgoblin can deal an extra 7 ({@damage 2d6}) damage to a creature it hits with a weapon attack if that creature is within 5 feet of an ally of the hobgoblin that isn''t {@condition incapacitated}."]}]', '[{"name": "Longsword", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d8 + 1}) slashing damage, or 6 ({@damage 1d10 + 1}) slashing damage if used with two hands."]}, {"name": "Longbow", "entries": ["{@atk rw} {@hit 3} to hit, range 150/600 ft., one target. {@h}5 ({@damage 1d8 + 1}) piercing damage."]}]', '[]', '[]', '["underdark", "grassland", "forest", "hill", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('hobgoblin_captain', 'Hobgoblin Captain', 'humanoid', 'goblinoid', 'M', 'L, E', 17, 39, '{"walk": 30}', 15, 14, 14, 12, 10, 13, '3', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Common", "Goblin"]', '[{"name": "Martial Advantage", "entries": ["Once per turn, the hobgoblin can deal an extra 10 ({@damage 3d6}) damage to a creature it hits with a weapon attack if that creature is within 5 feet of an ally of the hobgoblin that isn''t {@condition incapacitated}."]}]', '[{"name": "Multiattack", "entries": ["The hobgoblin makes two greatsword attacks."]}, {"name": "Greatsword", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}9 ({@damage 2d6 + 2}) slashing damage."]}, {"name": "Javelin", "entries": ["{@atk mw,rw} {@hit 4} to hit, reach 5 ft. or range 30/120 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage."]}, {"name": "Leadership (Recharges after a Short or Long Rest)", "entries": ["For 1 minute, the hobgoblin can utter a special command or warning whenever a nonhostile creature that it can see within 30 feet of it makes an attack roll or a saving throw. The creature can add a {@dice d4} to its roll provided it can hear and understand the hobgoblin. A creature can benefit from only one Leadership die at a time. This effect ends if the hobgoblin is {@condition incapacitated}."]}]', '[]', '[]', '["underdark", "grassland", "forest", "hill", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('hobgoblin_warlord', 'Hobgoblin Warlord', 'humanoid', 'goblinoid', 'M', 'L, E', 20, 97, '{"walk": 30}', 16, 14, 16, 14, 11, 15, '6', 0, 2, '{"int": "+5", "wis": "+3", "cha": "+5"}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Common", "Goblin"]', '[{"name": "Martial Advantage", "entries": ["Once per turn, the hobgoblin can deal an extra 14 ({@damage 4d6}) damage to a creature it hits with a weapon attack if that creature is within 5 feet of an ally of the hobgoblin that isn''t {@condition incapacitated}."]}]', '[{"name": "Multiattack", "entries": ["The hobgoblin makes three melee attacks. Alternatively, it can make two ranged attacks with its javelins."]}, {"name": "Longsword", "entries": ["{@atk mw} {@hit 9} to hit, reach 5 ft., one target. {@h}7 ({@damage 1d8 + 3}) slashing damage, or 8 ({@damage 1d10 + 3}) slashing damage if used with two hands."]}, {"name": "Shield Bash", "entries": ["{@atk mw} {@hit 9} to hit, reach 5 ft., one creature. {@h}5 ({@damage 1d4 + 3}) bludgeoning damage. If the target is Large or smaller, it must succeed on a {@dc 14} Strength saving throw or be knocked {@condition prone}."]}, {"name": "Javelin", "entries": ["{@atk mw,rw} {@hit 9} to hit, reach 5 ft. or range 30/120 ft., one target. {@h}6 ({@damage 1d6 + 3}) piercing damage."]}, {"name": "Leadership (Recharges after a Short or Long Rest)", "entries": ["For 1 minute, the hobgoblin can utter a special command or warning whenever a nonhostile creature that it can see within 30 feet of it makes an attack roll or a saving throw. The creature can add a {@dice d4} to its roll provided it can hear and understand the hobgoblin. A creature can benefit from only one Leadership die at a time. This effect ends if the hobgoblin is {@condition incapacitated}."]}]', '[]', '[]', '["underdark", "grassland", "forest", "hill", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('homunculus', 'Homunculus', 'construct', '', 'T', 'N', 13, 5, '{"walk": 20, "fly": 40}', 4, 15, 11, 10, 10, 7, '0', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["understands the languages of its creator but can''t speak"]', '[{"name": "Telepathic Bond", "entries": ["While the homunculus is on the same plane of existence as its master, it can magically convey what it senses to its master, and the two can communicate telepathically."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one creature. {@h}1 piercing damage, and the target must succeed on a {@dc 10} Constitution saving throw or be {@condition poisoned} for 1 minute. If the saving throw fails by 5 or more, the target is instead {@condition poisoned} for 5 ({@dice 1d10}) minutes and {@condition unconscious} while {@condition poisoned} in this way."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('hook_horror', 'Hook Horror', 'monstrosity', '', 'L', 'N', 15, 75, '{"walk": 30, "climb": 30}', 18, 10, 15, 6, 12, 7, '3', 0, 2, '{}', '{"perception": "+3"}', '[]', '[]', '[]', '["blindsight 60 ft.", "darkvision 120 ft."]', '["Hook Horror"]', '[{"name": "Echolocation", "entries": ["The hook horror can''t use its blindsight while {@condition deafened}."]}, {"name": "Keen Hearing", "entries": ["The hook horror has advantage on Wisdom ({@skill Perception}) checks that rely on hearing."]}]', '[{"name": "Multiattack", "entries": ["The hook horror makes two hook attacks."]}, {"name": "Hook", "entries": ["{@atk mw} {@hit 6} to hit, reach 10 ft., one target. {@h}11 ({@damage 2d6 + 4}) piercing damage."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('horned_devil', 'Horned Devil', 'fiend', 'devil', 'L', 'L, E', 18, 178, '{"walk": 20, "fly": 60}', 22, 17, 21, 12, 16, 17, '11', 0, 2, '{"str": "+10", "dex": "+7", "wis": "+7", "cha": "+7"}', '{}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Infernal", "telepathy 120 ft."]', '[{"name": "Devil''s Sight", "entries": ["Magical darkness doesn''t impede the devil''s darkvision."]}, {"name": "Magic Resistance", "entries": ["The devil has advantage on saving throws against spells and other magical effects."]}]', '[{"name": "Multiattack", "entries": ["The devil makes three melee attacks: two with its fork and one with its tail. It can use Hurl Flame in place of any melee attack."]}, {"name": "Fork", "entries": ["{@atk mw} {@hit 10} to hit, reach 10 ft., one target. {@h}15 ({@damage 2d8 + 6}) piercing damage."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 10} to hit, reach 10 ft., one target. {@h}10 ({@damage 1d8 + 6}) piercing damage. If the target is a creature other than an undead or a construct, it must succeed on a {@dc 17} Constitution saving throw or lose 10 ({@dice 3d6}) hit points at the start of each of its turns due to an infernal wound. Each time the devil hits the wounded target with this attack, the damage dealt by the wound increases by 10 ({@damage 3d6}). Any creature can take an action to stanch the wound with a successful {@dc 12} Wisdom ({@skill Medicine}) check. The wound also closes if the target receives magical healing."]}, {"name": "Hurl Flame", "entries": ["{@atk rs} {@hit 7} to hit, range 150 ft., one target. {@h}14 ({@damage 4d6}) fire damage. If the target is a flammable object that isn''t being worn or carried, it also catches fire."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('hunter_shark', 'Hunter Shark', 'beast', '', 'L', 'U', 12, 45, '{"swim": 40}', 18, 13, 15, 1, 10, 4, '2', 0, 2, '{}', '{"perception": "+2"}', '[]', '[]', '[]', '["blindsight 30 ft."]', '[]', '[{"name": "Blood Frenzy", "entries": ["The shark has advantage on melee attack rolls against any creature that doesn''t have all its hit points."]}, {"name": "Water Breathing", "entries": ["The shark can breathe only underwater."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}13 ({@damage 2d8 + 4}) piercing damage."]}]', '[]', '[]', '["underwater"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('hydra', 'Hydra', 'monstrosity', '', 'H', 'U', 15, 172, '{"walk": 30, "swim": 30}', 20, 12, 20, 2, 10, 7, '8', 0, 2, '{}', '{"perception": "+6"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '[]', '[{"name": "Hold Breath", "entries": ["The hydra can hold its breath for 1 hour."]}, {"name": "Multiple Heads", "entries": ["The hydra has five heads. While it has more than one head, the hydra has advantage on saving throws against being {@condition blinded}, {@condition charmed}, {@condition deafened}, {@condition frightened}, {@condition stunned}, and knocked {@condition unconscious}.", "Whenever the hydra takes 25 or more damage in a single turn, one of its heads dies. If all its heads die, the hydra dies.", "At the end of its turn, it grows two heads for each of its heads that died since its last turn, unless it has taken fire damage since its last turn. The hydra regains 10 hit points for each head regrown in this way."]}, {"name": "Reactive Heads", "entries": ["For each head the hydra has beyond one, it gets an extra reaction that can be used only for opportunity attacks."]}, {"name": "Wakeful", "entries": ["While the hydra sleeps, at least one of its heads is awake."]}]', '[{"name": "Multiattack", "entries": ["The hydra makes as many bite attacks as it has heads."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 8} to hit, reach 10 ft., one target. {@h}10 ({@damage 1d10 + 5}) piercing damage."]}]', '[]', '[]', '["swamp"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('hyena', 'Hyena', 'beast', '', 'M', 'U', 11, 5, '{"walk": 50}', 11, 13, 12, 2, 12, 5, '0', 0, 2, '{}', '{"perception": "+3"}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Pack Tactics", "entries": ["The hyena has advantage on an attack roll against a creature if at least one of the hyena''s allies is within 5 feet of the creature and the ally isn''t {@condition incapacitated}."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 2} to hit, reach 5 ft., one target. {@h}3 ({@damage 1d6}) piercing damage."]}]', '[]', '[]', '["grassland", "forest", "hill", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('ice_devil', 'Ice Devil', 'fiend', 'devil', 'L', 'L, E', 18, 180, '{"walk": 40}', 21, 14, 18, 18, 15, 18, '14', 0, 2, '{"dex": "+7", "con": "+9", "wis": "+7", "cha": "+9"}', '{}', '[]', '[]', '[]', '["blindsight 60 ft.", "darkvision 120 ft."]', '["Infernal", "telepathy 120 ft."]', '[{"name": "Devil''s Sight", "entries": ["Magical darkness doesn''t impede the devil''s darkvision."]}, {"name": "Magic Resistance", "entries": ["The devil has advantage on saving throws against spells and other magical effects."]}]', '[{"name": "Multiattack", "entries": ["The devil makes three attacks: one with its bite, one with its claws, and one with its tail."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 10} to hit, reach 5 ft., one target. {@h}12 ({@damage 2d6 + 5}) piercing damage plus 10 ({@damage 3d6}) cold damage."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 10} to hit, reach 5 ft., one target. {@h}10 ({@damage 2d4 + 5}) slashing damage plus 10 ({@damage 3d6}) cold damage."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 10} to hit, reach 10 ft., one target. {@h}12 ({@damage 2d6 + 5}) bludgeoning damage plus 10 ({@damage 3d6}) cold damage."]}, {"name": "Wall of Ice {@recharge}", "entries": ["The devil magically forms an opaque wall of ice on a solid surface it can see within 60 feet of it. The wall is 1 foot thick and up to 30 feet long and 10 feet high, or it''s a hemispherical dome up to 20 feet in diameter.", "When the wall appears, each creature in its space is pushed out of it by the shortest route. The creature chooses which side of the wall to end up on, unless the creature is {@condition incapacitated}. The creature then makes a {@dc 17} Dexterity saving throw, taking 35 ({@damage 10d6}) cold damage on a failed save, or half as much damage on a successful one.", "The wall lasts for 1 minute or until the devil is {@condition incapacitated} or dies. The wall can be damaged and breached; each 10-foot section has AC 5, 30 hit points, vulnerability to fire damage, and immunity to acid, cold, necrotic, poison, and psychic damage. If a section is destroyed, it leaves behind a sheet of frigid air in the space the wall occupied. Whenever a creature finishes moving through the frigid air on a turn, willingly or otherwise, the creature must make a {@dc 17} Constitution saving throw, taking 17 ({@damage 5d6}) cold damage on a failed save, or half as much damage on a successful one. The frigid air dissipates when the rest of the wall vanishes."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('ice_mephit', 'Ice Mephit', 'elemental', '', 'S', 'N, E', 11, 21, '{"walk": 30, "fly": 30}', 7, 13, 10, 9, 11, 12, '1/2', 0, 2, '{}', '{"perception": "+2", "stealth": "+3"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Aquan", "Auran"]', '[{"name": "Death Burst", "entries": ["When the mephit dies, it explodes in a burst of jagged ice. Each creature within 5 feet of it must make a {@dc 10} Dexterity saving throw, taking 4 ({@damage 1d8}) slashing damage on a failed save, or half as much damage on a successful one."]}, {"name": "False Appearance", "entries": ["While the mephit remains motionless, it is indistinguishable from an ordinary shard of ice."]}]', '[{"name": "Claws", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one creature. {@h}3 ({@damage 1d4 + 1}) slashing damage plus 2 ({@damage 1d4}) cold damage."]}, {"name": "Frost Breath {@recharge}", "entries": ["The mephit exhales a 15-foot cone of cold air. Each creature in that area must succeed on a {@dc 10} Dexterity saving throw, taking 5 ({@damage 2d4}) cold damage on a failed save, or half as much damage on a successful one."]}]', '[]', '[]', '["arctic"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('imp', 'Imp', 'fiend', 'devil', 'T', 'L, E', 13, 10, '{"walk": 20, "fly": 40}', 6, 17, 13, 11, 12, 14, '1', 0, 2, '{}', '{"deception": "+4", "insight": "+3", "persuasion": "+4", "stealth": "+5"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Infernal", "Common"]', '[{"name": "Shapechanger", "entries": ["The imp can use its action to polymorph into a beast form that resembles a rat (speed 20 ft.), a raven (20 ft., fly 60 ft.), or a spider (20 ft., climb 20 ft.), or back into its true form. Its statistics are the same in each form, except for the speed changes noted. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies."]}, {"name": "Devil''s Sight", "entries": ["Magical darkness doesn''t impede the imp''s darkvision."]}, {"name": "Magic Resistance", "entries": ["The imp has advantage on saving throws against spells and other magical effects."]}]', '[{"name": "Sting (Bite in Beast Form)", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d4 + 3}) piercing damage, and the target must make a {@dc 11} Constitution saving throw, taking 10 ({@damage 3d6}) poison damage on a failed save, or half as much damage on a successful one."]}, {"name": "Invisibility", "entries": ["The imp magically turns {@condition invisible} until it attacks, or until its {@status concentration} ends (as if {@status concentration||concentrating} on a spell). Any equipment the imp wears or carries is {@condition invisible} with it."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('incubus', 'Incubus', 'fiend', 'shapechanger', 'M', 'N, E', 15, 66, '{"walk": 30, "fly": 60}', 8, 17, 13, 15, 12, 20, '4', 0, 2, '{}', '{"deception": "+9", "insight": "+5", "perception": "+5", "persuasion": "+9", "stealth": "+7"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Abyssal", "Common", "Infernal", "telepathy 60 ft."]', '[{"name": "Telepathic Bond", "entries": ["The fiend ignores the range restriction on its telepathy when communicating with a creature it has {@condition charmed}. The two don''t even need to be on the same plane of existence."]}, {"name": "Shapechanger", "entries": ["The fiend can use its action to polymorph into a Small or Medium humanoid, or back into its true form. Without wings, the fiend loses its flying speed. Other than its size and speed, its statistics are the same in each form. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies."]}]', '[{"name": "Claw (Fiend Form Only)", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}6 ({@damage 1d6 + 3}) slashing damage."]}, {"name": "Charm", "entries": ["One humanoid the fiend can see within 30 feet of it must succeed on a {@dc 15} Wisdom saving throw or be magically {@condition charmed} for 1 day. The {@condition charmed} target obeys the fiend''s verbal or telepathic commands. If the target suffers any harm or receives a suicidal command, it can repeat the saving throw, ending the effect on a success. If the target successfully saves against the effect, or if the effect on it ends, the target is immune to this fiend''s Charm for the next 24 hours.", "The fiend can have only one target {@condition charmed} at a time. If it charms another, the effect on the previous target ends."]}, {"name": "Draining Kiss", "entries": ["The fiend kisses a creature {@condition charmed} by it or a willing creature. The target must make a {@dc 15} Constitution saving throw against this magic, taking 32 ({@damage 5d10 + 5}) psychic damage on a failed save, or half as much damage on a successful one. The target''s hit point maximum is reduced by an amount equal to the damage taken. This reduction lasts until the target finishes a long rest. The target dies if this effect reduces its hit point maximum to 0."]}, {"name": "Etherealness", "entries": ["The fiend magically enters the Ethereal Plane from the Material Plane, or vice versa."]}]', '[]', '[]', '["urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('intellect_devourer', 'Intellect Devourer', 'aberration', '', 'T', 'L, E', 12, 21, '{"walk": 40}', 6, 14, 13, 12, 11, 10, '2', 0, 2, '{}', '{"perception": "+2", "stealth": "+4"}', '[]', '[]', '[]', '["blindsight 60 ft. (blind beyond this radius)"]', '["understands Deep Speech but can''t speak", "telepathy 60 ft."]', '[{"name": "Detect Sentience", "entries": ["The intellect devourer can sense the presence and location of any creature within 300 feet of it that has an Intelligence of 3 or higher, regardless of interposing barriers, unless the creature is protected by a {@spell mind blank} spell."]}]', '[{"name": "Multiattack", "entries": ["The intellect devourer makes one attack with its claws and uses Devour Intellect."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}7 ({@damage 2d4 + 2}) slashing damage."]}, {"name": "Devour Intellect", "entries": ["The intellect devourer targets one creature it can see within 10 feet of it that has a brain. The target must succeed on a {@dc 12} Intelligence saving throw against this magic or take 11 ({@damage 2d10}) psychic damage. Also on a failure, roll {@dice 3d6}: If the total equals or exceeds the target''s Intelligence score, that score is reduced to 0. The target is {@condition stunned} until it regains at least one point of Intelligence."]}, {"name": "Body Thief", "entries": ["The intellect devourer initiates an Intelligence contest with an {@condition incapacitated} humanoid within 5 feet of it that isn''t protected by {@spell protection from evil and good}. If it wins the contest, the intellect devourer magically consumes the target''s brain, teleports into the target''s skull, and takes control of the target''s body. While inside a creature, the intellect devourer has {@quickref Cover||3||total cover} against attacks and other effects originating outside its host. The intellect devourer retains its Intelligence, Wisdom, and Charisma scores, as well as its understanding of Deep Speech, its telepathy, and its traits. It otherwise adopts the target''s statistics. It knows everything the creature knew, including spells and languages.", "If the host body dies, the intellect devourer must leave it. A {@spell protection from evil and good} spell cast on the body drives the intellect devourer out. The intellect devourer is also forced out if the target regains its devoured brain by means of a {@spell wish}. By spending 5 feet of its movement, the intellect devourer can voluntarily leave the body, teleporting to the nearest unoccupied space within 5 feet of it. The body then dies, unless its brain is restored within 1 round."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('invisible_stalker', 'Invisible Stalker', 'elemental', '', 'M', 'N', 14, 104, '{"walk": 50, "fly": {"number": 50, "condition": "(hover)"}, "canHover": true}', 16, 19, 14, 10, 15, 11, '6', 0, 2, '{}', '{"perception": "+8", "stealth": "+10"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Auran", "understands Common but doesn''t speak it"]', '[{"name": "Invisibility", "entries": ["The stalker is {@condition invisible}."]}, {"name": "Faultless Tracker", "entries": ["The stalker is given a quarry by its summoner. The stalker knows the direction and distance to its quarry as long as the two of them are on the same plane of existence. The stalker also knows the location of its summoner."]}]', '[{"name": "Multiattack", "entries": ["The stalker makes two slam attacks."]}, {"name": "Slam", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}10 ({@damage 2d6 + 3}) bludgeoning damage."]}]', '[]', '[]', '["urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('iron_golem', 'Iron Golem', 'construct', '', 'L', 'U', 20, 210, '{"walk": 30}', 24, 9, 20, 3, 11, 1, '16', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["understands the languages of its creator but can''t speak"]', '[{"name": "Fire Absorption", "entries": ["Whenever the golem is subjected to fire damage, it takes no damage and instead regains a number of hit points equal to the fire damage dealt."]}, {"name": "Immutable Form", "entries": ["The golem is immune to any spell or effect that would alter its form."]}, {"name": "Magic Resistance", "entries": ["The golem has advantage on saving throws against spells and other magical effects."]}, {"name": "Magic Weapons", "entries": ["The golem''s weapon attacks are magical."]}]', '[{"name": "Multiattack", "entries": ["The golem makes two melee attacks."]}, {"name": "Slam", "entries": ["{@atk mw} {@hit 13} to hit, reach 5 ft., one target. {@h}20 ({@damage 3d8 + 7}) bludgeoning damage."]}, {"name": "Sword", "entries": ["{@atk mw} {@hit 13} to hit, reach 10 ft., one target. {@h}23 ({@damage 3d10 + 7}) slashing damage."]}, {"name": "Poison Breath {@recharge 5}", "entries": ["The golem exhales poisonous gas in a 15-foot cone. Each creature in that area must make a {@dc 19} Constitution saving throw, taking 45 ({@damage 10d8}) poison damage on a failed save, or half as much damage on a successful one."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('jackal', 'Jackal', 'beast', '', 'S', 'U', 12, 3, '{"walk": 40}', 8, 15, 11, 3, 12, 6, '0', 0, 2, '{}', '{"perception": "+3"}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Keen Hearing and Smell", "entries": ["The jackal has advantage on Wisdom ({@skill Perception}) checks that rely on hearing or smell."]}, {"name": "Pack Tactics", "entries": ["The jackal has advantage on an attack roll against a creature if at least one of the jackal''s allies is within 5 feet of the creature and the ally isn''t {@condition incapacitated}."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 1} to hit, reach 5 ft., one target. {@h}1 ({@damage 1d4 - 1}) piercing damage."]}]', '[]', '[]', '["grassland", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('jackalwere', 'Jackalwere', 'humanoid', 'shapechanger', 'M', 'C, E', 12, 18, '{"walk": 40}', 11, 15, 11, 13, 11, 10, '1/2', 0, 2, '{}', '{"deception": "+4", "perception": "+2", "stealth": "+4"}', '[]', '[]', '[]', '[]', '["Common (can''t speak in jackal form)"]', '[{"name": "Shapechanger", "entries": ["The jackalwere can use its action to polymorph into a specific Medium human or a jackal-humanoid hybrid, or back into its true form (that of a Small jackal). Other than its size, its statistics are the same in each form. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies."]}, {"name": "Keen Hearing and Smell", "entries": ["The jackalwere has advantage on Wisdom ({@skill Perception}) checks that rely on hearing or smell."]}, {"name": "Pack Tactics", "entries": ["The jackalwere has advantage on an attack roll against a creature if at least one of the jackalwere''s allies is within 5 feet of the creature and the ally isn''t {@condition incapacitated}."]}]', '[{"name": "Bite (Jackal or Hybrid Form Only)", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}4 ({@damage 1d4 + 2}) piercing damage."]}, {"name": "Scimitar (Human or Hybrid Form Only)", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d6 + 2}) slashing damage."]}, {"name": "Sleep Gaze", "entries": ["The jackalwere gazes at one creature it can see within 30 feet of it. The target must make a {@dc 10} Wisdom saving throw. On a failed save, the target succumbs to a magical slumber, falling {@condition unconscious} for 10 minutes or until someone uses an action to shake the target awake. A creature that successfully saves against the effect is immune to this jackalwere''s gaze for the next 24 hours. Undead and creatures immune to being {@condition charmed} aren''t affected by it."]}]', '[]', '[]', '["grassland", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('kenku', 'Kenku', 'humanoid', 'kenku', 'M', 'C, N', 13, 13, '{"walk": 30}', 10, 16, 10, 11, 10, 10, '1/4', 0, 2, '{}', '{"deception": "+4", "perception": "+2", "stealth": "+5"}', '[]', '[]', '[]', '[]', '["understands Auran and Common but speaks only through the use of its Mimicry trait"]', '[{"name": "Ambusher", "entries": ["In the first round of a combat, the kenku has advantage on attack rolls against any creature it {@status surprised}."]}, {"name": "Mimicry", "entries": ["The kenku can mimic any sounds it has heard, including voices. A creature that hears the sounds can tell they are imitations with a successful {@dc 14} Wisdom ({@skill Insight}) check."]}]', '[{"name": "Shortsword", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}6 ({@damage 1d6 + 3}) piercing damage."]}, {"name": "Shortbow", "entries": ["{@atk rw} {@hit 5} to hit, range 80/320 ft., one target. {@h}6 ({@damage 1d6 + 3}) piercing damage."]}]', '[]', '[]', '["forest", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('killer_whale', 'Killer Whale', 'beast', '', 'H', 'U', 12, 90, '{"swim": 60}', 19, 10, 13, 3, 12, 7, '3', 0, 2, '{}', '{"perception": "+3"}', '[]', '[]', '[]', '["blindsight 120 ft."]', '[]', '[{"name": "Echolocation", "entries": ["The whale can''t use its blindsight while {@condition deafened}."]}, {"name": "Hold Breath", "entries": ["The whale can hold its breath for 30 minutes."]}, {"name": "Keen Hearing", "entries": ["The whale has advantage on Wisdom ({@skill Perception}) checks that rely on hearing."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}21 ({@damage 5d6 + 4}) piercing damage."]}]', '[]', '[]', '["underwater"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('knight', 'Knight', 'humanoid', 'any race', 'M', 'A', 18, 52, '{"walk": 30}', 16, 11, 14, 11, 11, 15, '3', 0, 2, '{"con": "+4", "wis": "+2"}', '{}', '[]', '[]', '[]', '[]', '["any one language (usually Common)"]', '[{"name": "Brave", "entries": ["The knight has advantage on saving throws against being {@condition frightened}."]}]', '[{"name": "Multiattack", "entries": ["The knight makes two melee attacks."]}, {"name": "Greatsword", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}10 ({@damage 2d6 + 3}) slashing damage."]}, {"name": "Heavy Crossbow", "entries": ["{@atk rw} {@hit 2} to hit, range 100/400 ft., one target. {@h}5 ({@damage 1d10}) piercing damage."]}, {"name": "Leadership (Recharges after a Short or Long Rest)", "entries": ["For 1 minute, the knight can utter a special command or warning whenever a nonhostile creature that it can see within 30 feet of it makes an attack roll or a saving throw. The creature can add a {@dice d4} to its roll provided it can hear and understand the knight. A creature can benefit from only one Leadership die at a time. This effect ends if the knight is {@condition incapacitated}."]}]', '[]', '[]', '["urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('kobold', 'Kobold', 'humanoid', 'kobold', 'S', 'L, E', 12, 5, '{"walk": 30}', 7, 15, 9, 8, 7, 8, '1/8', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Common", "Draconic"]', '[{"name": "Sunlight Sensitivity", "entries": ["While in sunlight, the kobold has disadvantage on attack rolls, as well as on Wisdom ({@skill Perception}) checks that rely on sight."]}, {"name": "Pack Tactics", "entries": ["The kobold has advantage on an attack roll against a creature if at least one of the kobold''s allies is within 5 feet of the creature and the ally isn''t {@condition incapacitated}."]}]', '[{"name": "Dagger", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}4 ({@damage 1d4 + 2}) piercing damage."]}, {"name": "Sling", "entries": ["{@atk rw} {@hit 4} to hit, range 30/120 ft., one target. {@h}4 ({@damage 1d4 + 2}) bludgeoning damage."]}]', '[]', '[]', '["forest", "swamp", "hill", "urban", "desert", "coastal", "arctic", "mountain", "underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('kraken', 'Kraken', 'monstrosity', 'titan', 'G', 'C, E', 18, 472, '{"walk": 20, "swim": 60}', 30, 11, 25, 22, 18, 20, '23', 0, 2, '{"str": "+17", "dex": "+7", "con": "+14", "int": "+13", "wis": "+11"}', '{}', '[]', '[]', '[]', '["truesight 120 ft."]', '["Abyssal", "Celestial", "Infernal", "Primordial", "telepathy 120 ft. but can''t speak"]', '[{"name": "Amphibious", "entries": ["The kraken can breathe air and water."]}, {"name": "Freedom of Movement", "entries": ["The kraken ignores {@quickref difficult terrain||3}, and magical effects can''t reduce its speed or cause it to be {@condition restrained}. It can spend 5 feet of movement to escape from nonmagical restraints or being {@condition grappled}."]}, {"name": "Siege Monster", "entries": ["The kraken deals double damage to objects and structures."]}]', '[{"name": "Multiattack", "entries": ["The kraken makes three tentacle attacks, each of which it can replace with one use of Fling."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 17} to hit, reach 5 ft., one target. {@h}23 ({@damage 3d8 + 10}) piercing damage. If the target is a Large or smaller creature {@condition grappled} by the kraken, that creature is swallowed, and the grapple ends. While swallowed, the creature is {@condition blinded} and {@condition restrained}, it has {@quickref Cover||3||total cover} against attacks and other effects outside the kraken, and it takes 42 ({@damage 12d6}) acid damage at the start of each of the kraken''s turns. If the kraken takes 50 damage or more on a single turn from a creature inside it, the kraken must succeed on a {@dc 25} Constitution saving throw at the end of that turn or regurgitate all swallowed creatures, which fall {@condition prone} in a space within 10 feet of the kraken. If the kraken dies, a swallowed creature is no longer {@condition restrained} by it and can escape from the corpse using 15 feet of movement, exiting {@condition prone}."]}, {"name": "Tentacle", "entries": ["{@atk mw} {@hit 17} to hit, reach 30 ft., one target. {@h}20 ({@damage 3d6 + 10}) bludgeoning damage, and the target is {@condition grappled} (escape {@dc 18}). Until this grapple ends, the target is {@condition restrained}. The kraken has ten tentacles, each of which can grapple one target."]}, {"name": "Fling", "entries": ["One Large or smaller object held or creature {@condition grappled} by the kraken is thrown up to 60 feet in a random direction and knocked {@condition prone}. If a thrown target strikes a solid surface, the target takes 3 ({@damage 1d6}) bludgeoning damage for every 10 feet it was thrown. If the target is thrown at another creature, that creature must succeed on a {@dc 18} Dexterity saving throw or take the same damage and be knocked {@condition prone}."]}, {"name": "Lightning Storm", "entries": ["The kraken magically creates three bolts of lightning, each of which can strike a target the kraken can see within 120 feet of it. A target must make a {@dc 23} Dexterity saving throw, taking 22 ({@damage 4d10}) lightning damage on a failed save, or half as much damage on a successful one."]}]', '[{"name": "Tentacle Attack or Fling", "entries": ["The kraken makes one tentacle attack or uses its Fling."]}, {"name": "Lightning Storm (Costs 2 Actions)", "entries": ["The kraken uses Lightning Storm."]}, {"name": "Ink Cloud (Costs 3 Actions)", "entries": ["While underwater, the kraken expels an ink cloud in a 60-foot radius. The cloud spreads around corners, and that area is heavily obscured to creatures other than the kraken. Each creature other than the kraken that ends its turn there must succeed on a {@dc 23} Constitution saving throw, taking 16 ({@damage 3d10}) poison damage on a failed save, or half as much damage on a successful one. A strong current disperses the cloud, which otherwise disappears at the end of the kraken''s next turn."]}]', '[]', '["underwater"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('kuo-toa', 'Kuo-toa', 'humanoid', 'kuo-toa', 'M', 'N, E', 13, 18, '{"walk": 30, "swim": 30}', 13, 10, 11, 11, 10, 8, '1/4', 0, 2, '{}', '{"perception": "+4"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Undercommon"]', '[{"name": "Amphibious", "entries": ["The kuo-toa can breathe air and water."]}, {"name": "Otherworldly Perception", "entries": ["The kuo-toa can sense the presence of any creature within 30 feet of it that is {@condition invisible} or on the Ethereal Plane. It can pinpoint such a creature that is moving."]}, {"name": "Slippery", "entries": ["The kuo-toa has advantage on ability checks and saving throws made to escape a grapple."]}, {"name": "Sunlight Sensitivity", "entries": ["While in sunlight, the kuo-toa has disadvantage on attack rolls, as well as on Wisdom ({@skill Perception}) checks that rely on sight."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}3 ({@damage 1d4 + 1}) piercing damage."]}, {"name": "Spear", "entries": ["{@atk mw,rw} {@hit 3} to hit, reach 5 ft. or range 20/60 ft., one target. {@h}4 ({@damage 1d6 + 1}) piercing damage, or 5 ({@damage 1d8 + 1}) piercing damage if used with two hands to make a melee attack."]}, {"name": "Net", "entries": ["{@atk rw} {@hit 3} to hit, range 5/15 ft., one Large or smaller creature. {@h}The target is {@condition restrained}. A creature can use its action to make a {@dc 10} Strength check to free itself or another creature in a net, ending the effect on a success. Dealing 5 slashing damage to the net (AC 10) frees the target without harming it and destroys the net."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('kuo-toa_archpriest', 'Kuo-toa Archpriest', 'humanoid', 'kuo-toa', 'M', 'N, E', 13, 97, '{"walk": 30, "swim": 30}', 16, 14, 16, 13, 16, 14, '6', 0, 2, '{}', '{"perception": "+9", "religion": "+7"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Undercommon"]', '[{"name": "Amphibious", "entries": ["The kuo-toa can breathe air and water."]}, {"name": "Otherworldly Perception", "entries": ["The kuo-toa can sense the presence of any creature within 30 feet of it that is {@condition invisible} or on the Ethereal Plane. It can pinpoint such a creature that is moving."]}, {"name": "Slippery", "entries": ["The kuo-toa has advantage on ability checks and saving throws made to escape a grapple."]}, {"name": "Sunlight Sensitivity", "entries": ["While in sunlight, the kuo-toa has disadvantage on attack rolls, as well as on Wisdom ({@skill Perception}) checks that rely on sight."]}]', '[{"name": "Multiattack", "entries": ["The kuo-toa makes two melee attacks."]}, {"name": "Scepter", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}6 ({@damage 1d6 + 3}) bludgeoning damage plus 14 ({@damage 4d6}) lightning damage."]}, {"name": "Unarmed Strike", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d4 + 3}) bludgeoning damage."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('kuo-toa_monitor', 'Kuo-toa Monitor', 'humanoid', 'kuo-toa', 'M', 'N, E', 13, 65, '{"walk": 30, "swim": 30}', 14, 10, 14, 12, 14, 11, '3', 0, 2, '{}', '{"perception": "+6", "religion": "+5"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Undercommon"]', '[{"name": "Amphibious", "entries": ["The kuo-toa can breathe air and water."]}, {"name": "Otherworldly Perception", "entries": ["The kuo-toa can sense the presence of any creature within 30 feet of it that is {@condition invisible} or on the Ethereal Plane. It can pinpoint such a creature that is moving."]}, {"name": "Slippery", "entries": ["The kuo-toa has advantage on ability checks and saving throws made to escape a grapple."]}, {"name": "Sunlight Sensitivity", "entries": ["While in sunlight, the kuo-toa has disadvantage on attack rolls, as well as on Wisdom ({@skill Perception}) checks that rely on sight."]}, {"name": "Unarmored Defense", "entries": ["The kuo-toa adds its Wisdom modifier to its armor class."]}]', '[{"name": "Multiattack", "entries": ["The kuo-toa makes one bite attack and two unarmed strikes."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}4 ({@damage 1d4 + 2}) piercing damage."]}, {"name": "Unarmed Strike", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d6 + 2}) bludgeoning damage plus 3 ({@damage 1d6}) lightning damage, and the target can''t take reactions until the end of the kuo-toa''s next turn."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('kuo-toa_whip', 'Kuo-toa Whip', 'humanoid', 'kuo-toa', 'M', 'N, E', 11, 65, '{"walk": 30, "swim": 30}', 14, 10, 14, 12, 14, 11, '1', 0, 2, '{}', '{"perception": "+6", "religion": "+5"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Undercommon"]', '[{"name": "Amphibious", "entries": ["The kuo-toa can breathe air and water."]}, {"name": "Otherworldly Perception", "entries": ["The kuo-toa can sense the presence of any creature within 30 feet of it that is {@condition invisible} or on the Ethereal Plane. It can pinpoint such a creature that is moving."]}, {"name": "Slippery", "entries": ["The kuo-toa has advantage on ability checks and saving throws made to escape a grapple."]}, {"name": "Sunlight Sensitivity", "entries": ["While in sunlight, the kuo-toa has disadvantage on attack rolls, as well as on Wisdom ({@skill Perception}) checks that rely on sight."]}]', '[{"name": "Multiattack", "entries": ["The kuo-toa makes two attacks: one with its bite and one with its pincer staff."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}4 ({@damage 1d4 + 2}) piercing damage."]}, {"name": "Pincer Staff", "entries": ["{@atk mw} {@hit 4} to hit, reach 10 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage. If the target is a Medium or smaller creature, it is {@condition grappled} (escape {@dc 14}). Until this grapple ends, the kuo-toa can''t use its pincer staff on another target."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('lamia', 'Lamia', 'monstrosity', '', 'L', 'C, E', 13, 97, '{"walk": 30}', 16, 13, 15, 14, 15, 16, '4', 0, 2, '{}', '{"deception": "+7", "insight": "+4", "stealth": "+3"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Abyssal", "Common"]', '[]', '[{"name": "Multiattack", "entries": ["The lamia makes two attacks: one with its claws and one with its dagger or Intoxicating Touch."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}14 ({@damage 2d10 + 3}) slashing damage."]}, {"name": "Dagger", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d4 + 3}) piercing damage."]}, {"name": "Intoxicating Touch", "entries": ["{@atk ms} {@hit 5} to hit, reach 5 ft., one creature. {@h}The target is magically cursed for 1 hour. Until the curse ends, the target has disadvantage on Wisdom saving throws and all ability checks."]}]', '[]', '[]', '["desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('lemure', 'Lemure', 'fiend', 'devil', 'M', 'L, E', 7, 13, '{"walk": 15}', 10, 5, 11, 1, 11, 3, '0', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["understands Infernal but can''t speak"]', '[{"name": "Devil''s Sight", "entries": ["Magical darkness doesn''t impede the lemure''s darkvision."]}, {"name": "Hellish Rejuvenation", "entries": ["A lemure that dies in the Nine Hells comes back to life with all its hit points in {@dice 1d10} days unless it is killed by a good-aligned creature with a {@spell bless} spell cast on that creature or its remains are sprinkled with holy water."]}]', '[{"name": "Fist", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}2 ({@damage 1d4}) bludgeoning damage"]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('lich', 'Lich', 'undead', '', 'M', 'L, NX, C, E', 17, 135, '{"walk": 30}', 11, 16, 16, 20, 14, 16, '{''cr'': ''21'', ''lair'': ''22''}', 0, 2, '{"con": "+10", "int": "+12", "wis": "+9"}', '{"arcana": "+19", "history": "+12", "insight": "+9", "perception": "+9"}', '[]', '[]', '[]', '["truesight 120 ft."]', '["Common plus up to five other languages"]', '[{"name": "Legendary Resistance (3/Day)", "entries": ["If the lich fails a saving throw, it can choose to succeed instead."]}, {"name": "Rejuvenation", "entries": ["If it has a phylactery, a destroyed lich gains a new body in {@dice 1d10} days, regaining all its hit points and becoming active again. The new body appears within 5 feet of the phylactery."]}, {"name": "Turn Resistance", "entries": ["The lich has advantage on saving throws against any effect that turns undead."]}]', '[{"name": "Paralyzing Touch", "entries": ["{@atk ms} {@hit 12} to hit, reach 5 ft., one creature. {@h}10 ({@damage 3d6}) cold damage. The target must succeed on a {@dc 18} Constitution saving throw or be {@condition paralyzed} for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."]}]', '[{"name": "Cantrip", "entries": ["The lich casts a cantrip."]}, {"name": "Paralyzing Touch (Costs 2 Actions)", "entries": ["The lich uses its Paralyzing Touch."]}, {"name": "Frightening Gaze (Costs 2 Actions)", "entries": ["The lich fixes its gaze on one creature it can see within 10 feet of it. The target must succeed on a {@dc 18} Wisdom saving throw against this magic or become {@condition frightened} for 1 minute. The {@condition frightened} target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a target''s saving throw is successful or the effect ends for it, the target is immune to the lich''s gaze for the next 24 hours."]}, {"name": "Disrupt Life (Costs 3 Actions)", "entries": ["Each non-undead creature within 20 feet of the lich must make a {@dc 18} Constitution saving throw against this magic, taking 21 ({@damage 6d6}) necrotic damage on a failed save, or half as much damage on a successful one."]}]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('lion', 'Lion', 'beast', '', 'L', 'U', 12, 26, '{"walk": 50}', 17, 15, 13, 3, 12, 8, '1', 0, 2, '{}', '{"perception": "+3", "stealth": "+6"}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Keen Smell", "entries": ["The lion has advantage on Wisdom ({@skill Perception}) checks that rely on smell."]}, {"name": "Pack Tactics", "entries": ["The lion has advantage on an attack roll against a creature if at least one of the lion''s allies is within 5 feet of the creature and the ally isn''t {@condition incapacitated}."]}, {"name": "Pounce", "entries": ["If the lion moves at least 20 feet straight toward a creature and then hits it with a claw attack on the same turn, that target must succeed on a {@dc 13} Strength saving throw or be knocked {@condition prone}. If the target is {@condition prone}, the lion can make one bite attack against it as a bonus action."]}, {"name": "Running Leap", "entries": ["With a 10-foot running start, the lion can long jump up to 25 feet."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}7 ({@damage 1d8 + 3}) piercing damage."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}6 ({@damage 1d6 + 3}) slashing damage."]}]', '[]', '[]', '["mountain", "grassland", "hill", "desert"]');
