INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('lizard_king', 'Lizard King', 'humanoid', 'lizardfolk', 'M', 'C, E', 15, 78, '{"walk": 30, "swim": 30}', 17, 12, 15, 11, 11, 15, '4', 0, 2, '{"con": "+4", "wis": "+2"}', '{"perception": "+4", "stealth": "+5", "survival": "+4"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Abyssal", "Draconic"]', '[{"name": "Hold Breath", "entries": ["The lizardfolk can hold its breath for 15 minutes."]}, {"name": "Skewer", "entries": ["Once per turn, when the lizardfolk makes a melee attack with its trident and hits, the target takes an extra 10 ({@damage 3d6}) damage, and the lizardfolk gains temporary hit points equal to the extra damage dealt."]}]', '[{"name": "Multiattack", "entries": ["The lizardfolk makes two attacks: one with its bite and one with its claws or trident or two melee attacks with its trident."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}6 ({@damage 1d6 + 3}) piercing damage."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d4 + 3}) slashing damage."]}, {"name": "Trident", "entries": ["{@atk mw,rw} {@hit 5} to hit, reach 5 ft. or range 20/60 ft., one target. {@h}6 ({@damage 1d6 + 3}) piercing damage, or 7 ({@damage 1d8 + 3}) piercing damage if used with two hands to make a melee attack."]}]', '[]', '[]', '["forest", "swamp"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('lizard_queen', 'Lizard Queen', 'humanoid', 'lizardfolk', 'M', 'C, E', 15, 78, '{"walk": 30, "swim": 30}', 17, 12, 15, 11, 11, 15, '4', 0, 2, '{"con": "+4", "wis": "+2"}', '{"perception": "+4", "stealth": "+5", "survival": "+4"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Abyssal", "Draconic"]', '[{"name": "Hold Breath", "entries": ["The lizardfolk can hold its breath for 15 minutes."]}, {"name": "Skewer", "entries": ["Once per turn, when the lizardfolk makes a melee attack with its trident and hits, the target takes an extra 10 ({@damage 3d6}) damage, and the lizardfolk gains temporary hit points equal to the extra damage dealt."]}]', '[{"name": "Multiattack", "entries": ["The lizardfolk makes two attacks: one with its bite and one with its claws or trident or two melee attacks with its trident."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}6 ({@damage 1d6 + 3}) piercing damage."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d4 + 3}) slashing damage."]}, {"name": "Trident", "entries": ["{@atk mw,rw} {@hit 5} to hit, reach 5 ft. or range 20/60 ft., one target. {@h}6 ({@damage 1d6 + 3}) piercing damage, or 7 ({@damage 1d8 + 3}) piercing damage if used with two hands to make a melee attack."]}]', '[]', '[]', '["forest", "swamp"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('lizardfolk', 'Lizardfolk', 'humanoid', 'lizardfolk', 'M', 'N', 15, 22, '{"walk": 30, "swim": 30}', 15, 10, 13, 7, 12, 7, '1/2', 0, 2, '{}', '{"perception": "+3", "stealth": "+4", "survival": "+5"}', '[]', '[]', '[]', '[]', '["Draconic"]', '[{"name": "Hold Breath", "entries": ["The lizardfolk can hold its breath for 15 minutes."]}]', '[{"name": "Multiattack", "entries": ["The lizardfolk makes two melee attacks, each one with a different weapon."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage."]}, {"name": "Heavy Club", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d6 + 2}) bludgeoning damage."]}, {"name": "Javelin", "entries": ["{@atk mw,rw} {@hit 4} to hit, reach 5 ft. or range 30/120 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage."]}, {"name": "Spiked Shield", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage."]}]', '[]', '[]', '["forest", "swamp"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('lizardfolk_shaman', 'Lizardfolk Shaman', 'humanoid', 'lizardfolk', 'M', 'N', 13, 27, '{"walk": 30, "swim": 30}', 15, 10, 13, 10, 15, 8, '2', 0, 2, '{}', '{"perception": "+4", "stealth": "+4", "survival": "+6"}', '[]', '[]', '[]', '[]', '["Draconic"]', '[{"name": "Hold Breath", "entries": ["The lizardfolk can hold its breath for 15 minutes."]}]', '[{"name": "Multiattack (Lizardfolk Form Only)", "entries": ["The lizardfolk makes two attacks: one with its bite and one with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage, or 7 ({@damage 1d10 + 2}) piercing damage in {@creature crocodile} form. If the lizardfolk is in crocodile form and the target is a Large or smaller creature, the target is {@condition grappled} (escape {@dc 12}). Until this grapple ends, the target is {@condition restrained}, and the lizardfolk can''t bite another target. If the lizardfolk reverts to its true form, the grapple ends."]}, {"name": "Claws (Lizardfolk Form Only)", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}4 ({@damage 1d4 + 2}) slashing damage."]}, {"name": "Change Shape (Recharges after a Short or Long Rest)", "entries": ["The lizardfolk magically polymorphs into a {@creature crocodile}, remaining in that form for up to 1 hour. It can revert to its true form as a bonus action. Its statistics, other than its size, are the same in each form. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies."]}]', '[]', '[]', '["forest", "swamp"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('mage', 'Mage', 'humanoid', 'any race', 'M', 'A', 12, 40, '{"walk": 30}', 9, 14, 11, 17, 12, 11, '6', 0, 2, '{"int": "+6", "wis": "+4"}', '{"arcana": "+6", "history": "+6"}', '[]', '[]', '[]', '[]', '["any four languages"]', '[]', '[{"name": "Dagger", "entries": ["{@atk mw,rw} {@hit 5} to hit, reach 5 ft. or range 20/60 ft., one target. {@h}4 ({@damage 1d4 + 2}) piercing damage."]}]', '[]', '[]', '["urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('magma_mephit', 'Magma Mephit', 'elemental', '', 'S', 'N, E', 11, 22, '{"walk": 30, "fly": 30}', 8, 12, 12, 7, 10, 10, '1/2', 0, 2, '{}', '{"stealth": "+3"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Ignan", "Terran"]', '[{"name": "Death Burst", "entries": ["When the mephit dies, it explodes in a burst of lava. Each creature within 5 feet of it must make a {@dc 11} Dexterity saving throw, taking 7 ({@damage 2d6}) fire damage on a failed save, or half as much damage on a successful one."]}, {"name": "False Appearance", "entries": ["While the mephit remains motionless, it is indistinguishable from an ordinary mound of magma."]}]', '[{"name": "Claws", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one creature. {@h}3 ({@damage 1d4 + 1}) slashing damage plus 2 ({@damage 1d4}) fire damage."]}, {"name": "Fire Breath {@recharge}", "entries": ["The mephit exhales a 15-foot cone of fire. Each creature in that area must make a {@dc 11} Dexterity saving throw, taking 7 ({@damage 2d6}) fire damage on a failed save, or half as much damage on a successful one."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('magmin', 'Magmin', 'elemental', '', 'S', 'C, N', 14, 9, '{"walk": 30}', 7, 15, 12, 8, 11, 10, '1/2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Ignan"]', '[{"name": "Death Burst", "entries": ["When the magmin dies, it explodes in a burst of fire and magma. Each creature within 10 feet of it must make a {@dc 11} Dexterity saving throw, taking 7 ({@damage 2d6}) fire damage on a failed save, or half as much damage on a successful one. Flammable objects that aren''t being worn or carried in that area are ignited."]}, {"name": "Ignited Illumination", "entries": ["As a bonus action, the magmin can set itself ablaze or extinguish its flames. While ablaze, the magmin sheds bright light in a 10-foot radius and dim light for an additional 10 feet."]}]', '[{"name": "Touch", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}7 ({@damage 2d6}) fire damage. If the target is a creature or a flammable object, it ignites. Until a creature takes an action to douse the fire, the target takes 3 ({@damage 1d6}) fire damage at the end of each of its turns."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('mammoth', 'Mammoth', 'beast', '', 'H', 'U', 13, 126, '{"walk": 40}', 24, 9, 21, 3, 11, 6, '6', 0, 2, '{}', '{}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Trampling Charge", "entries": ["If the mammoth moves at least 20 feet straight toward a creature and then hits it with a gore attack on the same turn, that target must succeed on a {@dc 18} Strength saving throw or be knocked {@condition prone}. If the target is {@condition prone}, the mammoth can make one stomp attack against it as a bonus action."]}]', '[{"name": "Gore", "entries": ["{@atk mw} {@hit 10} to hit, reach 10 ft., one target. {@h}25 ({@damage 4d8 + 7}) piercing damage."]}, {"name": "Stomp", "entries": ["{@atk mw} {@hit 10} to hit, reach 5 ft., one {@condition prone} creature. {@h}29 ({@damage 4d10 + 7}) bludgeoning damage."]}]', '[]', '[]', '["arctic"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('manes', 'Manes', 'fiend', 'demon', 'S', 'C, E', 9, 9, '{"walk": 20}', 10, 9, 13, 3, 8, 4, '1/8', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["understands Abyssal but can''t speak"]', '[]', '[{"name": "Claws", "entries": ["{@atk mw} {@hit 2} to hit, reach 5 ft., one target. {@h}5 ({@damage 2d4}) slashing damage."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('manticore', 'Manticore', 'monstrosity', '', 'L', 'L, E', 14, 68, '{"walk": 30, "fly": 50}', 17, 16, 17, 7, 12, 8, '3', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Common"]', '[{"name": "Tail Spike Regrowth", "entries": ["The manticore has twenty-four tail spikes. Used spikes regrow when the manticore finishes a long rest."]}]', '[{"name": "Multiattack", "entries": ["The manticore makes three attacks: one with its bite and two with its claws or three with its tail spikes."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}7 ({@damage 1d8 + 3}) piercing damage."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}6 ({@damage 1d6 + 3}) slashing damage."]}, {"name": "Tail Spike", "entries": ["{@atk rw} {@hit 5} to hit, range 100/200 ft., one target. {@h}7 ({@damage 1d8 + 3}) piercing damage."]}]', '[]', '[]', '["mountain", "grassland", "hill", "coastal", "arctic"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('marid', 'Marid', 'elemental', '', 'L', 'C, N', 17, 229, '{"walk": 30, "fly": 60, "swim": 90}', 22, 12, 26, 18, 17, 18, '11', 0, 2, '{"dex": "+5", "wis": "+7", "cha": "+8"}', '{}', '[]', '[]', '[]', '["blindsight 30 ft.", "darkvision 120 ft."]', '["Aquan"]', '[{"name": "Amphibious", "entries": ["The marid can breathe air and water."]}, {"name": "Elemental Demise", "entries": ["If the marid dies, its body disintegrates into a burst of water and foam, leaving behind only equipment the marid was wearing or carrying."]}]', '[{"name": "Multiattack", "entries": ["The marid makes two trident attacks."]}, {"name": "Trident", "entries": ["{@atk mw,rw} {@hit 10} to hit, reach 5 ft. or range 20/60 ft., one target. {@h}13 ({@damage 2d6 + 6}) piercing damage, or 15 ({@damage 2d8 + 6}) piercing damage if used with two hands to make a melee attack."]}, {"name": "Water Jet", "entries": ["The marid magically shoots water in a 60-foot line that is 5 feet wide. Each creature in that line must make a {@dc 16} Dexterity saving throw. On a failure, a target takes 21 ({@damage 6d6}) bludgeoning damage and, if it is Huge or smaller, is pushed up to 20 feet away from the marid and knocked {@condition prone}. On a success, a target takes half the bludgeoning damage, but is neither pushed nor knocked {@condition prone}."]}]', '[]', '[]', '["underwater", "coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('marilith', 'Marilith', 'fiend', 'demon', 'L', 'C, E', 18, 189, '{"walk": 40}', 18, 20, 20, 18, 16, 20, '16', 0, 2, '{"str": "+9", "con": "+10", "wis": "+8", "cha": "+10"}', '{}', '[]', '[]', '[]', '["truesight 120 ft."]', '["Abyssal", "telepathy 120 ft."]', '[{"name": "Magic Resistance", "entries": ["The marilith has advantage on saving throws against spells and other magical effects."]}, {"name": "Magic Weapons", "entries": ["The marilith''s weapon attacks are magical."]}, {"name": "Reactive", "entries": ["The marilith can take one reaction on every turn in combat."]}]', '[{"name": "Multiattack", "entries": ["The marilith can make seven attacks: six with its longswords and one with its tail."]}, {"name": "Longsword", "entries": ["{@atk mw} {@hit 9} to hit, reach 5 ft., one target. {@h}13 ({@damage 2d8 + 4}) slashing damage."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 9} to hit, reach 10 ft., one creature. {@h}15 ({@damage 2d10 + 4}) bludgeoning damage. If the target is Medium or smaller, it is {@condition grappled} (escape {@dc 19}). Until this grapple ends, the target is {@condition restrained}, the marilith can automatically hit the target with its tail, and the marilith can''t make tail attacks against other targets."]}, {"name": "Teleport", "entries": ["The marilith magically teleports, along with any equipment it is wearing or carrying, up to 120 feet to an unoccupied space it can see."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('mastiff', 'Mastiff', 'beast', '', 'M', 'U', 12, 5, '{"walk": 40}', 13, 14, 12, 3, 12, 7, '1/8', 0, 2, '{}', '{"perception": "+3"}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Keen Hearing and Smell", "entries": ["The mastiff has advantage on Wisdom ({@skill Perception}) checks that rely on hearing or smell."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}4 ({@damage 1d6 + 1}) piercing damage. If the target is a creature, it must succeed on a {@dc 11} Strength saving throw or be knocked {@condition prone}."]}]', '[]', '[]', '["forest", "hill", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('medusa', 'Medusa', 'monstrosity', '', 'M', 'L, E', 15, 127, '{"walk": 30}', 10, 15, 16, 12, 13, 15, '6', 0, 2, '{}', '{"deception": "+5", "insight": "+4", "perception": "+4", "stealth": "+5"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Common"]', '[{"name": "Petrifying Gaze", "entries": ["When a creature that can see the medusa''s eyes starts its turn within 30 feet of the medusa, the medusa can force it to make a {@dc 14} Constitution saving throw if the medusa isn''t {@condition incapacitated} and can see the creature. If the saving throw fails by 5 or more, the creature is instantly {@condition petrified}. Otherwise, a creature that fails the save begins to turn to stone and is {@condition restrained}. The {@condition restrained} creature must repeat the saving throw at the end of its next turn, becoming {@condition petrified} on a failure or ending the effect on a success. The petrification lasts until the creature is freed by the  {@spell greater restoration} spell or other magic.", "Unless {@status surprised}, a creature can avert its eyes to avoid the saving throw at the start of its turn. If the creature does so, it can''t see the medusa until the start of its next turn, when it can avert its eyes again. If the creature looks at the medusa in the meantime, it must immediately make the save.", "If the medusa sees itself reflected on a polished surface within 30 feet of it and in an area of bright light, the medusa is, due to its curse, affected by its own gaze."]}]', '[{"name": "Multiattack", "entries": ["The medusa makes either three melee attacks\u2014one with its snake hair and two with its shortsword\u2014or two ranged attacks with its longbow."]}, {"name": "Snake Hair", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one creature. {@h}4 ({@damage 1d4 + 2}) piercing damage plus 14 ({@damage 4d6}) poison damage."]}, {"name": "Shortsword", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage."]}, {"name": "Longbow", "entries": ["{@atk rw} {@hit 5} to hit, range 150/600 ft., one target. {@h}6 ({@damage 1d8 + 2}) piercing damage plus 7 ({@damage 2d6}) poison damage."]}]', '[]', '[]', '["desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('merfolk', 'Merfolk', 'humanoid', 'merfolk', 'M', 'N', 11, 11, '{"walk": 10, "swim": 40}', 10, 13, 12, 11, 11, 12, '1/8', 0, 2, '{}', '{"perception": "+2"}', '[]', '[]', '[]', '[]', '["Aquan", "Common"]', '[{"name": "Amphibious", "entries": ["The merfolk can breathe air and water."]}]', '[{"name": "Spear", "entries": ["{@atk mw,rw} {@hit 2} to hit, reach 5 ft. or range 20/60 ft., one target. {@h}3 ({@damage 1d6}) piercing damage, or 4 ({@damage 1d8}) piercing damage if used with two hands to make a melee attack."]}]', '[]', '[]', '["underwater", "coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('merrow', 'Merrow', 'monstrosity', '', 'L', 'C, E', 13, 45, '{"walk": 10, "swim": 40}', 18, 10, 15, 8, 10, 9, '2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Abyssal", "Aquan"]', '[{"name": "Amphibious", "entries": ["The merrow can breathe air and water."]}]', '[{"name": "Multiattack", "entries": ["The merrow makes two attacks: one with its bite and one with its claws or harpoon."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}8 ({@damage 1d8 + 4}) piercing damage."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}9 ({@damage 2d4 + 4}) slashing damage."]}, {"name": "Harpoon", "entries": ["{@atk mw,rw} {@hit 6} to hit, reach 5 ft. or range 20/60 ft., one target. {@h}11 ({@damage 2d6 + 4}) piercing damage. If the target is a Huge or smaller creature, it must succeed on a Strength contest against the merrow or be pulled up to 20 feet toward the merrow."]}]', '[]', '[]', '["underwater", "coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('mezzoloth', 'Mezzoloth', 'fiend', 'yugoloth', 'M', 'N, E', 18, 75, '{"walk": 40}', 18, 11, 16, 7, 10, 11, '5', 0, 2, '{}', '{"perception": "+3"}', '[]', '[]', '[]', '["blindsight 60 ft.", "darkvision 60 ft."]', '["Abyssal", "Infernal", "telepathy 60 ft."]', '[{"name": "Magic Resistance", "entries": ["The mezzoloth has advantage on saving throws against spells and other magical effects."]}, {"name": "Magic Weapons", "entries": ["The mezzoloth''s weapon attacks are magical."]}]', '[{"name": "Multiattack", "entries": ["The mezzoloth makes two attacks: one with its claws and one with its trident."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}9 ({@damage 2d4 + 4}) slashing damage."]}, {"name": "Trident", "entries": ["{@atk mw,rw} {@hit 7} to hit, reach 5 ft. or range 20/60 ft., one target. {@h}7 ({@damage 1d6 + 4}) piercing damage, or 8 ({@damage 1d8 + 4}) piercing damage when held with two claws and used to make a melee attack."]}, {"name": "Teleport", "entries": ["The mezzoloth magically teleports, along with any equipment it is wearing or carrying, up to 60 feet to an unoccupied space it can see."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('mimic', 'Mimic', 'monstrosity', 'shapechanger', 'M', 'N', 12, 58, '{"walk": 15}', 17, 12, 15, 5, 13, 8, '2', 0, 2, '{}', '{"stealth": "+5"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '[]', '[{"name": "Shapechanger", "entries": ["The mimic can use its action to polymorph into an object or back into its true, amorphous form. Its statistics are the same in each form. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies."]}, {"name": "Adhesive (Object Form Only)", "entries": ["The mimic adheres to anything that touches it. A Huge or smaller creature adhered to the mimic is also {@condition grappled} by it (escape {@dc 13}). Ability checks made to escape this grapple have disadvantage."]}, {"name": "False Appearance (Object Form Only)", "entries": ["While the mimic remains motionless, it is indistinguishable from an ordinary object."]}, {"name": "Grappler", "entries": ["The mimic has advantage on attack rolls against any creature {@condition grappled} by it."]}]', '[{"name": "Pseudopod", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}7 ({@damage 1d8 + 3}) bludgeoning damage. If the mimic is in object form, the target is subjected to its Adhesive trait."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}7 ({@damage 1d8 + 3}) piercing damage plus 4 ({@damage 1d8}) acid damage."]}]', '[]', '[]', '["underdark", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('mind_flayer', 'Mind Flayer', 'aberration', '', 'M', 'L, E', 15, 71, '{"walk": 30}', 11, 12, 12, 19, 17, 17, '7', 0, 2, '{"int": "+7", "wis": "+6", "cha": "+6"}', '{"arcana": "+7", "deception": "+6", "insight": "+6", "perception": "+6", "persuasion": "+6", "stealth": "+4"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Deep Speech", "Undercommon", "telepathy 120 ft."]', '[{"name": "Magic Resistance", "entries": ["The mind flayer has advantage on saving throws against spells and other magical effects."]}]', '[{"name": "Tentacles", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one creature. {@h}15 ({@damage 2d10 + 4}) psychic damage. If the target is Medium or smaller, it is {@condition grappled} (escape {@dc 15}) and must succeed on a {@dc 15} Intelligence saving throw or be {@condition stunned} until this grapple ends."]}, {"name": "Extract Brain", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one {@condition incapacitated} humanoid {@condition grappled} by the mind flayer. {@h}The target takes 55 ({@damage 10d10}) piercing damage. If this damage reduces the target to 0 hit points, the mind flayer kills the target by extracting and devouring its brain."]}, {"name": "Mind Blast {@recharge 5}", "entries": ["The mind flayer magically emits psychic energy in a 60-foot cone. Each creature in that area must succeed on a {@dc 15} Intelligence saving throw or take 22 ({@damage 4d8 + 4}) psychic damage and be {@condition stunned} for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('mind_flayer_arcanist', 'Mind Flayer Arcanist', 'aberration', '', 'M', 'L, E', 15, 71, '{"walk": 30}', 11, 12, 12, 19, 17, 17, '8', 0, 2, '{"int": "+7", "wis": "+6", "cha": "+6"}', '{"arcana": "+7", "deception": "+6", "insight": "+6", "perception": "+6", "persuasion": "+6", "stealth": "+4"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Deep Speech", "Undercommon", "telepathy 120 ft."]', '[{"name": "Magic Resistance", "entries": ["The mind flayer has advantage on saving throws against spells and other magical effects."]}]', '[{"name": "Tentacles", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one creature. {@h}15 ({@damage 2d10 + 4}) psychic damage. If the target is Medium or smaller, it is {@condition grappled} (escape {@dc 15}) and must succeed on a {@dc 15} Intelligence saving throw or be {@condition stunned} until this grapple ends."]}, {"name": "Extract Brain", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one {@condition incapacitated} humanoid {@condition grappled} by the mind flayer. {@h}The target takes 55 ({@damage 10d10}) piercing damage. If this damage reduces the target to 0 hit points, the mind flayer kills the target by extracting and devouring its brain."]}, {"name": "Mind Blast {@recharge 5}", "entries": ["The mind flayer magically emits psychic energy in a 60-foot cone. Each creature in that area must succeed on a {@dc 15} Intelligence saving throw or take 22 ({@damage 4d8 + 4}) psychic damage and be {@condition stunned} for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('minotaur', 'Minotaur', 'monstrosity', '', 'L', 'C, E', 14, 76, '{"walk": 40}', 18, 11, 16, 6, 16, 9, '3', 0, 2, '{}', '{"perception": "+7"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Abyssal"]', '[{"name": "Charge", "entries": ["If the minotaur moves at least 10 feet straight toward a target and then hits it with a gore attack on the same turn, the target takes an extra 9 ({@damage 2d8}) piercing damage. If the target is a creature, it must succeed on a {@dc 14} Strength saving throw or be pushed up to 10 feet away and knocked {@condition prone}."]}, {"name": "Labyrinthine Recall", "entries": ["The minotaur can perfectly recall any path it has traveled."]}, {"name": "Reckless", "entries": ["At the start of its turn, the minotaur can gain advantage on all melee weapon attack rolls it makes during that turn, but attack rolls against it have advantage until the start of its next turn."]}]', '[{"name": "Greataxe", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}17 ({@damage 2d12 + 4}) slashing damage."]}, {"name": "Gore", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}13 ({@damage 2d8 + 4}) piercing damage."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('minotaur_skeleton', 'Minotaur Skeleton', 'undead', '', 'L', 'L, E', 12, 67, '{"walk": 40}', 18, 11, 15, 6, 8, 5, '2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["understands Abyssal but can''t speak"]', '[{"name": "Charge", "entries": ["If the skeleton moves at least 10 feet straight toward a target and then hits it with a gore attack on the same turn, the target takes an extra 9 ({@damage 2d8}) piercing damage. If the target is a creature, it must succeed on a {@dc 14} Strength saving throw or be pushed up to 10 feet away and knocked {@condition prone}."]}]', '[{"name": "Greataxe", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}17 ({@damage 2d12 + 4}) slashing damage."]}, {"name": "Gore", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}13 ({@damage 2d8 + 4}) piercing damage."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('monodrone', 'Monodrone', 'construct', '', 'M', 'L, N', 15, 5, '{"walk": 30, "fly": 30}', 10, 13, 12, 4, 10, 5, '1/8', 0, 2, '{}', '{}', '[]', '[]', '[]', '["truesight 120 ft."]', '["Modron"]', '[{"name": "Axiomatic Mind", "entries": ["The monodrone can''t be compelled to act in a manner contrary to its nature or its instructions."]}, {"name": "Disintegration", "entries": ["If the monodrone dies, its body disintegrates into dust, leaving behind its weapons and anything else it was carrying."]}]', '[{"name": "Dagger", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}3 ({@damage 1d4 + 1}) piercing damage."]}, {"name": "Javelin", "entries": ["{@atk mw,rw} {@hit 2} to hit, reach 5 ft. or range 30/120 ft., one target. {@h}3 ({@damage 1d6}) piercing damage."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('mud_mephit', 'Mud Mephit', 'elemental', '', 'S', 'N, E', 11, 27, '{"walk": 20, "fly": 20, "swim": 20}', 8, 12, 12, 9, 11, 7, '1/4', 0, 2, '{}', '{"stealth": "+3"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Aquan", "Terran"]', '[{"name": "Death Burst", "entries": ["When the mephit dies, it explodes in a burst of sticky mud. Each Medium or smaller creature within 5 feet of it must succeed on a {@dc 11} Dexterity saving throw or be {@condition restrained} until the end of the creature''s next turn."]}, {"name": "False Appearance", "entries": ["While the mephit remains motionless, it is indistinguishable from an ordinary mound of mud."]}]', '[{"name": "Fists", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one creature. {@h}4 ({@damage 1d6 + 1}) bludgeoning damage."]}, {"name": "Mud Breath {@recharge}", "entries": ["The mephit belches viscid mud onto one creature within 5 feet of it. If the target is Medium or smaller, it must succeed on a {@dc 11} Dexterity saving throw or be {@condition restrained} for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."]}]', '[]', '[]', '["swamp"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('mule', 'Mule', 'beast', '', 'M', 'U', 10, 11, '{"walk": 40}', 14, 10, 13, 2, 10, 5, '1/8', 0, 2, '{}', '{}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Beast of Burden", "entries": ["The mule is considered to be a Large animal for the purpose of determining its carrying capacity."]}, {"name": "Sure-Footed", "entries": ["The mule has advantage on Strength and Dexterity saving throws made against effects that would knock it {@condition prone}."]}]', '[{"name": "Hooves", "entries": ["{@atk mw} {@hit 2} to hit, reach 5 ft., one target. {@h}4 ({@damage 1d4 + 2}) bludgeoning damage."]}]', '[]', '[]', '["hill", "urban", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('mummy', 'Mummy', 'undead', '', 'M', 'L, E', 11, 58, '{"walk": 20}', 16, 8, 15, 6, 10, 12, '3', 0, 2, '{"wis": "+2"}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["the languages it knew in life"]', '[]', '[{"name": "Multiattack", "entries": ["The mummy can use its Dreadful Glare and makes one attack with its rotting fist."]}, {"name": "Rotting Fist", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}10 ({@damage 2d6 + 3}) bludgeoning damage plus 10 ({@damage 3d6}) necrotic damage. If the target is a creature, it must succeed on a {@dc 12} Constitution saving throw or be cursed with mummy rot. The cursed target can''t regain hit points, and its hit point maximum decreases by 10 ({@dice 3d6}) for every 24 hours that elapse. If the curse reduces the target''s hit point maximum to 0, the target dies, and its body turns to dust. The curse lasts until removed by the {@spell remove curse} spell or other magic."]}, {"name": "Dreadful Glare", "entries": ["The mummy targets one creature it can see within 60 feet of it. If the target can see the mummy, it must succeed on a {@dc 11} Wisdom saving throw against this magic or become {@condition frightened} until the end of the mummy''s next turn. If the target fails the saving throw by 5 or more, it is also {@condition paralyzed} for the same duration. A target that succeeds on the saving throw is immune to the Dreadful Glare of all mummies (but not mummy lords) for the next 24 hours."]}]', '[]', '[]', '["desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('mummy_lord', 'Mummy Lord', 'undead', '', 'M', 'L, E', 17, 97, '{"walk": 20}', 18, 10, 17, 11, 18, 16, '{''cr'': ''15'', ''lair'': ''16''}', 0, 2, '{"con": "+8", "int": "+5", "wis": "+9", "cha": "+8"}', '{"history": "+5", "religion": "+5"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["the languages it knew in life"]', '[{"name": "Magic Resistance", "entries": ["The mummy lord has advantage on saving throws against spells and other magical effects."]}, {"name": "Rejuvenation", "entries": ["A destroyed mummy lord gains a new body in 24 hours if its heart is intact, regaining all its hit points and becoming active again. The new body appears within 5 feet of the mummy lord''s heart."]}]', '[{"name": "Multiattack", "entries": ["The mummy can use its Dreadful Glare and makes one attack with its rotting fist."]}, {"name": "Rotting Fist", "entries": ["{@atk mw} {@hit 9} to hit, reach 5 ft., one target. {@h}14 ({@damage 3d6 + 4}) bludgeoning damage plus 21 ({@damage 6d6}) necrotic damage. If the target is a creature, it must succeed on a {@dc 16} Constitution saving throw or be cursed with mummy rot. The cursed target can''t regain hit points, and its hit point maximum decreases by 10 ({@dice 3d6}) for every 24 hours that elapse. If the curse reduces the target''s hit point maximum to 0, the target dies, and its body turns to dust. The curse lasts until removed by the {@spell remove curse} spell or other magic."]}, {"name": "Dreadful Glare", "entries": ["The mummy lord targets one creature it can see within 60 feet of it. If the target can see the mummy lord, it must succeed on a {@dc 16} Wisdom saving throw against this magic or become {@condition frightened} until the end of the mummy''s next turn. If the target fails the saving throw by 5 or more, it is also {@condition paralyzed} for the same duration. A target that succeeds on the saving throw is immune to the Dreadful Glare of all mummies and mummy lords for the next 24 hours."]}]', '[{"name": "Attack", "entries": ["The mummy lord makes one attack with its rotting fist or uses its Dreadful Glare."]}, {"name": "Blinding Dust", "entries": ["Blinding dust and sand swirls magically around the mummy lord. Each creature within 5 feet of the mummy lord must succeed on a {@dc 16} Constitution saving throw or be {@condition blinded} until the end of the creature''s next turn."]}, {"name": "Blasphemous Word (Costs 2 Actions)", "entries": ["The mummy lord utters a blasphemous word. Each non-undead creature within 10 feet of the mummy lord that can hear the magical utterance must succeed on a {@dc 16} Constitution saving throw or be {@condition stunned} until the end of the mummy lord''s next turn."]}, {"name": "Channel Negative Energy (Costs 2 Actions)", "entries": ["The mummy lord magically unleashes negative energy. Creatures within 60 feet of the mummy lord, including ones behind barriers and around corners, can''t regain hit points until the end of the mummy lord''s next turn."]}, {"name": "Whirlwind of Sand (Costs 2 Actions)", "entries": ["The mummy lord magically transforms into a whirlwind of sand, moves up to 60 feet, and reverts to its normal form. While in whirlwind form, the mummy lord is immune to all damage, and it can''t be {@condition grappled}, {@condition petrified}, knocked {@condition prone}, {@condition restrained}, or {@condition stunned}. Equipment worn or carried by the mummy lord remain in its possession."]}]', '[]', '["desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('myconid_adult', 'Myconid Adult', 'plant', '', 'M', 'L, N', 12, 22, '{"walk": 20}', 10, 10, 12, 10, 13, 7, '1/2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 120 ft."]', '[]', '[{"name": "Distress Spores", "entries": ["When the myconid takes damage, all other myconids within 240 feet of it can sense its pain."]}, {"name": "Sun Sickness", "entries": ["While in sunlight, the myconid has disadvantage on ability checks, attack rolls, and saving throws. The myconid dies if it spends more than 1 hour in direct sunlight."]}]', '[{"name": "Fist", "entries": ["{@atk mw} {@hit 2} to hit, reach 5 ft., one target. {@h}5 ({@damage 2d4}) bludgeoning damage plus 5 ({@damage 2d4}) poison damage."]}, {"name": "Pacifying Spores (3/Day)", "entries": ["The myconid ejects spores at one creature it can see within 5 feet of it. The target must succeed on a {@dc 11} Constitution saving throw or be {@condition stunned} for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."]}, {"name": "Rapport Spores", "entries": ["A 20-foot radius of spores extends from the myconid. These spores can go around corners and affect only creatures with an Intelligence of 2 or higher that aren''t undead, constructs, or elementals. Affected creatures can communicate telepathically with one another while they are within 30 feet of each other. The effect lasts for 1 hour."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('myconid_sovereign', 'Myconid Sovereign', 'plant', '', 'L', 'L, N', 13, 60, '{"walk": 30}', 12, 10, 14, 13, 15, 10, '2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 120 ft."]', '[]', '[{"name": "Distress Spores", "entries": ["When the myconid takes damage, all other myconids within 240 feet of it can sense its pain."]}, {"name": "Sun Sickness", "entries": ["While in sunlight, the myconid has disadvantage on ability checks, attack rolls, and saving throws. The myconid dies if it spends more than 1 hour in direct sunlight."]}]', '[{"name": "Multiattack", "entries": ["The myconid uses either its Hallucination Spores or its Pacifying Spores, then makes a fist attack."]}, {"name": "Fist", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}8 ({@damage 3d4 + 1}) bludgeoning damage plus 7 ({@damage 3d4}) poison damage."]}, {"name": "Animating Spores (3/Day)", "entries": ["The myconid targets one corpse of a humanoid or a Large or smaller beast within 5 feet of it and releases spores at the corpse. In 24 hours, the corpse rises as a spore servant. The corpse stays animated for {@dice 1d4 + 1} weeks or until destroyed, and it can''t be animated again in this way."]}, {"name": "Hallucination Spores", "entries": ["The myconid ejects spores at one creature it can see within 5 feet of it. The target must succeed on a {@dc 12} Constitution saving throw or be {@condition poisoned} for 1 minute. The {@condition poisoned} target is {@condition incapacitated} while it hallucinates. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."]}, {"name": "Pacifying Spores", "entries": ["The myconid ejects spores at one creature it can see within 5 feet of it. The target must succeed on a {@dc 12} Constitution saving throw or be {@condition stunned} for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."]}, {"name": "Rapport Spores", "entries": ["A 30-foot radius of spores extends from the myconid. These spores can go around corners and affect only creatures with an Intelligence of 2 or higher that aren''t undead, constructs, or elementals. Affected creatures can communicate telepathically with one another while they are within 30 feet of each other. The effect lasts for 1 hour."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('myconid_sprout', 'Myconid Sprout', 'plant', '', 'S', 'L, N', 10, 7, '{"walk": 10}', 8, 10, 10, 8, 11, 5, '0', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 120 ft."]', '[]', '[{"name": "Distress Spores", "entries": ["When the myconid takes damage, all other myconids within 240 feet of it can sense its pain."]}, {"name": "Sun Sickness", "entries": ["While in sunlight, the myconid has disadvantage on ability checks, attack rolls, and saving throws. The myconid dies if it spends more than 1 hour in direct sunlight."]}]', '[{"name": "Fist", "entries": ["{@atk mw} {@hit 1} to hit, reach 5 ft., one target. {@h}1 ({@damage 1d4 - 1}) bludgeoning damage plus 2 ({@damage 1d4}) poison damage."]}, {"name": "Rapport Spores (3/Day)", "entries": ["A 10-foot radius of spores extends from the myconid. These spores can go around corners and affect only creatures with an Intelligence of 2 or higher that aren''t undead, constructs, or elementals. Affected creatures can communicate telepathically with one another while they are within 30 feet of each other. The effect lasts for 1 hour."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('nalfeshnee', 'Nalfeshnee', 'fiend', 'demon', 'L', 'C, E', 18, 184, '{"walk": 20, "fly": 30}', 21, 10, 22, 19, 12, 15, '13', 0, 2, '{"con": "+11", "int": "+9", "wis": "+6", "cha": "+7"}', '{}', '[]', '[]', '[]', '["truesight 120 ft."]', '["Abyssal", "telepathy 120 ft."]', '[{"name": "Magic Resistance", "entries": ["The nalfeshnee has advantage on saving throws against spells and other magical effects."]}]', '[{"name": "Multiattack", "entries": ["The nalfeshnee uses Horror Nimbus if it can. It then makes three attacks: one with its bite and two with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 10} to hit, reach 5 ft., one target. {@h}32 ({@damage 5d10 + 5}) piercing damage."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 10} to hit, reach 10 ft., one target. {@h}15 ({@damage 3d6 + 5}) slashing damage."]}, {"name": "Horror Nimbus {@recharge 5}", "entries": ["The nalfeshnee magically emits scintillating, multicolored light. Each creature within 15 feet of the nalfeshnee that can see the light must succeed on a {@dc 15} Wisdom saving throw or be {@condition frightened} for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the nalfeshnee''s Horror Nimbus for the next 24 hours."]}, {"name": "Teleport", "entries": ["The nalfeshnee magically teleports, along with any equipment it is wearing or carrying, up to 120 feet to an unoccupied space it can see."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('needle_blight', 'Needle Blight', 'plant', '', 'M', 'N, E', 12, 11, '{"walk": 30}', 12, 12, 13, 4, 8, 3, '1/4', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 60 ft. (blind beyond this radius)"]', '["understands Common but can''t speak"]', '[]', '[{"name": "Claws", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}6 ({@damage 2d4 + 1}) piercing damage."]}, {"name": "Needles", "entries": ["{@atk rw} {@hit 3} to hit, range 30/60 ft., one target. {@h}8 ({@damage 2d6 + 1}) piercing damage."]}]', '[]', '[]', '["forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('night_hag', 'Night Hag', 'fiend', '', 'M', 'N, E', 17, 112, '{"walk": 30}', 18, 15, 16, 16, 14, 16, '{''cr'': ''5'', ''coven'': ''7''}', 0, 2, '{}', '{"deception": "+6", "insight": "+5", "perception": "+5", "stealth": "+5"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Abyssal", "Common", "Infernal", "Primordial"]', '[{"name": "Magic Resistance", "entries": ["The hag has advantage on saving throws against spells and other magical effects."]}, {"name": "Night Hag Items", "entries": ["A night hag carries two very rare magic items that she must craft for herself. If either object is lost, the night hag will go to great lengths to retrieve it, as creating a new tool takes time and effort.", "Heartstone: This lustrous black gem allows a night hag to become ethereal while it is in her possession. The touch of a heartstone also cures any disease. Crafting a heartstone takes 30 days.", "Soul Bag: When an evil humanoid dies as a result of a night hag''s Nightmare Haunting, the hag catches the soul in this black sack made of stitched flesh. A soul bag can hold only one evil soul at a time, and only the night hag who crafted the bag can catch a soul with it. Crafting a soul bag takes 7 days and a humanoid sacrifice (whose flesh is used to make the bag)."]}]', '[{"name": "Claws (Hag Form Only)", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}13 ({@damage 2d8 + 4}) slashing damage."]}, {"name": "Change Shape", "entries": ["The hag magically polymorphs into a Small or Medium female humanoid, or back into her true form. Her statistics are the same in each form. Any equipment she is wearing or carrying isn''t transformed. She reverts to her true form if she dies."]}, {"name": "Etherealness", "entries": ["The hag magically enters the Ethereal Plane from the Material Plane, or vice versa. To do so, the hag must have a heartstone in her possession."]}, {"name": "Nightmare Haunting (1/Day)", "entries": ["While on the Ethereal Plane, the hag magically touches a sleeping humanoid on the Material Plane. A {@spell protection from evil and good} spell cast on the target prevents this contact, as does a magic circle. As long as the contact persists, the target has dreadful visions. If these visions last for at least 1 hour, the target gains no benefit from its rest, and its hit point maximum is reduced by 5 ({@dice 1d10}). If this effect reduces the target''s hit point maximum to 0, the target dies, and if the target was evil, its soul is trapped in the hag''s soul bag. The reduction to the target''s hit point maximum lasts until removed by the  {@spell greater restoration} spell or similar magic."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('nightmare', 'Nightmare', 'fiend', '', 'L', 'N, E', 13, 68, '{"walk": 60, "fly": 90}', 18, 15, 16, 10, 13, 15, '3', 0, 2, '{}', '{}', '[]', '[]', '[]', '[]', '["understands Abyssal, Common, and Infernal but can''t speak "]', '[{"name": "Confer Fire Resistance", "entries": ["The nightmare can grant resistance to fire damage to anyone riding it."]}, {"name": "Illumination", "entries": ["The nightmare sheds bright light in a 10-foot radius and dim light for an additional 10 feet."]}]', '[{"name": "Hooves", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}13 ({@damage 2d8 + 4}) bludgeoning damage plus 7 ({@damage 2d6}) fire damage."]}, {"name": "Ethereal Stride", "entries": ["The nightmare and up to three willing creatures within 5 feet of it magically enter the Ethereal Plane from the Material Plane, or vice versa."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('noble', 'Noble', 'humanoid', 'any race', 'M', 'A', 15, 9, '{"walk": 30}', 11, 12, 11, 12, 14, 16, '1/8', 0, 2, '{}', '{"deception": "+5", "insight": "+4", "persuasion": "+5"}', '[]', '[]', '[]', '[]', '["any two languages"]', '[]', '[{"name": "Rapier", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d8 + 1}) piercing damage."]}]', '[]', '[]', '["urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('nothic', 'Nothic', 'aberration', '', 'M', 'N, E', 15, 45, '{"walk": 30}', 14, 16, 16, 13, 10, 8, '2', 0, 2, '{}', '{"arcana": "+3", "insight": "+4", "perception": "+2", "stealth": "+5"}', '[]', '[]', '[]', '["truesight 120 ft."]', '["Undercommon"]', '[{"name": "Keen Sight", "entries": ["The nothic has advantage on Wisdom ({@skill Perception}) checks that rely on sight."]}]', '[{"name": "Multiattack", "entries": ["The nothic makes two claw attacks."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}6 ({@damage 1d6 + 3}) slashing damage."]}, {"name": "Rotting Gaze", "entries": ["The nothic targets one creature it can see within 30 feet of it. The target must succeed on a {@dc 12} Constitution saving throw against this magic or take 10 ({@damage 3d6}) necrotic damage."]}, {"name": "Weird Insight", "entries": ["The nothic targets one creature it can see within 30 feet of it. The target must contest its Charisma ({@skill Deception}) check against the nothic''s Wisdom ({@skill Insight}) check. If the nothic wins, it magically learns one fact or secret about the target. The target automatically wins if it is immune to being {@condition charmed}."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('nycaloth', 'Nycaloth', 'fiend', 'yugoloth', 'L', 'N, E', 18, 123, '{"walk": 40, "fly": 60}', 20, 11, 19, 12, 10, 15, '9', 0, 2, '{}', '{"intimidation": "+6", "perception": "+4", "stealth": "+4"}', '[]', '[]', '[]', '["blindsight 60 ft.", "darkvision 60 ft."]', '["Abyssal", "Infernal", "telepathy 60 ft."]', '[{"name": "Magic Resistance", "entries": ["The nycaloth has advantage on saving throws against spells and other magical effects."]}, {"name": "Magic Weapons", "entries": ["The nycaloth''s weapon attacks are magical."]}]', '[{"name": "Multiattack", "entries": ["The nycaloth makes two melee attacks, or it makes one melee attack and teleports before or after the attack."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 9} to hit, reach 5 ft., one target. {@h}12 ({@damage 2d6 + 5}) slashing damage. If the target is a creature, it must succeed on a {@dc 16} Constitution saving throw or take 5 ({@damage 2d4}) slashing damage at the start of each of its turns due to a fiendish wound. Each time the nycaloth hits the wounded target with this attack, the damage dealt by the wound increases by 5 ({@damage 2d4}). Any creature can take an action to stanch the wound with a successful {@dc 13} Wisdom ({@skill Medicine}) check. The wound also closes if the target receives magical healing."]}, {"name": "Greataxe", "entries": ["{@atk mw} {@hit 9} to hit, reach 5 ft., one target. {@h}18 ({@damage 2d12 + 5}) slashing damage."]}, {"name": "Teleport", "entries": ["The nycaloth magically teleports, along with any equipment it is wearing or carrying, up to 60 feet to an unoccupied space it can see."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('ochre_jelly', 'Ochre Jelly', 'ooze', '', 'L', 'U', 8, 45, '{"walk": 10, "climb": 10}', 15, 6, 14, 2, 6, 1, '2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 60 ft. (blind beyond this radius)"]', '[]', '[{"name": "Amorphous", "entries": ["The jelly can move through a space as narrow as 1 inch wide without squeezing."]}, {"name": "Spider Climb", "entries": ["The jelly can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."]}]', '[{"name": "Pseudopod", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}9 ({@damage 2d6 + 2}) bludgeoning damage plus 3 ({@damage 1d6}) acid damage."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('octopus', 'Octopus', 'beast', '', 'S', 'U', 12, 3, '{"walk": 5, "swim": 30}', 4, 15, 11, 3, 10, 4, '0', 0, 2, '{}', '{"perception": "+2", "stealth": "+4"}', '[]', '[]', '[]', '["darkvision 30 ft."]', '[]', '[{"name": "Hold Breath", "entries": ["While out of water, the octopus can hold its breath for 30 minutes."]}, {"name": "Underwater Camouflage", "entries": ["The octopus has advantage on Dexterity ({@skill Stealth}) checks made while underwater."]}, {"name": "Water Breathing", "entries": ["The octopus can breathe only underwater."]}]', '[{"name": "Tentacles", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}1 bludgeoning damage, and the target is {@condition grappled} (escape {@dc 10}). Until this grapple ends, the octopus can''t use its tentacles on another target."]}, {"name": "Ink Cloud (Recharges after a Short or Long Rest)", "entries": ["A 5-foot-radius cloud of ink extends all around the octopus if it is underwater. The area is heavily obscured for 1 minute, although a significant current can disperse the ink. After releasing the ink, the octopus can use the Dash action as a bonus action."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('ogre', 'Ogre', 'giant', '', 'L', 'C, E', 11, 59, '{"walk": 40}', 19, 8, 16, 5, 7, 7, '2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Common", "Giant"]', '[]', '[{"name": "Greatclub", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}13 ({@damage 2d8 + 4}) bludgeoning damage."]}, {"name": "Javelin", "entries": ["{@atk mw,rw} {@hit 6} to hit, reach 5 ft. or range 30/120 ft., one target. {@h}11 ({@damage 2d6 + 4}) piercing damage."]}]', '[]', '[]', '["grassland", "forest", "swamp", "hill", "desert", "coastal", "arctic", "underdark", "mountain"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('ogre_zombie', 'Ogre Zombie', 'undead', '', 'L', 'N, E', 8, 85, '{"walk": 30}', 19, 6, 18, 3, 6, 5, '2', 0, 2, '{"wis": "+0"}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["understands Common and Giant but can''t speak"]', '[{"name": "Undead Fortitude", "entries": ["If damage reduces the zombie to 0 hit points, it must make a Constitution saving throw with a DC of 5 + the damage taken, unless the damage is radiant or from a critical hit. On a success, the zombie drops to 1 hit point instead."]}]', '[{"name": "Morningstar", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}13 ({@damage 2d8 + 4}) bludgeoning damage."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('oni', 'Oni', 'giant', '', 'L', 'L, E', 16, 110, '{"walk": 30, "fly": 30}', 19, 11, 16, 14, 12, 15, '7', 0, 2, '{"dex": "+3", "con": "+6", "wis": "+4", "cha": "+5"}', '{"arcana": "+5", "deception": "+8", "perception": "+4"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Common", "Giant"]', '[{"name": "Magic Weapons", "entries": ["The oni''s weapon attacks are magical."]}, {"name": "Regeneration", "entries": ["The oni regains 10 hit points at the start of its turn if it has at least 1 hit point."]}]', '[{"name": "Multiattack", "entries": ["The oni makes two attacks, either with its claws or its glaive."]}, {"name": "Claw (Oni Form Only)", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}8 ({@damage 1d8 + 4}) slashing damage."]}, {"name": "Glaive", "entries": ["{@atk mw} {@hit 7} to hit, reach 10 ft., one target. {@h}15 ({@damage 2d10 + 4}) slashing damage, or 9 ({@damage 1d10 + 4}) slashing damage in Small or Medium form."]}, {"name": "Change Shape", "entries": ["The oni magically polymorphs into a Small or Medium humanoid, into a Large giant, or back into its true form. Other than its size, its statistics are the same in each form. The only equipment that is transformed is its glaive, which shrinks so that it can be wielded in humanoid form. If the oni dies, it reverts to its true form, and its glaive reverts to its normal size."]}]', '[]', '[]', '["forest", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('orc', 'Orc', 'humanoid', 'orc', 'M', 'C, E', 13, 15, '{"walk": 30}', 16, 12, 16, 7, 11, 10, '1/2', 0, 2, '{}', '{"intimidation": "+2"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Common", "Orc"]', '[{"name": "Aggressive", "entries": ["As a bonus action, the orc can move up to its speed toward a hostile creature that it can see."]}]', '[{"name": "Greataxe", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}9 ({@damage 1d12 + 3}) slashing damage."]}, {"name": "Javelin", "entries": ["{@atk mw,rw} {@hit 5} to hit, reach 5 ft. or range 30/120 ft., one target. {@h}6 ({@damage 1d6 + 3}) piercing damage."]}]', '[]', '[]', '["underdark", "mountain", "grassland", "forest", "swamp", "hill", "arctic"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('orc_eye_of_gruumsh', 'Orc Eye of Gruumsh', 'humanoid', 'orc', 'M', 'C, E', 16, 45, '{"walk": 30}', 16, 12, 17, 9, 13, 12, '2', 0, 2, '{}', '{"intimidation": "+3", "religion": "+1"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Common", "Orc"]', '[{"name": "Aggressive", "entries": ["As a bonus action, the orc can move up to its speed toward a hostile creature that it can see."]}, {"name": "Gruumsh''s Fury", "entries": ["The orc deals an extra 4 ({@damage 1d8}) damage when it hits with a weapon attack (included in the attacks)."]}]', '[{"name": "Spear", "entries": ["{@atk mw,rw} {@hit 5} to hit, reach 5 ft. or range 20/60 ft., one target. {@h}11 ({@damage 1d6 + 3} plus {@damage 1d8}) piercing damage, or 12 ({@damage 2d8 + 3}) piercing damage if used with two hands to make a melee attack."]}]', '[]', '[]', '["underdark", "mountain", "grassland", "forest", "swamp", "hill", "arctic"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('orc_war_chief', 'Orc War Chief', 'humanoid', 'orc', 'M', 'C, E', 16, 93, '{"walk": 30}', 18, 12, 18, 11, 11, 16, '4', 0, 2, '{"str": "+6", "con": "+6", "wis": "+2"}', '{"intimidation": "+5"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Common", "Orc"]', '[{"name": "Aggressive", "entries": ["As a bonus action, the orc can move up to its speed toward a hostile creature that it can see."]}, {"name": "Gruumsh''s Fury", "entries": ["The orc deals an extra 4 ({@damage 1d8}) damage when it hits with a weapon attack (included in the attacks)."]}]', '[{"name": "Multiattack", "entries": ["The orc makes two attacks with its greataxe or its spear."]}, {"name": "Greataxe", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}15 ({@damage 1d12 + 4} plus {@damage 1d8}) slashing damage."]}, {"name": "Spear", "entries": ["{@atk mw,rw} {@hit 6} to hit, reach 5 ft. or range 20/60 ft., one target. {@h}12 ({@damage 1d6 + 4} plus {@damage 1d8}) piercing damage, or 13 ({@damage 2d8 + 4}) piercing damage if used with two hands to make a melee attack."]}, {"name": "Battle Cry (1/Day)", "entries": ["Each creature of the war chief''s choice that is within 30 feet of it, can hear it, and not already affected by Battle Cry gain advantage on attack rolls until the start of the war chief''s next turn. The war chief can then make one attack as a bonus action."]}]', '[]', '[]', '["underdark", "mountain", "grassland", "forest", "swamp", "hill", "arctic"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('orog', 'Orog', 'humanoid', 'orc', 'M', 'C, E', 18, 42, '{"walk": 30}', 18, 12, 18, 12, 11, 12, '2', 0, 2, '{}', '{"intimidation": "+5", "survival": "+2"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Common", "Orc"]', '[{"name": "Aggressive", "entries": ["As a bonus action, the orog can move up to its speed toward a hostile creature that it can see."]}]', '[{"name": "Multiattack", "entries": ["The orog makes two greataxe attacks."]}, {"name": "Greataxe", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}10 ({@damage 1d12 + 4}) slashing damage."]}, {"name": "Javelin", "entries": ["{@atk mw,rw} {@hit 6} to hit, reach 5 ft. or range 30/120 ft., one target. {@h}7 ({@damage 1d6 + 4}) piercing damage."]}]', '[]', '[]', '["underdark", "mountain", "grassland", "forest", "hill", "arctic"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('otyugh', 'Otyugh', 'aberration', '', 'L', 'N', 14, 114, '{"walk": 30}', 16, 11, 19, 6, 13, 6, '5', 0, 2, '{"con": "+7"}', '{}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Otyugh"]', '[{"name": "Limited Telepathy", "entries": ["The otyugh can magically transmit simple messages and images to any creature within 120 feet of it that can understand a language. This form of telepathy doesn''t allow the receiving creature to telepathically respond."]}]', '[{"name": "Multiattack", "entries": ["The otyugh makes three attacks: one with its bite and two with its tentacles."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}12 ({@damage 2d8 + 3}) piercing damage. If the target is a creature, it must succeed on a {@dc 15} Constitution saving throw against disease or become {@condition poisoned} until the disease is cured. Every 24 hours that elapse, the target must repeat the saving throw, reducing its hit point maximum by 5 ({@dice 1d10}) on a failure. The disease is cured on a success. The target dies if the disease reduces its hit point maximum to 0. This reduction to the target''s hit point maximum lasts until the disease is cured."]}, {"name": "Tentacle", "entries": ["{@atk mw} {@hit 6} to hit, reach 10 ft., one target. {@h}7 ({@damage 1d8 + 3}) bludgeoning damage plus 4 ({@damage 1d8}) piercing damage. If the target is Medium or smaller, it is {@condition grappled} (escape {@dc 13}) and {@condition restrained} until the grapple ends. The otyugh has two tentacles, each of which can grapple one target."]}, {"name": "Tentacle Slam", "entries": ["The otyugh slams creatures {@condition grappled} by it into each other or a solid surface. Each creature must succeed on a {@dc 14} Constitution saving throw or take 10 ({@damage 2d6 + 3}) bludgeoning damage and be {@condition stunned} until the end of the otyugh''s next turn. On a successful save, the target takes half the bludgeoning damage and isn''t {@condition stunned}."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('owl', 'Owl', 'beast', '', 'T', 'U', 11, 1, '{"walk": 5, "fly": 60}', 3, 13, 8, 2, 12, 7, '0', 0, 2, '{}', '{"perception": "+3", "stealth": "+3"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '[]', '[{"name": "Flyby", "entries": ["The owl doesn''t provoke opportunity attacks when it flies out of an enemy''s reach."]}, {"name": "Keen Hearing and Sight", "entries": ["The owl has advantage on Wisdom ({@skill Perception}) checks that rely on hearing or sight."]}]', '[{"name": "Talons", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}1 slashing damage."]}]', '[]', '[]', '["forest", "arctic"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('owlbear', 'Owlbear', 'monstrosity', '', 'L', 'U', 13, 59, '{"walk": 40}', 20, 12, 17, 3, 12, 7, '3', 0, 2, '{}', '{"perception": "+3"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '[]', '[{"name": "Keen Sight and Smell", "entries": ["The owlbear has advantage on Wisdom ({@skill Perception}) checks that rely on sight or smell."]}]', '[{"name": "Multiattack", "entries": ["The owlbear makes two attacks: one with its beak and one with its claws."]}, {"name": "Beak", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one creature. {@h}10 ({@damage 1d10 + 5}) piercing damage."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}14 ({@damage 2d8 + 5}) slashing damage."]}]', '[]', '[]', '["forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('panther', 'Panther', 'beast', '', 'M', 'U', 12, 13, '{"walk": 50, "climb": 40}', 14, 15, 10, 3, 14, 7, '1/4', 0, 2, '{}', '{"perception": "+4", "stealth": "+6"}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Keen Smell", "entries": ["The panther has advantage on Wisdom ({@skill Perception}) checks that rely on smell."]}, {"name": "Pounce", "entries": ["If the panther moves at least 20 feet straight toward a creature and then hits it with a claw attack on the same turn, that target must succeed on a {@dc 12} Strength saving throw or be knocked {@condition prone}. If the target is {@condition prone}, the panther can make one bite attack against it as a bonus action."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}4 ({@damage 1d4 + 2}) slashing damage."]}]', '[]', '[]', '["grassland", "forest", "hill"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('pegasus', 'Pegasus', 'celestial', '', 'L', 'C, G', 12, 59, '{"walk": 60, "fly": 90}', 18, 15, 16, 10, 15, 13, '2', 0, 2, '{"dex": "+4", "wis": "+4", "cha": "+3"}', '{"perception": "+6"}', '[]', '[]', '[]', '[]', '["understands Celestial", "Common", "Elvish", "and Sylvan but can''t speak"]', '[]', '[{"name": "Hooves", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}11 ({@damage 2d6 + 4}) bludgeoning damage."]}]', '[]', '[]', '["grassland", "forest", "hill"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('pentadrone', 'Pentadrone', 'construct', '', 'L', 'L, N', 16, 32, '{"walk": 40}', 15, 14, 12, 10, 10, 13, '2', 0, 2, '{}', '{"perception": "+4"}', '[]', '[]', '[]', '["truesight 120 ft."]', '["Modron"]', '[{"name": "Axiomatic Mind", "entries": ["The pentadrone can''t be compelled to act in a manner contrary to its nature or its instructions."]}, {"name": "Disintegration", "entries": ["If the pentadrone dies, its body disintegrates into dust, leaving behind its weapons and anything else it was carrying."]}]', '[{"name": "Multiattack", "entries": ["The pentadrone makes five arm attacks."]}, {"name": "Arm", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d6 + 2}) bludgeoning damage."]}, {"name": "Paralysis Gas {@recharge 5}", "entries": ["The pentadrone exhales a 30-foot cone of gas. Each creature in that area must succeed on a {@dc 11} Constitution saving throw or be {@condition paralyzed} for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('peryton', 'Peryton', 'monstrosity', '', 'M', 'C, E', 13, 33, '{"walk": 20, "fly": 60}', 16, 12, 13, 9, 12, 10, '2', 0, 2, '{}', '{"perception": "+5"}', '[]', '[]', '[]', '[]', '["understands Common and Elvish but can''t speak"]', '[{"name": "Dive Attack", "entries": ["If the peryton is flying and dives at least 30 feet straight toward a target and then hits it with a melee weapon attack, the attack deals an extra 9 ({@damage 2d8}) damage to the target."]}, {"name": "Flyby", "entries": ["The peryton doesn''t provoke an opportunity attack when it flies out of an enemy''s reach."]}, {"name": "Keen Sight and Smell", "entries": ["The peryton has advantage on Wisdom ({@skill Perception}) checks that rely on sight or smell."]}]', '[{"name": "Multiattack", "entries": ["The peryton makes one gore attack and one talon attack."]}, {"name": "Gore", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}7 ({@damage 1d8 + 3}) piercing damage."]}, {"name": "Talons", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}8 ({@damage 2d4 + 3}) piercing damage."]}]', '[]', '[]', '["mountain", "hill"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('phase_spider', 'Phase Spider', 'monstrosity', '', 'L', 'U', 13, 32, '{"walk": 30, "climb": 30}', 15, 15, 12, 6, 10, 6, '3', 0, 2, '{}', '{"stealth": "+6"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '[]', '[{"name": "Ethereal Jaunt", "entries": ["As a bonus action, the spider can magically shift from the Material Plane to the Ethereal Plane, or vice versa."]}, {"name": "Spider Climb", "entries": ["The spider can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."]}, {"name": "Web Walker", "entries": ["The spider ignores movement restrictions caused by webbing."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one creature. {@h}7 ({@damage 1d10 + 2}) piercing damage, and the target must make a {@dc 11} Constitution saving throw, taking 18 ({@damage 4d8}) poison damage on a failed save, or half as much damage on a successful one. If the poison damage reduces the target to 0 hit points, the target is stable but {@condition poisoned} for 1 hour, even after regaining hit points, and is {@condition paralyzed} while {@condition poisoned} in this way."]}]', '[]', '[]', '["underdark", "grassland", "forest", "hill", "urban", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('piercer', 'Piercer', 'monstrosity', '', 'M', 'U', 15, 22, '{"walk": 5, "climb": 5}', 10, 13, 16, 1, 7, 3, '1/2', 0, 2, '{}', '{"stealth": "+5"}', '[]', '[]', '[]', '["blindsight 30 ft.", "darkvision 60 ft."]', '[]', '[{"name": "False Appearance", "entries": ["While the piercer remains motionless on the ceiling, it is indistinguishable from a normal stalactite."]}, {"name": "Spider Climb", "entries": ["The piercer can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."]}]', '[{"name": "Drop", "entries": ["{@atk mw} {@hit 3} to hit, one creature directly underneath the piercer. {@h}3 ({@damage 1d6}) piercing damage per 10 feet fallen, up to 21 ({@damage 6d6}). Miss: The piercer takes half the normal falling damage for the distance fallen."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('pit_fiend', 'Pit Fiend', 'fiend', 'devil', 'L', 'L, E', 19, 300, '{"walk": 30, "fly": 60}', 26, 14, 24, 22, 18, 24, '20', 0, 2, '{"dex": "+8", "con": "+13", "wis": "+10"}', '{}', '[]', '[]', '[]', '["truesight 120 ft."]', '["Infernal", "telepathy 120 ft."]', '[{"name": "Fear Aura", "entries": ["Any creature hostile to the pit fiend that starts its turn within 20 feet of the pit fiend must make a {@dc 21} Wisdom saving throw, unless the pit fiend is {@condition incapacitated}. On a failed save, the creature is {@condition frightened} until the start of its next turn. If a creature''s saving throw is successful, the creature is immune to the pit fiend''s Fear Aura for the next 24 hours."]}, {"name": "Magic Resistance", "entries": ["The pit fiend has advantage on saving throws against spells and other magical effects."]}, {"name": "Magic Weapons", "entries": ["The pit fiend''s weapon attacks are magical."]}]', '[{"name": "Multiattack", "entries": ["The pit fiend makes four attacks: one with its bite, one with its claw, one with its mace, and one with its tail."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 14} to hit, reach 5 ft., one target. {@h}22 ({@damage 4d6 + 8}) piercing damage. The target must succeed on a {@dc 21} Constitution saving throw or become {@condition poisoned}. While {@condition poisoned} in this way, the target can''t regain hit points, and it takes 21 ({@damage 6d6}) poison damage at the start of each of its turns. The {@condition poisoned} target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 14} to hit, reach 10 ft., one target. {@h}17 ({@damage 2d8 + 8}) slashing damage."]}, {"name": "Mace", "entries": ["{@atk mw} {@hit 14} to hit, reach 10 ft., one target. {@h}15 ({@damage 2d6 + 8}) bludgeoning damage plus 21 ({@damage 6d6}) fire damage."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 14} to hit, reach 10 ft., one target. {@h}24 ({@damage 3d10 + 8}) bludgeoning damage."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('pixie', 'Pixie', 'fey', '', 'T', 'N, G', 15, 1, '{"walk": 10, "fly": 30}', 2, 20, 8, 10, 14, 15, '1/4', 0, 2, '{}', '{"perception": "+4", "stealth": "+7"}', '[]', '[]', '[]', '[]', '["Sylvan"]', '[{"name": "Magic Resistance", "entries": ["The pixie has advantage on saving throws against spells and other magical effects."]}]', '[{"name": "Superior Invisibility", "entries": ["The pixie magically turns {@condition invisible} until its {@status concentration} ends (as if {@status concentration||concentrating} on a spell). Any equipment the pixie wears or carries is {@condition invisible} with it."]}]', '[]', '[]', '["forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('planetar', 'Planetar', 'celestial', '', 'L', 'L, G', 19, 200, '{"walk": 40, "fly": 120}', 24, 20, 24, 19, 22, 25, '16', 0, 2, '{"con": "+12", "wis": "+11", "cha": "+12"}', '{"perception": "+11"}', '[]', '[]', '[]', '["truesight 120 ft."]', '["all", "telepathy 120 ft."]', '[{"name": "Angelic Weapons", "entries": ["The planetar''s weapon attacks are magical. When the planetar hits with any weapon, the weapon deals an extra {@damage 5d8} radiant damage (included in the attack)."]}, {"name": "Divine Awareness", "entries": ["The planetar knows if it hears a lie."]}, {"name": "Magic Resistance", "entries": ["The planetar has advantage on saving throws against spells and other magical effects."]}]', '[{"name": "Multiattack", "entries": ["The planetar makes two melee attacks."]}, {"name": "Greatsword", "entries": ["{@atk mw} {@hit 12} to hit, reach 5 ft., one target. {@h}21 ({@damage 4d6 + 7}) slashing damage plus 22 ({@damage 5d8}) radiant damage."]}, {"name": "Healing Touch (4/Day)", "entries": ["The planetar touches another creature. The target magically regains 30 ({@dice 6d8 + 3}) hit points and is freed from any curse, disease, poison, blindness, or deafness."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('plesiosaurus', 'Plesiosaurus', 'beast', '', 'L', 'U', 13, 68, '{"walk": 20, "swim": 40}', 18, 15, 16, 2, 12, 5, '2', 0, 2, '{}', '{"perception": "+3", "stealth": "+4"}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Hold Breath", "entries": ["The plesiosaurus can hold its breath for 1 hour."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 6} to hit, reach 10 ft., one target. {@h}14 ({@damage 3d6 + 4}) piercing damage."]}]', '[]', '[]', '["underwater", "coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('poisonous_snake', 'Poisonous Snake', 'beast', '', 'T', 'U', 13, 2, '{"walk": 30, "swim": 30}', 2, 16, 11, 1, 10, 3, '1/8', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 10 ft."]', '[]', '[]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}1 piercing damage, and the target must make a {@dc 10} Constitution saving throw, taking 5 ({@damage 2d4}) poison damage on a failed save, or half as much damage on a successful one."]}]', '[]', '[]', '["grassland", "forest", "swamp", "hill", "desert", "coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('polar_bear', 'Polar Bear', 'beast', '', 'L', 'U', 12, 42, '{"walk": 40, "swim": 30}', 20, 10, 16, 2, 13, 7, '2', 0, 2, '{}', '{"perception": "+3"}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Keen Smell", "entries": ["The bear has advantage on Wisdom ({@skill Perception}) checks that rely on smell."]}]', '[{"name": "Multiattack", "entries": ["The bear makes two attacks: one with its bite and one with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}9 ({@damage 1d8 + 5}) piercing damage."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}12 ({@damage 2d6 + 5}) slashing damage."]}]', '[]', '[]', '["underdark", "arctic"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('poltergeist', 'Poltergeist', 'undead', '', 'M', 'C, E', 12, 22, '{"walk": 0, "fly": {"number": 50, "condition": "(hover)"}, "canHover": true}', 1, 14, 11, 10, 10, 11, '2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["understands all languages it knew in life but can''t speak"]', '[{"name": "Incorporeal Movement", "entries": ["The poltergeist can move through other creatures and objects as if they were {@quickref difficult terrain||3}. It takes 5 ({@damage 1d10}) force damage if it ends its turn inside an object."]}, {"name": "Sunlight Sensitivity", "entries": ["While in sunlight, the poltergeist has disadvantage on attack rolls, as well as on Wisdom ({@skill Perception}) checks that rely on sight."]}, {"name": "Invisibility", "entries": ["The poltergeist is {@condition invisible}."]}]', '[{"name": "Forceful Slam", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one creature. {@h}10 ({@damage 3d6}) force damage."]}, {"name": "Telekinetic Thrust", "entries": ["The poltergeist targets a creature or unattended object within 30 feet of it. A creature must be Medium or smaller to be affected by this magic, and an object can weigh up to 150 pounds.", "If the target is a creature, the poltergeist makes a Charisma check contested by the target''s Strength check. If the poltergeist wins the contest, the poltergeist hurls the target up to 30 feet in any direction, including upward. If the target then comes into contact with a hard surface or heavy object, the target takes {@damage 1d6} damage per 10 feet moved.", "If the target is an object that isn''t being worn or carried, the poltergeist hurls it up to 30 feet in any direction. The poltergeist can use the object as a ranged weapon, attacking one creature along the object''s path ({@hit 4} to hit) and dealing 5 ({@damage 2d4}) bludgeoning damage on a hit."]}]', '[]', '[]', '["underdark", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('pony', 'Pony', 'beast', '', 'M', 'U', 10, 11, '{"walk": 40}', 15, 10, 13, 2, 11, 7, '1/8', 0, 2, '{}', '{}', '[]', '[]', '[]', '[]', '[]', '[]', '[{"name": "Hooves", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}7 ({@damage 2d4 + 2}) bludgeoning damage."]}]', '[]', '[]', '["urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('priest', 'Priest', 'humanoid', 'any race', 'M', 'A', 13, 27, '{"walk": 30}', 10, 10, 12, 13, 16, 13, '2', 0, 2, '{}', '{"medicine": "+7", "persuasion": "+3", "religion": "+5"}', '[]', '[]', '[]', '[]', '["any two languages"]', '[{"name": "Divine Eminence", "entries": ["As a bonus action, the priest can expend a spell slot to cause its melee weapon attacks to magically deal an extra 10 ({@damage 3d6}) radiant damage to a target on a hit. This benefit lasts until the end of the turn. If the priest expends a spell slot of 2nd level or higher, the extra damage increases by {@damage 1d6} for each level above 1st."]}]', '[{"name": "Mace", "entries": ["{@atk mw} {@hit 2} to hit, reach 5 ft., one target. {@h}3 ({@damage 1d6}) bludgeoning damage."]}]', '[]', '[]', '["urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('pseudodragon', 'Pseudodragon', 'dragon', '', 'T', 'N, G', 13, 7, '{"walk": 15, "fly": 60}', 6, 15, 13, 10, 12, 10, '1/4', 0, 2, '{}', '{"perception": "+3", "stealth": "+4"}', '[]', '[]', '[]', '["blindsight 10 ft.", "darkvision 60 ft."]', '["understands Common and Draconic but can''t speak"]', '[{"name": "Keen Senses", "entries": ["The pseudodragon has advantage on Wisdom ({@skill Perception}) checks that rely on sight, hearing, or smell."]}, {"name": "Magic Resistance", "entries": ["The pseudodragon has advantage on saving throws against spells and other magical effects."]}, {"name": "Limited Telepathy", "entries": ["The pseudodragon can magically communicate simple ideas, emotions, and images telepathically with any creature within 100 feet of it that can understand a language."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}4 ({@damage 1d4 + 2}) piercing damage."]}, {"name": "Sting", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one creature. {@h}4 ({@damage 1d4 + 2}) piercing damage, and the target must succeed on a {@dc 11} Constitution saving throw or become {@condition poisoned} for 1 hour. If the saving throw fails by 5 or more, the target falls {@condition unconscious} for the same duration, or until it takes damage or another creature uses an action to shake it awake."]}]', '[]', '[]', '["mountain", "forest", "hill", "urban", "desert", "coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('pteranodon', 'Pteranodon', 'beast', '', 'M', 'U', 13, 13, '{"walk": 10, "fly": 60}', 12, 15, 10, 2, 9, 5, '1/4', 0, 2, '{}', '{"perception": "+1"}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Flyby", "entries": ["The pteranodon doesn''t provoke opportunity attacks when it flies out of an enemy''s reach."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}6 ({@damage 2d4 + 1}) piercing damage"]}]', '[]', '[]', '["mountain", "grassland", "coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('purple_worm', 'Purple Worm', 'monstrosity', '', 'G', 'U', 18, 247, '{"walk": 50, "burrow": 30}', 28, 7, 22, 1, 8, 4, '15', 0, 2, '{"con": "+11", "wis": "+4"}', '{}', '[]', '[]', '[]', '["blindsight 30 ft.", "tremorsense 60 ft."]', '[]', '[{"name": "Tunneler", "entries": ["The worm can burrow through solid rock at half its burrow speed and leaves a 10-foot-diameter tunnel in its wake."]}]', '[{"name": "Multiattack", "entries": ["The worm makes two attacks: one with its bite and one with its stinger."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 14} to hit, reach 10 ft., one target. {@h}22 ({@damage 3d8 + 9}) piercing damage. If the target is a Large or smaller creature, it must succeed on a {@dc 19} Dexterity saving throw or be swallowed by the worm. A swallowed creature is {@condition blinded} and {@condition restrained}, it has {@quickref Cover||3||total cover} against attacks and other effects outside the worm, and it takes 21 ({@damage 6d6}) acid damage at the start of each of the worm''s turns.", "If the worm takes 30 damage or more on a single turn from a creature inside it, the worm must succeed on a {@dc 21} Constitution saving throw at the end of that turn or regurgitate all swallowed creatures, which fall {@condition prone} in a space within 10 feet of the worm. If the worm dies, a swallowed creature is no longer {@condition restrained} by it and can escape from the corpse by using 20 feet of movement, exiting {@condition prone}."]}, {"name": "Tail Stinger", "entries": ["{@atk mw} {@hit 14} to hit, reach 10 ft., one creature. {@h}19 ({@damage 3d6 + 9}) piercing damage, and the target must make a {@dc 19} Constitution saving throw, taking 42 ({@damage 12d6}) poison damage on a failed save, or half as much damage on a successful one."]}]', '[]', '[]', '["underdark", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('quadrone', 'Quadrone', 'construct', '', 'M', 'L, N', 16, 22, '{"walk": 30, "fly": 30}', 12, 14, 12, 10, 10, 11, '1', 0, 2, '{}', '{"perception": "+2"}', '[]', '[]', '[]', '["truesight 120 ft."]', '["Modron"]', '[{"name": "Axiomatic Mind", "entries": ["The quadrone can''t be compelled to act in a manner contrary to its nature or its instructions."]}, {"name": "Disintegration", "entries": ["If the quadrone dies, its body disintegrates into dust, leaving behind its weapons and anything else it was carrying."]}]', '[{"name": "Multiattack", "entries": ["The quadrone makes two fist attacks or four shortbow attacks."]}, {"name": "Fist", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}3 ({@damage 1d4 + 1}) bludgeoning damage."]}, {"name": "Shortbow", "entries": ["{@atk rw} {@hit 4} to hit, range 80/320 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('quaggoth', 'Quaggoth', 'humanoid', 'quaggoth', 'M', 'C, N', 13, 45, '{"walk": 30, "climb": 30}', 17, 12, 16, 6, 12, 7, '2', 0, 2, '{}', '{"athletics": "+5"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Undercommon"]', '[{"name": "Wounded Fury", "entries": ["While it has 10 hit points or fewer, the quaggoth has advantage on attack rolls. In addition, it deals an extra 7 ({@damage 2d6}) damage to any target it hits with a melee attack."]}]', '[{"name": "Multiattack", "entries": ["The quaggoth makes two claw attacks."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}6 ({@damage 1d6 + 3}) slashing damage."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('quaggoth_spore_servant', 'Quaggoth Spore Servant', 'plant', '', 'M', 'U', 13, 45, '{"walk": 20, "climb": 20}', 17, 12, 16, 2, 6, 1, '1', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 30 ft. (blind beyond this radius)"]', '[]', '[]', '[{"name": "Multiattack", "entries": ["The spore servant makes two claw attacks."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}6 ({@damage 1d6 + 3}) slashing damage."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('quaggoth_thonot', 'Quaggoth Thonot', 'humanoid', 'quaggoth', 'M', 'C, N', 13, 45, '{"walk": 30, "climb": 30}', 17, 12, 16, 6, 12, 7, '3', 0, 2, '{}', '{"athletics": "+5"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Undercommon"]', '[{"name": "Wounded Fury", "entries": ["While it has 10 hit points or fewer, the quaggoth has advantage on attack rolls. In addition, it deals an extra 7 ({@damage 2d6}) damage to any target it hits with a melee attack."]}]', '[{"name": "Multiattack", "entries": ["The quaggoth makes two claw attacks."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}6 ({@damage 1d6 + 3}) slashing damage."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('quasit', 'Quasit', 'fiend', 'demon', 'T', 'C, E', 13, 7, '{"walk": 40}', 5, 17, 10, 7, 10, 10, '1', 0, 2, '{}', '{"stealth": "+5"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Abyssal", "Common"]', '[{"name": "Shapechanger", "entries": ["The quasit can use its action to polymorph into a beast form that resembles a bat (speed 10 feet fly 40 ft.), a centipede (40 ft., climb 40 ft.), or a toad (40 ft., swim 40 ft.), or back into its true form. Its statistics are the same in each form, except for the speed changes noted. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies."]}, {"name": "Magic Resistance", "entries": ["The quasit has advantage on saving throws against spells and other magical effects."]}]', '[{"name": "Claw (Bite in Beast Form)", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d4 + 3}) piercing damage, and the target must succeed on a {@dc 10} Constitution saving throw or take 5 ({@damage 2d4}) poison damage and become {@condition poisoned} for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."]}, {"name": "Scare (1/Day)", "entries": ["One creature of the quasit''s choice within 20 feet of it must succeed on a {@dc 10} Wisdom saving throw or be {@condition frightened} for 1 minute. The target can repeat the saving throw at the end of each of its turns, with disadvantage if the quasit is within line of sight, ending the effect on itself on a success."]}, {"name": "Invisibility", "entries": ["The quasit magically turns {@condition invisible} until it attacks or uses Scare, or until its {@status concentration} ends (as if {@status concentration||concentrating} on a spell). Any equipment the quasit wears or carries is {@condition invisible} with it."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('quipper', 'Quipper', 'beast', '', 'T', 'U', 13, 1, '{"swim": 40}', 2, 16, 9, 1, 7, 2, '0', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '[]', '[{"name": "Blood Frenzy", "entries": ["The quipper has advantage on melee attack rolls against any creature that doesn''t have all its hit points."]}, {"name": "Water Breathing", "entries": ["The quipper can breathe only underwater."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}1 piercing damage."]}]', '[]', '[]', '["underwater"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('rakshasa', 'Rakshasa', 'fiend', '', 'M', 'L, E', 16, 110, '{"walk": 40}', 14, 17, 18, 13, 16, 20, '13', 0, 2, '{}', '{"deception": "+10", "insight": "+8"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Common", "Infernal"]', '[{"name": "Limited Magic Immunity", "entries": ["The rakshasa can''t be affected or detected by spells of 6th level or lower unless it wishes to be. It has advantage on saving throws against all other spells and magical effects."]}]', '[{"name": "Multiattack", "entries": ["The rakshasa makes two claw attacks."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}9 ({@damage 2d6 + 2}) slashing damage, and the target is cursed if it is a creature. The magical curse takes effect whenever the target takes a short or long rest, filling the target''s thoughts with horrible images and dreams. The cursed target gains no benefit from finishing a short or long rest. The curse lasts until it is lifted by a {@spell remove curse} spell or similar magic."]}]', '[]', '[]', '["urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('rat', 'Rat', 'beast', '', 'T', 'U', 10, 1, '{"walk": 20}', 2, 11, 9, 2, 10, 4, '0', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 30 ft."]', '[]', '[{"name": "Keen Smell", "entries": ["The rat has advantage on Wisdom ({@skill Perception}) checks that rely on smell."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 0} to hit, reach 5 ft., one target. {@h}1 piercing damage."]}]', '[]', '[]', '["swamp", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('raven', 'Raven', 'beast', '', 'T', 'U', 12, 1, '{"walk": 10, "fly": 50}', 2, 14, 8, 2, 12, 6, '0', 0, 2, '{}', '{"perception": "+3"}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Mimicry", "entries": ["The raven can mimic simple sounds it has heard, such as a person whispering, a baby crying, or an animal chittering. A creature that hears the sounds can tell they are imitations with a successful {@dc 10} Wisdom ({@skill Insight}) check."]}]', '[{"name": "Beak", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}1 piercing damage."]}]', '[]', '[]', '["swamp", "hill", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('red_dragon_wyrmling', 'Red Dragon Wyrmling', 'dragon', '', 'M', 'C, E', 17, 75, '{"walk": 30, "climb": 30, "fly": 60}', 19, 10, 17, 12, 11, 15, '4', 0, 2, '{"dex": "+2", "con": "+5", "wis": "+2", "cha": "+4"}', '{"perception": "+4", "stealth": "+2"}', '[]', '[]', '[]', '["blindsight 10 ft.", "darkvision 60 ft."]', '["Draconic"]', '[]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}9 ({@damage 1d10 + 4}) piercing damage plus 3 ({@damage 1d6}) fire damage."]}, {"name": "Fire Breath {@recharge 5}", "entries": ["The dragon exhales fire in a 15-foot cone. Each creature in that area must make a {@dc 13} Dexterity saving throw, taking 24 ({@damage 7d6}) fire damage on a failed save, or half as much damage on a successful one."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('red_slaad', 'Red Slaad', 'aberration', '', 'L', 'C, N', 14, 93, '{"walk": 30}', 16, 12, 16, 6, 6, 7, '5', 0, 2, '{}', '{"perception": "+1"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Slaad", "telepathy 60 ft."]', '[{"name": "Magic Resistance", "entries": ["The slaad has advantage on saving throws against spells and other magical effects."]}, {"name": "Regeneration", "entries": ["The slaad regains 10 hit points at the start of its turn if it has at least 1 hit point."]}]', '[{"name": "Multiattack", "entries": ["The slaad makes three attacks: one with its bite and two with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}8 ({@damage 2d4 + 3}) piercing damage."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}7 ({@damage 1d8 + 3}) piercing damage. If the target is a humanoid, it must succeed on a {@dc 14} Constitution saving throw or be infected with a disease\u2014a minuscule slaad egg.", "A humanoid host can carry only one slaad egg to term at a time. Over three months, the egg moves to the chest cavity, gestates, and forms a {@creature slaad tadpole}. In the 24-hour period before giving birth, the host starts to feel unwell, its speed is halved, and it has disadvantage on attack rolls, ability checks, and saving throws. At birth, the tadpole chews its way through vital organs and out of the host''s chest in 1 round, killing the host in the process.", "If the disease is cured before the tadpole''s emergence, the unborn slaad is disintegrated."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('reef_shark', 'Reef Shark', 'beast', '', 'M', 'U', 12, 22, '{"swim": 40}', 14, 13, 13, 1, 10, 4, '1/2', 0, 2, '{}', '{"perception": "+2"}', '[]', '[]', '[]', '["blindsight 30 ft."]', '[]', '[{"name": "Pack Tactics", "entries": ["The shark has advantage on an attack roll against a creature if at least one of the shark''s allies is within 5 feet of the creature and the ally isn''t {@condition incapacitated}."]}, {"name": "Water Breathing", "entries": ["The shark can breathe only underwater."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}6 ({@damage 1d8 + 2}) piercing damage."]}]', '[]', '[]', '["underwater"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('remorhaz', 'Remorhaz', 'monstrosity', '', 'H', 'U', 17, 195, '{"walk": 30, "burrow": 20}', 24, 13, 21, 4, 10, 5, '11', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft.", "tremorsense 60 ft."]', '[]', '[{"name": "Heated Body", "entries": ["A creature that touches the remorhaz or hits it with a melee attack while within 5 feet of it takes 10 ({@damage 3d6}) fire damage."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 11} to hit, reach 10 ft., one target. {@h}40 ({@damage 6d10 + 7}) piercing damage plus 10 ({@damage 3d6}) fire damage. If the target is a creature, it is {@condition grappled} (escape {@dc 17}). Until this grapple ends, the target is {@condition restrained}, and the remorhaz can''t bite another target."]}, {"name": "Swallow", "entries": ["The remorhaz makes one bite attack against a Medium or smaller creature it is grappling. If the attack hits, that creature takes the bite''s damage and is swallowed, and the grapple ends. While swallowed, the creature is {@condition blinded} and {@condition restrained}, it has {@quickref Cover||3||total cover} against attacks and other effects outside the remorhaz, and it takes 21 ({@damage 6d6}) acid damage at the start of each of the remorhaz''s turns.", "If the remorhaz takes 30 damage or more on a single turn from a creature inside it, the remorhaz must succeed on a {@dc 15} Constitution saving throw at the end of that turn or regurgitate all swallowed creatures, which fall {@condition prone} in a space within 10 feet of the remorhaz. If the remorhaz dies, a swallowed creature is no longer {@condition restrained} by it and can escape from the corpse using 15 feet of movement, exiting {@condition prone}."]}]', '[]', '[]', '["arctic"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('revenant', 'Revenant', 'undead', '', 'M', 'N', 13, 136, '{"walk": 30}', 18, 14, 18, 13, 16, 18, '5', 0, 2, '{"str": "+7", "con": "+7", "wis": "+6", "cha": "+7"}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["the languages it knew in life"]', '[{"name": "Regeneration", "entries": ["The revenant regains 10 hit points at the start of its turn. If the revenant takes fire or radiant damage, this trait doesn''t function at the start of the revenant''s next turn. The revenant''s body is destroyed only if it starts its turn with 0 hit points and doesn''t regenerate."]}, {"name": "Rejuvenation", "entries": ["When the revenant''s body is destroyed, its soul lingers. After 24 hours, the soul inhabits and animates another humanoid corpse on the same plane of existence and regains all its hit points. While the soul is bodiless, a {@spell wish} spell can be used to force the soul to go to the afterlife and not return."]}, {"name": "Turn Immunity", "entries": ["The revenant is immune to effects that turn undead."]}, {"name": "Vengeful Tracker", "entries": ["The revenant knows the distance to and direction of any creature against which it seeks revenge, even if the creature and the revenant are on different planes of existence. If the creature being tracked by the revenant dies, the revenant knows."]}]', '[{"name": "Multiattack", "entries": ["The revenant makes two fist attacks."]}, {"name": "Fist", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}11 ({@damage 2d6 + 4}) bludgeoning damage. If the target is a creature against which the revenant has sworn vengeance, the target takes an extra 14 ({@damage 4d6}) bludgeoning damage. Instead of dealing damage, the revenant can grapple the target (escape {@dc 14}) provided the target is Large or smaller."]}, {"name": "Vengeful Glare", "entries": ["The revenant targets one creature it can see within 30 feet of it and against which it has sworn vengeance. The target must make a {@dc 15} Wisdom saving throw. On a failure, the target is {@condition paralyzed} until the revenant deals damage to it, or until the end of the revenant''s next turn. When the paralysis ends, the target is {@condition frightened} of the revenant for 1 minute. The {@condition frightened} target can repeat the saving throw at the end of each of its turns, with disadvantage if it can see the revenant, ending the {@condition frightened} condition on itself on a success."]}]', '[]', '[]', '["forest", "swamp", "hill", "urban", "desert", "arctic"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('rhinoceros', 'Rhinoceros', 'beast', '', 'L', 'U', 11, 45, '{"walk": 40}', 21, 8, 15, 2, 12, 6, '2', 0, 2, '{}', '{}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Charge", "entries": ["If the rhinoceros moves at least 20 feet straight toward a target and then hits it with a gore attack on the same turn, the target takes an extra 9 ({@damage 2d8}) bludgeoning damage. If the target is a creature, it must succeed on a {@dc 15} Strength saving throw or be knocked {@condition prone}."]}]', '[{"name": "Gore", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}14 ({@damage 2d8 + 5}) bludgeoning damage."]}]', '[]', '[]', '["grassland"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('riding_horse', 'Riding Horse', 'beast', '', 'L', 'U', 10, 13, '{"walk": 60}', 16, 10, 12, 2, 11, 7, '1/4', 0, 2, '{}', '{}', '[]', '[]', '[]', '[]', '[]', '[]', '[{"name": "Hooves", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}8 ({@damage 2d4 + 3}) bludgeoning damage."]}]', '[]', '[]', '["grassland", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('roc', 'Roc', 'monstrosity', '', 'G', 'U', 15, 248, '{"walk": 20, "fly": 120}', 28, 10, 20, 3, 10, 9, '11', 0, 2, '{"dex": "+4", "con": "+9", "wis": "+4", "cha": "+3"}', '{"perception": "+4"}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Keen Sight", "entries": ["The roc has advantage on Wisdom ({@skill Perception}) checks that rely on sight."]}]', '[{"name": "Multiattack", "entries": ["The roc makes two attacks: one with its beak and one with its talons."]}, {"name": "Beak", "entries": ["{@atk mw} {@hit 13} to hit, reach 10 ft., one target. {@h}27 ({@damage 4d8 + 9}) piercing damage."]}, {"name": "Talons", "entries": ["{@atk mw} {@hit 13} to hit, reach 5 ft., one target. {@h}23 ({@damage 4d6 + 9}) slashing damage, and the target is {@condition grappled} (escape {@dc 19}). Until this grapple ends, the target is {@condition restrained}, and the roc can''t use its talons on another target."]}]', '[]', '[]', '["mountain", "hill", "desert", "coastal", "arctic"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('roper', 'Roper', 'monstrosity', '', 'L', 'N, E', 20, 93, '{"walk": 10, "climb": 10}', 18, 8, 17, 7, 16, 6, '5', 0, 2, '{}', '{"perception": "+6", "stealth": "+5"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '[]', '[{"name": "False Appearance", "entries": ["While the roper remains motionless, it is indistinguishable from a normal cave formation, such as a stalagmite."]}, {"name": "Grasping Tendrils", "entries": ["The roper can have up to six tendrils at a time. Each tendril can be attacked (AC 20; 10 hit points; immunity to poison and psychic damage). Destroying a tendril deals no damage to the roper, which can extrude a replacement tendril on its next turn. A tendril can also be broken if a creature takes an action and succeeds on a {@dc 15} Strength check against it."]}, {"name": "Spider Climb", "entries": ["The roper can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."]}]', '[{"name": "Multiattack", "entries": ["The roper makes four attacks with its tendrils, uses Reel, and makes one attack with its bite."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}22 ({@damage 4d8 + 4}) piercing damage."]}, {"name": "Tendril", "entries": ["{@atk mw} {@hit 7} to hit, reach 50 ft., one creature. {@h}The target is {@condition grappled} (escape {@dc 15}). Until the grapple ends, the target is {@condition restrained} and has disadvantage on Strength checks and Strength saving throws, and the roper can''t use the same tendril on another target."]}, {"name": "Reel", "entries": ["The roper pulls each creature {@condition grappled} by it up to 25 feet straight toward it."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('rug_of_smothering', 'Rug of Smothering', 'construct', '', 'L', 'U', 12, 33, '{"walk": 10}', 17, 14, 10, 1, 3, 1, '2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 60 ft. (blind beyond this radius)"]', '[]', '[{"name": "Antimagic Susceptibility", "entries": ["The rug is {@condition incapacitated} while in the area of an {@spell antimagic field}. If targeted by {@spell dispel magic}, the rug must succeed on a Constitution saving throw against the caster''s spell save DC or fall {@condition unconscious} for 1 minute."]}, {"name": "Damage Transfer", "entries": ["While it is grappling a creature, the rug takes only half the damage dealt to it, and the creature {@condition grappled} by the rug takes the other half."]}, {"name": "False Appearance", "entries": ["While the rug remains motionless, it is indistinguishable from a normal rug."]}]', '[{"name": "Smother", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one Medium or smaller creature. {@h}The creature is {@condition grappled} (escape {@dc 13}). Until this grapple ends, the target is {@condition restrained}, {@condition blinded}, and at risk of suffocating, and the rug can''t smother another target. In addition, at the start of each of the target''s turns, the target takes 10 ({@damage 2d6 + 3}) bludgeoning damage."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('rust_monster', 'Rust Monster', 'monstrosity', '', 'M', 'U', 14, 27, '{"walk": 40}', 13, 12, 13, 2, 13, 6, '1/2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '[]', '[{"name": "Iron Scent", "entries": ["The rust monster can pinpoint, by scent, the location of ferrous metal within 30 feet of it."]}, {"name": "Rust Metal", "entries": ["Any nonmagical weapon made of metal that hits the rust monster corrodes. After dealing damage, the weapon takes a permanent and cumulative \u22121 penalty to damage rolls. If its penalty drops to \u22125, the weapon is destroyed. Non magical ammunition made of metal that hits the rust monster is destroyed after dealing damage."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d8 + 1}) piercing damage."]}, {"name": "Antennae", "entries": ["The rust monster corrodes a nonmagical ferrous metal object it can see within 5 feet of it. If the object isn''t being worn or carried, the touch destroys a 1-foot cube of it. If the object is being worn or carried by a creature, the creature can make a {@dc 11} Dexterity saving throw to avoid the rust monster''s touch.", "If the object touched is either metal armor or a metal shield being worn or carried, it takes a permanent and cumulative \u22121 penalty to the AC it offers. Armor reduced to an AC of 10 or a shield that drops to a +0 bonus is destroyed. If the object touched is a held metal weapon, it rusts as described in the Rust Metal trait."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('saber-toothed_tiger', 'Saber-Toothed Tiger', 'beast', '', 'L', 'U', 12, 52, '{"walk": 40}', 18, 14, 15, 3, 12, 8, '2', 0, 2, '{}', '{"perception": "+3", "stealth": "+6"}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Keen Smell", "entries": ["The tiger has advantage on Wisdom ({@skill Perception}) checks that rely on smell."]}, {"name": "Pounce", "entries": ["If the tiger moves at least 20 feet straight toward a creature and then hits it with a claw attack on the same turn, that target must succeed on a {@dc 14} Strength saving throw or be knocked {@condition prone}. If the target is {@condition prone}, the tiger can make one bite attack against it as a bonus action."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}10 ({@damage 1d10 + 5}) piercing damage."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}12 ({@damage 2d6 + 5}) slashing damage."]}]', '[]', '[]', '["mountain", "arctic"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('sahuagin', 'Sahuagin', 'humanoid', 'sahuagin', 'M', 'L, E', 12, 22, '{"walk": 30, "swim": 40}', 13, 11, 12, 12, 13, 9, '1/2', 0, 2, '{}', '{"perception": "+5"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Sahuagin"]', '[{"name": "Blood Frenzy", "entries": ["The sahuagin has advantage on melee attack rolls against any creature that doesn''t have all its hit points."]}, {"name": "Limited Amphibiousness", "entries": ["The sahuagin can breathe air and water, but it needs to be submerged at least once every 4 hours to avoid suffocating."]}, {"name": "Shark Telepathy", "entries": ["The sahuagin can magically command any shark within 120 feet of it, using a limited telepathy."]}]', '[{"name": "Multiattack", "entries": ["The sahuagin makes two melee attacks: one with its bite and one with its claws or spear."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}3 ({@damage 1d4 + 1}) piercing damage."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}3 ({@damage 1d4 + 1}) slashing damage."]}, {"name": "Spear", "entries": ["{@atk mw,rw} {@hit 3} to hit, reach 5 ft. or range 20/60 ft., one target. {@h}4 ({@damage 1d6 + 1}) piercing damage, or 5 ({@damage 1d8 + 1}) piercing damage if used with two hands to make a melee attack."]}]', '[]', '[]', '["underwater", "coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('sahuagin_baron', 'Sahuagin Baron', 'humanoid', 'sahuagin', 'L', 'L, E', 16, 76, '{"walk": 30, "swim": 50}', 19, 15, 16, 14, 13, 17, '5', 0, 2, '{"dex": "+5", "con": "+6", "int": "+5", "wis": "+4"}', '{"perception": "+7"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Sahuagin"]', '[{"name": "Blood Frenzy", "entries": ["The sahuagin has advantage on melee attack rolls against any creature that doesn''t have all its hit points."]}, {"name": "Limited Amphibiousness", "entries": ["The sahuagin can breathe air and water, but it needs to be submerged at least once every 4 hours to avoid suffocating."]}, {"name": "Shark Telepathy", "entries": ["The sahuagin can magically command any shark within 120 feet of it, using a limited telepathy."]}]', '[{"name": "Multiattack", "entries": ["The sahuagin makes three attacks: one with his bite and two with his claws or trident."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}9 ({@damage 2d4 + 4}) piercing damage."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}11 ({@damage 2d6 + 4}) slashing damage."]}, {"name": "Trident", "entries": ["{@atk mw,rw} {@hit 7} to hit, reach 5 ft. or range 20/60 ft., one target. {@h}11 ({@damage 2d6 + 4}) piercing damage, or 13 ({@damage 2d8 + 4}) piercing damage if used with two hands to make a melee attack."]}]', '[]', '[]', '["underwater", "coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('sahuagin_priestess', 'Sahuagin Priestess', 'humanoid', 'sahuagin', 'M', 'L, E', 12, 33, '{"walk": 30, "swim": 40}', 13, 11, 12, 12, 14, 13, '2', 0, 2, '{}', '{"perception": "+6", "religion": "+3"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Sahuagin"]', '[{"name": "Blood Frenzy", "entries": ["The sahuagin has advantage on melee attack rolls against any creature that doesn''t have all its hit points."]}, {"name": "Limited Amphibiousness", "entries": ["The sahuagin can breathe air and water, but it needs to be submerged at least once every 4 hours to avoid suffocating."]}, {"name": "Shark Telepathy", "entries": ["The sahuagin can magically command any shark within 120 feet of it, using a limited telepathy."]}]', '[{"name": "Multiattack", "entries": ["The sahuagin makes two melee attacks: one with her bite and one with her claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}3 ({@damage 1d4 + 1}) piercing damage."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}3 ({@damage 1d4 + 1}) slashing damage."]}]', '[]', '[]', '["underwater", "coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('salamander', 'Salamander', 'elemental', '', 'L', 'N, E', 15, 90, '{"walk": 30}', 18, 14, 15, 11, 10, 12, '5', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Ignan"]', '[{"name": "Heated Body", "entries": ["A creature that touches the salamander or hits it with a melee attack while within 5 feet of it takes 7 ({@damage 2d6}) fire damage."]}, {"name": "Heated Weapons", "entries": ["Any metal melee weapon the salamander wields deals an extra 3 ({@damage 1d6}) fire damage on a hit (included in the attack)."]}]', '[{"name": "Multiattack", "entries": ["The salamander makes two attacks: one with its spear and one with its tail."]}, {"name": "Spear", "entries": ["{@atk mw,rw} {@hit 7} to hit, reach 5 ft. or range 20/60 ft., one target. {@h}11 ({@damage 2d6 + 4}) piercing damage, or 13 ({@damage 2d8 + 4}) piercing damage if used with two hands to make a melee attack, plus 3 ({@damage 1d6}) fire damage."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 7} to hit, reach 10 ft., one target. {@h}11 ({@damage 2d6 + 4}) bludgeoning damage plus 7 ({@damage 2d6}) fire damage, and the target is {@condition grappled} (escape {@dc 14}). Until this grapple ends, the target is {@condition restrained}, the salamander can automatically hit the target with its tail, and the salamander can''t make tail attacks against other targets."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('satyr', 'Satyr', 'fey', '', 'M', 'C, N', 14, 31, '{"walk": 40}', 12, 16, 11, 12, 10, 14, '1/2', 0, 2, '{}', '{"perception": "+2", "performance": "+6", "stealth": "+5"}', '[]', '[]', '[]', '[]', '["Common", "Elvish", "Sylvan"]', '[{"name": "Magic Resistance", "entries": ["The satyr has advantage on saving throws against spells and other magical effects."]}]', '[{"name": "Ram", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}6 ({@damage 2d4 + 1}) bludgeoning damage."]}, {"name": "Shortsword", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}6 ({@damage 1d6 + 3}) piercing damage."]}, {"name": "Shortbow", "entries": ["{@atk rw} {@hit 5} to hit, range 80/320 ft., one target. {@h}6 ({@damage 1d6 + 3}) piercing damage."]}]', '[]', '[]', '["forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('scarecrow', 'Scarecrow', 'construct', '', 'M', 'C, E', 11, 36, '{"walk": 30}', 11, 13, 11, 10, 10, 13, '1', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["understands the languages of its creator but can''t speak"]', '[{"name": "False Appearance", "entries": ["While the scarecrow remains motionless, it is indistinguishable from an ordinary, inanimate scarecrow."]}]', '[{"name": "Multiattack", "entries": ["The scarecrow makes two claw attacks."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}6 ({@damage 2d4 + 1}) slashing damage. If the target is a creature, it must succeed on a {@dc 11} Wisdom saving throw or be {@condition frightened} until the end of the scarecrow''s next turn."]}, {"name": "Terrifying Glare", "entries": ["The scarecrow targets one creature it can see within 30 feet of it. If the target can see the scarecrow, the target must succeed on a {@dc 11} Wisdom saving throw or be magically {@condition frightened} until the end of the scarecrow''s next turn. The {@condition frightened} target is {@condition paralyzed}."]}]', '[]', '[]', '["grassland"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('scorpion', 'Scorpion', 'beast', '', 'T', 'U', 11, 1, '{"walk": 10}', 2, 11, 8, 1, 8, 2, '0', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 10 ft."]', '[]', '[]', '[{"name": "Sting", "entries": ["{@atk mw} {@hit 2} to hit, reach 5 ft., one creature. {@h}1 piercing damage, and the target must make a {@dc 9} Constitution saving throw, taking 4 ({@damage 1d8}) poison damage on a failed save, or half as much damage on a successful one."]}]', '[]', '[]', '["desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('scout', 'Scout', 'humanoid', 'any race', 'M', 'A', 13, 16, '{"walk": 30}', 11, 14, 12, 11, 13, 11, '1/2', 0, 2, '{}', '{"nature": "+4", "perception": "+5", "stealth": "+6", "survival": "+5"}', '[]', '[]', '[]', '[]', '["any one language (usually Common)"]', '[{"name": "Keen Hearing and Sight", "entries": ["The scout has advantage on Wisdom ({@skill Perception}) checks that rely on hearing or sight."]}]', '[{"name": "Multiattack", "entries": ["The scout makes two melee attacks or two ranged attacks."]}, {"name": "Shortsword", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage."]}, {"name": "Longbow", "entries": ["{@atk rw} {@hit 4} to hit, ranged 150/600 ft., one target. {@h}6 ({@damage 1d8 + 2}) piercing damage."]}]', '[]', '[]', '["coastal", "mountain", "grassland", "hill", "arctic", "forest", "swamp", "underdark", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('sea_hag', 'Sea Hag', 'fey', '', 'M', 'C, E', 14, 52, '{"walk": 30, "swim": 40}', 16, 13, 16, 12, 12, 13, '{''cr'': ''2'', ''coven'': ''4''}', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Aquan", "Common", "Giant"]', '[{"name": "Amphibious", "entries": ["The hag can breathe air and water."]}, {"name": "Horrific Appearance", "entries": ["Any humanoid that starts its turn within 30 feet of the hag and can see the hag''s true form must make a {@dc 11} Wisdom saving throw. On a failed save, the creature is {@condition frightened} for 1 minute. A creature can repeat the saving throw at the end of each of its turns, with disadvantage if the hag is within line of sight, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the hag''s Horrific Appearance for the next 24 hours.", "Unless the target is {@status surprised} or the revelation of the hag''s true form is sudden, the target can avert its eyes and avoid making the initial saving throw. Until the start of its next turn, a creature that averts its eyes has disadvantage on attack rolls against the hag."]}]', '[{"name": "Claws", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}10 ({@damage 2d6 + 3}) slashing damage."]}, {"name": "Death Glare", "entries": ["The hag targets one {@condition frightened} creature she can see within 30 feet of her. If the target can see the hag, it must succeed on a {@dc 11} Wisdom saving throw against this magic or drop to 0 hit points."]}, {"name": "Illusory Appearance", "entries": ["The hag covers herself and anything she is wearing or carrying with a magical illusion that makes her look like an ugly creature of her general size and humanoid shape. The effect ends if the hag takes a bonus action to end it or if she dies.", "The changes wrought by this effect fail to hold up to physical inspection. For example, the hag could appear to have no claws, but someone touching her hand might feel the claws. Otherwise, a creature must take an action to visually inspect the illusion and succeed on a {@dc 16} Intelligence ({@skill Investigation}) check to discern that the hag is disguised."]}]', '[]', '[]', '["underwater", "coastal"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('sea_horse', 'Sea Horse', 'beast', '', 'T', 'U', 11, 1, '{"swim": 20}', 1, 12, 8, 1, 10, 2, '{''cr'': ''0'', ''xp'': 0}', 0, 2, '{}', '{}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Water Breathing", "entries": ["The sea horse can breathe only underwater."]}]', '[]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('shadow', 'Shadow', 'undead', '', 'M', 'C, E', 12, 16, '{"walk": 40}', 6, 14, 13, 6, 10, 8, '1/2', 0, 2, '{}', '{"stealth": "+4"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '[]', '[{"name": "Amorphous", "entries": ["The shadow can move through a space as narrow as 1 inch wide without squeezing."]}, {"name": "Shadow Stealth", "entries": ["While in dim light or darkness, the shadow can take the Hide action as a bonus action. Its stealth bonus is also improved to +6."]}, {"name": "Sunlight Weakness", "entries": ["While in sunlight, the shadow has disadvantage on attack rolls, ability checks, and saving throws."]}]', '[{"name": "Strength Drain", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one creature. {@h}9 ({@damage 2d6 + 2}) necrotic damage, and the target''s Strength score is reduced by {@dice 1d4}. The target dies if this reduces its Strength to 0. Otherwise, the reduction lasts until the target finishes a short or long rest.", "If a non-evil humanoid dies from this attack, a new shadow rises from the corpse {@dice 1d4} hours later."]}]', '[]', '[]', '["underdark", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('shadow_demon', 'Shadow Demon', 'fiend', 'demon', 'M', 'C, E', 13, 66, '{"walk": 30, "fly": 30}', 1, 17, 12, 14, 13, 14, '4', 0, 2, '{"dex": "+5", "cha": "+4"}', '{"stealth": "+7"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Abyssal", "telepathy 120 ft."]', '[{"name": "Incorporeal Movement", "entries": ["The demon can move through other creatures and objects as if they were {@quickref difficult terrain||3}. It takes 5 ({@damage 1d10}) force damage if it ends its turn inside an object."]}, {"name": "Light Sensitivity", "entries": ["While in bright light, the demon has disadvantage on attack rolls, as well as on Wisdom ({@skill Perception}) checks that rely on sight."]}, {"name": "Shadow Stealth", "entries": ["While in dim light or darkness, the demon can take the Hide action as a bonus action."]}]', '[{"name": "Claws", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one creature. {@h}10 ({@damage 2d6 + 3}) psychic damage or, if the demon had advantage on the attack roll, 17 ({@damage 4d6 + 3}) psychic damage."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('shambling_mound', 'Shambling Mound', 'plant', '', 'L', 'U', 15, 136, '{"walk": 20, "swim": 20}', 18, 8, 16, 5, 10, 5, '5', 0, 2, '{}', '{"stealth": "+2"}', '[]', '[]', '[]', '["blindsight 60 ft. (blind beyond this radius)"]', '[]', '[{"name": "Lightning Absorption", "entries": ["Whenever the shambling mound is subjected to lightning damage, it takes no damage and regains a number of hit points equal to the lightning damage dealt."]}]', '[{"name": "Multiattack", "entries": ["The shambling mound makes two slam attacks. If both attacks hit a Medium or smaller target, the target is {@condition grappled} (escape {@dc 14}), and the shambling mound uses its Engulf on it."]}, {"name": "Slam", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}13 ({@damage 2d8 + 4}) bludgeoning damage."]}, {"name": "Engulf", "entries": ["The shambling mound engulfs a Medium or smaller creature {@condition grappled} by it. The engulfed target is {@condition blinded}, {@condition restrained}, and unable to breathe, and it must succeed on a {@dc 14} Constitution saving throw at the start of each of the mound''s turns or take 13 ({@damage 2d8 + 4}) bludgeoning damage. If the mound moves, the engulfed target moves with it. The mound can have only one creature engulfed at a time."]}]', '[]', '[]', '["forest", "swamp"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('shield_guardian', 'Shield Guardian', 'construct', '', 'L', 'U', 17, 142, '{"walk": 30}', 18, 8, 18, 7, 10, 3, '7', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 10 ft.", "darkvision 60 ft."]', '["understands commands given in any language but can''t speak"]', '[{"name": "Bound", "entries": ["The shield guardian is magically bound to an amulet. As long as the guardian and its amulet are on the same plane of existence, the amulet''s wearer can telepathically call the guardian to travel to it, and the guardian knows the distance and direction to the amulet. If the guardian is within 60 feet of the amulet''s wearer, half of any damage the wearer takes (rounded up) is transferred to the guardian."]}, {"name": "Regeneration", "entries": ["The shield guardian regains 10 hit points at the start of its turn if it has at least 1 hit point."]}, {"name": "Spell Storing", "entries": ["A spellcaster who wears the shield guardian''s amulet can cause the guardian to store one spell of 4th level or lower. To do so, the wearer must cast the spell on the guardian. The spell has no effect but is stored within the guardian. When commanded to do so by the wearer or when a situation arises that was predefined by the spellcaster, the guardian casts the stored spell with any parameters set by the original caster, requiring no components. When the spell is cast or a new spell is stored, any previously stored spell is lost."]}]', '[{"name": "Multiattack", "entries": ["The guardian makes two fist attacks."]}, {"name": "Fist", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}11 ({@damage 2d6 + 4}) bludgeoning damage."]}]', '[]', '[]', '["urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('shrieker', 'Shrieker', 'plant', '', 'M', 'U', 5, 13, '{"walk": 0}', 1, 1, 10, 1, 3, 1, '0', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 30 ft. (blind beyond this radius)"]', '[]', '[{"name": "False Appearance", "entries": ["While the shrieker remains motionless, it is indistinguishable from an ordinary fungus."]}]', '[]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('silver_dragon_wyrmling', 'Silver Dragon Wyrmling', 'dragon', '', 'M', 'L, G', 17, 45, '{"walk": 30, "fly": 60}', 19, 10, 17, 12, 11, 15, '2', 0, 2, '{"dex": "+2", "con": "+5", "wis": "+2", "cha": "+4"}', '{"perception": "+4", "stealth": "+2"}', '[]', '[]', '[]', '["blindsight 10 ft.", "darkvision 60 ft."]', '["Draconic"]', '[]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one target. {@h}9 ({@damage 1d10 + 4}) piercing damage."]}, {"name": "Breath Weapons {@recharge 5}", "entries": ["The dragon uses one of the following breath weapons.", {"type": "list", "style": "list-hang-notitle", "items": [{"type": "item", "name": "Cold Breath", "entry": "The dragon exhales an icy blast in a 15-foot cone. Each creature in that area must make a {@dc 13} Constitution saving throw, taking 18 ({@damage 4d8}) cold damage on a failed save, or half as much damage on a successful one."}, {"type": "item", "name": "Paralyzing Breath", "entry": "The dragon exhales paralyzing gas in a 15-foot cone. Each creature in that area must succeed on a {@dc 13} Constitution saving throw or be {@condition paralyzed} for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."}]}]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('skeleton', 'Skeleton', 'undead', '', 'M', 'L, E', 13, 13, '{"walk": 30}', 10, 14, 15, 6, 8, 5, '1/4', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["understands all languages it spoke in life but can''t speak"]', '[]', '[{"name": "Shortsword", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage."]}, {"name": "Shortbow", "entries": ["{@atk rw} {@hit 4} to hit, range 80/320 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage."]}]', '[]', '[]', '["urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('slaad_tadpole', 'Slaad Tadpole', 'aberration', '', 'T', 'C, N', 12, 10, '{"walk": 30}', 7, 15, 10, 3, 5, 3, '1/8', 0, 2, '{}', '{"stealth": "+4"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["understands Slaad but can''t speak"]', '[{"name": "Magic Resistance", "entries": ["The slaad has advantage on saving throws against spells and other magical effects."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}4 ({@damage 1d4 + 2}) piercing damage."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('smoke_mephit', 'Smoke Mephit', 'elemental', '', 'S', 'N, E', 12, 22, '{"walk": 30, "fly": 30}', 6, 14, 12, 10, 10, 11, '1/4', 0, 2, '{}', '{"perception": "+2", "stealth": "+4"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Auran", "Ignan"]', '[{"name": "Death Burst", "entries": ["When the mephit dies, it leaves behind a cloud of smoke that fills a 5-foot-radius sphere centered on its space. The sphere is heavily obscured. Wind disperses the cloud, which otherwise lasts for 1 minute."]}]', '[{"name": "Claws", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one creature. {@h}4 ({@damage 1d4 + 2}) slashing damage."]}, {"name": "Cinder Breath {@recharge}", "entries": ["The mephit exhales a 15-foot cone of smoldering ash. Each creature in that area must succeed on a {@dc 10} Dexterity saving throw or be {@condition blinded} until the end of the mephit''s next turn."]}]', '[]', '[]', '["urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('solar', 'Solar', 'celestial', '', 'L', 'L, G', 21, 243, '{"walk": 50, "fly": 150}', 26, 22, 26, 25, 25, 30, '21', 0, 2, '{"int": "+14", "wis": "+14", "cha": "+17"}', '{"perception": "+14"}', '[]', '[]', '[]', '["truesight 120 ft."]', '["all", "telepathy 120 ft."]', '[{"name": "Angelic Weapons", "entries": ["The solar''s weapon attacks are magical. When the solar hits with any weapon, the weapon deals an extra {@damage 6d8} radiant damage (included in the attack)."]}, {"name": "Divine Awareness", "entries": ["The solar knows if it hears a lie."]}, {"name": "Magic Resistance", "entries": ["The solar has advantage on saving throws against spells and other magical effects."]}]', '[{"name": "Multiattack", "entries": ["The solar makes two greatsword attacks."]}, {"name": "Greatsword", "entries": ["{@atk mw} {@hit 15} to hit, reach 5 ft., one target. {@h}22 ({@damage 4d6 + 8}) slashing damage plus 27 ({@damage 6d8}) radiant damage."]}, {"name": "Slaying Longbow", "entries": ["{@atk rw} {@hit 13} to hit, range 150/600 ft., one target. {@h}15 ({@damage 2d8 + 6}) piercing damage plus 27 ({@damage 6d8}) radiant damage. If the target is a creature that has 100 hit points or fewer, it must succeed on a {@dc 15} Constitution saving throw or die."]}, {"name": "Flying Sword", "entries": ["The solar releases its greatsword to hover magically in an unoccupied space within 5 feet of it. If the solar can see the sword, the solar can mentally command it as a bonus action to fly up to 50 feet and either make one attack against a target or return to the solar''s hands. If the hovering sword is targeted by any effect, the solar is considered to be holding it. The hovering sword falls if the solar dies."]}, {"name": "Healing Touch (4/Day)", "entries": ["The solar touches another creature. The target magically regains 40 ({@dice 8d8 + 4}) hit points and is freed from any curse, disease, poison, blindness, or deafness."]}]', '[{"name": "Teleport", "entries": ["The solar magically teleports, along with any equipment it is wearing or carrying, up to 120 feet to an unoccupied space it can see."]}, {"name": "Searing Burst (Costs 2 Actions)", "entries": ["The solar emits magical, divine energy. Each creature of its choice in a 10-foot radius must make a {@dc 23} Dexterity saving throw, taking 14 ({@damage 4d6}) fire damage plus 14 ({@damage 4d6}) radiant damage on a failed save, or half as much damage on a successful one."]}, {"name": "Blinding Gaze (Costs 3 Actions)", "entries": ["The solar targets one creature it can see within 30 feet of it. If the target can see it, the target must succeed on a {@dc 15} Constitution saving throw or be {@condition blinded} until magic such as the {@spell lesser restoration} spell removes the blindness."]}]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('spectator', 'Spectator', 'aberration', '', 'M', 'L, N', 14, 39, '{"walk": 0, "fly": {"number": 30, "condition": "(hover)"}, "canHover": true}', 8, 14, 14, 13, 14, 11, '3', 0, 2, '{}', '{"perception": "+6"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Deep Speech", "Undercommon", "telepathy 120 ft."]', '[]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 1} to hit, reach 5 ft., one target. {@h}2 ({@damage 1d6 - 1}) piercing damage."]}, {"name": "Eye Rays", "entries": ["The spectator shoots up to two of the following magical eye rays at one or two creatures it can see within 90 feet of it. It can use each ray only once on a turn.", {"type": "list", "style": "list-hang-notitle", "items": [{"type": "item", "name": "1. Confusion Ray", "style": "italic", "entry": "The target must succeed on a {@dc 13} Wisdom saving throw, or it can''t take reactions until the end of its next turn. On its turn, the target can''t move, and it uses its action to make a melee or ranged attack against a randomly determined creature within range. If the target can''t attack, it does nothing on its turn."}, {"type": "item", "name": "2. Paralyzing Ray", "style": "italic", "entry": "The target must succeed on a {@dc 13} Constitution saving throw or be {@condition paralyzed} for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."}, {"type": "item", "name": "3. Fear Ray", "style": "italic", "entry": "The target must succeed on a {@dc 13} Wisdom saving throw or be {@condition frightened} for 1 minute. The target can repeat the saving throw at the end of each of its turns, with disadvantage if the spectator is visible to the target, ending the effect on itself on a success."}, {"type": "item", "name": "4. Wounding Ray", "style": "italic", "entry": "The target must make a {@dc 13} Constitution saving throw, taking 16 ({@damage 3d10}) necrotic damage on a failed save, or half as much damage on a successful one."}]}]}, {"name": "Create Food and Water", "entries": ["The spectator magically creates enough food and water to sustain itself for 24 hours."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('specter', 'Specter', 'undead', '', 'M', 'C, E', 12, 22, '{"walk": 0, "fly": {"number": 50, "condition": "(hover)"}, "canHover": true}', 1, 14, 11, 10, 10, 11, '1', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["understands all languages it knew in life but can''t speak"]', '[{"name": "Incorporeal Movement", "entries": ["The specter can move through other creatures and objects as if they were {@quickref difficult terrain||3}. It takes 5 ({@damage 1d10}) force damage if it ends its turn inside an object."]}, {"name": "Sunlight Sensitivity", "entries": ["While in sunlight, the specter has disadvantage on attack rolls, as well as on Wisdom ({@skill Perception}) checks that rely on sight."]}]', '[{"name": "Life Drain", "entries": ["{@atk ms} {@hit 4} to hit, reach 5 ft., one creature. {@h}10 ({@damage 3d6}) necrotic damage. The target must succeed on a {@dc 10} Constitution saving throw or its hit point maximum is reduced by an amount equal to the damage taken. This reduction lasts until the creature finishes a long rest. The target dies if this effect reduces its hit point maximum to 0."]}]', '[]', '[]', '["underdark", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('spider', 'Spider', 'beast', '', 'T', 'U', 12, 1, '{"walk": 20, "climb": 20}', 2, 14, 8, 1, 10, 2, '0', 0, 2, '{}', '{"stealth": "+4"}', '[]', '[]', '[]', '["darkvision 30 ft."]', '[]', '[{"name": "Spider Climb", "entries": ["The spider can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."]}, {"name": "Web Sense", "entries": ["While in contact with a web, the spider knows the exact location of any other creature in contact with the same web."]}, {"name": "Web Walker", "entries": ["The spider ignores movement restrictions caused by webbing."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one creature. {@h}1 piercing damage, and the target must succeed on a {@dc 9} Constitution saving throw or take 2 ({@damage 1d4}) poison damage."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('spined_devil', 'Spined Devil', 'fiend', 'devil', 'S', 'L, E', 13, 22, '{"walk": 20, "fly": 40}', 10, 15, 12, 11, 14, 8, '2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["Infernal", "telepathy 120 ft."]', '[{"name": "Devil''s Sight", "entries": ["Magical darkness doesn''t impede the devil''s darkvision."]}, {"name": "Flyby", "entries": ["The devil doesn''t provoke an opportunity attack when it flies out of an enemy''s reach."]}, {"name": "Limited Spines", "entries": ["The devil has twelve tail spines. Used spines regrow by the time the devil finishes a long rest."]}, {"name": "Magic Resistance", "entries": ["The devil has advantage on saving throws against spells and other magical effects."]}]', '[{"name": "Multiattack", "entries": ["The devil makes two attacks: one with its bite and one with its fork or two with its tail spines."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 2} to hit, reach 5 ft., one target. {@h}5 ({@damage 2d4}) slashing damage."]}, {"name": "Fork", "entries": ["{@atk mw} {@hit 2} to hit, reach 5 ft., one target. {@h}3 ({@damage 1d6}) piercing damage."]}, {"name": "Tail Spine", "entries": ["{@atk rw} {@hit 4} to hit, range 20/80 ft., one target. {@h}4 ({@damage 1d4 + 2}) piercing damage plus 3 ({@damage 1d6}) fire damage."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('spirit_naga', 'Spirit Naga', 'monstrosity', '', 'L', 'C, E', 15, 75, '{"walk": 40}', 18, 17, 14, 16, 15, 16, '8', 0, 2, '{"dex": "+6", "con": "+5", "wis": "+5", "cha": "+6"}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Abyssal", "Common"]', '[{"name": "Rejuvenation", "entries": ["If it dies, the naga returns to life in {@dice 1d6} days and regains all its hit points. Only a {@spell wish} spell can prevent this trait from functioning."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 7} to hit, reach 10 ft., one creature. {@h}7 ({@damage 1d6 + 4}) piercing damage, and the target must make a {@dc 13} Constitution saving throw, taking 31 ({@damage 7d8}) poison damage on a failed save, or half as much damage on a successful one."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('sprite', 'Sprite', 'fey', '', 'T', 'N, G', 15, 2, '{"walk": 10, "fly": 40}', 3, 18, 10, 14, 13, 11, '1/4', 0, 2, '{}', '{"perception": "+3", "stealth": "+8"}', '[]', '[]', '[]', '[]', '["Common", "Elvish", "Sylvan"]', '[]', '[{"name": "Longsword", "entries": ["{@atk mw} {@hit 2} to hit, reach 5 ft., one target. {@h}1 slashing damage."]}, {"name": "Shortbow", "entries": ["{@atk rw} {@hit 6} to hit, range 40/160 ft., one target. {@h}1 piercing damage, and the target must succeed on a {@dc 10} Constitution saving throw or become {@condition poisoned} for 1 minute. If its saving throw result is 5 or lower, the {@condition poisoned} target falls {@condition unconscious} for the same duration, or until it takes damage or another creature takes an action to shake it awake."]}, {"name": "Heart Sight", "entries": ["The sprite touches a creature and magically knows the creature''s current emotional state. If the target fails a {@dc 10} Charisma saving throw, the sprite also knows the creature''s alignment. Celestials, fiends, and undead automatically fail the saving throw."]}, {"name": "Invisibility", "entries": ["The sprite magically turns {@condition invisible} until it attacks or casts a spell, or until its {@status concentration} ends (as if {@status concentration||concentrating} on a spell). Any equipment the sprite wears or carries is {@condition invisible} with it."]}]', '[]', '[]', '["forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('spy', 'Spy', 'humanoid', 'any race', 'M', 'A', 12, 27, '{"walk": 30}', 10, 15, 10, 12, 14, 16, '1', 0, 2, '{}', '{"deception": "+5", "insight": "+4", "investigation": "+5", "perception": "+6", "persuasion": "+5", "sleight of hand": "+4", "stealth": "+4"}', '[]', '[]', '[]', '[]', '["any two languages"]', '[{"name": "Cunning Action", "entries": ["On each of its turns, the spy can use a bonus action to take the Dash, Disengage, or Hide action."]}, {"name": "Sneak Attack (1/Turn)", "entries": ["The spy deals an extra 7 ({@damage 2d6}) damage when it hits a target with a weapon attack and has advantage on the attack roll, or when the target is within 5 feet of an ally of the spy that isn''t {@condition incapacitated} and the spy doesn''t have disadvantage on the attack roll."]}]', '[{"name": "Multiattack", "entries": ["The spy makes two melee attacks."]}, {"name": "Shortsword", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage."]}, {"name": "Hand Crossbow", "entries": ["{@atk rw} {@hit 4} to hit, range 30/120 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage."]}]', '[]', '[]', '["urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('steam_mephit', 'Steam Mephit', 'elemental', '', 'S', 'N, E', 10, 21, '{"walk": 30, "fly": 30}', 5, 11, 10, 11, 10, 12, '1/4', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Aquan", "Ignan"]', '[{"name": "Death Burst", "entries": ["When the mephit dies, it explodes in a cloud of steam. Each creature within 5 feet of the mephit must succeed on a {@dc 10} Dexterity saving throw or take 4 ({@damage 1d8}) fire damage."]}]', '[{"name": "Claws", "entries": ["{@atk mw} {@hit 2} to hit, reach 5 ft., one creature. {@h}2 ({@damage 1d4}) slashing damage plus 2 ({@damage 1d4}) fire damage."]}, {"name": "Steam Breath {@recharge}", "entries": ["The mephit exhales a 15-foot cone of scalding steam. Each creature in that area must succeed on a {@dc 10} Dexterity saving throw, taking 4 ({@damage 1d8}) fire damage on a failed save, or half as much damage on a successful one."]}]', '[]', '[]', '["underwater"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('stirge', 'Stirge', 'beast', '', 'T', 'U', 14, 2, '{"walk": 10, "fly": 40}', 4, 16, 11, 2, 8, 6, '1/8', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '[]', '[]', '[{"name": "Blood Drain", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one creature. {@h}5 ({@damage 1d4 + 3}) piercing damage, and the stirge attaches to the target. While attached, the stirge doesn''t attack. Instead, at the start of each of the stirge''s turns, the target loses 5 ({@dice 1d4 + 3}) hit points due to blood loss.", "The stirge can detach itself by spending 5 feet of its movement. It does so after it drains 10 hit points of blood from the target or the target dies. A creature, including the target, can use its action to detach the stirge."]}]', '[]', '[]', '["grassland", "forest", "swamp", "hill", "urban", "desert", "coastal", "mountain", "underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('stone_giant', 'Stone Giant', 'giant', '', 'H', 'N', 17, 126, '{"walk": 40}', 23, 15, 20, 10, 12, 9, '7', 0, 2, '{"dex": "+5", "con": "+8", "wis": "+4"}', '{"athletics": "+12", "perception": "+4"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Giant"]', '[{"name": "Stone Camouflage", "entries": ["The giant has advantage on Dexterity ({@skill Stealth}) checks made to hide in rocky terrain."]}]', '[{"name": "Multiattack", "entries": ["The giant makes two greatclub attacks."]}, {"name": "Greatclub", "entries": ["{@atk mw} {@hit 9} to hit, reach 15 ft., one target. {@h}19 ({@damage 3d8 + 6}) bludgeoning damage."]}, {"name": "Rock", "entries": ["{@atk rw} {@hit 9} to hit, range 60/240 ft., one target. {@h}28 ({@damage 4d10 + 6}) bludgeoning damage. If the target is a creature, it must succeed on a {@dc 17} Strength saving throw or be knocked {@condition prone}."]}]', '[]', '[]', '["underdark", "mountain", "hill"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('stone_golem', 'Stone Golem', 'construct', '', 'L', 'U', 17, 178, '{"walk": 30}', 22, 9, 20, 3, 11, 1, '10', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["understands the languages of its creator but can''t speak"]', '[{"name": "Immutable Form", "entries": ["The golem is immune to any spell or effect that would alter its form."]}, {"name": "Magic Resistance", "entries": ["The golem has advantage on saving throws against spells and other magical effects."]}, {"name": "Magic Weapons", "entries": ["The golem''s weapon attacks are magical."]}]', '[{"name": "Multiattack", "entries": ["The golem makes two slam attacks."]}, {"name": "Slam", "entries": ["{@atk mw} {@hit 10} to hit, reach 5 ft., one target. {@h}19 ({@damage 3d8 + 6}) bludgeoning damage."]}, {"name": "Slow {@recharge 5}", "entries": ["The golem targets one or more creatures it can see within 10 feet of it. Each target must make a {@dc 17} Wisdom saving throw against this magic. On a failed save, a target can''t use reactions, its speed is halved, and it can''t make more than one attack on its turn. In addition, the target can take either an action or a bonus action on its turn, not both. These effects last for 1 minute. A target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('storm_giant', 'Storm Giant', 'giant', '', 'H', 'C, G', 16, 230, '{"walk": 50, "swim": 50}', 29, 14, 20, 16, 18, 18, '13', 0, 2, '{"str": "+14", "con": "+10", "wis": "+9", "cha": "+9"}', '{"arcana": "+8", "athletics": "+14", "history": "+8", "perception": "+9"}', '[]', '[]', '[]', '[]', '["Common", "Giant"]', '[{"name": "Amphibious", "entries": ["The giant can breathe air and water."]}]', '[{"name": "Multiattack", "entries": ["The giant makes two greatsword attacks."]}, {"name": "Greatsword", "entries": ["{@atk mw} {@hit 14} to hit, reach 10 ft., one target. {@h}30 ({@damage 6d6 + 9}) slashing damage."]}, {"name": "Rock", "entries": ["{@atk rw} {@hit 14} to hit, range 60/240 ft., one target. {@h}35 ({@damage 4d12 + 9}) bludgeoning damage."]}, {"name": "Lightning Strike {@recharge 5}", "entries": ["The giant hurls a magical lightning bolt at a point it can see within 500 feet of it. Each creature within 10 feet of that point must make a {@dc 17} Dexterity saving throw, taking 54 ({@damage 12d8}) lightning damage on a failed save, or half as much damage on a successful one."]}]', '[]', '[]', '["coastal", "underwater"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('succubus', 'Succubus', 'fiend', 'shapechanger', 'M', 'N, E', 15, 66, '{"walk": 30, "fly": 60}', 8, 17, 13, 15, 12, 20, '4', 0, 2, '{}', '{"deception": "+9", "insight": "+5", "perception": "+5", "persuasion": "+9", "stealth": "+7"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Abyssal", "Common", "Infernal", "telepathy 60 ft."]', '[{"name": "Telepathic Bond", "entries": ["The fiend ignores the range restriction on its telepathy when communicating with a creature it has {@condition charmed}. The two don''t even need to be on the same plane of existence."]}, {"name": "Shapechanger", "entries": ["The fiend can use its action to polymorph into a Small or Medium humanoid, or back into its true form. Without wings, the fiend loses its flying speed. Other than its size and speed, its statistics are the same in each form. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies."]}]', '[{"name": "Claw (Fiend Form Only)", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}6 ({@damage 1d6 + 3}) slashing damage."]}, {"name": "Charm", "entries": ["One humanoid the fiend can see within 30 feet of it must succeed on a {@dc 15} Wisdom saving throw or be magically {@condition charmed} for 1 day. The {@condition charmed} target obeys the fiend''s verbal or telepathic commands. If the target suffers any harm or receives a suicidal command, it can repeat the saving throw, ending the effect on a success. If the target successfully saves against the effect, or if the effect on it ends, the target is immune to this fiend''s Charm for the next 24 hours.", "The fiend can have only one target {@condition charmed} at a time. If it charms another, the effect on the previous target ends."]}, {"name": "Draining Kiss", "entries": ["The fiend kisses a creature {@condition charmed} by it or a willing creature. The target must make a {@dc 15} Constitution saving throw against this magic, taking 32 ({@damage 5d10 + 5}) psychic damage on a failed save, or half as much damage on a successful one. The target''s hit point maximum is reduced by an amount equal to the damage taken. This reduction lasts until the target finishes a long rest. The target dies if this effect reduces its hit point maximum to 0."]}, {"name": "Etherealness", "entries": ["The fiend magically enters the Ethereal Plane from the Material Plane, or vice versa."]}]', '[]', '[]', '["urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('swarm_of_bats', 'Swarm of Bats', 'beast', '', 'M', 'U', 12, 22, '{"walk": 0, "fly": 30}', 5, 15, 10, 2, 12, 4, '1/4', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 60 ft."]', '[]', '[{"name": "Echolocation", "entries": ["The swarm can''t use its blindsight while {@condition deafened}."]}, {"name": "Keen Hearing", "entries": ["The swarm has advantage on Wisdom ({@skill Perception}) checks that rely on hearing."]}, {"name": "Swarm", "entries": ["The swarm can occupy another creature''s space and vice versa, and the swarm can move through any opening large enough for a Tiny bat. The swarm can''t regain hit points or gain temporary hit points."]}]', '[{"name": "Bites", "entries": ["{@atk mw} {@hit 4} to hit, reach 0 ft., one creature in the swarm''s space. {@h}5 ({@damage 2d4}) piercing damage, or 2 ({@damage 1d4}) piercing damage if the swarm has half of its hit points or fewer."]}]', '[]', '[]', '["underdark", "mountain", "hill", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('swarm_of_beetles', 'Swarm of Beetles', 'beast', '', 'M', 'U', 12, 22, '{"walk": 20, "burrow": 5, "climb": 20}', 3, 13, 10, 1, 7, 1, '1/2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 10 ft."]', '[]', '[{"name": "Swarm", "entries": ["The swarm can occupy another creature''s space and vice versa, and the swarm can move through any opening large enough for a Tiny insect. The swarm can''t regain hit points or gain temporary hit points."]}]', '[{"name": "Bites", "entries": ["{@atk mw} {@hit 3} to hit, reach 0 ft., one target in the swarm''s space. {@h}10 ({@damage 4d4}) piercing damage, or 5 ({@damage 2d4}) piercing damage if the swarm has half of its hit points or fewer."]}]', '[]', '[]', '["underdark", "grassland", "forest", "swamp", "hill", "urban", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('swarm_of_centipedes', 'Swarm of Centipedes', 'beast', '', 'M', 'U', 12, 22, '{"walk": 20, "climb": 20}', 3, 13, 10, 1, 7, 1, '1/2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 10 ft."]', '[]', '[{"name": "Swarm", "entries": ["The swarm can occupy another creature''s space and vice versa, and the swarm can move through any opening large enough for a Tiny insect. The swarm can''t regain hit points or gain temporary hit points."]}]', '[{"name": "Bites", "entries": ["{@atk mw} {@hit 3} to hit, reach 0 ft., one target in the swarm''s space. {@h}10 ({@damage 4d4}) piercing damage, or 5 ({@damage 2d4}) piercing damage if the swarm has half of its hit points or fewer.", "A creature reduced to 0 hit points by a swarm of centipedes is stable but {@condition poisoned} for 1 hour, even after regaining hit points, and {@condition paralyzed} while {@condition poisoned} in this way."]}]', '[]', '[]', '["underdark", "grassland", "forest", "swamp", "hill", "urban", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('swarm_of_insects', 'Swarm of Insects', 'beast', '', 'M', 'U', 12, 22, '{"walk": 20, "climb": 20}', 3, 13, 10, 1, 7, 1, '1/2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 10 ft."]', '[]', '[{"name": "Swarm", "entries": ["The swarm can occupy another creature''s space and vice versa, and the swarm can move through any opening large enough for a Tiny insect. The swarm can''t regain hit points or gain temporary hit points."]}]', '[{"name": "Bites", "entries": ["{@atk mw} {@hit 3} to hit, reach 0 ft., one target in the swarm''s space. {@h}10 ({@damage 4d4}) piercing damage, or 5 ({@damage 2d4}) piercing damage if the swarm has half of its hit points or fewer."]}]', '[]', '[]', '["underdark", "grassland", "forest", "swamp", "hill", "urban", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('swarm_of_poisonous_snakes', 'Swarm of Poisonous Snakes', 'beast', '', 'M', 'U', 14, 36, '{"walk": 30, "swim": 30}', 8, 18, 11, 1, 10, 3, '2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 10 ft."]', '[]', '[{"name": "Swarm", "entries": ["The swarm can occupy another creature''s space and vice versa, and the swarm can move through any opening large enough for a Tiny snake. The swarm can''t regain hit points or gain temporary hit points."]}]', '[{"name": "Bites", "entries": ["{@atk mw} {@hit 6} to hit, reach 0 ft., one creature in the swarm''s space. {@h}7 ({@damage 2d6}) piercing damage, or 3 ({@damage 1d6}) piercing damage if the swarm has half of its hit points or fewer. The target must make a {@dc 10} Constitution saving throw, taking 14 ({@damage 4d6}) poison damage on a failed save, or half as much damage on a successful one."]}]', '[]', '[]', '["forest", "swamp"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('swarm_of_quippers', 'Swarm of Quippers', 'beast', '', 'M', 'U', 13, 28, '{"walk": 0, "swim": 40}', 13, 16, 9, 1, 7, 2, '1', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '[]', '[{"name": "Blood Frenzy", "entries": ["The swarm has advantage on melee attack rolls against any creature that doesn''t have all its hit points."]}, {"name": "Swarm", "entries": ["The swarm can occupy another creature''s space and vice versa, and the swarm can move through any opening large enough for a Tiny quipper. The swarm can''t regain hit points or gain temporary hit points."]}, {"name": "Water Breathing", "entries": ["The swarm can breathe only underwater."]}]', '[{"name": "Bites", "entries": ["{@atk mw} {@hit 5} to hit, reach 0 ft., one creature in the swarm''s space. {@h}14 ({@damage 4d6}) piercing damage, or 7 ({@damage 2d6}) piercing damage if the swarm has half of its hit points or fewer."]}]', '[]', '[]', '["underwater"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('swarm_of_rats', 'Swarm of Rats', 'beast', '', 'M', 'U', 10, 24, '{"walk": 30}', 9, 11, 9, 2, 10, 3, '1/4', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 30 ft."]', '[]', '[{"name": "Keen Smell", "entries": ["The swarm has advantage on Wisdom ({@skill Perception}) checks that rely on smell."]}, {"name": "Swarm", "entries": ["The swarm can occupy another creature''s space and vice versa, and the swarm can move through any opening large enough for a Tiny rat. The swarm can''t regain hit points or gain temporary hit points."]}]', '[{"name": "Bites", "entries": ["{@atk mw} {@hit 2} to hit, reach 0 ft., one target in the swarm''s space. {@h}7 ({@damage 2d6}) piercing damage, or 3 ({@damage 1d6}) piercing damage if the swarm has half of its hit points or fewer."]}]', '[]', '[]', '["swamp", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('swarm_of_ravens', 'Swarm of Ravens', 'beast', '', 'M', 'U', 12, 24, '{"walk": 10, "fly": 50}', 6, 14, 8, 3, 12, 6, '1/4', 0, 2, '{}', '{"perception": "+5"}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Swarm", "entries": ["The swarm can occupy another creature''s space and vice versa, and the swarm can move through any opening large enough for a Tiny raven. The swarm can''t regain hit points or gain temporary hit points."]}]', '[{"name": "Beaks", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target in the swarm''s space. {@h}7 ({@damage 2d6}) piercing damage, or 3 ({@damage 1d6}) piercing damage if the swarm has half of its hit points or fewer."]}]', '[]', '[]', '["forest", "swamp", "hill", "urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('swarm_of_spiders', 'Swarm of Spiders', 'beast', '', 'M', 'U', 12, 22, '{"walk": 20, "climb": 20}', 3, 13, 10, 1, 7, 1, '1/2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 10 ft."]', '[]', '[{"name": "Swarm", "entries": ["The swarm can occupy another creature''s space and vice versa, and the swarm can move through any opening large enough for a Tiny insect. The swarm can''t regain hit points or gain temporary hit points."]}, {"name": "Spider Climb", "entries": ["The swarm can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."]}, {"name": "Web Sense", "entries": ["While in contact with a web, the swarm knows the exact location of any other creature in contact with the same web."]}, {"name": "Web Walker", "entries": ["The swarm ignores movement restrictions caused by webbing."]}]', '[{"name": "Bites", "entries": ["{@atk mw} {@hit 3} to hit, reach 0 ft., one target in the swarm''s space. {@h}10 ({@damage 4d4}) piercing damage, or 5 ({@damage 2d4}) piercing damage if the swarm has half of its hit points or fewer."]}]', '[]', '[]', '["underdark", "grassland", "forest", "swamp", "hill", "urban", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('swarm_of_wasps', 'Swarm of Wasps', 'beast', '', 'M', 'U', 12, 22, '{"walk": 5, "fly": 30}', 3, 13, 10, 1, 7, 1, '1/2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["blindsight 10 ft."]', '[]', '[{"name": "Swarm", "entries": ["The swarm can occupy another creature''s space and vice versa, and the swarm can move through any opening large enough for a Tiny insect. The swarm can''t regain hit points or gain temporary hit points."]}]', '[{"name": "Bites", "entries": ["{@atk mw} {@hit 3} to hit, reach 0 ft., one target in the swarm''s space. {@h}10 ({@damage 4d4}) piercing damage, or 5 ({@damage 2d4}) piercing damage if the swarm has half of its hit points or fewer."]}]', '[]', '[]', '["underdark", "grassland", "forest", "swamp", "hill", "urban", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('tarrasque', 'Tarrasque', 'monstrosity', 'titan', 'G', 'U', 25, 676, '{"walk": 40}', 30, 11, 30, 3, 11, 11, '30', 0, 2, '{"int": "+5", "wis": "+9", "cha": "+9"}', '{}', '[]', '[]', '[]', '["blindsight 120 ft."]', '[]', '[{"name": "Legendary Resistance (3/Day)", "entries": ["If the tarrasque fails a saving throw, it can choose to succeed instead."]}, {"name": "Magic Resistance", "entries": ["The tarrasque has advantage on saving throws against spells and other magical effects."]}, {"name": "Reflective Carapace", "entries": ["Any time the tarrasque is targeted by a {@spell magic missile} spell, a line spell, or a spell that requires a ranged attack roll, roll a {@dice d6}. On a 1 to 5, the tarrasque is unaffected. On a 6, the tarrasque is unaffected, and the effect is reflected back at the caster as though it originated from the tarrasque, turning the caster into the target."]}, {"name": "Siege Monster", "entries": ["The tarrasque deals double damage to objects and structures."]}]', '[{"name": "Multiattack", "entries": ["The tarrasque can use its Frightful Presence. It then makes five attacks: one with its bite, two with its claws, one with its horns, and one with its tail. It can use its Swallow instead of its bite."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 19} to hit, reach 10 ft., one target. {@h}36 ({@damage 4d12 + 10}) piercing damage. If the target is a creature, it is {@condition grappled} (escape {@dc 20}). Until this grapple ends, the target is {@condition restrained}, and the tarrasque can''t bite another target."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 19} to hit, reach 15 ft., one target. {@h}28 ({@damage 4d8 + 10}) slashing damage."]}, {"name": "Horns", "entries": ["{@atk mw} {@hit 19} to hit, reach 10 ft., one target. {@h}32 ({@damage 4d10 + 10}) piercing damage."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 19} to hit, reach 20 ft., one target. {@h}24 ({@damage 4d6 + 10}) bludgeoning damage. If the target is a creature, it must succeed on a {@dc 20} Strength saving throw or be knocked {@condition prone}."]}, {"name": "Frightful Presence", "entries": ["Each creature of the tarrasque''s choice within 120 feet of it and aware of it must succeed on a {@dc 17} Wisdom saving throw or become {@condition frightened} for 1 minute. A creature can repeat the saving throw at the end of each of its turns, with disadvantage if the tarrasque is within line of sight, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the tarrasque''s Frightful Presence for the next 24 hours."]}, {"name": "Swallow", "entries": ["The tarrasque makes one bite attack against a Large or smaller creature it is grappling. If the attack hits, the target takes the bite''s damage, the target is swallowed, and the grapple ends. While swallowed, the creature is {@condition blinded} and {@condition restrained}, it has {@quickref Cover||3||total cover} against attacks and other effects outside the tarrasque, and it takes 56 ({@damage 16d6}) acid damage at the start of each of the tarrasque''s turns.", "If the tarrasque takes 60 damage or more on a single turn from a creature inside it, the tarrasque must succeed on a {@dc 20} Constitution saving throw at the end of that turn or regurgitate all swallowed creatures, which fall {@condition prone} in a space within 10 feet of the tarrasque. If the tarrasque dies, a swallowed creature is no longer {@condition restrained} by it and can escape from the corpse by using 30 feet of movement, exiting {@condition prone}."]}]', '[{"name": "Attack", "entries": ["The tarrasque makes one claw attack or tail attack."]}, {"name": "Move", "entries": ["The tarrasque moves up to half its speed."]}, {"name": "Chomp (Costs 2 Actions)", "entries": ["The tarrasque makes one bite attack or uses its Swallow."]}]', '[]', '["urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('thri-kreen', 'Thri-kreen', 'humanoid', 'thri-kreen', 'M', 'C, N', 15, 33, '{"walk": 40}', 12, 15, 13, 8, 12, 7, '1', 0, 2, '{}', '{"perception": "+3", "stealth": "+4", "survival": "+3"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Thri-kreen"]', '[{"name": "Chameleon Carapace", "entries": ["The thri-kreen can change the color of its carapace to match the color and texture of its surroundings. As a result, it has advantage on Dexterity ({@skill Stealth}) checks made to hide."]}, {"name": "Standing Leap", "entries": ["The thri-kreen''s long jump is up to 30 feet and its high jump is up to 15 feet, with or without a running start."]}]', '[{"name": "Multiattack", "entries": ["The thri-kreen makes two attacks: one with its bite and one with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one creature. {@h}4 ({@damage 1d6 + 1}) piercing damage, and the target must succeed on a {@dc 11} Constitution saving throw or be {@condition poisoned} for 1 minute. If the saving throw fails by 5 or more, the target is also {@condition paralyzed} while {@condition poisoned} in this way. The {@condition poisoned} target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}6 ({@damage 2d4 + 1}) slashing damage."]}]', '[]', '[]', '["grassland", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('thug', 'Thug', 'humanoid', 'any race', 'M', 'L, NX, C, NY, E', 11, 32, '{"walk": 30}', 15, 11, 14, 10, 10, 11, '1/2', 0, 2, '{}', '{"intimidation": "+2"}', '[]', '[]', '[]', '[]', '["any one language (usually Common)"]', '[{"name": "Pack Tactics", "entries": ["The thug has advantage on an attack roll against a creature if at least one of the thug''s allies is within 5 feet of the creature and the ally isn''t {@condition incapacitated}."]}]', '[{"name": "Multiattack", "entries": ["The thug makes two melee attacks."]}, {"name": "Mace", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one creature. {@h}5 ({@damage 1d6 + 2}) bludgeoning damage."]}, {"name": "Heavy Crossbow", "entries": ["{@atk rw} {@hit 2} to hit, range 100/400 ft., one target. {@h}5 ({@damage 1d10}) piercing damage."]}]', '[]', '[]', '["urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('tiger', 'Tiger', 'beast', '', 'L', 'U', 12, 37, '{"walk": 40}', 17, 15, 14, 3, 12, 8, '1', 0, 2, '{}', '{"perception": "+3", "stealth": "+6"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '[]', '[{"name": "Keen Smell", "entries": ["The tiger has advantage on Wisdom ({@skill Perception}) checks that rely on smell."]}, {"name": "Pounce", "entries": ["If the tiger moves at least 20 feet straight toward a creature and then hits it with a claw attack on the same turn, that target must succeed on a {@dc 13} Strength saving throw or be knocked {@condition prone}. If the target is {@condition prone}, the tiger can make one bite attack against it as a bonus action."]}]', '[{"name": "Bite", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}8 ({@damage 1d10 + 3}) piercing damage."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}7 ({@damage 1d8 + 3}) slashing damage."]}]', '[]', '[]', '["grassland", "forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('treant', 'Treant', 'plant', '', 'H', 'C, G', 16, 138, '{"walk": 30}', 23, 8, 21, 12, 16, 12, '9', 0, 2, '{}', '{}', '[]', '[]', '[]', '[]', '["Common", "Druidic", "Elvish", "Sylvan"]', '[{"name": "False Appearance", "entries": ["While the treant remains motionless, it is indistinguishable from a normal tree."]}, {"name": "Siege Monster", "entries": ["The treant deals double damage to objects and structures."]}]', '[{"name": "Multiattack", "entries": ["The treant makes two slam attacks."]}, {"name": "Slam", "entries": ["{@atk mw} {@hit 10} to hit, reach 5 ft., one target. {@h}16 ({@damage 3d6 + 6}) bludgeoning damage."]}, {"name": "Rock", "entries": ["{@atk rw} {@hit 10} to hit, range 60/180 ft., one target. {@h}28 ({@damage 4d10 + 6}) bludgeoning damage."]}, {"name": "Animate Trees (1/Day)", "entries": ["The treant magically animates one or two trees it can see within 60 feet of it. These trees have the same statistics as a {@creature treant}, except they have Intelligence and Charisma scores of 1, they can''t speak, and they have only the Slam action option. An animated tree acts as an ally of the treant. The tree remains animate for 1 day or until it dies; until the treant dies or is more than 120 feet from the tree; or until the treant takes a bonus action to turn it back into an inanimate tree. The tree then takes root if possible."]}]', '[]', '[]', '["forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('tribal_warrior', 'Tribal Warrior', 'humanoid', 'any race', 'M', 'A', 12, 11, '{"walk": 30}', 13, 11, 12, 8, 11, 8, '1/8', 0, 2, '{}', '{}', '[]', '[]', '[]', '[]', '["any one language"]', '[{"name": "Pack Tactics", "entries": ["The warrior has advantage on an attack roll against a creature if at least one of the warrior''s allies is within 5 feet of the creature and the ally isn''t {@condition incapacitated}."]}]', '[{"name": "Spear", "entries": ["{@atk mw,rw} {@hit 3} to hit, reach 5 ft. or range 20/60 ft., one target. {@h}4 ({@damage 1d6 + 1}) piercing damage, or 5 ({@damage 1d8 + 1}) piercing damage if used with two hands to make a melee attack."]}]', '[]', '[]', '["coastal", "mountain", "grassland", "hill", "arctic", "forest", "swamp", "underdark", "desert"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('triceratops', 'Triceratops', 'beast', '', 'H', 'U', 13, 95, '{"walk": 50}', 22, 9, 17, 2, 11, 5, '5', 0, 2, '{}', '{}', '[]', '[]', '[]', '[]', '[]', '[{"name": "Trampling Charge", "entries": ["If the triceratops moves at least 20 feet straight toward a creature and then hits it with a gore attack on the same turn, that target must succeed on a {@dc 13} Strength saving throw or be knocked {@condition prone}. If the target is {@condition prone}, the triceratops can make one stomp attack against it as a bonus action."]}]', '[{"name": "Gore", "entries": ["{@atk mw} {@hit 9} to hit, reach 5 ft., one target. {@h}24 ({@damage 4d8 + 6}) piercing damage."]}, {"name": "Stomp", "entries": ["{@atk mw} {@hit 9} to hit, reach 5 ft., one {@condition prone} creature. {@h}22 ({@damage 3d10 + 6}) bludgeoning damage"]}]', '[]', '[]', '["grassland"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('tridrone', 'Tridrone', 'construct', '', 'M', 'L, N', 15, 16, '{"walk": 30}', 12, 13, 12, 9, 10, 9, '1/2', 0, 2, '{}', '{}', '[]', '[]', '[]', '["truesight 120 ft."]', '["Modron"]', '[{"name": "Axiomatic Mind", "entries": ["The tridrone can''t be compelled to act in a manner contrary to its nature or its instructions."]}, {"name": "Disintegration", "entries": ["If the tridrone dies, its body disintegrates into dust, leaving behind its weapons and anything else it was carrying."]}]', '[{"name": "Multiattack", "entries": ["The tridrone makes three fist attacks or three javelin attacks."]}, {"name": "Fist", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}3 ({@damage 1d4 + 1}) bludgeoning damage."]}, {"name": "Javelin", "entries": ["{@atk mw,rw} {@hit 3} to hit, reach 5 ft. or range 30/120 ft., one target. {@h}4 ({@damage 1d6 + 1}) piercing damage."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('troglodyte', 'Troglodyte', 'humanoid', 'troglodyte', 'M', 'C, E', 11, 13, '{"walk": 30}', 14, 10, 14, 6, 10, 6, '1/4', 0, 2, '{}', '{"stealth": "+2"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Troglodyte"]', '[{"name": "Chameleon Skin", "entries": ["The troglodyte has advantage on Dexterity ({@skill Stealth}) checks made to hide."]}, {"name": "Stench", "entries": ["Any creature other than a troglodyte that starts its turn within 5 feet of the troglodyte must succeed on a {@dc 12} Constitution saving throw or be {@condition poisoned} until the start of the creature''s next turn. On a successful saving throw, the creature is immune to the stench of all troglodytes for 1 hour."]}, {"name": "Sunlight Sensitivity", "entries": ["While in sunlight, the troglodyte has disadvantage on attack rolls, as well as on Wisdom ({@skill Perception}) checks that rely on sight."]}]', '[{"name": "Multiattack", "entries": ["The troglodyte makes three attacks: one with its bite and two with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}4 ({@damage 1d4 + 2}) piercing damage."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 4} to hit, reach 5 ft., one target. {@h}4 ({@damage 1d4 + 2}) slashing damage."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('troll', 'Troll', 'giant', '', 'L', 'C, E', 15, 84, '{"walk": 30}', 18, 13, 20, 7, 9, 7, '5', 0, 2, '{}', '{"perception": "+2"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Giant"]', '[{"name": "Keen Smell", "entries": ["The troll has advantage on Wisdom ({@skill Perception}) checks that rely on smell."]}, {"name": "Regeneration", "entries": ["The troll regains 10 hit points at the start of its turn. If the troll takes acid or fire damage, this trait doesn''t function at the start of the troll''s next turn. The troll dies only if it starts its turn with 0 hit points and doesn''t regenerate."]}]', '[{"name": "Multiattack", "entries": ["The troll makes three attacks: one with its bite and two with its claws."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}7 ({@damage 1d6 + 4}) piercing damage."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}11 ({@damage 2d6 + 4}) slashing damage."]}]', '[]', '[]', '["underdark", "mountain", "forest", "swamp", "hill", "arctic"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('twig_blight', 'Twig Blight', 'plant', '', 'S', 'N, E', 13, 4, '{"walk": 20}', 6, 13, 12, 4, 8, 3, '1/8', 0, 2, '{}', '{"stealth": "+3"}', '[]', '[]', '[]', '["blindsight 60 ft. (blind beyond this radius)"]', '["understands Common but can''t speak"]', '[{"name": "False Appearance", "entries": ["While the blight remains motionless, it is indistinguishable from a dead shrub."]}]', '[{"name": "Claws", "entries": ["{@atk mw} {@hit 3} to hit, reach 5 ft., one target. {@h}3 ({@damage 1d4 + 1}) piercing damage."]}]', '[]', '[]', '["forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('tyrannosaurus_rex', 'Tyrannosaurus Rex', 'beast', '', 'H', 'U', 13, 136, '{"walk": 50}', 25, 10, 19, 2, 12, 9, '8', 0, 2, '{}', '{"perception": "+4"}', '[]', '[]', '[]', '[]', '[]', '[]', '[{"name": "Multiattack", "entries": ["The tyrannosaurus makes two attacks: one with its bite and one with its tail. It can''t make both attacks against the same target."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 10} to hit, reach 10 ft., one target. {@h}33 ({@damage 4d12 + 7}) piercing damage. If the target is a Medium or smaller creature, it is {@condition grappled} (escape {@dc 17}). Until this grapple ends, the target is {@condition restrained}, and the tyrannosaurus can''t bite another target."]}, {"name": "Tail", "entries": ["{@atk mw} {@hit 10} to hit, reach 10 ft., one target. {@h}20 ({@damage 3d8 + 7}) bludgeoning damage."]}]', '[]', '[]', '["grassland"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('ultroloth', 'Ultroloth', 'fiend', 'yugoloth', 'M', 'N, E', 19, 153, '{"walk": 30, "fly": 60}', 16, 16, 18, 18, 15, 19, '13', 0, 2, '{}', '{"intimidation": "+9", "perception": "+7", "stealth": "+8"}', '[]', '[]', '[]', '["truesight 120 ft."]', '["Abyssal", "Infernal", "telepathy 120 ft."]', '[{"name": "Magic Resistance", "entries": ["The ultroloth has advantage on saving throws against spells and other magical effects."]}, {"name": "Magic Weapons", "entries": ["The ultroloth''s weapon attacks are magical."]}]', '[{"name": "Multiattack", "entries": ["The ultroloth can use its Hypnotic Gaze and makes three melee attacks."]}, {"name": "Longsword", "entries": ["{@atk mw} {@hit 8} to hit, reach 5 ft., one target. {@h}7 ({@damage 1d8 + 3}) slashing damage, or 8 ({@damage 1d10 + 3}) slashing damage if used with two hands."]}, {"name": "Hypnotic Gaze", "entries": ["The ultroloth''s eyes sparkle with opalescent light as it targets one creature it can see within 30 feet of it. If the target can see the ultroloth, the target must succeed on a {@dc 17} Wisdom saving throw against this magic or be {@condition charmed} until the end of the ultroloth''s next turn. The {@condition charmed} target is {@condition stunned}. If the target''s saving throw is successful, the target is immune to the ultroloth''s gaze for the next 24 hours."]}, {"name": "Teleport", "entries": ["The ultroloth magically teleports, along with any equipment it is wearing or carrying, up to 60 feet to an unoccupied space it can see."]}]', '[]', '[]', '[]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('umber_hulk', 'Umber Hulk', 'monstrosity', '', 'L', 'C, E', 18, 93, '{"walk": 30, "burrow": 20}', 20, 13, 16, 9, 10, 10, '5', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 120 ft.", "tremorsense 60 ft."]', '["Umber Hulk"]', '[{"name": "Confusing Gaze", "entries": ["When a creature starts its turn within 30 feet of the umber hulk and is able to see the umber hulk''s eyes, the umber hulk can magically force it to make a {@dc 15} Charisma saving throw, unless the umber hulk is {@condition incapacitated}.", "On a failed saving throw, the creature can''t take reactions until the start of its next turn and rolls a {@dice d8} to determine what it does during that turn. On a 1 to 4, the creature does nothing. On a 5 or 6, the creature takes no action but uses all its movement to move in a random direction. On a 7 or 8, the creature makes one melee attack against a random creature, or it does nothing if no creature is within reach.", "Unless {@status surprised}, a creature can avert its eyes to avoid the saving throw at the start of its turn. If the creature does so, it can''t see the umber hulk until the start of its next turn, when it can avert its eyes again. If the creature looks at the umber hulk in the meantime, it must immediately make the save."]}, {"name": "Tunneler", "entries": ["The umber hulk can burrow through solid rock at half its burrowing speed and leaves a 5 foot-wide, 8-foot-high tunnel in its wake."]}]', '[{"name": "Multiattack", "entries": ["The umber hulk makes three attacks: two with its claws and one with its mandibles."]}, {"name": "Claw", "entries": ["{@atk mw} {@hit 8} to hit, reach 5 ft., one target. {@h}9 ({@damage 1d8 + 5}) slashing damage."]}, {"name": "Mandibles", "entries": ["{@atk mw} {@hit 8} to hit, reach 5 ft., one target. {@h}14 ({@damage 2d8 + 5}) slashing damage."]}]', '[]', '[]', '["underdark"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('unicorn', 'Unicorn', 'celestial', '', 'L', 'L, G', 12, 67, '{"walk": 50}', 18, 14, 15, 11, 17, 16, '5', 0, 2, '{}', '{}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["Celestial", "Elvish", "Sylvan", "telepathy 60 ft."]', '[{"name": "Charge", "entries": ["If the unicorn moves at least 20 feet straight toward a target and then hits it with a horn attack on the same turn, the target takes an extra 9 ({@damage 2d8}) piercing damage. If the target is a creature, it must succeed on a {@dc 15} Strength saving throw or be knocked {@condition prone}."]}, {"name": "Magic Resistance", "entries": ["The unicorn has advantage on saving throws against spells and other magical effects."]}, {"name": "Magic Weapons", "entries": ["The unicorn''s weapon attacks are magical."]}]', '[{"name": "Multiattack", "entries": ["The unicorn makes two attacks: one with its hooves and one with its horn."]}, {"name": "Hooves", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}11 ({@damage 2d6 + 4}) bludgeoning damage."]}, {"name": "Horn", "entries": ["{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}8 ({@damage 1d8 + 4}) piercing damage."]}, {"name": "Healing Touch (3/Day)", "entries": ["The unicorn touches another creature with its horn. The target magically regains 11 ({@dice 2d8 + 2}) hit points. In addition, the touch removes all diseases and neutralizes all poisons afflicting the target."]}, {"name": "Teleport (1/Day)", "entries": ["The unicorn magically teleports itself and up to three willing creatures it can see within 5 feet of it, along with any equipment they are wearing or carrying, to a location the unicorn is familiar with, up to 1 mile away."]}]', '[{"name": "Hooves", "entries": ["The unicorn makes one attack with its hooves."]}, {"name": "Shimmering Shield (Costs 2 Actions)", "entries": ["The unicorn creates a shimmering, magical field around itself or another creature it can see within 60 feet of it. The target gains a +2 bonus to AC until the end of the unicorn''s next turn."]}, {"name": "Heal Self (Costs 3 Actions)", "entries": ["The unicorn magically regains 11 ({@dice 2d8 + 2}) hit points."]}]', '[]', '["forest"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('vampire', 'Vampire', 'undead', 'shapechanger', 'M', 'L, E', 16, 144, '{"walk": 30}', 18, 18, 18, 17, 15, 18, '13', 0, 2, '{"dex": "+9", "wis": "+7", "cha": "+9"}', '{"perception": "+7", "stealth": "+9"}', '[]', '[]', '[]', '["darkvision 120 ft."]', '["the languages it knew in life"]', '[{"name": "Shapechanger", "entries": ["If the vampire isn''t in sunlight or running water, it can use its action to polymorph into a Tiny bat or a Medium cloud of mist, or back into its true form.", "While in bat form, the vampire can''t speak, its walking speed is 5 feet, and it has a flying speed of 30 feet. Its statistics, other than its size and speed, are unchanged. Anything it is wearing transforms with it, but nothing it is carrying does. It reverts to its true form if it dies.", "While in mist form, the vampire can''t take any actions, speak, or manipulate objects. It is weightless, has a flying speed of 20 feet, can hover, and can enter a hostile creature''s space and stop there. In addition, if air can pass through a space, the mist can do so without squeezing, and it can''t pass through water. It has advantage on Strength, Dexterity, and Constitution saving throws, and it is immune to all nonmagical damage, except the damage it takes from sunlight."]}, {"name": "Legendary Resistance (3/Day)", "entries": ["If the vampire fails a saving throw, it can choose to succeed instead."]}, {"name": "Misty Escape", "entries": ["When it drops to 0 hit points outside its resting place, the vampire transforms into a cloud of mist (as in the Shapechanger trait) instead of falling {@condition unconscious}, provided that it isn''t in sunlight or running water. If it can''t transform, it is destroyed.", "While it has 0 hit points in mist form, it can''t revert to its vampire form, and it must reach its resting place within 2 hours or be destroyed. Once in its resting place, it reverts to its vampire form. It is then {@condition paralyzed} until it regains at least 1 hit point. After spending 1 hour in its resting place with 0 hit points, it regains 1 hit point."]}, {"name": "Regeneration", "entries": ["The vampire regains 20 hit points at the start of its turn if it has at least 1 hit point and isn''t in sunlight or running water. If the vampire takes radiant damage or damage from holy water, this trait doesn''t function at the start of the vampire''s next turn."]}, {"name": "Spider Climb", "entries": ["The vampire can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."]}, {"name": "Vampire Weaknesses", "entries": ["The vampire has the following flaws:", {"type": "list", "style": "list-hang-subtrait", "items": [{"type": "itemSub", "name": "Forbiddance", "entry": "The vampire can''t enter a residence without an invitation from one of the occupants."}, {"type": "itemSub", "name": "Harmed by Running Water", "entry": "The vampire takes 20 acid damage if it ends its turn in running water."}, {"type": "itemSub", "name": "Stake to the Heart", "entry": "If a piercing weapon made of wood is driven into the vampire''s heart while the vampire is {@condition incapacitated} in its resting place, the vampire is {@condition paralyzed} until the stake is removed."}, {"type": "itemSub", "name": "Sunlight Hypersensitivity", "entry": "The vampire takes 20 radiant damage when it starts its turn in sunlight. While in sunlight, it has disadvantage on attack rolls and ability checks."}]}]}]', '[{"name": "Multiattack (Vampire Form Only)", "entries": ["The vampire makes two attacks, only one of which can be a bite attack."]}, {"name": "Unarmed Strike (Vampire Form Only)", "entries": ["{@atk mw} {@hit 9} to hit, reach 5 ft., one creature. {@h}8 ({@damage 1d8 + 4}) bludgeoning damage. Instead of dealing damage, the vampire can grapple the target (escape {@dc 18})."]}, {"name": "Bite (Bat or Vampire Form Only)", "entries": ["{@atk mw} {@hit 9} to hit, reach 5 ft., one willing creature, or a creature that is {@condition grappled} by the vampire, {@condition incapacitated}, or {@condition restrained}. {@h}7 ({@damage 1d6 + 4}) piercing damage plus 10 ({@damage 3d6}) necrotic damage. The target''s hit point maximum is reduced by an amount equal to the necrotic damage taken, and the vampire regains hit points equal to that amount. The reduction lasts until the target finishes a long rest. The target dies if this effect reduces its hit point maximum to 0. A humanoid slain in this way and then buried in the ground rises the following night as a {@creature vampire spawn} under the vampire''s control."]}, {"name": "Charm", "entries": ["The vampire targets one humanoid it can see within 30 feet of it. If the target can see the vampire, the target must succeed on a {@dc 17} Wisdom saving throw against this magic or be {@condition charmed} by the vampire. The {@condition charmed} target regards the vampire as a trusted friend to be heeded and protected. Although the target isn''t under the vampire''s control, it takes the vampire''s requests or actions in the most favorable way it can, and it is a willing target for the vampire''s bite attack.", "Each time the vampire or the vampire''s companions do anything harmful to the target, it can repeat the saving throw, ending the effect on itself on a success. Otherwise, the effect lasts 24 hours or until the vampire is destroyed, is on a different plane of existence than the target, or takes a bonus action to end the effect."]}, {"name": "Children of the Night (1/Day)", "entries": ["The vampire magically calls {@dice 2d4} swarms of {@creature swarm of bats||bats} or {@creature swarm of rats||rats}, provided that the sun isn''t up. While outdoors, the vampire can call {@dice 3d6} {@creature wolf||wolves} instead. The called creatures arrive in {@dice 1d4} rounds, acting as allies of the vampire and obeying its spoken commands. The beasts remain for 1 hour, until the vampire dies, or until the vampire dismisses them as a bonus action."]}]', '[{"name": "Move", "entries": ["The vampire moves up to its speed without provoking opportunity attacks."]}, {"name": "Unarmed Strike", "entries": ["The vampire makes one unarmed strike."]}, {"name": "Bite (Costs 2 Actions)", "entries": ["The vampire makes one bite attack."]}]', '[]', '["urban"]');
INSERT INTO monsters (id, name, type, subtype, size, alignment, armor_class, hit_points, speed, strength, dexterity, constitution, intelligence, wisdom, charisma, challenge_rating, experience_points, proficiency_bonus, saving_throws, skills, damage_resistances, damage_immunities, condition_immunities, senses, languages, special_abilities, actions, legendary_actions, reactions, environment) VALUES ('vampire_spawn', 'Vampire Spawn', 'undead', '', 'M', 'N, E', 15, 82, '{"walk": 30}', 16, 16, 16, 11, 10, 12, '5', 0, 2, '{"dex": "+6", "wis": "+3"}', '{"perception": "+3", "stealth": "+6"}', '[]', '[]', '[]', '["darkvision 60 ft."]', '["the languages it knew in life"]', '[{"name": "Regeneration", "entries": ["The vampire regains 10 hit points at the start of its turn if it has at least 1 hit point and isn''t in sunlight or running water. If the vampire takes radiant damage or damage from holy water, this trait doesn''t function at the start of the vampire''s next turn."]}, {"name": "Spider Climb", "entries": ["The vampire can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."]}, {"name": "Vampire Weaknesses", "entries": ["The vampire has the following flaws:", {"type": "list", "style": "list-hang-subtrait", "items": [{"type": "itemSub", "name": "Forbiddance", "entry": "The vampire can''t enter a residence without an invitation from one of the occupants."}, {"type": "itemSub", "name": "Harmed by Running Water", "entry": "The vampire takes 20 acid damage when it ends its turn in running water."}, {"type": "itemSub", "name": "Stake to the Heart", "entry": "The vampire is destroyed if a piercing weapon made of wood is driven into its heart while it is {@condition incapacitated} in its resting place."}, {"type": "itemSub", "name": "Sunlight Hypersensitivity", "entry": "The vampire takes 20 radiant damage when it starts its turn in sunlight. While in sunlight, it has disadvantage on attack rolls and ability checks"}]}]}]', '[{"name": "Multiattack", "entries": ["The vampire makes two attacks, only one of which can be a bite attack."]}, {"name": "Bite", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one willing creature, or a creature that is {@condition grappled} by the vampire, {@condition incapacitated}, or {@condition restrained}. {@h}6 ({@damage 1d6 + 3}) piercing damage plus 7 ({@damage 2d6}) necrotic damage. The target''s hit point maximum is reduced by an amount equal to the necrotic damage taken, and the vampire regains hit points equal to that amount. The reduction lasts until the target finishes a long rest. The target dies if this effect reduces its hit point maximum to 0."]}, {"name": "Claws", "entries": ["{@atk mw} {@hit 6} to hit, reach 5 ft., one creature. {@h}8 ({@damage 2d4 + 3}) slashing damage. Instead of dealing damage, the vampire can grapple the target (escape {@dc 13})."]}]', '[]', '[]', '["underdark", "urban"]');
